/* libcob -- the SLOW-32 COBOL runtime.
 *
 * Guest code, built by the SLOW-32 C toolchain (cobol/ is in the tree's
 * ordinary universe, so the host compiles it).  The compiler lowers each
 * verb either to a short inline sequence or to a call in here with a
 * descriptor it built (cobrt.h); the runtime works in bytes and pictures
 * and knows nothing about the statement that called it.
 *
 * Stage 2: DISPLAY; MOVE across the conversion matrix; comparison; class
 * tests; a scaled-i64 numeric stack for the arithmetic statements; the
 * PERFORM stack.  Stage 3: editing and de-editing (kern.h), ROUNDED,
 * SIZE ERROR, COMPUTE's operators.  Stage 4: line sequential and fixed
 * sequential files, STRING, the case intrinsics.  Stage 5: indexed files
 * on the default path (docs/indexed.md).  Stage 7: Report Writer, the
 * cheap half (docs/report-writer.md).  Stage 8: SCREEN SECTION on the
 * term service (docs/screen.md).  Stage 9: INSPECT, reference
 * modification, CURRENT-DATE -- what menu and taskdt drag in.  Stage 10:
 * sequential V with the IBM RDW (docs/framing.md).  Stage 13: the
 * command line -- ARGUMENT-NUMBER, ARGUMENT-VALUE, COMMAND-LINE.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stddef.h>
#include <math.h>
#include <ctype.h>
#include <errno.h>
#include "cobrt.h"
#include "wide.h"
#include "ieee.h"
#include "dtfmt.h"     /* the 2014 date and time formats (15.3.1-15.3.3), shared with the compiler */
#include "kern.h"
#include "scredit.h"                    /* the screen field editor's core (docs/plans/screen-input.md) */

/* kern.h restates what it needs of cobrt.h; a disagreement fails here */
typedef char kern_chk_desc[(sizeof(cob_desc) == sizeof(cob_kdesc) && offsetof(cob_desc, size) == offsetof(cob_kdesc, size) &&
                            offsetof(cob_desc, pic) == offsetof(cob_kdesc, pic) && offsetof(cob_desc, flags) == offsetof(cob_kdesc, flags) &&
                            offsetof(cob_desc, flags2) == offsetof(cob_kdesc, flags2)) ? 1 : -1];
typedef char kern_chk_f2[(K_F2_BIGEND == COB_F2_BIGEND && K_F2_NOSIGN == COB_F2_NOSIGN && K_F2_TWOSC == COB_F2_TWOSC && K_F2_SIZEDIG == COB_F2_SIZEDIG) ? 1 : -1];
typedef char kern_chk_cat[K_NUM_ED == COB_NUM_ED ? 1 : -1];
typedef char kern_chk_u[(K_U_DISPLAY == COB_U_DISPLAY && K_U_BINARY == COB_U_BINARY && K_U_PACKED == COB_U_PACKED &&
                         K_U_NATIONAL == COB_U_NATIONAL && K_U_BIT == COB_U_BIT) ? 1 : -1];
typedef char kern_chk_f[(K_F_SIGNED == COB_F_SIGNED && K_F_SEPLEAD == COB_F_SEPLEAD && K_F_SEPTRAIL == COB_F_SEPTRAIL &&
                         K_F_BLANKZ == COB_F_BLANKZ && K_F_NOTRUNC == COB_F_NOTRUNC && K_F_LEAD == COB_F_LEAD) ? 1 : -1];
/* the thunks in front of the hookable routines, generated by build.sh:
 * each jumps to its _impl here */
long long cob_get_num(const void *vp, const cob_desc *d);
int cob_put_num_x(void *vp, const cob_desc *d, long long v, int vscale, int opts);
long long cob_get_edited(const void *vp, const cob_desc *d, int locale);
int cob_put_edited(void *vp, const cob_desc *d, long long v, int vscale, int opts, int locale);
void cob_wget(const void *vp, const cob_desc *d, cob_wnum *w);
int cob_wput_x(void *vp, const cob_desc *d, const cob_wnum *win, int opts);
#include <term.h>
#include <time.h>
#include <sys/stat.h>
#include "xsort.h"
#include "btree.h"
#include "../../common/s32utf.h"   /* the one Unicode model: coding, width, clusters (cobol ISSUES-94) */

/* ---- output: DISPLAY goes to stdout, buffered by us ------------------ */

static char out_buf[512];
static int  out_n;
static int  out_err;                    /* DISPLAY UPON SYSERR: this line to stderr */

/* Through stdio, not write(2): the DEBUG-instruction libc has no write,
 * and fwrite is byte-safe (COBOL data may hold NULs) under both libcs. */
static void out_flush(void)
{
    FILE *f = out_err ? stderr : stdout;
    if (out_n) { fwrite(out_buf, 1, out_n, f); fflush(f); out_n = 0; }
}

/* Once a program has painted with RM's positioned DISPLAY/ACCEPT, a plain
 * DISPLAY is positioned too: RM puts it on the line after the last
 * positioned statement, at column 1, and a DISPLAY's newline moves that
 * line down.  A SCREEN SECTION program (no positioned statement) keeps the
 * stdout stream it has always had. */
static int term_up;                     /* defined with the terminal service below */
static int scr_tty;                     /* standard input is a terminal (raw mode took): a person is typing */
static int scr_rm_mode;                 /* set by the first positioned slot painted */
static int scr_next_line;               /* the line a LINE-less statement takes; see scr_pos */
static int con_col = 1, con_rows;
static void con_write(const char *p, int n)
{
    if (!con_rows) { int r = 24, c = 80; term_get_size(&r, &c); con_rows = r > 0 ? r : 24; }
    /* the column moves as the terminal's does: a cluster at a time, by its
     * display width (s32utf.h, the model the term service's shadow keeps);
     * a cluster's width is settled when the next one starts */
    s32u_dec dec = { 0, 0, 0, 0 };
    s32u_clu clu; memset(&clu, 0, sizeof clu);
    int pend = 0, placed = 0;
    for (int i = 0; i < n; i++) {
        if (p[i] == '\n' || p[i] == '\r') {
            con_col = 1; pend = 0; placed = 0;
            memset(&clu, 0, sizeof clu); memset(&dec, 0, sizeof dec);
            if (p[i] == '\n' && scr_next_line < con_rows) scr_next_line++;
            continue;
        }
        if (!placed) { term_gotoxy(scr_next_line ? scr_next_line : 1, con_col); placed = 1; }
        term_putc(p[i]);
        uint32_t cp;
        int r;
        while ((r = s32u_dec_byte(&dec, (unsigned char)p[i], &cp)) != 0) {
            if (s32u_clu_step(&clu, cp)) { con_col += pend; }
            pend = s32u_clu_lone(&clu) ? 1 : s32u_clu_width(&clu);
            if (r == 1) break;
        }
    }
    con_col += pend;
}

static char *out_cap; static int out_cap_n, out_cap_max;   /* DISPLAY's text taken into a screen slot (scr_render) */
static void out_bytes(const char *p, int n)
{
    if (out_cap) { for (int i = 0; i < n && out_cap_n < out_cap_max; i++) out_cap[out_cap_n++] = p[i]; return; }
    if (term_up && scr_rm_mode) { con_write(p, n); return; }
    while (n > 0) {
        int room = (int)sizeof out_buf - out_n;
        int k = n < room ? n : room;
        memcpy(out_buf + out_n, p, k);
        out_n += k; p += k; n -= k;
        if (out_n == (int)sizeof out_buf) out_flush();
    }
}

static void out_char(char c) { out_bytes(&c, 1); }

static void cob_fatal(const char *msg)
{
    out_flush();
    fputs("libcob: ", stderr); fputs(msg, stderr); fputc('\n', stderr);
    exit(3);
}

/* ---- program lifetime -------------------------------------------------- */

extern int cob_switches[8];
void cob_init(void)
{
    out_n = 0;
    /* SPECIAL-NAMES SWITCH-1..8 as the environment sets them: COB_SWITCH_n
     * = ON (GnuCOBOL's convention, which NIST's report.pl relies on) */
    for (int i = 0; i < 8; i++) {
        char name[16]; snprintf(name, sizeof name, "COB_SWITCH_%d", i + 1);
        const char *v = getenv(name);
        cob_switches[i] = v && (v[0] == 'O' || v[0] == 'o') && (v[1] == 'N' || v[1] == 'n');
    }
}

static int term_up;      /* the terminal service is initialised and raw */

static void term_down(void)
{
    if (!term_up) return;
    term_set_attr(0);
    term_set_raw(0);
    term_cleanup();
    term_up = 0;
}

/* Every file that has been OPENed, so that STOP RUN (and the end-of-input
 * exit) can close what the program left open: RM/COBOL and GnuCOBOL close
 * open files at STOP RUN, and the suite's print programs count on it --
 * GLPRTCHR's tie-up closes the master and leaves PRINTER.TXT to the run's
 * end, whose buffered pages were lost. */
static cob_file **open_files; static int n_open_files, cap_open_files;
static void remember_file(cob_file *f)
{
    for (int i = 0; i < n_open_files; i++) if (open_files[i] == f) return;
    if (n_open_files == cap_open_files) {
        cap_open_files = cap_open_files ? cap_open_files * 2 : 32;
        open_files = realloc(open_files, cap_open_files * sizeof *open_files);
        if (!open_files) cob_fatal("out of memory");
    }
    open_files[n_open_files++] = f;
}
int cob_close(cob_file *f);
static void close_open_files(void)
{
    for (int i = 0; i < n_open_files; i++)
        if (open_files[i]->open_mode) cob_close(open_files[i]);
}

/* RETURN-CODE (IBM, Micro Focus; not standard): the run unit's, set by a
 * program or by a CALL from what the callee returned.  STOP RUN without a
 * status of its own -- and the end of the main program -- exits with it. */
int cob_return_code;

/* a component's work at the normal end of the run: the EXEC SQL runtime
 * commits there (libcob/esql.c); nothing sets it in a program without SQL */
void (*cob_at_stop)(void);

void cob_stop_run(int code)
{
    if (code == 0) code = cob_return_code;
    if (cob_at_stop) { void (*f)(void) = cob_at_stop; cob_at_stop = 0; f(); }
    close_open_files();
    out_flush();
    term_down();
    exit(code);
}

/* ---- numeric access: the canonical numeric is a scaled i64 ------------ */

static int capacity_digits(unsigned size)
{
    /* the digits of the largest value the bytes hold, 256^n - 1 (COMP-X
     * sizes by MF's rule run 1 to 8); eight bytes, 19 */
    static const int d[9] = { 0, 3, 5, 8, 10, 13, 15, 17, 19 };
    return size >= 1 && size <= 8 ? d[size] : 19;
}

#define COB_RBUF 8192   /* line-sequential read buffer */

/* the digit helpers (mag_to_digits, udiv_pow10, div_pow10) and pow10tab
 * are in kern.h, the hookable kernels */

/* Value of the item scaled by 10^scale (i.e. the integer the digits spell). */
/* de-editing: a 1985 feature IBM ANS COBOL never had.  Out of line so
 * its arrays do not put a 350-byte frame under every numeric fetch. */
/* the program's DECIMAL-POINT IS COMMA and CURRENCY SIGN, as the edited
 * kernels take them (kern.h K_LOC_*) */
extern int cob_dp_comma, cob_currency, cob_currency_len;
static int loc_word(void) { return (cob_dp_comma ? 1 : 0) | ((cob_currency & 255) << 8) | ((cob_currency_len & 255) << 16); }

/* the numeric-edited fetch and store: hookable thunks (build.sh) in front
 * of these */
long long cob_get_edited_impl(const void *vp, const cob_desc *d, int locale)
{
    return cob_k_get_edited(vp, (const cob_kdesc *)d, d->pic, locale);
}
static int eff_digits(const cob_desc *d);
int cob_put_edited_impl(void *vp, const cob_desc *d, long long v, int vscale, int opts, int locale)
{
    return cob_k_put_edited(vp, (const cob_kdesc *)d, d->pic, eff_digits(d), v, vscale, opts, locale);
}
/* ---- numeric USAGE NATIONAL (COBOL 2002; cobol ISSUES-72) --------------
 * The DISPLAY representation with each byte one UTF-16BE code unit: digits
 * U+0030..U+0039, a separate sign U+002B/U+002D, an unseparated one the
 * DISPLAY overpunch widened.  Each primitive narrows such an operand into
 * a scratch DISPLAY copy, and a receiver is written there and widened
 * back.  A code unit above U+00FF narrows to X'7F', which is no digit. */
#define NATNUM_MAX 256
/* ... and boolean USAGE BIT (cobol ISSUES-78) is the DISPLAY form packed:
 * size bits from the scale-th bit of the first byte, 1 for '1'.  Widening
 * it sets or clears only its own bits. */
static int is_natnum(const cob_desc *d) { return d->usage == COB_U_NATIONAL || d->usage == COB_U_BIT; }

/* ---- floating point: COMP-1 and COMP-2 (docs/usage.md) ----------------
 * IEEE single or double in the machine's order, as Micro Focus has them.
 * Arithmetic with a float among its operands runs on the wide stack in
 * double (cob_wnum.isf); a store into a decimal item truncates, or rounds
 * under ROUNDED, to the item's scale, then stores as any wide value. */
static int is_float(const cob_desc *d) { return d->usage == COB_U_FLOAT; }
/* the standard floating-point formats held in software (COBOL 2014,
 * ieee.h): FLOAT-DECIMAL-16/34 and FLOAT-BINARY-128, read into and
 * written from the wide decimal stack */
static int is_sfloat(const cob_desc *d) { return d->usage == COB_U_SFLOAT; }
static int fp_special_of(const void *vp, const cob_desc *d, int *neg);
/* the hardware floats, in the machine's byte order unless the item says
 * HIGH-ORDER-LEFT (FLOAT-BINARY-32/64, 2023 13.18.60; COB_F2_BIGEND) */
static double f_load(const void *p, const cob_desc *d)
{
    unsigned char b[8]; const unsigned char *q = p;
    if (d->flags2 & COB_F2_BIGEND) { for (unsigned i = 0; i < d->size; i++) b[i] = q[d->size - 1 - i]; q = b; }
    if (d->size == 4) { float f; memcpy(&f, q, 4); return f; }
    double x; memcpy(&x, q, 8); return x;
}
static void f_store(void *p, const cob_desc *d, double x)
{
    unsigned char b[8];
    if (d->size == 4) { float f = (float)x; memcpy(b, &f, 4); }
    else memcpy(b, &x, 8);
    unsigned char *q = p;
    if (d->flags2 & COB_F2_BIGEND) for (unsigned i = 0; i < d->size; i++) q[i] = b[d->size - 1 - i];
    else memcpy(q, b, d->size);
}
static int sf_load(const void *p, const cob_desc *d, cob_wnum *w)
{
    int neg, scale, r;
    memset(w, 0, sizeof *w);
    if (d->flags2 & COB_F2_FBIN) r = bin128_decode(p, d->flags2 & COB_F2_BIGEND, w->m, &scale, &neg);
    else r = dec_decode(p, (int)d->size, d->flags2 & COB_F2_BIGEND, d->flags2 & COB_F2_DPD, w->m, &scale, &neg);
    w->neg = neg && !mp_is_zero(w->m, WL); w->scale = scale; w->isq = 1;
    if (r) { memset(w->m, 0, sizeof w->m); w->scale = 0; }   /* an infinity or a NaN: no number; zero here, the class condition says NUMERIC is false */
    return r;
}
/* a double as a floating decimal of 36 digits: through binary128, which
 * holds every double exactly */
static int w_from_dbl_q(cob_wnum *w, double x)
{
    unsigned long long u; memcpy(&u, &x, 8);
    int neg = (int)(u >> 63), e = (int)((u >> 52) & 0x7FF);
    unsigned long long f = u & 0xFFFFFFFFFFFFFull;
    memset(w, 0, sizeof *w); w->isq = 1;
    if (e == 0x7FF) return 1;
    int e128;
    if (e == 0) {
        if (!f) { w->neg = 0; return 0; }
        e128 = 1 - 1023 + 16383;                    /* 0.f * 2^-1022 normalized */
        while (!(f >> 52)) { f <<= 1; e128--; }
        f &= 0xFFFFFFFFFFFFFull;
    } else e128 = e - 1023 + 16383;
    wl_t a[4] = { 0, 0, 0, 0 };
    /* the 52 fraction bits at the top of binary128's 112 */
    a[1] = (wl_t)(f << 28); a[2] = (wl_t)(f >> 4); a[3] = (wl_t)(f >> 36);
    a[3] |= (wl_t)e128 << 16; if (neg) a[3] |= 1u << 31;
    unsigned char b[16]; ieee_store(b, 16, 0, a);
    int sneg, scale; bin128_decode(b, 0, w->m, &scale, &sneg);
    w->neg = sneg && !mp_is_zero(w->m, WL); w->scale = scale; w->isq = 1;
    return 0;
}
/* a wide value into a standard software float: nearest-even (IEEE's
 * default, the standard usages' rounding); 1 when the value is past the
 * format (a size error) */
static int sf_store(void *p, const cob_desc *d, const cob_wnum *w0)
{
    cob_wnum w = *w0;
    if (w.isf) { if (w_from_dbl_q(&w, w.f)) return 1; }
    if (d->flags2 & COB_F2_FBIN) return bin128_encode(p, d->flags2 & COB_F2_BIGEND, w.m, w.scale, w.neg);
    /* the scale in a local of its own: the kit's cc reloads a local
     * struct's member from the wrong frame offset after a call takes its
     * address (selfhost ISSUES-81) */
    int sc = w.scale;
    ieee_round_digits(w.m, &sc, d->size == 8 ? 16 : 34);
    return dec_encode(p, (int)d->size, d->flags2 & COB_F2_BIGEND, d->flags2 & COB_F2_DPD, w.m, sc, w.neg);
}
/* DISPLAY of a standard float: the value's significant digits, one before
 * the point, and a decimal exponent -- 1.5E+00, -2.25E-03, 0E+00 */
static int sf_fmt(const cob_wnum *w, char *out)
{
    char d[40]; int n = w_to_digits(w->m, d, 39), o = 0;
    if (!n) { memcpy(out, "0E+00", 5); return 5; }
    const char *s = d + 39 - n;
    int exp = n - 1 - w->scale, m = n;
    while (m > 1 && s[m - 1] == '0') m--;           /* trailing zeros of the coefficient */
    if (w->neg) out[o++] = '-';
    out[o++] = s[0];
    if (m > 1) { out[o++] = '.'; memcpy(out + o, s + 1, (size_t)(m - 1)); o += m - 1; }
    o += sprintf(out + o, "E%c%02d", exp < 0 ? '-' : '+', exp < 0 ? -exp : exp);
    return o;
}
static double pow10d(int k)
{
    double r = 1; int n = k < 0 ? -k : k;
    while (n >= 8) { r *= 1e8; n -= 8; }
    while (n-- > 0) r *= 10;
    return k < 0 ? 1 / r : r;
}
static void w_set_f(cob_wnum *w, double x) { memset(w, 0, sizeof *w); w->isf = 1; w->f = x; }
static double w_to_dbl(const cob_wnum *w)
{
    if (w->isf) return w->f;
    double x = 0;
    int nd = w_ndigits(w->m), scale = w->scale;
    if (w->isq && (scale < -300 || scale > 300 || scale < 0)) {
        /* a floating value's exponent past a plain power of ten: digits and
         * an exponent for the library's conversion */
        char d[40], t[64]; int n = w_to_digits(w->m, d, 39);
        if (!n) return 0;
        snprintf(t, sizeof t, "%s%.*se%d", w->neg ? "-" : "", n, d + 39 - n, -scale);
        return strtod(t, NULL);
    }
    if (nd > 15 && scale > 0 && nd - 15 <= scale && scale - (nd - 15) <= 22) {
        /* to the nearest double in one rounding: the magnitude cut to 15
         * digits (exact in a double) by decimal division, rounded, then
         * divided by an exact power of ten (10^22 is the last) -- the
         * limb sum divided by an inexact 10^37 rounded twice and missed
         * the last digit of SIN's reduced argument */
        cob_wnum t = *w; int k = nd - 15, half = 0, nz = 0;
        w_drop_digits(t.m, WL, k, &half, &nz);
        if (half > 0 || (half == 0 && (t.m[0] & 1))) mp_mul_small(t.m, WL, 1, 1);   /* half: 1 above, 0 exactly half (to even), -1 below */
        for (int i = WL - 1; i >= 0; i--) x = x * 4294967296.0 + t.m[i];
        x /= pow10d(scale - k);
        return w->neg ? -x : x;
    }
    for (int i = WL - 1; i >= 0; i--) x = x * 4294967296.0 + w->m[i];
    x /= pow10d(scale);
    return w->neg ? -x : x;
}
/* x as a decimal of the given scale, truncated or rounded; high digits
 * past 38 are shed (the store's own truncation or size error decides the
 * rest); 1 when x is not a number or past 10^38 */
static int w_from_dbl(cob_wnum *w, double x, int scale, int rounded)
{
    /* exactly: x = mant * 2^e with mant below 2^53, so x * 10^scale is
     * mant * 10^scale, then shifted by e bits -- worked in eight limbs,
     * since mant * 10^30 passes 38 digits before the shift brings it
     * back; the shift's remainder rounds or is dropped (the old way
     * scaled in double and lost the digits past its 53 bits: 10^25 came
     * out 10000000000000001606221131, not the double's own value) */
    memset(w, 0, sizeof *w);
    if (x != x || fabs(x) >= 1e38) return 1;
    int e; double m = frexp(fabs(x), &e);
    unsigned long long mant = (unsigned long long)ldexp(m, 53); e -= 53;
    wl_t t[8]; memset(t, 0, sizeof t);
    t[0] = (wl_t)mant; t[1] = (wl_t)(mant >> 32);
    for (int k = scale; k > 0; ) { int c = k > 9 ? 9 : k; wl_t p = 1; for (int i = 0; i < c; i++) p *= 10; mp_mul_small(t, 8, p, 0); k -= c; }
    while (e > 0) { int c = e > 31 ? 31 : e; mp_mul_small(t, 8, (wl_t)1u << c, 0); e -= c; }
    int half = 0, sticky = 0;
    while (e < 0) {
        int c = -e > 31 ? 31 : -e;
        wl_t r = mp_div_small(t, 8, (wl_t)1u << c);
        if (-e - c == 0) { half = r >> (c - 1); sticky = sticky || (r & (((wl_t)1u << (c - 1)) - 1)); }   /* the last shift's remainder: its top bit, and the rest */
        else sticky = sticky || r;
        e += c;
    }
    if (rounded && half) mp_mul_small(t, 8, 1, 1);
    (void)sticky;
    for (int i = WL; i < 8; i++) if (t[i]) return 1;
    memcpy(w->m, t, sizeof w->m);
    if (w_ndigits(w->m) > 38) return 1;
    w->neg = x < 0 && !mp_is_zero(w->m, WL); w->scale = scale;
    return 0;
}
/* MF's DISPLAY of a float, as the PICTURE -.9(8)E-99 (COMP-1) or
 * -.9(18)E-99 (COMP-2) would edit it: 1.5 is " .15000000E 01" */
static int fmt_float(double x, int nd, char *out)
{
    char *o = out, dg[24];
    int e = 0;
    if (x != x || x - x != 0) {         /* a NaN or an infinity (SET CONTENT OF, 2014): named, with its sign */
        unsigned long long u; memcpy(&u, &x, 8);
        const char *v = x != x ? ((u >> 63) ? "-NaN" : "NaN") : (x < 0 ? "-Inf" : "Inf");
        memcpy(out, v, strlen(v)); return (int)strlen(v);
    }
    *o++ = x < 0 ? '-' : ' ';
    *o++ = cob_dp_comma ? ',' : '.';
    double a = fabs(x);
    if (a == 0 || a != a) memset(dg, '0', (size_t)nd);
    else {
        char t[64]; snprintf(t, sizeof t, "%.*e", nd - 1, a);     /* d.ddd...e+XX */
        char *q = t; int k = 0;
        while (*q && *q != 'e' && *q != 'E' && k < nd) { if (*q >= '0' && *q <= '9') dg[k++] = *q; q++; }
        while (k < nd) dg[k++] = '0';
        while (*q && *q != 'e' && *q != 'E') q++;
        e = (*q ? atoi(q + 1) : 0) + 1;
    }
    memcpy(o, dg, (size_t)nd); o += nd;
    *o++ = 'E'; *o++ = e < 0 ? '-' : ' ';
    int ae = e < 0 ? -e : e;
    if (ae > 99) o += snprintf(o, 8, "%d", ae);
    else { *o++ = (char)('0' + ae / 10); *o++ = (char)('0' + ae % 10); }
    return (int)(o - out);
}
/* The DISPLAY form goes in the caller's NATNUM_MAX buffer, or, for a
 * longer item (bits: a bit group of any size; cobol ISSUES-94 B8), in one
 * of a ring of heap buffers -- four, as many as are live at once.  Callers
 * use the pointer returned, which is the one to widen from. */
static unsigned char *natbig[4]; static size_t natbig_cap[4]; static int natbig_k;
static unsigned char *nat_room(unsigned char *buf, int n)
{
    if (n <= NATNUM_MAX) return buf;
    int k = natbig_k++ & 3;
    if (natbig_cap[k] < (size_t)n) {
        natbig[k] = realloc(natbig[k], (size_t)n);
        if (!natbig[k]) cob_fatal("out of memory");
        natbig_cap[k] = (size_t)n;
    }
    return natbig[k];
}
static const unsigned char *nat_narrow(const void *vp, const cob_desc *d, unsigned char *buf, cob_desc *nd)
{
    const unsigned char *p = vp;
    *nd = *d; nd->usage = COB_U_DISPLAY;
    if (d->usage == COB_U_BIT) {
        int n = (int)d->size, o = d->scale;
        buf = nat_room(buf, n);
        for (int i = 0; i < n; i++) buf[i] = (unsigned char)('0' + ((p[(o + i) / 8] >> (7 - (o + i) % 8)) & 1));
        nd->scale = 0;
        return buf;
    }
    int n = (int)d->size / 2;
    if (n > NATNUM_MAX) cob_fatal("numeric national item longer than 256 characters");
    nd->size = (unsigned)n;
    for (int i = 0; i < n; i++) buf[i] = p[2 * i] ? 0x7F : p[2 * i + 1];
    return buf;
}
static void nat_widen(void *vp, const cob_desc *d, const unsigned char *buf, int n)
{
    unsigned char *p = vp;
    if (d->usage == COB_U_BIT) {
        for (int i = 0; i < n; i++) {
            int b = d->scale + i; unsigned char m = (unsigned char)(0x80 >> (b % 8));
            if (buf[i] == '1') p[b / 8] |= m; else p[b / 8] &= (unsigned char)~m;
        }
        return;
    }
    for (int i = 0; i < n; i++) { p[2 * i] = 0; p[2 * i + 1] = buf[i]; }
}

/* cob_get_num is a hookable thunk (build.sh, docs/dbt-hooks.md) in front
 * of this: the kernel's descriptors go to kern.h, the rest are here */
long long cob_get_num_impl(const void *vp, const cob_desc *d)
{
    const unsigned char *p = vp;
    if (cob_k_get_ok((const cob_kdesc *)d)) return cob_k_get_num(p, (const cob_kdesc *)d);
    if (is_sfloat(d)) { cob_wnum w; sf_load(p, d, &w); if (w.scale > 0) w_drop_digits(w.m, WL, w.scale > 40 ? 40 : w.scale, 0, 0); else if (w.scale < 0 && !w_scale_up(w.m, -w.scale > 40 ? 40 : -w.scale)) return w.neg ? -9200000000000000000LL : 9200000000000000000LL; return w_fits_i64(&w) ? w_to_i64(&w) : w.neg ? -9200000000000000000LL : 9200000000000000000LL; }
    if (is_float(d)) {                              /* its integer part (the descriptor's scale is 0) */
        double x = f_load(p, d) * pow10d(d->scale);
        if (x != x) return 0;
        return x >= 9.2e18 ? 9200000000000000000LL : x <= -9.2e18 ? -9200000000000000000LL : (long long)x;
    }
    if (d->digits > 18 || (d->usage == COB_U_BINARY && d->size > 8)) {
        /* a 31-digit item where only 18 fit: its value when it fits, and
         * a stop, never a wrong number, when it does not (docs/wide.md) */
        cob_wnum w; cob_wget(vp, d, &w);
        if (!w_fits_i64(&w)) cob_fatal("a value of more than 18 digits reached an operation that holds 18 (not implemented yet: docs/wide.md)");
        return w_to_i64(&w);
    }
    if (is_natnum(d)) { unsigned char b[NATNUM_MAX]; cob_desc nd; return cob_get_num(nat_narrow(vp, d, b, &nd), &nd); }
    if (d->cat == COB_NUM_ED) return cob_get_edited(p, d, loc_word());
    return cob_k_get_num(p, (const cob_kdesc *)d);     /* as before: any other usage reads as DISPLAY */
}

static int is_wide(const cob_desc *d);

/* the digit positions that hold a character: P scaling positions do not */
static int eff_digits(const cob_desc *d)
{
    int eff = d->digits;
    if (d->pic) for (const char *q = d->pic; *q; q++) if (*q == 'P') eff--;
    return eff;
}

/* Store v (scaled by vscale) into the item, aligning the scale by
 * truncation and truncating high-order digits to the picture (unless the
 * usage says the binary field's capacity is the limit).
 * opts: 1 = ROUNDED (nearest, ties away from zero -- the 85 rule),
 * 2 = report a size error instead of truncating.  Returns 1 on a size
 * error (nothing stored), else 0.
 * cob_put_num_x is a hookable thunk (build.sh, docs/dbt-hooks.md) in front
 * of this: the kernel's descriptors go to kern.h, the rest are here */
int cob_put_num_x_impl(void *vp, const cob_desc *d, long long v, int vscale, int opts)
{
    if (is_float(d)) { f_store(vp, d, (double)v / pow10d(vscale)); return 0; }
    if (is_sfloat(d)) { cob_wnum w; w_from_i64(&w, v, vscale); return sf_store(vp, d, &w) && (opts & 2); }
    if (cob_k_put_ok((const cob_kdesc *)d)) return cob_k_put_num(vp, (const cob_kdesc *)d, eff_digits(d), v, vscale, opts);
    if (d->digits > 18 || (d->usage == COB_U_BINARY && d->size > 8)) {
        if (is_wide(d)) { cob_wnum w; w_from_i64(&w, v, vscale); return cob_wput_x(vp, d, &w, opts); }
    }
    if (is_natnum(d)) {
        unsigned char b[NATNUM_MAX]; cob_desc nd;
        unsigned char *q = (unsigned char *)nat_narrow(vp, d, b, &nd);
        int r = cob_put_num_x(q, &nd, v, vscale, opts);
        nat_widen(vp, d, q, (int)nd.size);
        return r;
    }
    if (d->cat != COB_NUM_ED) return cob_k_put_num(vp, (const cob_kdesc *)d, eff_digits(d), v, vscale, opts);  /* any other usage, as before */

    return cob_put_edited(vp, d, v, vscale, opts, loc_word());     /* numeric-edited */
}

void cob_put_num(void *vp, const cob_desc *d, long long v, int vscale) { cob_put_num_x(vp, d, v, vscale, 0); }

/* ---- 31 digits (COBOL 2002; docs/wide.md, cobol ISSUES-117) -----------
 * An item of more than 18 digits (or a binary field wider than eight
 * bytes) is read and written through a cob_wnum, a 128-bit magnitude
 * with a sign and a scale; everything narrower keeps the 64-bit path. */
static int is_wide(const cob_desc *d)
{
    return (d->cat == COB_NUM || d->cat == COB_NUM_ED) && (d->digits > 18 || (d->usage == COB_U_BINARY && d->size > 8) || d->usage == COB_U_SFLOAT);
}

/* any numeric item's value as a double (a float's own, a decimal's to
 * the nearest) */
static double num_dbl(const void *p, const cob_desc *d)
{
    if (is_float(d)) return f_load(p, d);
    if (is_wide(d)) { cob_wnum w; cob_wget(p, d, &w); return w_to_dbl(&w); }
    return (double)cob_get_num(p, d) / pow10d(d->scale);
}
static int is_numcat(const cob_desc *d) { return d->cat == COB_NUM || d->cat == COB_NUM_ED; }

void cob_wget(const void *vp, const cob_desc *d, cob_wnum *w)
{
    if (is_natnum(d)) { unsigned char b[NATNUM_MAX]; cob_desc nd; cob_wget(nat_narrow(vp, d, b, &nd), &nd, w); return; }
    if (is_float(d)) { w_set_f(w, f_load(vp, d)); return; }
    if (is_sfloat(d)) { sf_load(vp, d, w); return; }
    const unsigned char *p = vp;
    char digs[80]; int n = 0, neg = 0;
    memset(w, 0, sizeof *w); w->scale = d->scale;
    if (d->cat == COB_NUM_ED) {
        unsigned char sw[256];
        if ((cob_dp_comma || cob_currency != '$' || cob_currency_len > 1) && d->size <= sizeof sw) {
            for (size_t i = 0; i < d->size; i++) {
                unsigned char c = p[i];
                if (cob_dp_comma) c = c == '.' ? ',' : c == ',' ? '.' : c;
                if (cob_currency_len <= 1 && cob_currency != '$' && c == (unsigned char)cob_currency) c = '$';
                sw[i] = c;
            }
            if (cob_currency_len > 1) cob_k_cs_shrink(sw, (int)d->size, cob_currency_str, cob_currency_len);
            p = sw;
        }
        if (strchr(d->pic, 'E')) {
            /* floating-point edited: the significand at the exponent's
             * scale, which may be negative (trailing zeros) or past 38 */
            int sc; n = cob_k_get_fpedited(p, d->pic, digs, &neg, &sc);
            while (sc < 0 && n < 76) { digs[n++] = '0'; sc++; }
            w->scale = sc;
            if (sc > 38) { memset(w, 0, sizeof *w); w->scale = 0; return; }   /* smaller than a wide number tells: zero */
        } else
        n = cob_deedit(d->pic, p, digs, &neg);
    } else switch (d->usage) {
    case COB_U_BINARY: {
        /* two's complement, up to sixteen bytes, little- or big-endian */
        unsigned sz = d->size < 16 ? d->size : 16, be = d->flags2 & COB_F2_BIGEND;
        for (unsigned i = 0; i < sz; i++) w->m[i / 4] |= (wl_t)p[be ? d->size - 1 - i : i] << (8 * (i % 4));
        if ((d->flags & COB_F_SIGNED) && (p[be ? d->size - sz : sz - 1] & 0x80)) {
            for (unsigned i = sz; i < 16; i++) w->m[i / 4] |= (wl_t)0xFF << (8 * (i % 4));
            for (int i = 0; i < WL; i++) w->m[i] = ~w->m[i];
            wl_t one[WL] = { 1, 0, 0, 0 };
            mp_add(w->m, one, WL);
            w->neg = 1;
        }
        return;
    }
    case COB_U_PACKED: {
        int bytes = (int)d->size;
        int nosign = d->flags2 & COB_F2_NOSIGN;         /* COMP-6: every nibble a digit */
        for (int i = 0; i < bytes; i++) {
            digs[n++] = (char)('0' + ((p[i] >> 4) % 10));
            if (i < bytes - 1 || nosign) digs[n++] = (char)('0' + ((p[i] & 15) % 10));
        }
        neg = !nosign && (p[bytes - 1] & 15) == 0xD;
        break;
    }
    default: {
        int sz = (int)d->size, i = 0, end = sz;
        if (d->flags & COB_F_SEPLEAD) { neg = p[0] == '-'; i = 1; }
        if (d->flags & COB_F_SEPTRAIL) { neg = p[sz - 1] == '-'; end = sz - 1; }
        for (; i < end; i++) {
            unsigned char ch = p[i];
            unsigned c = (unsigned)ch - '0';
            if (c > 9) {
                if (ch >= 'p' && ch <= 'y') { c = ch - 'p'; neg = 1; }
                else if (ch == ' ') c = 0;
                else c = (ch & 15) % 10;
            }
            digs[n++] = (char)('0' + c);
        }
        break;
    }
    }
    int k = n > 38 ? n - 38 : 0;                 /* the low 38 digits */
    w_from_digits(w->m, digs + k, n - k);
    w->neg = neg && !mp_is_zero(w->m, WL);
}

static int rmode_away(int mode, int cmp, int odd, int neg);
/* store w, as cob_put_num_x does: opts 1 ROUNDED, 2 report a size error
 * (1 returned, the item untouched) instead of truncating */
int cob_wput_x(void *vp, const cob_desc *d, const cob_wnum *win, int opts)
{
    if (is_float(d)) { f_store(vp, d, w_to_dbl(win)); return 0; }
    if (is_sfloat(d)) return sf_store(vp, d, win) && (opts & 2);
    if (win->isq && !win->isf && !is_natnum(d) && win->scale < d->scale - 60) {
        /* a floating value far past any receiver's digits */
        if (opts & 2) return 1;
        cob_wnum z; memset(&z, 0, sizeof z); z.scale = d->scale;
        return cob_wput_x(vp, d, &z, opts);
    }
    if (win->isf && !is_natnum(d)) {
        if (d->cat == COB_NUM_ED && d->pic && strchr(d->pic, 'E')) {
            /* a float into a floating-point numeric-edited item: its exact
             * decimal digits with their exponent, not cut to the picture's
             * fixed scale first (1.0E-30 went to zero that way; 2014 E.2
             * item 11's underflow is the edit's to find) */
            cob_wnum t;
            if (w_from_dbl_q(&t, win->f)) return (opts & 2) ? 1 : 0;      /* an infinity or a NaN: no digits */
            return cob_wput_x(vp, d, &t, opts);
        }
        /* a float into a decimal item: to its scale (truncated, or ROUNDED),
         * then as a wide value; past 38 digits a size error */
        cob_wnum t;
        if (w_from_dbl(&t, win->f, d->scale > 0 ? d->scale : 0, opts & 1)) {
            if (opts & 2) return 1;
            double y = fmod(fabs(win->f) * pow10d(d->scale > 0 ? d->scale : 0), 1e38);
            w_from_dbl(&t, win->f < 0 ? -y : y, 0, 0); t.scale = d->scale > 0 ? d->scale : 0;
        }
        return cob_wput_x(vp, d, &t, opts & ~1);
    }
    if (is_natnum(d)) {
        unsigned char b[NATNUM_MAX]; cob_desc nd;
        unsigned char *q = (unsigned char *)nat_narrow(vp, d, b, &nd);
        int r = cob_wput_x(q, &nd, win, opts);
        nat_widen(vp, d, q, (int)nd.size);
        return r;
    }
    unsigned char *p = vp;
    cob_wnum w = *win;
    int eff = d->digits;
    if (d->pic) for (const char *q = d->pic; *q; q++) if (*q == 'P') eff--;
    if (d->cat == COB_NUM_ED && d->pic && strchr(d->pic, 'E') && !w.isf) {
        /* a floating-point numeric-edited receiver takes the value's
         * leading 18 digits at their scale (the kernel's edit works in
         * 64 bits; the significand has at most that many positions) */
        char ds[48]; int nd = 0;
        { wl_t t[WL]; memcpy(t, w.m, sizeof t); char r[48]; int k = 0;
          while (!mp_is_zero(t, WL) && k < 40) r[k++] = (char)('0' + mp_div_small(t, WL, 10));
          while (k) ds[nd++] = r[--k]; }
        long long v = 0; int take = nd > 18 ? 18 : nd;
        for (int i = 0; i < take; i++) v = v * 10 + (ds[i] - '0');
        if (w.neg) v = -v;
        return cob_put_edited(vp, d, v, w.scale - (nd - take), opts, loc_word());
    }
    int m = w.scale - d->scale;
    if (m > 0) {
        int half, nz, mode = (opts >> 4) & 15;
        w_drop_digits(w.m, WL, m > 40 ? 40 : m, &half, &nz);
        if (mode && nz) {                           /* ROUNDED MODE (rmode_away) */
            if (mode == 5) return 1;
            if (rmode_away(mode, half, (int)(w.m[0] & 1), w.neg)) { wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(w.m, one, WL); }
        } else if ((opts & 1) && half >= 0) { wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(w.m, one, WL); }
    }
    /* the digits, the receiver's fraction aligned at the end */
    char D[96]; int L = 38;
    w_to_digits(w.m, D, 38);
    for (int k = m < 0 ? -m : 0; k > 0 && L < 90; k--) D[L++] = '0';
    int zero = 1; for (int i = 0; i < L; i++) if (D[i] != '0') { zero = 0; break; }
    int neg = w.neg && !zero;
    if (!(d->flags & COB_F_NOTRUNC) && eff < L) {
        for (int i = 0; i < L - eff; i++) if (D[i] != '0') { if (opts & 2) return 1; break; }
        for (int i = 0; i < L - eff; i++) D[i] = '0';
    }
    /* a value the receiver's digits cut to zero keeps its sign, as the
     * 64-bit store keeps it (cob_k_put_scale): the sign of the numeric
     * value is represented in a signed receiver (2023 14.9.25.4, MOVE) --
     * and the two stores give one statement one answer (ISSUES-122) */
    zero = 1; for (int i = 0; i < L; i++) if (D[i] != '0') { zero = 0; break; }
    if ((d->flags & COB_F_NOTRUNC) && (opts & 2)) {
        /* a native binary (BINARY-DOUBLE): the field's capacity is the limit */
        for (int i = 0; i < L - 38; i++) if (D[i] != '0') return 1;
        wl_t mag[WL]; w_from_digits(mag, D + L - 38, 38);
        int sgn = (d->flags & COB_F_SIGNED) != 0, bits = (int)d->size * 8 - sgn, nb = mp_bits(mag, WL);
        if (!sgn && neg && !zero) return 1;
        if (nb > bits) {
            int exact = nb == bits + 1 && neg && sgn;   /* -2^bits fits */
            for (int i = 0; exact && i < bits; i++) if ((mag[i / 32] >> (i % 32)) & 1) exact = 0;
            if (!exact) return 1;
        }
    }
    if (!(d->flags & COB_F_SIGNED)) neg = 0;
    if (d->cat == COB_NUM_ED) {
        int nd = eff > 0 ? eff : 0;
        int w2 = cob_edit_apply(d->pic, D + L - nd, neg, d->flags & COB_F_BLANKZ, (char *)p);
        if (cob_dp_comma) for (int i = 0; i < w2; i++) { if (p[i] == '.') p[i] = ','; else if (p[i] == ',') p[i] = '.'; }
        if (cob_currency_len > 1) cob_k_cs_expand(p, w2, cob_currency_str, cob_currency_len);
        else if (cob_currency != '$') for (int i = 0; i < w2; i++) if (p[i] == '$') p[i] = (unsigned char)cob_currency;
        return 0;
    }
    switch (d->usage) {
    case COB_U_BINARY: {
        wl_t mag[WL];
        w_from_digits(mag, D + L - 38, 38);
        if (neg) { for (int i = 0; i < WL; i++) mag[i] = ~mag[i]; wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(mag, one, WL); }
        unsigned be = d->flags2 & COB_F2_BIGEND;
        for (unsigned i = 0; i < d->size; i++) p[be ? d->size - 1 - i : i] = i < 16 ? (unsigned char)(mag[i / 4] >> (8 * (i % 4))) : (neg ? 0xFF : 0);
        break;
    }
    case COB_U_PACKED: {
        int digits = d->digits, bytes = (int)d->size;
        const char *dg = D + L - digits;
        int k = digits - 1, j = bytes - 1;
        if (d->flags2 & COB_F2_NOSIGN) {                /* COMP-6: the digits right-aligned, no sign */
            for (; j >= 0; j--, k -= 2) {
                unsigned lo = k >= 0 ? (unsigned)(dg[k] - '0') : 0u, hi = k > 0 ? (unsigned)(dg[k - 1] - '0') : 0u;
                p[j] = (unsigned char)((hi << 4) | lo);
            }
            break;
        }
        p[j] = (unsigned char)(((dg[k] - '0') << 4) | ((d->flags & COB_F_SIGNED) ? (neg ? 0xD : 0xC) : 0xF));
        for (k--; k >= 0; k -= 2) {
            unsigned hi = k > 0 ? (unsigned)(dg[k - 1] - '0') : 0u;
            p[--j] = (unsigned char)((hi << 4) | (unsigned)(dg[k] - '0'));
        }
        while (j > 0) p[--j] = 0;
        break;
    }
    default: {
        int n = (int)d->size, i = n - 1, start = 0;
        if ((d->flags & COB_F_BLANKZ) && zero) { memset(p, ' ', (size_t)n); break; }
        if (d->flags & COB_F_SEPLEAD) { p[0] = neg ? '-' : '+'; start = 1; }
        if (d->flags & COB_F_SEPTRAIL) { p[n - 1] = neg ? '-' : '+'; i = n - 2; }
        int wdt = i - start + 1;
        memcpy(p + start, D + L - wdt, (size_t)wdt);
        if (neg && !(d->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL))) {
            int k = (d->flags & COB_F_LEAD) ? 0 : n - 1;
            p[k] = (unsigned char)(p[k] - '0' + 'p');
        }
        break;
    }
    }
    return 0;
}

/* compare two wide values, -1 0 1 */
static int w_cmp_val(const cob_wnum *a0, const cob_wnum *b0)
{
    cob_wnum qa, qb; const cob_wnum *a = a0, *b = b0;
    if ((a->isq || b->isq) && (a->isf || b->isf)) {
        /* a double beside a software float: both as floating decimals */
        if (a->isf) { if (w_from_dbl_q(&qa, a->f)) qa = *a; a = &qa; }
        if (b->isf) { if (w_from_dbl_q(&qb, b->f)) qb = *b; b = &qb; }
    }
    if (a->isf || b->isf) { double x = w_to_dbl(a), y = w_to_dbl(b); return x < y ? -1 : x > y ? 1 : 0; }
    int za = mp_is_zero(a->m, WL), zb = mp_is_zero(b->m, WL);
    int na = a->neg && !za, nb = b->neg && !zb;
    if (na != nb) return na ? -1 : 1;
    if (za != zb) return za ? (nb ? 1 : -1) : (na ? -1 : 1);
    if (a->isq || b->isq) {
        /* floating values: by their decimal exponents first, which keeps the
         * alignment below within the limbs */
        int ea = w_ndigits(a->m) - a->scale, eb = w_ndigits(b->m) - b->scale;
        if (ea != eb) return (ea < eb) != na ? -1 : 1;
    }
    wl_t x[2 * WL] = { 0 }, y[2 * WL] = { 0 };
    memcpy(x, a->m, sizeof a->m); memcpy(y, b->m, sizeof b->m);
    int s = a->scale > b->scale ? a->scale : b->scale;
    for (int k = s - a->scale; k > 0; k--) mp_mul_small(x, 2 * WL, 10, 0);
    for (int k = s - b->scale; k > 0; k--) mp_mul_small(y, 2 * WL, 10, 0);
    int c = mp_cmp(x, y, 2 * WL);
    return na ? -c : c;
}

/* ---- DISPLAY ---------------------------------------------------------- */

void cob_display(const char *p, int n) { out_bytes(p, n); }
void cob_display_nl(void) { out_char('\n'); out_flush(); }
void cob_display_flush(void) { out_flush(); }
/* DISPLAY ... UPON SYSERR: what is pending goes where it was meant, then
 * the line goes to stderr (on = 1), and back to stdout after it (on = 0) */
void cob_display_err(int on) { out_flush(); out_err = on; }

/* Emit a magnitude as `digits` characters with a point where the scale
 * says, a leading sign when the picture is signed.  GnuCOBOL's convention;
 * the standard leaves DISPLAY of numeric items to the implementor. */
static void emit_scaled(unsigned long long mag, int neg, int digits, int scale, int is_signed)
{
    char d[40];
    if (is_signed) out_char(neg ? '-' : '+');
    mag_to_digits(mag, d, digits);
    for (int i = 0; i < digits; i++) {
        if (scale > 0 && i == digits - scale) out_char(cob_dp_comma ? ',' : '.');   /* as a DISPLAY item's (DECIMAL-POINT IS COMMA) */
        out_char(d[i]);
    }
}

static int nat_to_utf8(const unsigned char *p, int nch, char *out);
void cob_display_field(const void *vp, const cob_desc *d)
{
    if (is_natnum(d)) { unsigned char b[NATNUM_MAX]; cob_desc nd; cob_display_field(nat_narrow(vp, d, b, &nd), &nd); return; }
    const unsigned char *p = vp;
    if (d->cat == COB_NATIONAL) {                   /* national: written as UTF-8 */
        int n = (int)d->size / 2;
        char stk[768], *t = n * 4 <= (int)sizeof stk ? stk : malloc((size_t)n * 4);
        if (!t) cob_fatal("out of memory");
        out_bytes(t, nat_to_utf8(p, n, t));
        if (t != stk) free(t);
        return;
    }
    if (d->cat != COB_NUM) { out_bytes((const char *)p, (int)d->size); return; }
    if (is_float(d)) { char t[40]; out_bytes(t, fmt_float(f_load(p, d), d->size == 4 ? 8 : 18, t)); return; }
    if (is_sfloat(d)) {
        cob_wnum w; char t[64]; int neg, sp = fp_special_of(p, d, &neg);
        if (sp) { const char *v = sp == 1 ? (neg ? "-Inf" : "Inf") : (neg ? "-NaN" : "NaN"); out_bytes(v, (int)strlen(v)); return; }
        sf_load(p, d, &w); out_bytes(t, sf_fmt(&w, t)); return;
    }
    if (d->flags & COB_F_INTFN) {                   /* an integer function's value, no leading zeros */
        char t[24]; long long v = cob_get_num(p, d);
        out_bytes(t, snprintf(t, sizeof t, "%lld", v));
        return;
    }
    if (d->usage == COB_U_DISPLAY && !(d->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL)) && d->digits == d->size) {
        /* the digits as stored (a picture with P positions takes the general path) */
        int n = (int)d->size;
        int sk = (d->flags & COB_F_LEAD) ? 0 : n - 1;
        unsigned char last = p[sk];
        int neg = (d->flags & COB_F_SIGNED) && last >= 'p' && last <= 'y';
        /* zero is one value whatever sign it is stored with (2023 8.8.4.2.2):
         * shown "+", as the packed and binary items' values are -- a negative
         * value cut to zero by its receiver keeps its sign in storage */
        int nz = 0;
        for (int i = 0; i < n && !nz; i++) { unsigned char c = p[i]; if (i == sk && neg) c = (unsigned char)(c - 'p' + '0'); nz = c != '0'; }
        if (d->flags & COB_F_SIGNED) out_char(neg && nz ? '-' : '+');
        for (int i = 0; i < n; i++) {
            if (d->scale > 0 && i == n - d->scale) out_char(cob_dp_comma ? ',' : '.');
            unsigned char c = p[i];
            if (i == sk && neg) c = (unsigned char)(last - 'p' + '0');
            out_char((char)c);
        }
        return;
    }
    if (is_wide(d)) {                           /* 31 digits: as emit_scaled, from the wide value */
        cob_wnum w; cob_wget(p, d, &w);
        char D[40]; w_to_digits(w.m, D, 38);
        int digits = d->digits, scale = d->scale;
        if (d->flags & COB_F_SIGNED) out_char(w.neg ? '-' : '+');
        for (int i = 38 - digits; i < 38; i++) {
            if (scale > 0 && i == 38 - scale) out_char(cob_dp_comma ? ',' : '.');
            out_char(D[i]);
        }
        return;
    }
    long long v = cob_get_num(p, d);
    int neg = v < 0;
    unsigned long long mag = neg ? (unsigned long long)(-v) : (unsigned long long)v;
    int digits = (d->flags & COB_F_NOTRUNC) ? capacity_digits(d->size) : d->digits;
    int scale = d->scale;
    if (scale < 0) { mag *= (unsigned long long)pow10tab[-scale]; scale = 0; }   /* trailing P: the value, its low zeros shown */
    emit_scaled(mag, neg, digits, scale, d->flags & COB_F_SIGNED);
}

/* ---- MOVE ------------------------------------------------------------- */

/* alphanumeric to alphanumeric: left-justified, space-filled, truncated
 * on the right (JUSTIFIED RIGHT: the mirror image) */
void cob_move_alnum(const void *src, int slen, void *dst, int dlen, int just)
{
    int n = slen < dlen ? slen : dlen;
    if (!just) {
        memmove(dst, src, n);
        if (n < dlen) memset((char *)dst + n, ' ', dlen - n);
    } else {
        memmove((char *)dst + dlen - n, (const char *)src + slen - n, n);
        if (n < dlen) memset(dst, ' ', dlen - n);
    }
}

/* The digits of a numeric item as unsigned DISPLAY characters (what a
 * numeric-to-alphanumeric MOVE sends: no sign, no point). */
/* the digits of a numeric item as an alphanumeric sending item: the
 * sign and the point unrepresented, and P positions as zeros (NC114M:
 * S9P(17) holding 1 reads 100000000000000000) */
static int num_to_digits(const void *p, const cob_desc *d, char *out)
{
    if (is_natnum(d)) { unsigned char b[NATNUM_MAX]; cob_desc nd; return num_to_digits(nat_narrow(p, d, b, &nd), &nd, out); }
    int np = 0, lead_p = 0;
    if (d->pic) { for (const char *q = d->pic; *q; q++) if (*q == 'P') np++; lead_p = np && (d->pic[0] == 'P' || (d->pic[0] == 'S' && d->pic[1] == 'P')); }
    if (d->usage == COB_U_DISPLAY && !(d->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL)) && !np) {
        memcpy(out, p, d->size);
        int sk = (d->flags & COB_F_LEAD) ? 0 : (int)d->size - 1;
        unsigned char last = (unsigned char)out[sk];
        if (last >= 'p' && last <= 'y') out[sk] = (char)(last - 'p' + '0');
        return (int)d->size;
    }
    if (is_wide(d)) {                           /* 31 digits: the P positions as zeros too */
        cob_wnum w; cob_wget(p, d, &w);
        char D[40]; w_to_digits(w.m, D, 38);
        int stored = d->digits - np, o = 0;
        if (lead_p) for (int i = 0; i < np; i++) out[o++] = '0';
        memcpy(out + o, D + 38 - stored, (size_t)stored); o += stored;
        if (!lead_p) for (int i = 0; i < np; i++) out[o++] = '0';
        return o;
    }
    long long v = cob_get_num(p, d);
    unsigned long long mag = v < 0 ? (unsigned long long)(-v) : (unsigned long long)v;
    int digits = (d->flags & COB_F_NOTRUNC) ? capacity_digits(d->size) : d->digits;
    if (np) {
        /* the stored digits, the P positions zeros on the side they sit */
        int stored = digits - np, o = 0;
        if (lead_p) for (int i = 0; i < np; i++) out[o++] = '0';
        mag_to_digits(mag, out + o, stored);
        o += stored;
        if (!lead_p) for (int i = 0; i < np; i++) out[o++] = '0';
        return o;
    }
    mag_to_digits(mag, out, digits);
    return digits;
}

/* alphanumeric-edited receiver: source characters into the A/X/9
 * positions, insertion characters where the picture puts them */
static void move_alnum_edited(const char *s, int n, char *dst, const cob_desc *dd)
{
    int si = 0, o = 0;
    for (const char *p = dd->pic; *p; p++) {
        switch (*p) {
        case 'B': dst[o++] = ' '; break;
        case '0': dst[o++] = '0'; break;
        case '/': dst[o++] = '/'; break;
        default:  dst[o++] = si < n ? s[si++] : ' '; break;
        }
    }
}

/* ---- national data (COBOL 2002; cobol ISSUES-62) ------------------------ */

/* A national character is one UTF-16 code unit, stored big-endian, two
 * bytes (2023 8.5.1.4: no special handling of surrogates or composites).
 * Alphanumeric text is UTF-8 when it becomes national (the user's ruling:
 * this side of the fence).  A byte that begins no valid sequence is
 * malformed data, not another encoding: it becomes U+FFFD and nat_bad is
 * set, for EC-DATA-CONVERSION (14.9.25 general rule 6).
 * Returns the code units written (at most max). */
static int nat_bad;
static unsigned nat_repl = 0xFFFD;              /* what a malformed byte becomes: NATIONAL-OF's argument-2 */
int cob_nat_conv_bad(void) { int b = nat_bad; nat_bad = 0; return b; }
static int utf8_to_nat(const unsigned char *p, int n, unsigned short *out, int max)
{
    int k = 0, i = 0;
    while (i < n && k < max) {
        uint32_t cp;
        int len = (int)s32u_decode(p + i, (size_t)(n - i), &cp);
        if (cp == S32U_REPL && !(len == 3 && p[i] == 0xEF && p[i + 1] == 0xBF && p[i + 2] == 0xBD)) {
            nat_bad = 1; cp = nat_repl;             /* malformed, not a U+FFFD in the text */
        }
        i += len;
        unsigned char u[4];
        int nu = s32u_u16_put(u, cp);               /* a pair past U+FFFF: two character positions */
        for (int q = 0; q < nu && k < max; q++) out[k++] = (unsigned short)(u[2 * q] << 8 | u[2 * q + 1]);
    }
    return k;
}

static unsigned nat_at(const unsigned char *p, int i) { return s32u_u16_at(p, (size_t)i); }
static void nat_put(unsigned char *p, int i, unsigned u) { p[2 * i] = (unsigned char)(u >> 8); p[2 * i + 1] = (unsigned char)u; }

/* national characters to UTF-8; an unpaired surrogate becomes U+FFFD */
static int nat_to_utf8(const unsigned char *p, int nch, char *out)
{
    int k = 0;
    for (int i = 0; i < nch; ) {
        uint32_t cp;
        i += (int)s32u_u16_get(p, (size_t)nch, (size_t)i, &cp);
        k += s32u_encode(cp, (unsigned char *)out + k);
    }
    return k;
}

/* National text in character cells -- a report line's columns, a screen
 * field's (cobol ISSUES-92) -- goes by display width, as the terminal
 * shows it: the text is split into grapheme clusters (UAX #29) and each
 * takes its display width in columns, the model of common/s32utf.h that
 * the term service shares (cobol ISSUES-94).  A cluster is a span of the
 * item's own code units, so laying text out never loses any of it.  An
 * item of n national character positions is a field of n columns: its
 * text is laid out left to right, a cluster that would cross the field's
 * last column dropped with all after it, the rest spaces.  Positions,
 * lengths and reference modification still count code units; only the
 * laying out is visual. */
typedef struct { int off, units; unsigned char w, lone, space; } cob_cluster;

static int nat_clusters(const unsigned char *p, int nch, cob_cluster *out, int max)
{
    s32u_clu st; memset(&st, 0, sizeof st);
    int n = 0;
    for (int i = 0; i < nch; ) {
        uint32_t cp;
        int u = (int)s32u_u16_get(p, (size_t)nch, (size_t)i, &cp);
        if (s32u_clu_step(&st, cp)) {
            if (n == max) break;
            out[n].off = i; out[n].units = 0; out[n].space = cp == ' ';
            n++;
        } else out[n - 1].space = 0;
        cob_cluster *c = &out[n - 1];
        c->units += u;
        c->lone = (unsigned char)s32u_clu_lone(&st);
        c->w = (unsigned char)(c->lone ? 1 : s32u_clu_width(&st));   /* a mark alone: over a space */
        i += u;
    }
    return n;
}

/* a cluster of the text at p, as UTF-8 (after a space when it is a mark
 * with nothing to sit on); out holds 1 + 4 * units bytes */
static int cluster_utf8(const unsigned char *p, const cob_cluster *c, char *out)
{
    int k = 0;
    if (c->lone) out[k++] = ' ';
    return k + nat_to_utf8(p + 2 * c->off, c->units, out + k);
}

/* an operand as national characters: a national one as it is, an
 * alphanumeric one decoded from UTF-8, a numeric one as its digits */
/* the national characters an operand can become: a national one's own, a
 * numeric one's digits and sign (num_to_digits' 40 -- a binary or packed
 * item has more digits than bytes, cobol ISSUES-94 N1), an alphanumeric
 * one's bytes and room for a pair */
static int nat_cap(const cob_desc *d)
{
    return d->cat == COB_NATIONAL ? (int)d->size / 2 : d->cat == COB_NUM ? 40 : (int)d->size + 2;
}

static int as_national(const void *p, const cob_desc *d, unsigned short *out, int max)
{
    if (d->cat == COB_NATIONAL) {
        int n = (int)d->size / 2; if (n > max) n = max;
        for (int i = 0; i < n; i++) out[i] = (unsigned short)nat_at(p, i);
        return n;
    }
    if (d->cat == COB_NUM) {
        char t[40]; int n = num_to_digits(p, d, t);
        return utf8_to_nat((const unsigned char *)t, n, out, max);
    }
    return utf8_to_nat(p, (int)d->size, out, max);
}

/* a national receiver: aligned left, or right under JUSTIFIED, padded
 * with national spaces (14.6.8) */
static void move_to_national(const void *src, const cob_desc *sd, void *dst, const cob_desc *dd)
{
    int dn = (int)dd->size / 2;
    nat_bad = 0;                                    /* this MOVE's own conversion, for EC-DATA-CONVERSION */
    unsigned short stk[256], *u = stk;
    int max = nat_cap(sd);
    if (max > 256) { u = malloc((size_t)max * sizeof *u); if (!u) cob_fatal("out of memory"); }
    int n = as_national(src, sd, u, max);
    unsigned char *q = dst;
    if (dd->pic && dd->pic[0]) {
        /* national-edited (cobol ISSUES-73): the characters fill the N
         * positions left to right; B, 0 and / are inserted (13.18.40) */
        int si = 0, o = 0;
        for (const char *p = dd->pic; *p && o < dn; p++, o++)
            nat_put(q, o, *p == 'B' ? 0x20 : *p == '0' ? 0x30 : *p == '/' ? 0x2F : si < n ? u[si++] : 0x20);
        if (u != stk) free(u);
        return;
    }
    int just = dd->flags & COB_F_JUST, off = 0;
    if (just && n < dn) off = dn - n;
    const unsigned short *from = u;
    if (n > dn) { if (just) from = u + (n - dn); n = dn; }
    for (int i = 0; i < dn; i++) nat_put(q, i, (i >= off && i - off < n) ? from[i - off] : 0x20);
    if (u != stk) free(u);
}

void cob_fill_nat(void *dst, int nch, int unit)
{
    unsigned char *q = dst;
    for (int i = 0; i < nch; i++) nat_put(q, i, (unsigned)unit);
}

void cob_move(const void *src, const cob_desc *sd, void *dst, const cob_desc *dd)
{
    if (is_natnum(sd)) { unsigned char b[NATNUM_MAX]; cob_desc nd; cob_move(nat_narrow(src, sd, b, &nd), &nd, dst, dd); return; }
    if (is_natnum(dd)) {
        /* written as DISPLAY, then widened: editing included */
        unsigned char b[NATNUM_MAX]; cob_desc nd;
        unsigned char *q = (unsigned char *)nat_narrow(dst, dd, b, &nd);
        cob_move(src, sd, q, &nd);
        nat_widen(dst, dd, q, (int)nd.size);
        return;
    }
    if ((is_sfloat(sd) || is_sfloat(dd)) && is_numcat(sd) && is_numcat(dd)) {
        /* a standard software float either side: through the wide value */
        cob_wnum w; cob_wget(src, sd, &w); cob_wput_x(dst, dd, &w, 0);
        return;
    }
    if ((is_float(sd) || is_float(dd)) && is_numcat(sd) && is_numcat(dd)) {
        /* a float either side: converted (docs/usage.md); into a decimal
         * item truncated to its scale, as any MOVE */
        if (is_float(dd)) f_store(dst, dd, num_dbl(src, sd));
        else { cob_wnum w; w_set_f(&w, f_load(src, sd)); cob_wput_x(dst, dd, &w, 0); }
        return;
    }
    if (dd->cat == COB_BOOLEAN) {
        /* a boolean receiver (cobol ISSUES-76): the sender's characters,
         * aligned left, zero-filled or truncated on the right (2023
         * 14.6.8.6); a national sender's characters narrowed, one that is
         * not 0 or 1 left for a BOOLEAN class test to find */
        const unsigned char *sp = src; unsigned char *q = dst;
        int n = (int)dd->size, m = sd->cat == COB_NATIONAL ? (int)sd->size / 2 : (int)sd->size;
        for (int i = 0; i < n; i++) {
            if (i >= m) q[i] = '0';
            else if (sd->cat == COB_NATIONAL) q[i] = sp[2 * i] ? 0x7F : sp[2 * i + 1];
            else q[i] = sp[i];
        }
        return;
    }
    if (sd->cat == COB_NATIONAL && (dd->cat == COB_NUM || dd->cat == COB_NUM_ED)) {
        /* national text to a numeric receiver (an UNSTRING part): as its
         * UTF-8, which for digits and signs is their ASCII */
        int n = (int)sd->size / 2;
        char *t = malloc((size_t)n * 4 + 1); if (!t) cob_fatal("out of memory");
        cob_desc ad; memset(&ad, 0, sizeof ad); ad.cat = COB_ALNUM; ad.usage = COB_U_DISPLAY;
        ad.size = (unsigned)nat_to_utf8(src, n, t);
        cob_move(t, &ad, dst, dd);
        free(t);
        return;
    }
    if (dd->cat == COB_NATIONAL) { move_to_national(src, sd, dst, dd); return; }
    char tmp[40];
    int dnum = dd->cat == COB_NUM || dd->cat == COB_NUM_ED;
    int snum = sd->cat == COB_NUM || sd->cat == COB_NUM_ED;

    if (dd->cat == COB_ALNUM_ED) {
        if (!snum || sd->cat == COB_NUM_ED) move_alnum_edited(src, (int)sd->size, dst, dd);
        else { int n = num_to_digits(src, sd, tmp); move_alnum_edited(tmp, n, dst, dd); }
        return;
    }

    if (!dnum) {
        /* a numeric-edited sending item is alphanumeric to an alphanumeric
         * receiver: its edited characters as they are (NC124A's ZZZPP to X(5));
         * only a numeric one sends its digits */
        if (sd->cat != COB_NUM || dd->cat == COB_GROUP) {
            cob_move_alnum(src, (int)sd->size, dst, (int)dd->size, dd->flags & COB_F_JUST);
        } else {
            int n = num_to_digits(src, sd, tmp);
            cob_move_alnum(tmp, n, dst, (int)dd->size, dd->flags & COB_F_JUST);
        }
        return;
    }

    if (snum) {
        if (is_wide(sd) || is_wide(dd)) { cob_wnum w; cob_wget(src, sd, &w); cob_wput_x(dst, dd, &w, 0); return; }
        cob_put_num(dst, dd, cob_get_num(src, sd), sd->scale);
        return;
    }
    if (is_wide(dd)) {
        /* alphanumeric to a 31-digit receiver: the text read as below --
         * blanks, a sign, digits, a point and fraction -- the rightmost
         * integer digits kept (docs/wide.md) */
        const char *s = src; unsigned n = sd->size, i = 0;
        while (i < n && s[i] == ' ') i++;
        int neg = 0;
        if (i < n && (s[i] == '+' || s[i] == '-')) { neg = s[i] == '-'; i++; }
        char ig[128], fg[64]; int ni = 0, nf = 0, pt = 0;
        for (; i < n; i++) {
            char c = s[i];
            if (c >= '0' && c <= '9') { if (pt) { if (nf < 38) fg[nf++] = c; } else if (ni < 128) ig[ni++] = c; }
            else if (c == (cob_dp_comma ? ',' : '.') && !pt) pt = 1;
            else break;
        }
        char all[80]; int na = 0, keep = ni > 38 - nf ? 38 - nf : ni;
        memcpy(all, ig + ni - keep, (size_t)keep); na = keep;
        memcpy(all + na, fg, (size_t)nf); na += nf;
        cob_wnum w; memset(&w, 0, sizeof w);
        w_from_digits(w.m, all, na); w.scale = nf; w.neg = neg && !mp_is_zero(w.m, WL);
        cob_wput_x(dst, dd, &w, 0);
        return;
    }

    /* alphanumeric (or group) to numeric: not a standard-conforming MOVE.
     * GnuCOBOL (measured) reads the text as a decimal number -- blanks
     * skipped, an optional sign, digits, an optional point and fraction,
     * anything else ending it, no digits at all meaning zero -- and stores
     * it with the receiver's scale and digits.  usescreen's typed amount
     * relies on exactly this. */
    const char *s = src;
    unsigned n = sd->size, i = 0;
    while (i < n && s[i] == ' ') i++;
    int neg = 0;
    if (i < n && (s[i] == '+' || s[i] == '-')) { neg = (s[i] == '-'); i++; }
    long long v = 0; int scale = 0, seen_point = 0, digits = 0;
    /* a run of digits longer than the receiver's integer positions: the
     * rightmost are the ones that survive (an unsigned integer moved to a
     * numeric item, X3.23 6.18.2; NC105A moves 28 digits into 9(10)) */
    unsigned run_end = i; while (run_end < n && s[run_end] >= '0' && s[run_end] <= '9') run_end++;
    if (run_end - i > 18 && (run_end == n || s[run_end] != '.')) i = run_end - 18;
    for (; i < n; i++) {
        char c = s[i];
        if (c >= '0' && c <= '9') { if (digits < 18) { v = v * 10 + (c - '0'); digits++; if (seen_point) scale++; } }
        else if (c == '.' && !seen_point) seen_point = 1;
        else break;
    }
    cob_put_num(dst, dd, neg ? -v : v, scale);
}

void cob_fill(void *dst, int n, int c) { memset(dst, c, n); }

void cob_fill_all(void *dst, int n, const char *lit, int len)
{
    char *d = dst;
    for (int i = 0; i < n; i++) d[i] = lit[i % len];
}

/* ---- comparison ------------------------------------------------------- */

/* PROGRAM COLLATING SEQUENCE: the rank of each character, or native order */
static const unsigned char *cob_collating;
const unsigned char *cob_set_collating(const unsigned char *t) { const unsigned char *old = cob_collating; cob_collating = t; return old; }

/* The program registry: every unit registers its PROGRAM-ID and entry
 * from .init_array before main; CALL identifier looks the name up. */
static struct { const char *name; void *fn; void (*cancel)(void); const int *act; int nested; } cob_progs[256];
static int cob_nprogs;
void cob_register(const char *name, void *fn, void (*cancel)(void))
{
    if (cob_nprogs == 256) cob_fatal("more than 256 programs in one executable");
    cob_progs[cob_nprogs].name = name; cob_progs[cob_nprogs].fn = fn; cob_progs[cob_nprogs].cancel = cancel; cob_nprogs++;
}
/* a contained program: found by name only from where its name is in
 * scope (2023 8.4.6.3) -- the caller's table of the contained programs it
 * may name, their entries, ends in 0 */
void cob_register_nested(const char *name, void *fn, void (*cancel)(void))
{
    cob_register(name, fn, cancel);
    cob_progs[cob_nprogs - 1].nested = 1;
}
static int prog_index_v(const unsigned char *p, int len, void *const *vis)
{
    while (len > 0 && (p[len - 1] == ' ' || p[len - 1] == 0)) len--;
    for (int i = 0; i < cob_nprogs; i++) {
        const char *n = cob_progs[i].name; int k = 0;
        while (k < len && n[k] && tolower((unsigned char)n[k]) == tolower(p[k])) k++;
        if (!(k == len && !n[k])) continue;
        if (!cob_progs[i].nested) return i;
        for (int v = 0; vis && vis[v]; v++) if (vis[v] == cob_progs[i].fn) return i;
    }
    return -1;
}
/* CANCEL: the program back to its initial state -- WORKING-STORAGE,
 * its files closed, its contained programs likewise (the compiled cancel
 * routine); a name that is not a program here is ignored (2023 14.9.5.4
 * rule 7).  1 when the program is active (-std=2002 keeps the count): it
 * is not canceled (rule 5; EC-PROGRAM-CANCEL-ACTIVE when checked) */
int cob_cancel_v(const unsigned char *p, int len, void *const *vis)
{
    int i = prog_index_v(p, len, vis);
    if (i < 0 || !cob_progs[i].cancel) return 0;
    if (cob_progs[i].act && cob_progs[i].act[0] > 0) return 1;
    cob_progs[i].cancel();
    return 0;
}
/* a canceled program's file: the implicit CLOSE without options, when it
 * is open (14.9.5.4 rule 9) */
int cob_cancel(const unsigned char *p, int len) { return cob_cancel_v(p, len, 0); }
void cob_cancel_close(cob_file *f) { if (f->open_mode) (void)cob_close(f); }
/* STOP RUN WITH STATUS alphanumeric: the text to the operating system --
 * here, standard error -- then the exit (14.9.42.4 rules 2-5) */
void cob_stop_text(const char *p, int n, int error)
{
    fwrite(p, 1, (size_t)n, stderr); fputc('\n', stderr);
    cob_stop_run(error ? 1 : 0);
}
/* -std=2002: a program's activation descriptor (active count, RECURSIVE),
 * so a CALL can tell before calling that it would re-enter an active
 * program that is not recursive (EC-PROGRAM-RECURSIVE-CALL; cobol ISSUES-60) */
void cob_register_act(const char *name, const int *act)
{
    for (int i = 0; i < cob_nprogs; i++) if (cob_progs[i].name == name) { cob_progs[i].act = act; return; }
}
int cob_program_busy_v(const unsigned char *p, int len, void *const *vis)
{
    int i = prog_index_v(p, len, vis);
    return i >= 0 && cob_progs[i].act && cob_progs[i].act[0] > 0 && !cob_progs[i].act[1];
}

int cob_program_busy(const unsigned char *p, int len) { return cob_program_busy_v(p, len, 0); }
void *cob_resolve_v(const unsigned char *p, int len, int must, void *const *vis)
{
    int i = prog_index_v(p, len, vis);
    if (i >= 0) return cob_progs[i].fn;
    while (len > 0 && (p[len - 1] == ' ' || p[len - 1] == 0)) len--;
    if (must) {
        char msg[200]; snprintf(msg, sizeof msg, "CALL: the program '%.*s' is not in this executable", len > 120 ? 120 : len, (const char *)p);
        cob_fatal(msg);
    }
    return 0;
}
void *cob_resolve(const unsigned char *p, int len, int must) { return cob_resolve_v(p, len, must, 0); }
/* CALL through a program-pointer holding NULL, with no ON EXCEPTION and
 * EC-PROGRAM-PTR-NULL not checked: the run stops (2023 14.9.4.4 rule 3h) */
void cob_call_null_ptr(const char *item)
{
    char msg[200]; snprintf(msg, sizeof msg, "CALL %s: the program-pointer is NULL", item);
    cob_fatal(msg);
}
/* The function registry (2023 8.4.3.12 ADDRESS OF FUNCTION identifier):
 * every function in the executable joins at start-up under its
 * externalized name, as a program does the program registry; a name not
 * there is NULL, EC-FUNCTION-NOT-FOUND when checked (rule 4).  A function
 * is invoked by its prototype's name otherwise, linked by name. */
static struct { const char *name; void *fn; } cob_fns[128]; static int cob_nfns;
void cob_register_fn(const char *name, void *fn)
{
    if (cob_nfns == 128) cob_fatal("more than 128 functions in one executable");
    cob_fns[cob_nfns].name = name; cob_fns[cob_nfns].fn = fn; cob_nfns++;
}
void *cob_resolve_fn(const unsigned char *p, int len)
{
    while (len > 0 && (p[len - 1] == ' ' || p[len - 1] == 0)) len--;
    for (int i = 0; i < cob_nfns; i++) {
        const char *n = cob_fns[i].name; int k = 0;
        while (k < len && n[k] && tolower((unsigned char)n[k]) == tolower(p[k])) k++;
        if (k == len && !n[k]) return cob_fns[i].fn;
    }
    return 0;
}
/* a function invoked through a function-pointer holding NULL, with
 * EC-FUNCTION-PTR-NULL not checked: the run stops (2023 8.4.3.2.4 rule 6c, 6f) */
void cob_fn_null_ptr(const char *item)
{
    char msg[200]; snprintf(msg, sizeof msg, "FUNCTION %s: the function-pointer is NULL", item);
    cob_fatal(msg);
}

/* EXTERNAL: storage shared by name between the programs of one executable.
 * A record's block is made on first request (zeroed, as GnuCOBOL's); an
 * EXTERNAL file has one connector, the image of the first program to enter
 * with it, whose record area is that program's shared record block.  Each
 * program entering sets the connector's FILE STATUS item to its own and
 * puts the previous one back on exit, so the statement's own program's
 * status is the one written. */
static struct { const char *name; void *p; unsigned size; const char *sig; } cob_exts[128]; static int cob_nexts;
void *cob_external(const char *name, unsigned size)
{
    for (int i = 0; i < cob_nexts; i++)
        if (!strcmp(cob_exts[i].name, name)) {
            if (size > cob_exts[i].size) {
                void *q = calloc(size, 1);
                if (!q) cob_fatal("out of memory for an EXTERNAL item");
                memcpy(q, cob_exts[i].p, cob_exts[i].size);
                cob_exts[i].p = q; cob_exts[i].size = size;
            }
            return cob_exts[i].p;
        }
    if (cob_nexts == 128) cob_fatal("more than 128 EXTERNAL items");
    cob_exts[cob_nexts].name = name; cob_exts[cob_nexts].p = calloc(size ? size : 1, 1); cob_exts[cob_nexts].size = size; cob_exts[cob_nexts].sig = NULL;
    if (!cob_exts[cob_nexts].p) cob_fatal("out of memory for an EXTERNAL item");
    return cob_exts[cob_nexts++].p;
}
/* EC-EXTERNAL conformance (2023 14.8.4; standard-queue item 35): the
 * description a program gives an external record or file, as a string
 * the compiler built, against the first entering program's -- the first
 * to check records its own; 1 when they differ.  Called by a program
 * whose checking is on, after cob_external / before cob_ext_file_enter */
int cob_ext_sig(const char *name, const char *sig)
{
    for (int i = 0; i < cob_nexts; i++)
        if (!strcmp(cob_exts[i].name, name)) {
            if (!cob_exts[i].sig) { cob_exts[i].sig = sig; return 0; }
            return strcmp(cob_exts[i].sig, sig) != 0;
        }
    return 0;
}
static struct { const char *name; cob_file *f; const char *sig; } cob_extf[64]; static int cob_nextf;
int cob_ext_file_sig(const char *name, const char *sig)
{
    for (int i = 0; i < cob_nextf; i++)
        if (!strcmp(cob_extf[i].name, name)) {
            if (!cob_extf[i].sig) { cob_extf[i].sig = sig; return 0; }
            return strcmp(cob_extf[i].sig, sig) != 0;
        }
    return 0;
}
/* 14.8.4.2: the FILE STATUS, RELATIVE KEY and LINAGE items of every
 * program's entry for an external file are the same storage.  After
 * cob_ext_file_enter: the connector's status item is this program's now,
 * the previous one in saved_status */
int cob_ext_file_items(const char *name, cob_file *mine)
{
    for (int i = 0; i < cob_nextf; i++)
        if (!strcmp(cob_extf[i].name, name) && cob_extf[i].f) {
            cob_file *f = cob_extf[i].f;
            if (f == mine) return 0;
            if (mine->saved_status != mine->status || f->rel_key != mine->rel_key) return 1;
            if (f->linage && mine->linage)
                for (int k = 0; k < 4; k++) if (((void *const *)f->linage)[3 * k + 1] != ((void *const *)mine->linage)[3 * k + 1]) return 1;
            return 0;
        }
    return 0;
}
cob_file *cob_ext_file_enter(const char *name, cob_file *mine, void *rec)
{
    for (int i = 0; i < cob_nextf; i++)
        if (!strcmp(cob_extf[i].name, name)) {
            cob_file *f = cob_extf[i].f;
            if (f != mine) { mine->saved_status = f->status; f->status = mine->status; }
            return f;
        }
    if (cob_nextf == 64) cob_fatal("more than 64 EXTERNAL files");
    mine->record = rec;
    cob_extf[cob_nextf].name = name; cob_extf[cob_nextf].f = mine; cob_extf[cob_nextf].sig = NULL; cob_nextf++;
    return mine;
}
void cob_ext_file_exit(const char *name, cob_file *mine)
{
    for (int i = 0; i < cob_nextf; i++)
        if (!strcmp(cob_extf[i].name, name)) {
            cob_file *f = cob_extf[i].f;
            if (f != mine) f->status = mine->saved_status;
            return;
        }
}

/* CALL ... BY CONTENT: the callee is handed a copy, from an arena that
 * behaves as a stack -- pushed before the CALL, popped after it */
static char cob_content_arena[1 << 16]; static unsigned cob_content_top;
static unsigned cob_content_mark[256]; static int cob_content_nmark;
void *cob_content_push(const void *p, unsigned n)
{
    unsigned at = (cob_content_top + 7u) & ~7u;
    if (at + n > sizeof cob_content_arena || cob_content_nmark == 256) cob_fatal("BY CONTENT: too much or too deep");
    cob_content_mark[cob_content_nmark++] = cob_content_top;
    memcpy(cob_content_arena + at, p, n);
    cob_content_top = at + n;
    return cob_content_arena + at;
}
void cob_content_pop(int k)
{
    while (k-- > 0 && cob_content_nmark > 0) cob_content_top = cob_content_mark[--cob_content_nmark];
}

/* DECIMAL-POINT IS COMMA: the program's own; a called program's is restored on its exit */
int cob_dp_comma;
/* the edited fetch and store's locale argument, kept current here so the
 * compiled code passes it straight to the hooked cob_put_edited /
 * cob_get_edited (s32-cobc dx_store) */
int cob_locale_word = '$' << 8;
int cob_set_decimal_point(int comma) { int old = cob_dp_comma; cob_dp_comma = comma; cob_locale_word = loc_word(); return old; }
/* CURRENCY SIGN: the character printed where the picture says '$' */
int cob_currency = '$';
/* CURRENCY SIGN IS "EUR" WITH PICTURE SYMBOL "$": the string (2023
 * 12.3.7 rule 23), its length in the locale word; the string itself
 * reaches the editor after each picture (kern.h) and NUMVAL-C from here */
char cob_currency_str[32] = "$"; int cob_currency_len = 1;
int cob_set_currency(int c) { int old = cob_currency; cob_currency = c ? c : '$'; cob_currency_str[0] = (char)cob_currency; cob_currency_str[1] = 0; cob_currency_len = 1; cob_locale_word = loc_word(); return old; }
/* ... with a currency string: the symbol c and the string s of n bytes;
 * the returned word restores both (cob_restore_currency) */
int cob_set_currency_str(int c, const char *s, int n)
{
    int old = (cob_currency & 255) | (cob_currency_len << 8);
    cob_currency = c ? c : '$';
    if (n < 1 || n > 31) n = 1;
    memcpy(cob_currency_str, s, (size_t)n); cob_currency_str[n] = 0; cob_currency_len = n;
    cob_locale_word = loc_word();
    return old;
}
void cob_restore_currency(int old)
{
    /* the symbol only: a program with a currency string is the outermost
     * of its kind in practice; its caller's string, if any, is reset to
     * the symbol it had (a caller using the same string sees no change) */
    cob_currency = old & 255; cob_currency_len = 1;
    cob_currency_str[0] = (char)cob_currency; cob_currency_str[1] = 0;
    cob_locale_word = loc_word();
}

static int cmp_bytes(const unsigned char *a, int na, const unsigned char *b, int nb)
{
    int n = na > nb ? na : nb;          /* the shorter is extended with spaces */
    const unsigned char *t = cob_collating;
    for (int i = 0; i < n; i++) {
        int ca = i < na ? a[i] : ' ', cb = i < nb ? b[i] : ' ';
        if (t) { ca = t[ca]; cb = t[cb]; }
        if (ca != cb) return ca < cb ? -1 : 1;
    }
    return 0;
}

static unsigned long long cob_mag(long long v)
{
    return v < 0 ? 0 - (unsigned long long)v : (unsigned long long)v;
}

/* Can v be multiplied by 10^k without signed 64-bit overflow? */
static int cob_fits_mul10(long long v, int k)
{
    unsigned long long a;
    if (k <= 0) return 1;
    if (k > 18) return 0;
    a = cob_mag(v);
    if (a == 0) return 1;
    return a <= (unsigned long long)0x7fffffffffffffffLL / (unsigned long long)pow10tab[k];
}

static long long cob_rescale(long long v, int from, int to)
{
    int k;
    if (from == to) return v;
    if (from > to) {
        k = from - to;
        if (k > 18) return 0;
        return v / pow10tab[k];
    }
    k = to - from;
    if (!cob_fits_mul10(v, k))
        return v < 0 ? -0x7fffffffffffffffLL : 0x7fffffffffffffffLL;
    return v * pow10tab[k];
}

static int cmp_scaled(long long a, int sa, long long b, int sb)
{
    long long aa = cob_rescale(a, sa, sa > sb ? sa : sb);
    long long bb = cob_rescale(b, sb, sa > sb ? sa : sb);
    return aa < bb ? -1 : aa > bb ? 1 : 0;
}

/* -1, 0, 1 */
int cob_cmp(const void *a, const cob_desc *ad, const void *b, const cob_desc *bd)
{
    if (is_natnum(ad)) { unsigned char t[NATNUM_MAX]; cob_desc nd; return cob_cmp(nat_narrow(a, ad, t, &nd), &nd, b, bd); }
    if (is_natnum(bd)) { unsigned char t[NATNUM_MAX]; cob_desc nd; return cob_cmp(a, ad, nat_narrow(b, bd, t, &nd), &nd); }
    if ((is_sfloat(ad) || is_sfloat(bd)) && is_numcat(ad) && is_numcat(bd)) {   /* by the wide values */
        cob_wnum x, y; cob_wget(a, ad, &x); cob_wget(b, bd, &y);
        return w_cmp_val(&x, &y);
    }
    if ((is_float(ad) || is_float(bd)) && is_numcat(ad) && is_numcat(bd)) {   /* in double (docs/usage.md) */
        double x = num_dbl(a, ad), y = num_dbl(b, bd);
        return x < y ? -1 : x > y ? 1 : 0;
    }
    if (ad->cat == COB_NATIONAL || bd->cat == COB_NATIONAL) {
        /* national against anything: both as national characters, the
         * shorter padded with national spaces, as for nonnumeric operands */
        int ma = nat_cap(ad), mb = nat_cap(bd);
        unsigned short *ua = malloc((size_t)(ma + 1) * 2), *ub = malloc((size_t)(mb + 1) * 2);
        if (!ua || !ub) cob_fatal("out of memory");
        int na = as_national(a, ad, ua, ma), nb = as_national(b, bd, ub, mb), r = 0;
        for (int i = 0; i < na || i < nb; i++) {
            unsigned x = i < na ? ua[i] : 0x20, y = i < nb ? ub[i] : 0x20;
            if (x != y) { r = x < y ? -1 : 1; break; }
        }
        free(ua); free(ub);
        return r;
    }
    if (ad->cat == COB_BOOLEAN && bd->cat == COB_BOOLEAN) {
        /* boolean values, the shorter extended on the right with zeros
         * (2023 8.8.4.2.8) */
        const unsigned char *pa = a, *pb = b;
        int na = (int)ad->size, nb = (int)bd->size;
        for (int i = 0; i < na || i < nb; i++) {
            unsigned x = i < na ? pa[i] : '0', y = i < nb ? pb[i] : '0';
            if (x != y) return x < y ? -1 : 1;
        }
        return 0;
    }
    int an = ad->cat == COB_NUM, bn = bd->cat == COB_NUM;
    if (an && bn && (is_wide(ad) || is_wide(bd))) { cob_wnum x, y; cob_wget(a, ad, &x); cob_wget(b, bd, &y); return w_cmp_val(&x, &y); }
    if (an && bn) return cmp_scaled(cob_get_num(a, ad), ad->scale, cob_get_num(b, bd), bd->scale);
    char ta[40], tb[40];
    const unsigned char *pa = a, *pb = b;
    int na = (int)ad->size, nb = (int)bd->size;
    /* one side numeric, the other not: the numeric side is compared as the
     * characters of its digits (a literal's sign, a separate sign, an
     * overpunch, a binary or packed usage all go) */
    unsigned signs = COB_F_SEPLEAD | COB_F_SEPTRAIL | COB_F_LEAD | COB_F_SIGNED;
    if (an && (ad->usage != COB_U_DISPLAY || (ad->flags & signs))) { na = num_to_digits(a, ad, ta); pa = (unsigned char *)ta; }
    if (bn && (bd->usage != COB_U_DISPLAY || (bd->flags & signs))) { nb = num_to_digits(b, bd, tb); pb = (unsigned char *)tb; }
    return cmp_bytes(pa, na, pb, nb);
}

/* two strongly-typed groups of one type (2023 8.8.4.2.12): each elementary
 * item compared in order, by its own rules, until a pair differs (cobol
 * ISSUES-80); tab holds (offset, descriptor) pairs */
int cob_cmp_struct(const void *a, const void *b, const unsigned *tab, int n)
{
    for (int i = 0; i < n; i++) {
        const cob_desc *d = (const cob_desc *)(size_t)tab[2 * i + 1];
        int r = cob_cmp((const char *)a + tab[2 * i], d, (const char *)b + tab[2 * i], d);
        if (r) return r;
    }
    return 0;
}

/* a PIC N item's characters as bytes, for the class tests (2023 8.8.4.4.3
 * rules 3 and 8; cobol ISSUES-94 N6): 0 when one lies past U+00FF, which
 * is no digit, no Latin letter and in no class table.  The caller frees
 * *out. */
static int nat_class_bytes(const void *vp, const cob_desc *d, unsigned char **out, cob_desc *nd)
{
    int n = (int)d->size / 2;
    unsigned char *b = malloc((size_t)n + 1);
    if (!b) cob_fatal("out of memory");
    for (int i = 0; i < n; i++) {
        unsigned u = nat_at(vp, i);
        if (u > 0xFF) { free(b); return 0; }
        b[i] = (unsigned char)u;
    }
    *nd = *d; nd->cat = COB_ALNUM; nd->usage = COB_U_DISPLAY; nd->size = (unsigned)n;
    *out = b;
    return 1;
}

/* class conditions: 0 NUMERIC, 1 ALPHABETIC, 2 ALPHABETIC-LOWER, 3 ALPHABETIC-UPPER */
int cob_class_bytes(const unsigned char *p, int n, int kind);
int cob_class(const void *vp, const cob_desc *d, int kind)
{
    if (d->size == 0) return 0;         /* a zero-length item is in no class (2023 8.8.4.4.4 rule 1) */
    if (is_natnum(d)) { unsigned char b[NATNUM_MAX]; cob_desc nd; return cob_class(nat_narrow(vp, d, b, &nd), &nd, kind); }
    if (d->cat == COB_NATIONAL && kind != 4) {
        unsigned char *b; cob_desc nd;
        if (!nat_class_bytes(vp, d, &b, &nd)) return 0;
        int r = cob_class(b, &nd, kind);
        free(b);
        return r;
    }
    const unsigned char *p = vp;
    int n = (int)d->size;
    if (kind == 0) {
        if (d->cat == COB_NUM && d->usage == COB_U_PACKED) {
            /* packed decimal: each digit nibble 0-9, the last nibble a
             * sign (A-F: C, D and F as written here, A, B, E as IBM also
             * reads them) */
            int nosign = d->flags2 & COB_F2_NOSIGN;     /* COMP-6: every nibble a digit */
            for (int i = 0; i < n; i++) {
                unsigned hi = p[i] >> 4, lo = p[i] & 15;
                if (hi > 9) return 0;
                if (i < n - 1 || nosign ? lo > 9 : lo < 10) return 0;
            }
            return 1;
        }
        if (d->usage == COB_U_SFLOAT) { cob_wnum w; return sf_load(p, d, &w) == 0; }   /* NUMERIC: a finite value (2023 8.8.4.4.4 rule 3n.1b) */
        if (d->usage == COB_U_FLOAT) { double x = f_load(p, d); return x == x && x - x == 0; }   /* likewise: not a NaN, not an infinity */
        if (d->cat == COB_NUM && d->usage == COB_U_BINARY && !(d->flags & COB_F_NOTRUNC) && d->digits && d->digits < 19) {
            /* a binary of the standard's truncating kind (COMP, BINARY,
             * COMP-4): every bit pattern is a value, so NUMERIC asks
             * whether the value is within the PICTURE (2023 8.8.4.4.4
             * rule 3n.1c); the capacity-limited usages (COMP-5, COMP-X)
             * hold whatever their bytes say (docs/usage.md) */
            long long v = cob_get_num(vp, d), lim = 1;
            for (int i = 0; i < d->digits; i++) lim *= 10;
            if (v < 0 && !(d->flags & COB_F_SIGNED)) return 0;
            return v < lim && v > -lim;
        }
        if (d->cat == COB_NUM && d->usage != COB_U_DISPLAY) return 1;
        int start = (d->flags & COB_F_SEPLEAD) ? 1 : 0, end = (d->flags & COB_F_SEPTRAIL) ? n - 1 : n;
        for (int i = start; i < end; i++) {
            unsigned char c = p[i];
            if (c >= '0' && c <= '9') continue;
            if (i == ((d->flags & COB_F_LEAD) ? 0 : n - 1) && (d->flags & COB_F_SIGNED) && c >= 'p' && c <= 'y') continue;
            return 0;
        }
        return 1;
    }
    if (kind == 4) {                                    /* BOOLEAN: every position 0 or 1 */
        if (d->cat == COB_NATIONAL) { for (int i = 0; i + 1 < n; i += 2) if (p[i] || (p[i + 1] != '0' && p[i + 1] != '1')) return 0; return 1; }
        for (int i = 0; i < n; i++) if (p[i] != '0' && p[i] != '1') return 0;
        return 1;
    }
    return cob_class_bytes(p, n, kind);
}

/* The class test of alphanumeric bytes -- an alphanumeric item, a
 * reference-modified part: kind 0 NUMERIC (every one a digit), 1
 * ALPHABETIC, 2 ALPHABETIC-LOWER, 3 ALPHABETIC-UPPER (letters of that
 * kind, and spaces).  No descriptor: the compiler calls this with the
 * address and the length when the operand is such bytes, and tests a
 * single character itself. */
int cob_class_bytes(const unsigned char *p, int n, int kind)
{
    if (n == 0) return 0;               /* 8.8.4.4.4 rule 1 */
    if (kind == 0) {
        for (int i = 0; i < n; i++) if ((unsigned)(p[i] - '0') > 9) return 0;
        return 1;
    }
    for (int i = 0; i < n; i++) {
        unsigned char c = p[i];
        if (c == ' ') continue;
        int lo = (c >= 'a' && c <= 'z'), up = (c >= 'A' && c <= 'Z');
        if (kind == 1 && !(lo || up)) return 0;
        if (kind == 2 && !lo) return 0;
        if (kind == 3 && !up) return 0;
    }
    return 1;
}

/* a SPECIAL-NAMES CLASS: every character of the item is in the class's
 * 256-entry table (the compiler builds it from the literals and ranges) */
/* ---- the 2014 numeric and floating-point class conditions, and SET
 * CONTENT OF (2023 8.8.4.4, 14.9.39 format 15; docs/plans/standard-queue.md
 * item 21) --------------------------------------------------------------
 * The values a numeric item's specifications permit: the one farthest from
 * zero and the nonzero one nearest to it.  A DISPLAY, packed or truncating
 * binary item by its PICTURE (all nines; one in the last place); a
 * capacity-limited binary (COMP-5, the native usages) by its bytes; the
 * floats by their formats -- binary32/64 the largest finite and the
 * smallest subnormal, the software formats theirs.  The mode of arithmetic
 * (NATIVE: 38 decimal digits, doubles, floating decimals of 38 digits with
 * any exponent) holds every one of them, so IN-ARITHMETIC-RANGE changes
 * nothing here (a ruling, docs/usage.md). */

/* the special values of the binary and decimal formats: what 1 infinity,
 * 2 quiet NaN, 3 signaling NaN; neg the sign */
static void fp_special(unsigned char *p, const cob_desc *d, int what, int neg)
{
    wl_t a[4] = { 0, 0, 0, 0 };
    int size = (int)d->size, bigend = d->flags2 & COB_F2_BIGEND;
    if (d->usage == COB_U_FLOAT || (d->flags2 & COB_F2_FBIN)) {
        /* exponent all ones; the fraction 0, its top bit (quiet), or its lowest bit (signaling) */
        int ebits = size == 4 ? 8 : size == 8 ? 11 : 15, fbits = size * 8 - 1 - ebits;
        bits_put(a, fbits, ebits, (1u << ebits) - 1);
        if (what == 2) bits_put(a, fbits - 1, 1, 1);
        if (what == 3) bits_put(a, 0, 1, 1);
    } else {
        /* the five bits after the sign 11110 or 11111; the next bit marks a signaling NaN */
        int top = size * 8 - 1;
        bits_put(a, top - 5, 5, what == 1 ? 0x1E : 0x1F);
        if (what == 3) bits_put(a, top - 6, 1, 1);
    }
    bits_put(a, size * 8 - 1, 1, (wl_t)(neg != 0));
    ieee_store(p, size, bigend, a);
}
/* which special a float holds: 0 finite, 1 infinity, 2 quiet NaN, 3 signaling NaN; *neg its sign */
static int fp_special_of(const void *vp, const cob_desc *d, int *neg)
{
    wl_t a[4] = { 0, 0, 0, 0 };
    int size = (int)d->size, bigend = d->flags2 & COB_F2_BIGEND;
    ieee_load(vp, size, bigend, a);
    *neg = (int)bits_get(a, size * 8 - 1, 1);
    if (d->usage == COB_U_FLOAT || (d->flags2 & COB_F2_FBIN)) {
        int ebits = size == 4 ? 8 : size == 8 ? 11 : 15, fbits = size * 8 - 1 - ebits;
        if (bits_get(a, fbits, ebits) != (1u << ebits) - 1) return 0;
        wl_t f[4] = { 0, 0, 0, 0 };
        for (int i = 0; i < fbits; i += 32) { int n = fbits - i < 32 ? fbits - i : 32; bits_put(f, i, n, bits_get(a, i, n)); }
        if (mp_is_zero(f, 4)) return 1;
        return bits_get(a, fbits - 1, 1) ? 2 : 3;
    }
    int top = size * 8 - 1;
    unsigned comb = bits_get(a, top - 5, 5);
    if ((comb & 0x1E) != 0x1E) return 0;
    if (!(comb & 1)) return 1;
    return bits_get(a, top - 6, 1) ? 3 : 2;
}
/* the value farthest from zero (far) or nearest to it a numeric item
 * permits, as a wide number (positive) */
static void num_extreme(const cob_desc *d, int far, cob_wnum *w)
{
    memset(w, 0, sizeof *w);
    if (d->usage == COB_U_FLOAT) {
        if (far) { w_set_f(w, d->size == 4 ? 3.4028234663852886e38 : 1.7976931348623157e308); return; }
        if (d->size == 4) { w_set_f(w, 1.401298464324817e-45); return; }
        /* 2^-1074: not a literal every libc parses; built */
        { double x = 1; for (int i = 0; i < 1074; i++) x *= 0.5; w_set_f(w, x); return; }
    }
    if (d->usage == COB_U_SFLOAT) {
        w->isq = 1; w->m[0] = 1;
        if (d->flags2 & COB_F2_FBIN) {
            if (far) { unsigned char b[16]; wl_t a[4] = { 0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0x7FFEFFFFu }; ieee_store(b, 16, 0, a); int ng; bin128_decode(b, 0, w->m, &w->scale, &ng); }
            else { unsigned char b[16]; wl_t a[4] = { 1, 0, 0, 0 }; ieee_store(b, 16, 0, a); int ng; bin128_decode(b, 0, w->m, &w->scale, &ng); }
            return;
        }
        dec_fmt f = dec_format((int)d->size);
        if (far) { wl_t one[WL] = { 1, 0, 0, 0 }; w_pow10(w->m, f.digits); mp_sub(w->m, one, WL); w->scale = -(f.emax - (f.digits - 1)); }   /* 10^digits - 1 at the top exponent */
        else w->scale = -(f.emin - (f.digits - 1));                                                        /* 1 at the bottom one */
        return;
    }
    if (d->usage == COB_U_BINARY && (d->flags & COB_F_NOTRUNC)) {
        /* the bytes' capacity: 2^(bits-1) - 1 (the sign's own extra below zero is the SIGN phrase's business) */
        if (far) { int bits = (int)d->size * 8 - ((d->flags & COB_F_SIGNED) ? 1 : 0); for (int i = 0; i < bits; i++) w->m[i / 32] |= 1u << (i % 32); }
        else w->m[0] = 1;
        w->scale = d->scale;
        return;
    }
    int digits = eff_digits(d);
    if (far) { wl_t one[WL] = { 1, 0, 0, 0 }; w_pow10(w->m, digits); mp_sub(w->m, one, WL); }
    else w->m[0] = 1;
    w->scale = d->scale;                /* P positions: the digits are the integer's own (eff_digits) */
    if (d->scale < 0 && !far) { w_pow10(w->m, -d->scale); w->scale = 0; }
}
/* |the item's value| == the extreme?  The floats by their formats' own representations */
static int num_is_extreme(const void *vp, const cob_desc *d, int far)
{
    cob_wnum v, e;
    int neg;
    if ((d->usage == COB_U_FLOAT || d->usage == COB_U_SFLOAT) && fp_special_of(vp, d, &neg)) return 0;
    cob_wget(vp, d, &v);
    if (v.isf) { double x = fabs(v.f); num_extreme(d, far, &e); return x == e.f; }
    if (d->usage == COB_U_BINARY && (d->flags & COB_F_NOTRUNC) && far && v.neg) {
        /* two's complement: the negative extreme is one farther */
        wl_t one[WL] = { 1, 0, 0, 0 }; mp_sub(v.m, one, WL);
    }
    v.neg = 0;
    num_extreme(d, far, &e);
    return w_cmp_val(&v, &e) == 0;
}
/* the 2014 class conditions: 10 FARTHEST-FROM-ZERO, 11 NEAREST-TO-ZERO, 12
 * IN-ARITHMETIC-RANGE, 13 FLOAT-INFINITY, 14 FLOAT-NOT-A-NUMBER, 15 -QUIET,
 * 16 -SIGNALING */
int cob_class_2014(const void *vp, const cob_desc *d, int kind)
{
    if (d->size == 0) return 0;         /* 8.8.4.4.4 rule 1 */
    int neg, sp;
    switch (kind) {
    case 10: return num_is_extreme(vp, d, 1);
    case 11: return num_is_extreme(vp, d, 0);
    case 12:                            /* every finite value is within NATIVE's range */
        if (d->usage == COB_U_FLOAT || d->usage == COB_U_SFLOAT) return fp_special_of(vp, d, &neg) == 0;
        return 1;
    default:
        sp = fp_special_of(vp, d, &neg);
        return kind == 13 ? sp == 1 : kind == 14 ? sp >= 2 : kind == 15 ? sp == 2 : sp == 3;
    }
}
/* SET CONTENT OF item TO what (1 FARTHEST-FROM-ZERO, 2 NEAREST-TO-ZERO, 3
 * FLOAT-INFINITY, 4 FLOAT-NOT-A-NUMBER, 5 -SIGNALING) SIGN sign (-1
 * NEGATIVE, 1 POSITIVE, 0 none: positive) */
void cob_set_content(void *vp, const cob_desc *d, int what, int sign)
{
    int neg = sign < 0;
    if (what >= 3) { fp_special(vp, d, what - 2, neg); return; }
    if (d->usage == COB_U_SFLOAT && (d->flags2 & COB_F2_FBIN)) {
        /* binary128's extremes by their bits (a decimal of 36 digits would round) */
        wl_t a[4] = { 1, 0, 0, 0 };
        if (what == 1) { a[0] = a[1] = a[2] = 0xFFFFFFFFu; a[3] = 0x7FFEFFFFu; }
        if (neg) a[3] |= 1u << 31;
        ieee_store(vp, 16, d->flags2 & COB_F2_BIGEND, a);
        return;
    }
    cob_wnum w; num_extreme(d, what == 1, &w);
    if (d->usage == COB_U_BINARY && (d->flags & COB_F_NOTRUNC) && what == 1 && neg) { wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(w.m, one, WL); }   /* -2^(bits-1) */
    if (w.isf) { if (neg) w.f = -w.f; }
    else w.neg = neg;
    cob_wput_x(vp, d, &w, 0);
}

int cob_class_user(const void *vp, const cob_desc *d, const unsigned char *tab)
{
    if (d->size == 0) return 0;         /* 8.8.4.4.4 rule 1 */
    if (d->cat == COB_NATIONAL) {
        unsigned char *b; cob_desc nd;
        if (!nat_class_bytes(vp, d, &b, &nd)) return 0;
        int r = cob_class_user(b, &nd, tab);
        free(b);
        return r;
    }
    const unsigned char *p = vp;
    int n = (int)d->size;
    for (int i = 0; i < n; i++) if (!tab[p[i]]) return 0;
    return 1;
}

/* ---- the numeric stack: ADD/SUBTRACT/MULTIPLY/DIVIDE, COMPUTE later --- */

typedef struct { long long v; int scale; } cob_num;
/* The evaluation stack grows: a user-defined function (COBOL 2002) runs
 * with its caller's pending operands still on it, so the depth is the
 * recursion's, not one statement's (cobol ISSUES-50). */
static cob_num *nstk;
static int nsp, ncap;

static void nstk_room(void)
{
    if (nsp < ncap) return;
    ncap = ncap ? 2 * ncap : 64;
    nstk = realloc(nstk, (size_t)ncap * sizeof *nstk);
    if (!nstk) cob_fatal("numeric stack: out of memory");
}

void cob_push(const void *p, const cob_desc *d)
{
    nstk_room();
    if (is_float(d)) {
        /* a float on the narrow stack (an intrinsic's argument): nine
         * decimals, or as many as 64 bits leave room for */
        double x = f_load(p, d); int sc = 9;
        while (sc > 0 && fabs(x) * pow10d(sc) >= 9e17) sc--;
        double y = x * pow10d(sc);
        if (!(fabs(y) < 9.2e18)) cob_fatal("a floating-point value past 18 digits reached an operation that holds 18");
        nstk[nsp].v = (long long)(y < 0 ? y - 0.5 : y + 0.5); nstk[nsp].scale = sc; nsp++;
        return;
    }
    if (d->digits > 18 && is_wide(d)) {
        /* a wide value on the narrow stack (an exact function's result in
         * a narrow statement): decimals shed until 64 bits hold it, as
         * cob_nmul sheds them; one whose integer part does not fit stops
         * the run, never a wrong number (docs/wide.md) */
        cob_wnum w; cob_wget(p, d, &w);
        while (!w_fits_i64(&w) && w.scale > 0) { mp_div_small(w.m, WL, 10); w.scale--; }
        if (!w_fits_i64(&w)) cob_fatal("a value of more than 18 digits reached an operation that holds 18 (docs/wide.md)");
        nstk[nsp].v = w_to_i64(&w); nstk[nsp].scale = w.scale; nsp++;
        return;
    }
    nstk[nsp].v = cob_get_num(p, d); nstk[nsp].scale = d->scale; nsp++;
}

void cob_push_lit(long long v, int scale)
{
    nstk_room();
    nstk[nsp].v = v; nstk[nsp].scale = scale; nsp++;
}

static void align2(cob_num *a, cob_num *b)
{
    /* Prefer scaling the smaller magnitude up. If that would overflow
     * i64, shed a fraction digit from the other instead (GitHub #21). */
    while (a->scale != b->scale) {
        if (a->scale < b->scale) {
            if (cob_fits_mul10(a->v, 1)) { a->v *= 10; a->scale++; }
            else { b->v /= 10; b->scale--; }
        } else {
            if (cob_fits_mul10(b->v, 1)) { b->v *= 10; b->scale++; }
            else { a->v /= 10; a->scale--; }
        }
    }
}

static int div0;        /* a size error happened in this statement: 1 a zero divisor, 2 an i64 overflow */
/* INTERMEDIATE ROUNDING (2014; 2023 11.9.11): how an intermediate loses
 * the digits it cannot keep -- 0 TRUNCATION (the implementor's rule for
 * NATIVE arithmetic, GR 1, and the one in effect unless a unit's OPTIONS
 * paragraph says otherwise), 1 NEAREST-AWAY-FROM-ZERO, 2 NEAREST-EVEN, 3
 * PROHIBITED (EC-SIZE-TRUNCATION: a size error, the statement's).  Set
 * by the unit's activation descriptor on entry, the caller's restored on
 * leaving.  Applied wherever the stacks shed digits: a quotient's last
 * digit (narrow and wide), the operand fraction digits a multiplication
 * sheds for room, the digits the wide stack sheds to align two scales or
 * to fit 38. */
static int cob_iround;
static int iround_stack[256]; static int iround_sp;
/* round up by one unit?  half: the first dropped digit against half a
 * unit (1 above, 0 exactly half, -1 below); sticky: more dropped below
 * it; odd: the kept value's last digit */
static int iround_up(int half, int sticky, int odd)
{
    switch (cob_iround) {
    case 1: return half >= 0;
    case 2: return half > 0 || (half == 0 && (sticky || odd));
    case 3: if (half >= 0 || sticky) div0 = 2; return 0;
    default: return 0;
    }
}
static int size_kind;   /* the last size error's kind, for EC-SIZE (cobol ISSUES-55): 1 zero divide, 2 overflow, 3 truncation, 4 exponentiation */
int cob_size_kind(void) { return size_kind; }

void cob_nadd(void) { cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1]; align2(a, b); a->v += b->v; nsp--; }
void cob_nsub(void) { cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1]; align2(a, b); a->v -= b->v; nsp--; }
void cob_nmul(void)
{
    cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1];
    /* wide operands (the NIST suite works with S9V9(17) items): shed
     * fraction digits until the product fits 64 bits and 18 of scale */
    for (;;) {
        unsigned long long ua = a->v < 0 ? 0 - (unsigned long long)a->v : (unsigned long long)a->v;
        unsigned long long ub = b->v < 0 ? 0 - (unsigned long long)b->v : (unsigned long long)b->v;
        int over = ub && ua > 0x7fffffffffffffffULL / ub;
        if (!over && a->scale + b->scale <= 18) break;
        cob_num *w = a->scale >= b->scale ? a : b;
        if (w->scale == 0) w = w == a ? b : a;
        if (w->scale == 0) break;                    /* nothing left to shed: the store's size error catches it */
        if (cob_iround) {
            /* the digit shed, rounded into what stays (each step on its own:
             * the digits below it were already rounded away) */
            long long d = w->v % 10; int neg = w->v < 0; if (neg) d = -d;
            w->v /= 10; w->scale--;
            if (iround_up(d > 5 ? 1 : d == 5 ? 0 : -1, 0, (int)((neg ? -w->v : w->v) & 1))) w->v += neg ? -1 : 1;
            continue;
        }
        w->v /= 10; w->scale--;
    }
    {
    unsigned long long ua = a->v < 0 ? 0 - (unsigned long long)a->v : (unsigned long long)a->v;
    unsigned long long ub = b->v < 0 ? 0 - (unsigned long long)b->v : (unsigned long long)b->v;
    if (ub && ua > 0x7fffffffffffffffULL / ub) {
        div0 = 2;                                   /* size error: product does not fit i64 */
        nsp--;
        return;
    }
    }
    a->v *= b->v; a->scale += b->scale; nsp--;
}

/* Division carries the operands' larger scale plus guard digits, so a
 * receiver with a wider scale than either operand still gets its digits;
 * the store truncates.  (The 85 intermediate rules are implementor-defined;
 * this is the stage-2 rule and stage 3 may tighten it.) */
static int ndiv_core(cob_num *a, const cob_num *b, int need);
void cob_ndiv(void)
{
    cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1];
    if (ndiv_core(a, b, 99)) div0 = 1;             /* size error; the left operand stands in */
    nsp--;
}

/* the compiler's decimal arithmetic in registers (cobc/arith_reg.h dx_*):
 * a division at the top of a statement, by the stack's own rule; the
 * quotient's scale in cob_xdiv_scale, -1 for a zero divisor.  need: the
 * most fraction digits any receiver keeps, one more where it is ROUNDED.
 * The quotient's digits are produced one at a time and each is exact, so
 * stopping at need gives the store the same digits it would have cut the
 * longer quotient down to -- without making the rest. */
int cob_xdiv_scale;
long long cob_xdivn(long long a, long long b, int sa, int sb, int need)
{
    cob_num x = { a, sa }, y = { b, sb };
    if (ndiv_core(&x, &y, need)) { cob_xdiv_scale = -1; return 0; }
    cob_xdiv_scale = x.scale;
    return x.v;
}

/* a / b into *a; 1 for a zero divisor (a left as it was).  need: the
 * fraction digits wanted at most (99: the stack's own rule alone) */
static int ndiv_core(cob_num *a, const cob_num *b, int need)
{
    if (b->v == 0) return 1;
    /* long division in decimal: the integer quotient of the scaled values,
     * then one fraction digit at a time from the remainder (ten times a
     * remainder below 10^18 fits in 64 bits), until the quotient holds
     * seventeen digits or the wanted scale -- the operands' larger one plus
     * six guard digits -- is reached.  Exact, so 111111111.111111111
     * divided by itself is 1.000000000 and not 1.001001001. */
    int neg = (a->v < 0) != (b->v < 0);
    unsigned long long ua = a->v < 0 ? (unsigned long long)(-a->v) : (unsigned long long)a->v;
    unsigned long long ub = b->v < 0 ? (unsigned long long)(-b->v) : (unsigned long long)b->v;
    unsigned long long q, r;
    if (!((ua | ub) >> 32)) { unsigned x = (unsigned)ua, y = (unsigned)ub, qq = x / y; q = qq; r = x - qq * y; }
    else { q = ua / ub; r = ua % ub; }
    int scale = a->scale - b->scale;
    int want = (a->scale > b->scale ? a->scale : b->scale) + 6;
    if (want < 9) want = 9;                         /* an intrinsic's argument keeps nine fraction digits (TAN(1 / 180)) */
    if (want > 18) want = 18;                       /* the stack's scale never passes 18 */
    if (want > need) want = need;                   /* no receiver keeps more (cob_xdivn) */
    if (ub < (1u << 28)) {                          /* r * 10 stays in 32 bits: the hardware divider */
        unsigned d32 = (unsigned)ub, r32 = (unsigned)r;
        while (scale < want && q < (unsigned long long)pow10tab[17]) {
            r32 *= 10;
            unsigned t = r32 / d32;
            q = q * 10 + t; r32 -= t * d32;
            scale++;
        }
        r = r32;
    } else {
        while (scale < want && q < (unsigned long long)pow10tab[17]) {
            r *= 10;
            q = q * 10 + r / ub; r %= ub;
            scale++;
        }
    }
    if (scale < 0) {                            /* the divisor's scale exceeded the dividend's */
        while (scale < 0 && q < (unsigned long long)pow10tab[17]) { q *= 10; scale++; }
        if (scale < 0) { q = (unsigned long long)pow10tab[18]; scale = 0; }   /* beyond eighteen digits: a size error at the store */
    }
    if (cob_iround && r) {                      /* the fraction left over, against half the divisor */
        int half = r > ub - r ? 1 : r == ub - r ? 0 : -1;
        if (iround_up(half, half != 0, (int)(q & 1))) q++;   /* any remainder is something dropped (PROHIBITED) */
    }
    a->v = neg ? -(long long)q : (long long)q; a->scale = scale;
    return 0;
}

void cob_nneg(void) { nstk[nsp - 1].v = -nstk[nsp - 1].v; }
/* the magnitude: DIVIDE ... REMAINDER's quotient when the quotient item is
 * unsigned (X3.23-1985 VI-81, DIVIDE rule 6) */
void cob_nabs(void) { if (nstk[nsp - 1].v < 0) nstk[nsp - 1].v = -nstk[nsp - 1].v; }
/* the top truncated to `scale` decimals (DIVIDE ... REMAINDER: the
 * quotient as it would be stored before ROUNDED, X3.23 6.9.4) */
void cob_ntrunc(int scale)
{
    cob_num *a = &nstk[nsp - 1];
    if (a->scale > scale) { a->v = div_pow10(a->v, a->scale - scale, 0); a->scale = scale; }
}

/* a ** b for an integer b >= 0; anything else is beyond this stage */
void cob_npow(void)
{
    cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1];
    if ((b->scale > 0 && b->v % pow10tab[b->scale]) || b->v < 0) {
        /* a fractional or negative exponent: approximate, in double (a zero
         * base to such a power, or a negative one to a fraction, is a size
         * error), at nine decimals or as many as 64 bits leave room for */
        double x = (double)a->v / pow10d(a->scale), y = (double)b->v / pow10d(b->scale);
        /* no NAN: stage08 cc has no __builtin_nanf (selfhost ISSUES-71) */
        int bad = (x == 0 && y <= 0) || (x < 0 && y != floor(y));
        double r = bad ? 0 : pow(x, y);
        if (bad || r != r) { div0 = 4; nsp--; return; }    /* 2023 8.8.1.2 rule 6a, 6c: EC-SIZE-EXPONENTIATION */
        if (fabs(r) >= 9e17) { div0 = 2; nsp--; return; }
        int sc = 9;
        while (sc > 0 && fabs(r) * pow10d(sc) >= 9e17) sc--;
        double v = r * pow10d(sc);
        a->v = (long long)(v < 0 ? v - 0.5 : v + 0.5); a->scale = sc;
        nsp--;
        return;
    }
    if (b->scale > 0) { b->v /= pow10tab[b->scale]; b->scale = 0; }
    if (a->v == 0 && b->v == 0) { div0 = 4; nsp--; return; }   /* zero to the power zero (rule 6a) */
    long long base = a->v, r = 1; int bs = a->scale, scale = 0;
    while (bs > 9) { base /= 10; bs--; }            /* nine fraction digits of base carry the answer */
    unsigned long long ab = base < 0 ? 0 - (unsigned long long)base : (unsigned long long)base;
    for (long long i = 0; i < b->v; i++) {
        while (scale > 0 && ab &&
               (unsigned long long)(r < 0 ? -r : r) > 0x7fffffffffffffffULL / ab) { r /= 10; scale--; }
        r *= base; scale += bs;
        while (scale > 12) { r /= 10; scale--; }
    }
    a->v = r; a->scale = scale;
    nsp--;
}

/* compare the two on top; pops both; -1 0 1 */
int cob_ncmp(void)
{
    cob_num *a = &nstk[nsp - 2], *b = &nstk[nsp - 1];
    align2(a, b);
    int r = a->v < b->v ? -1 : a->v > b->v ? 1 : 0;
    nsp -= 2;
    return r;
}

/* ROUNDED MODE IS (2014; 2023 14.7.4): opts bits 4-7, 1 AWAY-FROM-ZERO,
 * 3 NEAREST-EVEN, 4 NEAREST-TOWARD-ZERO, 5 PROHIBITED, 6 TOWARD-GREATER,
 * 7 TOWARD-LESSER (NEAREST-AWAY-FROM-ZERO is plain ROUNDED, bit 0, and
 * TRUNCATION no ROUNDED: the compiler sends those as before).  Should the
 * value step one unit away from zero when dropped digits are lost: cmp
 * the remainder against half a unit (-1 0 1), odd the kept value's last
 * digit, neg its sign. */
static int rmode_away(int mode, int cmp, int odd, int neg)
{
    switch (mode) {
    case 1: return 1;
    case 3: return cmp > 0 || (cmp == 0 && odd);
    case 4: return cmp > 0;
    case 6: return !neg;
    case 7: return neg;
    default: return cmp >= 0;               /* NEAREST-AWAY-FROM-ZERO */
    }
}
/* v at vs digits of fraction to the receiver's ds by mode: 1 when
 * PROHIBITED and the value is not exact (the size error, 14.7.4.3 rule 7) */
static int rmode_round(long long *v, int *vs, int ds, int mode)
{
    if (*vs <= ds) return 0;
    int k = *vs - ds;
    long long q, r, p = 0;
    if (k > 18) { q = 0; r = *v; }
    else { p = (long long)pow10tab[k]; q = *v / p; r = *v % p; }
    if (!r) { *v = q; *vs = ds; return 0; }
    if (mode == 5) return 1;
    unsigned long long ar = (unsigned long long)(r < 0 ? -r : r);
    int cmp = k > 18 ? -1 : 2 * ar > (unsigned long long)p ? 1 : 2 * ar == (unsigned long long)p ? 0 : -1;
    if (rmode_away(mode, cmp, (int)((q < 0 ? -q : q) & 1), *v < 0)) q += *v < 0 ? -1 : 1;
    *v = q; *vs = ds;
    return 0;
}
/* a narrow store through rmode_round, then as before -- the rounding done,
 * the stored value is exact (cob_put_num_x itself is a hooked thunk) */
static int put_rmode(void *p, const cob_desc *d, long long v, int vs, int opts)
{
    int mode = (opts >> 4) & 15;
    if (mode && !is_float(d) && !is_sfloat(d)) {
        if (rmode_round(&v, &vs, d->scale, mode)) return 1;
        opts &= ~0xF1;
    }
    return cob_put_num_x(p, d, v, vs, opts & ~0xF0);
}

/* opts as cob_put_num_x; return 1 on a size error (receiver unchanged) */
int cob_top_store(void *p, const cob_desc *d, int opts)
{
    if (div0) { size_kind = div0; return 1; }
    int r = put_rmode(p, d, nstk[nsp - 1].v, nstk[nsp - 1].scale, opts);
    if (r) size_kind = 3;
    return r;
}

int cob_top_addto(void *p, const cob_desc *d, int opts)
{
    if (div0) { size_kind = div0; return 1; }
    cob_num a = { cob_get_num(p, d), d->scale }, b = nstk[nsp - 1];
    align2(&a, &b);
    int r = put_rmode(p, d, a.v + b.v, a.scale, opts);
    if (r) size_kind = 3;
    return r;
}

int cob_top_subfrom(void *p, const cob_desc *d, int opts)
{
    if (div0) { size_kind = div0; return 1; }
    cob_num a = { cob_get_num(p, d), d->scale }, b = nstk[nsp - 1];
    align2(&a, &b);
    int r = put_rmode(p, d, a.v - b.v, a.scale, opts);
    if (r) size_kind = 3;
    return r;
}

void cob_drop(void) { if (nsp) nsp--; div0 = 0; }

/* ---- the wide evaluation stack (docs/wide.md phase 2) ----------------
 * The narrow stack's operations over cob_wnum, for a statement the
 * compiler found to need more than 18 digits.  Magnitudes stay below
 * 10^38: a result past that sheds fraction digits, and with none left is
 * a size error (div0 = 2), as the narrow stack does at 64 bits.  div0 and
 * size_kind are the narrow stack's own, so ON SIZE ERROR and EC-SIZE
 * work the same way. */
static cob_wnum *wstk;
static int wsp, wcap;

static void wstk_room(void)
{
    if (wsp < wcap) return;
    wcap = wcap ? 2 * wcap : 32;
    wstk = realloc(wstk, (size_t)wcap * sizeof *wstk);
    if (!wstk) cob_fatal("wide numeric stack: out of memory");
}

/* is a limb array (n limbs) at least 10^38? */
static int mp_ge_1e38(const wl_t *a, int n)
{
    wl_t p[2 * WL] = { 0 };
    w_pow10(p, 38);
    for (int i = n - 1; i >= WL; i--) if (a[i]) return 1;
    return mp_cmp(a, p, WL) >= 0;
}

/* keep a value below 10^38 digits by shedding fraction digits; 0 when it
 * cannot (a size error) */
static int w_fit_q(wl_t *a, int n, int *scale, int q)
{
    int first = -1, rest = 0;
    while (mp_ge_1e38(a, n)) {
        if (*scale <= 0 && !q) return 0;
        wl_t r = mp_div_small(a, n, 10); (*scale)--;
        if (first >= 0 && first) rest = 1;
        first = (int)r;
    }
    if (cob_iround && first >= 0 && iround_up(first > 5 ? 1 : first == 5 ? 0 : -1, rest, (int)(a[0] & 1))) mp_mul_small(a, n, 1, 1);
    return 1;
}
static int w_fit(wl_t *a, int n, int *scale) { return w_fit_q(a, n, scale, 0); }

void cob_wpush(const void *p, const cob_desc *d) { wstk_room(); cob_wget(p, d, &wstk[wsp++]); }
void cob_wpush_lit(long long v, int scale) { wstk_room(); w_from_i64(&wstk[wsp++], v, scale); }
/* a statement that computes in double (a float among its operands or
 * receivers, docs/usage.md): every operand goes on as a double */
void cob_fpush(const void *p, const cob_desc *d) { wstk_room(); w_set_f(&wstk[wsp++], num_dbl(p, d)); }
void cob_fpush_lit(long long v, int scale) { wstk_room(); w_set_f(&wstk[wsp++], (double)v / pow10d(scale)); }
/* a statement that computes as floating decimals (a standard software
 * float among its operands or receivers): every operand goes on marked
 * so, and the stack sheds digits for room instead of a size error */
void cob_qpush(const void *p, const cob_desc *d) { wstk_room(); cob_wget(p, d, &wstk[wsp]); if (!wstk[wsp].isf) wstk[wsp].isq = 1; wsp++; }
void cob_qpush_lit(long long v, int scale) { wstk_room(); w_from_i64(&wstk[wsp++], v, scale); wstk[wsp - 1].isq = 1; }

/* one scale for both: the smaller scaled up while it has room below 38
 * digits, the rest shed from the larger (as align2) */
static void w_align2(cob_wnum *a, cob_wnum *b)
{
    if (a->scale == b->scale) return;
    cob_wnum *lo = a->scale < b->scale ? a : b, *hi = lo == a ? b : a;
    int k = hi->scale - lo->scale, room = 38 - w_ndigits(lo->m);
    int up = k < room ? k : room;
    if (up > 0) { w_scale_up(lo->m, up); lo->scale += up; }
    if (hi->scale > lo->scale) {
        int half, nz; w_drop_digits(hi->m, WL, hi->scale - lo->scale, &half, &nz); hi->scale = lo->scale;
        if (cob_iround && iround_up(half, nz && half < 0 ? 1 : 0, (int)(hi->m[0] & 1))) mp_mul_small(hi->m, WL, 1, 1);
    }
}

static void w_addsub(cob_wnum *a, const cob_wnum *b0, int sub)
{
    cob_wnum qb; if (b0->isf && a->isq && !w_from_dbl_q(&qb, b0->f)) b0 = &qb;
    if (a->isf && b0->isq) { cob_wnum qa; if (!w_from_dbl_q(&qa, a->f)) *a = qa; }
    if (a->isf || b0->isf) { double x = w_to_dbl(a), y = w_to_dbl(b0); w_set_f(a, sub ? x - y : x + y); return; }
    cob_wnum b = *b0;
    if (sub) b.neg = !b.neg;
    int q = a->isq || b.isq;
    w_align2(a, &b);
    if (a->neg == b.neg) {
        mp_add(a->m, b.m, WL);                      /* two below 10^38 fit 128 bits */
        if (!w_fit_q(a->m, WL, &a->scale, q)) div0 = 2;
    } else if (mp_cmp(a->m, b.m, WL) >= 0) mp_sub(a->m, b.m, WL);
    else { wl_t t[WL]; memcpy(t, b.m, sizeof t); mp_sub(t, a->m, WL); memcpy(a->m, t, sizeof t); a->neg = b.neg; }
    if (mp_is_zero(a->m, WL)) a->neg = 0;
    a->isq = q;
}

void cob_wadd(void) { w_addsub(&wstk[wsp - 2], &wstk[wsp - 1], 0); wsp--; }
void cob_wsub(void) { w_addsub(&wstk[wsp - 2], &wstk[wsp - 1], 1); wsp--; }

static void w_mul(cob_wnum *a, const cob_wnum *b)
{
    cob_wnum qb; if (b->isf && a->isq && !w_from_dbl_q(&qb, b->f)) b = &qb;
    if (a->isf && b->isq) { cob_wnum qa; if (!w_from_dbl_q(&qa, a->f)) *a = qa; }
    if (a->isf || b->isf) { w_set_f(a, w_to_dbl(a) * w_to_dbl(b)); return; }
    wl_t p[2 * WL];
    mp_mul(a->m, WL, b->m, WL, p);
    int scale = a->scale + b->scale, q = a->isq || b->isq;
    if (scale > 38) {
        int half, nz; w_drop_digits(p, 2 * WL, scale - 38, &half, &nz); scale = 38;
        if (cob_iround && iround_up(half, nz && half < 0 ? 1 : 0, (int)(p[0] & 1))) mp_mul_small(p, 2 * WL, 1, 1);
    }
    if (!w_fit_q(p, 2 * WL, &scale, q)) { div0 = 2; return; }
    memcpy(a->m, p, sizeof a->m);
    a->scale = scale;
    a->neg = a->neg != b->neg && !mp_is_zero(a->m, WL);
    a->isq = q;
}
void cob_wmul(void) { w_mul(&wstk[wsp - 2], &wstk[wsp - 1]); wsp--; }

/* the quotient to the operands' larger scale and six guard digits (at
 * least nine), truncated, as the narrow division; as many as 38 digits
 * hold */
static void w_div(cob_wnum *a, const cob_wnum *b)
{
    cob_wnum qb; if (b->isf && a->isq && !w_from_dbl_q(&qb, b->f)) b = &qb;
    if (a->isf && b->isq) { cob_wnum qa; if (!w_from_dbl_q(&qa, a->f)) *a = qa; }
    if (a->isf || b->isf) {
        double y = w_to_dbl(b);
        if (y == 0) div0 = 1; else w_set_f(a, w_to_dbl(a) / y);
        return;
    }
    if (mp_is_zero(b->m, WL)) { div0 = 1; return; }
    int fq = a->isq || b->isq;
    int want = (a->scale > b->scale ? a->scale : b->scale) + 6;
    if (want < 9) want = 9;
    if (want > 38) want = 38;
    if (fq) {
        /* a floating quotient: as many digits as 38 hold, from the operands'
         * sizes (a 36-digit dividend over a 1-digit divisor wants them all) */
        int na = w_ndigits(a->m), nb = w_ndigits(b->m);
        want = a->scale - b->scale + 36 - na + nb;
    }
    /* a * 10^k / b has the scale a.scale + k - b.scale = want */
    int k = want - a->scale + b->scale;
    wl_t n[2 * WL] = { 0 }, dv[2 * WL] = { 0 }, q[2 * WL], r[2 * WL];
    memcpy(n, a->m, sizeof a->m); memcpy(dv, b->m, sizeof b->m);
    int nd = w_ndigits(a->m);
    while (k > 0 && nd + k > 76) { k--; want--; }   /* the numerator stays within 256 bits */
    if (fq && k < 0) { int nb = w_ndigits(b->m); while (k < 0 && nb - k > 76) { k++; want++; } }
    for (int i = 0; i < k; i++) mp_mul_small(n, 2 * WL, 10, 0);
    for (int i = 0; i < -k; i++) mp_mul_small(dv, 2 * WL, 10, 0);
    mp_divmod(n, dv, 2 * WL, q, r);                 /* a*10^k/b, or a/(b*10^-k): scale want either way */
    int scale = want;
    if (cob_iround && !mp_is_zero(r, 2 * WL) && scale <= 38) {
        /* the remainder against half the divisor: 2r vs dv */
        wl_t r2[2 * WL]; memcpy(r2, r, sizeof r2); mp_mul_small(r2, 2 * WL, 2, 0);
        int c = mp_cmp(r2, dv, 2 * WL);
        if (iround_up(c, c != 0, (int)(q[0] & 1))) mp_mul_small(q, 2 * WL, 1, 1);   /* a remainder is something dropped (PROHIBITED) */
    }
    if (scale > 38 && !fq) {
        int half, nz; w_drop_digits(q, 2 * WL, scale - 38, &half, &nz); scale = 38;
        if (cob_iround && iround_up(half, (nz && half < 0) || !mp_is_zero(r, 2 * WL) ? 1 : 0, (int)(q[0] & 1))) mp_mul_small(q, 2 * WL, 1, 1);
    }
    if (!w_fit_q(q, 2 * WL, &scale, fq)) { div0 = 2; return; }
    int neg = a->neg != b->neg;
    memcpy(a->m, q, sizeof a->m); a->scale = scale;
    a->neg = neg && !mp_is_zero(a->m, WL);
    a->isq = fq;
}
void cob_wdiv(void) { w_div(&wstk[wsp - 2], &wstk[wsp - 1]); wsp--; }

void cob_wneg(void) { cob_wnum *a = &wstk[wsp - 1]; if (a->isf) { a->f = -a->f; return; } a->neg = !a->neg && !mp_is_zero(a->m, WL); }
void cob_wabs(void) { cob_wnum *a = &wstk[wsp - 1]; if (a->isf) { if (a->f < 0) a->f = -a->f; return; } a->neg = 0; }
void cob_wtrunc(int scale)
{
    cob_wnum *a = &wstk[wsp - 1];
    if (a->isf) { double s = pow10d(scale); a->f = trunc(a->f * s) / s; return; }
    if (a->scale > scale) { w_drop_digits(a->m, WL, a->scale - scale, 0, 0); a->scale = scale; if (mp_is_zero(a->m, WL)) a->neg = 0; }
}

/* a ** b for an integer b >= 0, by repeated multiplication */
void cob_wpow(void)
{
    cob_wnum *a = &wstk[wsp - 2], *b = &wstk[wsp - 1];
    int frac = 0;
    if (!b->isf && b->scale > 0) { cob_wnum t = *b; w_drop_digits(t.m, WL, t.scale, 0, &frac); }
    if (a->isf || b->isf || frac || (b->neg && !mp_is_zero(b->m, WL))) {
        /* a float, or a fractional or negative exponent: in double; a zero
         * base to such a power, or a negative one to a fraction, is a size
         * error */
        double x = w_to_dbl(a), y = w_to_dbl(b);
        int bad = (x == 0 && y <= 0) || (x < 0 && y != floor(y));
        double r = bad ? 0 : pow(x, y);
        if (bad || r != r) div0 = 4; else w_set_f(a, r);   /* 2023 8.8.1.2 rule 6a, 6c: EC-SIZE-EXPONENTIATION */
        wsp--; return;
    }
    if (b->scale > 0) { w_drop_digits(b->m, WL, b->scale, 0, 0); b->scale = 0; }
    if (mp_is_zero(a->m, WL) && mp_is_zero(b->m, WL)) { div0 = 4; wsp--; return; }   /* zero to the power zero (rule 6a) */
    if (b->m[1] || b->m[2] || b->m[3] || b->m[0] > 1000) cob_fatal("** with an exponent past 1000 is not implemented");
    cob_wnum r; w_from_i64(&r, 1, 0);
    for (wl_t i = 0; i < b->m[0] && !div0; i++) w_mul(&r, a);
    *a = r;
    wsp--;
}

int cob_wcmp(void)
{
    int r = w_cmp_val(&wstk[wsp - 2], &wstk[wsp - 1]);
    wsp -= 2;
    return r;
}

int cob_wtop_store(void *p, const cob_desc *d, int opts)
{
    if (div0) { size_kind = div0; return 1; }
    if (wstk[wsp - 1].isf) opts |= 1;           /* a floating-point result is always rounded (MF: ROUNDED documentary) */
    int r = cob_wput_x(p, d, &wstk[wsp - 1], opts);
    if (r) size_kind = 3;
    return r;
}

static int w_top_addsub(void *p, const cob_desc *d, int opts, int sub)
{
    if (div0) { size_kind = div0; return 1; }
    cob_wnum a; cob_wget(p, d, &a);
    w_addsub(&a, &wstk[wsp - 1], sub);
    if (div0) { size_kind = div0; return 1; }
    if (a.isf) opts |= 1;                       /* a floating-point result is always rounded (MF) */
    int r = cob_wput_x(p, d, &a, opts);
    if (r) size_kind = 3;
    return r;
}
int cob_wtop_addto(void *p, const cob_desc *d, int opts) { return w_top_addsub(p, d, opts, 0); }
int cob_wtop_subfrom(void *p, const cob_desc *d, int opts) { return w_top_addsub(p, d, opts, 1); }
void cob_wdrop(void) { if (wsp) wsp--; div0 = 0; }

/* A value taken off the numeric stack into a buffer of the program's, and
 * pushed again from it as often as wanted: an EVALUATE subject is
 * evaluated once, at the beginning (2023 14.9.13.4 rule 3), and compared
 * with each WHEN's objects.  Kept in the wide form whichever stack it
 * came from, so it goes back onto either. */
void cob_nsave(cob_wnum *b) { if (!nsp) return; nsp--; w_from_i64(b, nstk[nsp].v, nstk[nsp].scale); }
void cob_wnsave(cob_wnum *b) { if (!wsp) return; *b = wstk[--wsp]; }
void cob_npush_saved(const cob_wnum *b)
{
    cob_wnum w = *b;
    nstk_room();
    nstk[nsp].v = w_to_i64(&w); nstk[nsp].scale = w.scale; nsp++;
}
void cob_wnpush_saved(const cob_wnum *b) { wstk_room(); wstk[wsp++] = *b; }

/* subscripts: the integer value of an item */
int cob_load_int(const void *p, const cob_desc *d)
{
    if (is_float(d)) {                          /* a float subscript: the nearest integer (MF) */
        double x = f_load(p, d); x = x < 0 ? ceil(x - 0.5) : floor(x + 0.5);
        return x >= 2147483647.0 ? 0x7fffffff : x <= -2147483647.0 ? -0x7fffffff : (int)x;
    }
    long long v = cob_get_num(p, d);
    if (d->scale > 0) v = div_pow10(v, d->scale, 0);
    return (int)v;
}

/* ---- PERFORM ---------------------------------------------------------- */

/* PERFORM p THRU q pushes (q's id, return address); the code at the end
 * of every paragraph and section asks whether it is the top exit and, if
 * so, pops and returns there.  Nested and recursive PERFORMs behave like
 * GnuCOBOL's frame stack, not like a single exit cell. */
/* An exit is named by its cell, a word of the compiled program's own for
 * each paragraph and section: it holds the place (from 1) of the topmost
 * frame waiting on that exit, 0 when there is none, and each frame keeps
 * what the cell held before it.  So "is this exit being performed" is one
 * load -- the end of every paragraph asks it, and most are told no without
 * a call -- where it was a search of the activation's frames, in PERFORM
 * and at every paragraph's end (csv2fw, a byte at a time through three
 * levels of PERFORM: 6% of the program; docs/performance.md). */
/* A frame is sixteen bytes so that its place is a shift, and the stack's
 * four words are one structure so that one address reaches them all:
 * PERFORM and the exit it comes back through are counted in instructions
 * (docs/performance.md, 2026-10-02). */
typedef struct { int *cell; void *ret; int prev; int unused; } cob_frame;
struct cob_pf {
    cob_frame *stk;         /* +0: grows, as recursion deepens it */
    int sp, cap;            /* +4, +8 */
    int base;               /* +12: the first frame of the running program's activation */
};
struct cob_pf cob_pf;       /* named, and not static: the entries (entries.s) are written against its layout */
/* ... which a compiler that lays either out differently must not get past */
typedef char cob_frame_is_16_bytes[sizeof(cob_frame) == 16 ? 1 : -1];
typedef char cob_pf_is_4_words[sizeof(struct cob_pf) == 16 ? 1 : -1];
#define pf    cob_pf
#define pstk  pf.stk
#define psp   pf.sp
#define pcap  pf.cap
#define pbase pf.base
/* frames k and above are abandoned: each exit's cell back to what it held */
static void pframes_drop(int k)
{
    while (psp > k) { psp--; *pstk[psp].cell = pstk[psp].prev; }
}

/* Paragraph ids are numbered from 1 in every program, so the frames of a
 * calling program must be out of reach of the called one: without this, a
 * CALL made inside PERFORM P (id k) to a program that performs its own
 * paragraph k found the caller's frame, "abandoned" it, and the caller
 * fell through into the paragraph after P.  Each activation starts its
 * frames above a base, searches no lower, and on return drops them all;
 * a RECURSIVE program's activations are kept apart the same way. */
static int prog_depth;          /* program activations under way: the first is the run unit's own */
int cob_perform_enter(void) { int old = pbase; pbase = psp; prog_depth++; return old; }
void cob_perform_leave(int old) { pframes_drop(pbase); pbase = old; prog_depth--; }
/* is the running program under the control of a calling one (EXIT
 * PROGRAM: X3.23-1985 general rule 1, 2023 14.9.14.4 rule 2) */
int cob_called(void) { return prog_depth > 1; }

/* ---- exception conditions (COBOL 2002 14.6.13; cobol ISSUES-53) -------- */

/* The last exception status: the exception-name, and the statement's name
 * when its checking was turned on WITH LOCATION.  The compiler decides the
 * rest -- whether checking is on, which declarative runs, fatality. */
static char *fn_buffer(int n);
static char ec_last[31], ec_stmt[63];
static const char *ec_loc, *ec_file;   /* EXCEPTION-LOCATION's string (WITH LOCATION), EC-I-O's file-name */
static char ec_io[2];                   /* EC-I-O's I-O status */
static unsigned io_stw;                 /* the last I-O statement's status (below) */
static int ec_any;

void cob_ec_raise(const char *name, const char *stmt, const char *loc, const char *file)
{
    memset(ec_last, ' ', sizeof ec_last); memset(ec_stmt, ' ', sizeof ec_stmt);
    for (int i = 0; name[i] && i < 31; i++) ec_last[i] = (char)toupper((unsigned char)name[i]);
    if (stmt) for (int i = 0; stmt[i] && i < 63; i++) ec_stmt[i] = stmt[i];
    ec_loc = loc; ec_file = file;
    if (file) { ec_io[0] = (char)('0' + (io_stw >> 8)); ec_io[1] = (char)('0' + (io_stw & 255)); }
    ec_any = 1;
}

void cob_ec_clear(void) { ec_any = 0; }

/* Exception propagation (2023 14.9.14 and 14.9.18, RAISING; 7.3.21
 * PROPAGATE).  The ending program hands a condition to its caller:
 * named, or LAST (the condition raised and not yet cleared, if any;
 * name NULL).  An EC-USER name not in the header's RAISING list
 * (allowed: NUL-separated, double NUL at the end) becomes
 * EC-RAISING-NOT-SPECIFIED (14.9.18.4 rule 1b3a).  The caller, when any
 * checking is on at its CALL, asks for the condition by its own table
 * of names and raises it as its own. */
static char ec_prop[64];
void cob_ec_propagate(const char *name, const char *allowed)
{
    char nm[64]; int n = 0;
    if (!name) {
        if (!ec_any) return;                       /* LAST with nothing raised: ignored (rule 1b3b) */
        for (; n < 63 && ec_last[n] != ' '; n++) nm[n] = ec_last[n];
    } else for (; n < 63 && name[n]; n++) nm[n] = (char)toupper((unsigned char)name[n]);
    nm[n] = 0;
    if (!strncmp(nm, "EC-USER", 7)) {
        int ok = 0;
        for (const char *a = allowed; a && *a && !ok; a += strlen(a) + 1) if (!strcasecmp(a, nm)) ok = 1;
        if (!ok) snprintf(nm, sizeof nm, "EC-RAISING-NOT-SPECIFIED");
    }
    snprintf(ec_prop, sizeof ec_prop, "%s", nm);
}
int cob_ec_propagated(const char *names, int n)
{
    if (!ec_prop[0]) return -1;
    /* the caller's enabled names, every level: the condition itself,
     * else its level-2 group (EC-USER-X under EC-USER), else EC-ALL --
     * the caller may not know a user name the callee made up, and
     * checking by the group is what lets it through (14.6.13.1.4) */
    int r = -2, best = 9;
    const char *p = names;
    for (int i = 0; i < n; i++, p += strlen(p) + 1) {
        size_t pl = strlen(p);
        int rank = !strcasecmp(p, ec_prop) ? 0 : (!strncasecmp(p, ec_prop, pl) && ec_prop[pl] == '-') ? 1 : !strcasecmp(p, "EC-ALL") ? 2 : 9;
        if (rank < best) { best = rank; r = i; }
    }
    if (r >= 0) cob_ec_raise(ec_prop, 0, 0, 0);    /* the exact name is the condition that exists */
    ec_prop[0] = 0;
    return r;
}

/* EC-BOUND-REF-MOD: 1 when (start:len) leaves an item of size bytes;
 * len -1 when the length was omitted (the rest of the item) */
static int pos_nonint;
/* EC-ARGUMENT-FUNCTION (2023 15.3): an argument, or the returned value,
 * outside a function's rules.  The function notes it here and returns 0
 * (CHAR a space); the compiled check reads and clears the note when the
 * condition is checked.  Unchecked, that 0 is the implementor's result
 * the rule leaves to us -- GnuCOBOL's too.  X3.23a-1989 left the value
 * undefined and had no exception condition. */
static int fn_argbad;
int cob_fn_argbad(void) { int r = fn_argbad; fn_argbad = 0; return r; }
/* SET's sending value, from cob_pop_pos: 1 when it was not an integer,
 * EC-BOUND-SUBSCRIPT (2023 14.9.39.4 rules 2 and 3); the note cleared */
int cob_pos_nonint(void) { int r = pos_nonint; pos_nonint = 0; return r; }
int cob_bound_refmod(int start, int len, int size)
{
    if (pos_nonint) { pos_nonint = 0; return 1; }
    if (start < 1 || start > size) return 1;
    if (len == -1) return 0;
    return len < 1 || start + len - 1 > size;
}

/* a fatal exception condition, checked and not resumed: abnormal
 * termination of the run unit (14.6.12) */
void cob_ec_abort(void)
{
    char m[80];
    int n = 31; while (n > 0 && ec_last[n - 1] == ' ') n--;
    snprintf(m, sizeof m, "fatal exception condition %.*s", n, ec_last);
    cob_fatal(m);
}

/* An exception-checking PERFORM's raises (2023 14.9.28 rule 20; cobol
 * ISSUES-94 E9): where each WHEN phrase's return resumes, and whether its
 * condition was fatal.  A stack, so a recursive activation's raise in a
 * phrase does not overwrite its caller's.  Entries carry the PERFORM's id
 * and the activation's frame (its sp): a recursive activation runs the
 * same PERFORM with the same id. */
static struct ecp_ent { int id, fatal; void *resume, *frame; } *ecps;
static int necps, ecps_cap;
void cob_ecp_push(int id, void *resume, int fatal, void *frame)
{
    if (necps == ecps_cap) {
        ecps_cap = ecps_cap ? 2 * ecps_cap : 16;
        ecps = realloc(ecps, (size_t)ecps_cap * sizeof *ecps);
        if (!ecps) cob_fatal("out of memory");
    }
    ecps[necps].id = id; ecps[necps].resume = resume; ecps[necps].fatal = fatal; ecps[necps].frame = frame; necps++;
}
/* the end of the last phrase: where to resume; a fatal condition ends
 * the run instead (14.6.13.1.3 rule 4) */
/* RESUME (2023 14.9.33): a declarative or a WHEN phrase that leaves by
 * RESUME AT NEXT STATEMENT recovers from the condition, a fatal one too
 * -- the mark is read where the return would end the run */
static int ec_resumed;
void cob_resume_mark(void) { ec_resumed = 1; }
void cob_ec_abort_unless_resumed(void)
{
    if (ec_resumed) { ec_resumed = 0; return; }
    cob_ec_abort();
}
void *cob_ecp_pop(int id, void *frame)
{
    if (!necps || ecps[necps - 1].id != id || ecps[necps - 1].frame != frame) cob_fatal("exception-checking PERFORM: no raise to return to");
    struct ecp_ent e = ecps[--necps];
    if (e.fatal && !ec_resumed) cob_ec_abort();
    ec_resumed = 0;
    return e.resume;
}
/* the end of the PERFORM: a raise whose phrase left by EXIT PERFORM is
 * dropped -- and a fatal one still ends the run */
void cob_ecp_drop(int id, void *frame)
{
    while (necps && ecps[necps - 1].id == id && ecps[necps - 1].frame == frame) {
        if (ecps[--necps].fatal) cob_ec_abort();
    }
}

char *cob_fn_exception_status(void)
{
    char *b = fn_buffer(31);
    if (ec_any) memcpy(b, ec_last, 31); else memset(b, ' ', 31);
    return b;
}

char *cob_fn_exception_statement(void)
{
    char *b = fn_buffer(63);
    if (ec_any) memcpy(b, ec_stmt, 63); else memset(b, ' ', 63);
    return b;
}

static int fn_var_len;
static char *fn_var_result(const char *s, int n, int national);

/* EXCEPTION-FILE[-N] (2002 15.23, 15.24): the I-O status and the file-name
 * as written in SELECT when the last exception status is EC-I-O, else two
 * zeros; as long as its contents */
char *cob_fn_exception_file(int national)
{
    char t[80]; int n = 2;
    if (ec_any && ec_file) {
        t[0] = ec_io[0]; t[1] = ec_io[1];
        for (int i = 0; ec_file[i] && n < (int)sizeof t; i++) t[n++] = ec_file[i];
    } else t[0] = t[1] = '0';
    return fn_var_result(t, n, national);
}

/* EXCEPTION-FILE[-N] (file-name) (2023 15.28.4 rule 2): the connector's
 * last I-O status and its name as the SELECT clause wrote it; two spaces
 * while it has never been accessed */
char *cob_fn_exception_file_of(cob_file *f, const char *name, int national)
{
    char t[80]; int n = 2;
    if (!f->last_st) { t[0] = t[1] = ' '; return fn_var_result(t, n, national); }
    t[0] = (char)(f->last_st >> 8); t[1] = (char)f->last_st;
    for (int i = 0; name[i] && n < (int)sizeof t; i++) t[n++] = name[i];
    return fn_var_result(t, n, national);
}

/* EXCEPTION-LOCATION[-N] (2002 15.25, 15.26): "program; paragraph OF
 * section; line" when checking was turned on WITH LOCATION, else one
 * space -- this implementation saves no location without it */
char *cob_fn_exception_location(int national)
{
    if (!ec_any || !ec_loc) return fn_var_result(" ", 1, national);
    return fn_var_result(ec_loc, (int)strlen(ec_loc), national);
}

/* ---- activations (COBOL 2002, -std=2002) --------------------------------- */

/* The compiler's activation descriptor (s32-cobc.c emit_act_desc): active
 * count, RECURSIVE flag, program name, the static words an activation owns
 * (saved here and restored on return), then each LOCAL-STORAGE record as
 * cell, initial image, size.  The block holds the saved words and the
 * records; the cells point into it, so a LOCAL-STORAGE item's address may
 * be passed on and stays this activation's (2023 8.6.4). */
typedef struct { int active, recursive; const char *name; char *cache; int nwords; } cob_act_hdr;

/* The outermost activation -- none of this program live, which is nearly
 * every call of a user function -- has nothing to save: the words belong
 * to no other activation, so they are neither copied nor restored, and
 * its block is the descriptor's cached one, kept from call to call
 * instead of a malloc and a free each time (majesty's date functions
 * spent a third of their time here).  A nested activation of the same
 * program saves the words and has a block of its own, as before. */
static __attribute__((noinline)) void act_recursive_call(const cob_act_hdr *h)
{
    char m[160];
    snprintf(m, sizeof m, "EC-PROGRAM-RECURSIVE-CALL: '%s' was called while active and is not RECURSIVE", h->name);
    cob_fatal(m);
}

/* the names of the activations under way, outermost first (FUNCTION
 * MODULE-NAME, 2023 15.65): pushed by cob_act_enter, popped by cob_act_leave */
static const char *act_names[256]; static int act_depth;
void *cob_act_enter(int *desc)
{
    cob_act_hdr *h = (cob_act_hdr *)desc;
    if (h->active && !(h->recursive & 1)) act_recursive_call(h);    /* out of line: its buffer made every call's frame 224 bytes */
    /* a contained program (bit 1) runs as part of its outermost program's
     * module (15.65.4 rules 6, 7, 9): no module of its own on the stack */
    if (act_depth < 256) act_names[act_depth] = (h->recursive & 2) ? NULL : h->name;
    act_depth++;
    /* the unit's INTERMEDIATE ROUNDING (bits 8- of the second word), the caller's kept for the leave */
    if (iround_sp < 256) iround_stack[iround_sp++] = cob_iround;
    cob_iround = h->recursive >> 8;
    int **words = (int **)(desc + 5);
    int *loc = desc + 5 + h->nwords, nl = loc[0];
    if (!h->active && h->cache) {
        /* the outermost again: its cells still point into the kept block
         * (set on its first entry, and restored with the words by any
         * nested activation's leave), so only the initial images go back */
        h->active = 1;
        for (int k = 0; k < nl; k++) {
            const char *image = (const char *)(intptr_t)loc[1 + 3 * k + 1];
            if (image) memcpy(*(char **)(intptr_t)loc[1 + 3 * k], image, (size_t)loc[1 + 3 * k + 2]);
            else if (!loc[1 + 3 * k + 2]) *(char **)(intptr_t)loc[1 + 3 * k] = 0;   /* a BASED entry: NULL again (8.6.5) */
        }
        return h->cache;
    }
    size_t size = (size_t)h->nwords * sizeof(int);
    for (int k = 0; k < nl; k++) size = ((size + 7) & ~(size_t)7) + (size_t)loc[1 + 3 * k + 2];
    int outer = h->active == 0;
    h->active++;
    if (!size) return 0;
    char *b = outer && h->cache ? h->cache : malloc(size);
    if (!b) cob_fatal("EC-STORAGE-NOT-AVAIL: no storage for an activation's LOCAL-STORAGE");
    if (outer) h->cache = b;
    else for (int k = 0; k < h->nwords; k++) ((int *)b)[k] = *words[k];
    size_t at = (size_t)h->nwords * sizeof(int);
    for (int k = 0; k < nl; k++) {
        char **cell = (char **)(intptr_t)loc[1 + 3 * k];
        const char *image = (const char *)(intptr_t)loc[1 + 3 * k + 1];
        int n = loc[1 + 3 * k + 2];
        if (!image && !n) { *cell = 0; continue; }   /* a BASED entry in LOCAL-STORAGE: its cell NULL at each activation (13.18.5.4 rule 2; 8.6.5) */
        at = (at + 7) & ~(size_t)7;
        if (image) memcpy(b + at, image, (size_t)n);  /* none for a function's result temporary */
        *cell = b + at;
        at += (size_t)n;
    }
    return b;
}

void cob_act_leave(int *desc, void *block)
{
    cob_act_hdr *h = (cob_act_hdr *)desc;
    h->active--;
    if (act_depth > 0) act_depth--;
    if (iround_sp > 0) cob_iround = iround_stack[--iround_sp];
    if (!block || block == h->cache) return;      /* the outermost: nothing saved, the block kept */
    int **words = (int **)(desc + 5);
    for (int k = 0; k < h->nwords; k++) *words[k] = ((int *)block)[k];
    free(block);
}

/* PERFORM's push and the exit's pop are small entries in front of the
 * general routines, as READ and WRITE are: a range that is not under way,
 * with room on the stack for its frame, is three stores and two counts,
 * and an exit that is the innermost frame's is two loads and two stores.
 * A function pays for its whole frame on every path, and compiled these
 * were 43 and 30 instructions -- five million times in a program that
 * performs a paragraph for each byte it reads.  Written as entries of
 * their own the C compiler still gave each a frame and three instructions
 * for every word of the stack's state (28 and 25), so they are written
 * out: 17 and 16, no frame, the general routine a jump away with the
 * arguments where they were.  They are in entries.s, which build.sh
 * appends to this file's assembly: the self-hosted cc builds this runtime
 * where there is no LLVM (cctool.sh), and it has no file-scope asm.
 *
 *   void  cob_perform_push(int *cell, void *ret);
 *   void *cob_perform_exit(int *cell);     the place to return to, or 0
 */
void cob_perform_push_rest(int *cell, void *ret);
void *cob_perform_exit_rest(int *cell);
void cob_perform_push(int *cell, void *ret);

void cob_perform_push_rest(int *cell, void *ret)
{
    /* A range already on the stack was left by a GO TO (GLENTER: the S
     * command inside PERFORM 600-GET-ENTRY THRU 690-GET-EXIT goes back to
     * the screen); COBOL forbids performing an active range, so that frame
     * and everything above it are abandoned.  Replacing it keeps the stack
     * bounded by the number of distinct ranges, as the per-paragraph return
     * slots of the classic runtimes are.  A frame at or below the base is
     * another activation's (a recursive program's caller): not this one's. */
    int k = *cell;
    if (k > pbase) pframes_drop(k - 1);
    if (psp == pcap) {
        pcap = pcap ? 2 * pcap : 256;
        pstk = realloc(pstk, (size_t)pcap * sizeof *pstk);
        if (!pstk) cob_fatal("PERFORM stack: out of memory");
    }
    pstk[psp].cell = cell; pstk[psp].ret = ret; pstk[psp].prev = *cell; psp++;
    *cell = psp;
}

/* a USE declarative performed for an exception condition: one already
 * active -- performed and not yet returned -- is EC-FLOW-USE (2023
 * 14.9.49.4 rule 2), a fatal condition; it ends the run whether or not
 * its checking is on (unchecked, the implementor decides, 14.6.13.1.3
 * rule 8), where performing it again would lose its return (cobol
 * ISSUES-94 E14) */
void cob_ec_raise(const char *name, const char *stmt, const char *loc, const char *file);
void cob_ec_abort(void);
void cob_use_push(int *cell, void *ret)
{
    if (*cell > pbase) { cob_ec_raise("EC-FLOW-USE", 0, 0, 0); cob_ec_abort(); }
    cob_perform_push(cell, ret);
}

void *cob_perform_exit_rest(int *cell)
{
    /* The innermost frame, usually; one below it only when a GO TO left a
     * performed paragraph for the enclosing range's exit (Open Systems
     * PAPOST: 745's INVALID KEY GO TO 750 inside PERFORM 705 THRU 750).
     * The abandoned frames above the match are dropped, as the
     * per-paragraph return slots of the classic runtimes would have them.
     * The compiled code calls only when the cell is not zero; a frame of
     * another activation is not this one's exit. */
    int k = *cell;
    if (k <= pbase) return 0;
    void *r = pstk[k - 1].ret;
    pframes_drop(k - 1);
    return r;
}

/* ====================================================================== */
/* Files                                                                   */
/* ====================================================================== */

/* Line sequential and fixed sequential.  The framing is the FD's fact
 * (docs/framing.md): line sequential is payload then '\n', trailing
 * spaces removed on WRITE (GnuCOBOL's convention, and csv2fw's), the
 * record area space-filled beyond a short line on READ, a '\r' before
 * the '\n' dropped.  A line longer than the record area is truncated with
 * status 04 -- not split into further records as GnuCOBOL 4 does. */

/* Why an operation failed, from errno -- the host's, carried over the
 * MMIO ring into the guest's libc (runtime/mmio_request.c).  X3.23-1985
 * VII-3: 35 a non-optional file not present (ENOENT); 37 a file that will
 * not support the open mode (not readable for INPUT, not writable for
 * OUTPUT or EXTEND); 34 a write beyond the file's externally defined
 * boundaries -- here a full device or the file-size limit; 30 anything
 * else.  Before this every failure was 35 or 30, and an OPTIONAL file
 * that could not be read was taken for absent and created anew, over
 * the top of the one that was there (cobol/tests/fault). */
static const char *open_fail_st(int err)
{
    if (err == EACCES || err == EPERM || err == EROFS || err == EISDIR) return "37";
    return "30";
}
static const char *write_fail_st(void)
{
    return errno == ENOSPC || errno == EFBIG ? "34" : "30";
}

static void set_status(cob_file *f, const char *st)
{
    if (f->status) { f->status[0] = st[0]; f->status[1] = st[1]; }
    f->last_st = 0x10000u | ((unsigned)(unsigned char)st[0] << 8) | (unsigned char)st[1];
}

/* 0 success, 1 at end / no record, 2 error.  A hard error with no FILE
 * STATUS to report it in stops the run, as GnuCOBOL does. */
/* DECLARATIVES: the USE AFTER ERROR PROCEDURE section that applies to a
 * file -- its own, else the one for its open mode -- as a paragraph id
 * the compiled code dispatches on; 0 when none */
/* the open mode a USE ... ON INPUT/OUTPUT/I-O/EXTEND procedure is chosen by:
 * the mode the file is open in, or the one the failing OPEN tried */
int cob_open_mode(cob_file *f) { return f->open_mode ? (int)f->open_mode : (int)f->open_try; }

/* An I/O statement's result for the compiler's dispatch: 0 fine, 1 the
 * statement's own condition (AT END, INVALID KEY), 2 an error recorded in
 * a FILE STATUS, 3 an error with no FILE STATUS to record it -- the
 * compiler runs a USE procedure if one applies, else cob_io_unhandled. */
static char cob_last_st[3]; static const char *cob_last_op = "";
/* Every I-O statement's status, for EC-I-O: one word that is zero for 00
 * -- each character less '0', the first above the second -- so that the
 * short entries of READ and WRITE say "fine" with one store. */
static unsigned io_stw;
/* the last I-O status's class for EC-I-O (cobol ISSUES-58): its first digit,
 * or -1 for 00 */
int cob_io_class(void) { return io_stw == 0 ? -1 : (int)(io_stw >> 8); }
static int file_result(cob_file *f, const char *st, const char *what)
{
    io_stw = ((unsigned)(unsigned char)(st[0] - '0') << 8) | (unsigned char)(st[1] - '0');
    set_status(f, st);
    if (st[0] == '0') return 0;
    if (st[0] == '1' || st[0] == '2') return 1;      /* at end; the invalid key condition */
    cob_last_st[0] = st[0]; cob_last_st[1] = st[1]; cob_last_op = what;
    return f->status ? 2 : 3;
}
void cob_io_unhandled(cob_file *f)
{
    (void)f;
    char msg[96];
    int n = 0;
    const char *pre = "file error (status ", *what = cob_last_op;
    while (*pre) msg[n++] = *pre++;
    msg[n++] = cob_last_st[0]; msg[n++] = cob_last_st[1]; msg[n++] = ')'; msg[n++] = ' ';
    while (*what && n < 90) msg[n++] = *what++;
    msg[n] = 0;
    cob_fatal(msg);
}

/* the file's name: the ASSIGN item's content, trailing spaces dropped
 * (2023 12.4.5 GR 3b, dynamic assignment); all spaces, the literal when
 * there is one (ASSIGN TO literal USING data-name: the literal is the
 * name until the item is set -- the implementor's consistency rule), else
 * "", which OPEN turns into 31 */
static const char *file_name(cob_file *f)
{
    static char name[256];
    int n = f->assign_item ? (int)f->assign_len : 0;
    if (n > 255) n = 255;
    while (n > 0 && f->assign_item[n - 1] == ' ') n--;
    if (n == 0) return f->assign ? f->assign : "";
    memcpy(name, f->assign_item, n); name[n] = 0;
    return name;
}

static int idx_open(cob_file *f, int mode);
static int idx_close(cob_file *f);
static int idx_read_next(cob_file *f);
static int idx_write(cob_file *f);
static int rel_read_next(cob_file *f);
static int rel_read_key(cob_file *f);
static int rel_write(cob_file *f, int reclen);
static int rel_rewrite(cob_file *f);
static int rel_delete(cob_file *f);
static int rel_start(cob_file *f, int op);
static unsigned rel_slot_size(cob_file *f);
static void lin_values(cob_file *f);

int cob_open(cob_file *f, int mode)
{
    int reversed = mode & 8; mode &= 7;
    f->reversed = 0;
    if (reversed) {
        if (f->org != COB_ORG_SEQ || f->varying) cob_fatal("OPEN REVERSED needs a sequential file of fixed-length records");
        int rc = cob_open(f, mode);
        if (rc == 0 && f->fp) {
            fseek((FILE *)f->fp, 0, 2);
            long end = ftell((FILE *)f->fp);
            f->fpos = end < 0 ? 0 : (unsigned)end; f->reversed = 1;
        }
        return rc;
    }
    f->open_try = (unsigned)mode;
    if (f->open_mode) return file_result(f, "41", "OPEN of a file already open");
    remember_file(f);          /* every organisation: STOP RUN closes what is left open */
    if (!*file_name(f)) return file_result(f, "31", "the ASSIGN item holds no file name");   /* 9.1.13.6 (2): dynamic assignment with nothing to go on */
    if (f->org == COB_ORG_INDEXED) return idx_open(f, mode);
    const char *name = file_name(f);
    const char *fm = mode == COB_OPEN_INPUT ? "rb" : mode == COB_OPEN_OUTPUT ? "wb"
                   : mode == COB_OPEN_EXTEND ? "ab" : "r+b";
    /* a relative file is addressed by slot, so EXTEND keeps read-write
     * access and positions after the last slot (created when absent) */
    if (f->org == COB_ORG_RELATIVE && mode == COB_OPEN_EXTEND) fm = "r+b";
    if (f->org == COB_ORG_RELATIVE && mode == COB_OPEN_OUTPUT) fm = "w+b";   /* WRITE checks the slot first */
    if (f->locked) return file_result(f, "38", "OPEN of a file closed WITH LOCK");
    FILE *fp;
    int err = 0;
    errno = 0;
    if (mode == COB_OPEN_EXTEND) {           /* "ab" would create it: look first */
        fp = fopen(name, "rb");
        if (fp) { fclose(fp); errno = 0; fp = fopen(name, fm); }
        else if (errno != ENOENT) { errno = 0; fp = fopen(name, fm); }   /* there, but not readable: EXTEND writes */
        else fp = 0;
    } else fp = fopen(name, fm);
    if (!fp) err = errno ? errno : ENOENT;
    /* a file that is there but cannot be opened so: 37 (or 30), whether
     * OPTIONAL or not -- never taken for absent */
    if (!fp && err != ENOENT) return file_result(f, open_fail_st(err), name);
    /* EXTEND or I-O on an absent file: an OPTIONAL one comes into being
     * (05), any other is 35 */
    if (!fp && (mode == COB_OPEN_EXTEND || mode == COB_OPEN_IO)) {
        if (!f->optional) return file_result(f, "35", name);
        fp = fopen(name, "w+b");
        if (fp) {
            f->fp = fp; f->open_mode = (unsigned char)mode; f->at_eof = 0; f->eof_seen = 0; f->last_len = 0; f->fpos = 0;
            f->pr_state = 0;
            if (f->org == COB_ORG_RELATIVE) { f->rel_pos = 1; f->rel_last = 0; }
            return file_result(f, "05", name);
        }
    }
    f->at_eof = 0; f->eof_seen = 0; f->last_len = 0; f->fpos = 0;
    f->rpos = f->rlen = 0; f->pr_state = 0;
    if (fp && f->org == COB_ORG_RELATIVE) {
        f->rel_pos = 1; f->rel_last = 0;
        if (mode == COB_OPEN_EXTEND && fseek(fp, 0, 2) == 0)
            f->rel_pos = (unsigned)(ftell(fp) / (long)rel_slot_size(f)) + 1;
    }
    if (!fp) {
        if (mode == COB_OPEN_INPUT && f->optional) {
            /* OPTIONAL and absent: open succeeds, the first READ is at end */
            f->open_mode = (unsigned char)mode; f->fp = 0; f->at_eof = 1;
            return file_result(f, "05", name);
        }
        if (mode == COB_OPEN_INPUT) return file_result(f, "35", name);
        return file_result(f, "30", name);
    }
    f->fp = fp; f->open_mode = (unsigned char)mode;
    if (mode == COB_OPEN_EXTEND && fseek(fp, 0, 2) == 0) { long e = ftell(fp); f->fpos = e > 0 ? (unsigned)e : 0; }
    if (f->linage) { lin_values(f); f->lin_counter = 1; f->lin_needs_top = 1; f->lin_eop = 0; }
    return file_result(f, "00", name);
}

int cob_close(cob_file *f);

/* UNLOCK file (2023 14.9.47): the record locks released -- there are
 * none here, one user -- and the I-O status set (GR 3): 00 for an open
 * file, 47 for one not open (GR 2) */
int cob_unlock(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "47", "UNLOCK of a file not open");
    return file_result(f, "00", "");
}

/* CLOSE ... WITH NO REWIND on a file that is not on unit media: closed,
 * and the I-O status 07 (2014; 2023 14.9.6.4, 9.1.13: successful, the
 * phrase does not apply to the media) */
int cob_close(cob_file *f);
int cob_close_norewind(cob_file *f)
{
    int r = cob_close(f);
    if (r) return r;
    return file_result(f, "07", "");
}
/* CLOSE ... REEL/UNIT on a file that has no reels: 07 */
int cob_close_reel(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "42", "CLOSE of a file not open");
    return file_result(f, "07", "");
}

/* CLOSE ... WITH LOCK: the file cannot be opened again in this run */
int cob_close_lock(cob_file *f)
{
    int r = cob_close(f);
    if (r == 0) f->locked = 1;
    return r;
}

int cob_close(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "42", "CLOSE of a file not open");
    if (f->org == COB_ORG_INDEXED) return idx_close(f);
    if (f->fp && f->pr_state >= 2) fputc('\n', (FILE *)f->fp);   /* the printer's last line (pr_advance) */
    f->pr_state = 0;
    /* the last buffered records are written here: a device full now is a
     * permanent error (30), not the 00 it was -- the file closes either
     * way (X3.23-1985 VII-3; cobol/tests/fault) */
    int bad = 0;
    errno = 0;
    if (f->fp) bad = fclose((FILE *)f->fp) != 0;
    f->fp = 0; f->open_mode = 0; f->at_eof = 0;
    f->fast_r1 = f->fast_r = f->fast_w1 = f->fast_w = 0;     /* READ and WRITE ask again */
    if (f->rbuf) { free(f->rbuf); f->rbuf = 0; }
    f->rpos = f->rlen = 0;
    return file_result(f, bad ? "30" : "00", bad ? "close: buffered records not written" : "");
}

/* A line sequential file whose records are national (cobol ISSUES-74;
 * the compiler marks it varying = 2, a field line sequential files do
 * not otherwise use) holds UTF-8 text, as every text file here does.
 * READ decodes a line into national characters, padded with national
 * spaces (2023 14.9.30 rule 15): a byte that is not UTF-8 becomes U+FFFD
 * and the status is 09, a line of more characters than the record holds
 * is truncated, 04, the rest dropped -- as the alphanumeric line
 * sequential READ does, and GnuCOBOL.  Rule 15 goes on to say 06, with the
 * rest of the line left for the next READ; that is ISSUES-94 N8, for
 * -std=2002, both kinds of record.  WRITE encodes the record, trailing national spaces
 * dropped as spaces are (14.9.51 rule 21); a lone surrogate has no UTF-8
 * form, and the WRITE fails with 71 (rule 23).  Each runs the ordinary
 * line sequential code once over a UTF-8 buffer, marked varying = 3. */
int cob_read(cob_file *f);
int cob_write(cob_file *f, int before, int after, int reclen);
static int ls_national(cob_file *f) { return f->org == COB_ORG_LINESEQ && (f->varying & 3) == 2; }
/* 2023 14.9.30 rule 15, which the compiler asks for under -std=2002 by
 * setting 4 in a line sequential file's varying (cobol ISSUES-94 N8): a
 * line longer than the record fills it, the status is 06, and the rest
 * of the line is left for the next READ.  Otherwise the rest is dropped
 * and the status is 04, as GnuCOBOL does and majesty reads. */
static int ls_rule15(const cob_file *f) { return f->org == COB_ORG_LINESEQ && (f->varying & 4); }
static int ls_read_national_r15(cob_file *f);

static int ls_read_national(cob_file *f)
{
    if (ls_rule15(f)) return ls_read_national_r15(f);
    char *rec = f->record; unsigned n = f->recsize, nch = n / 2, cap = nch * 4 + 8;
    char *t = malloc(cap); if (!t) cob_fatal("out of memory");
    unsigned v = f->varying;
    f->record = t; f->recsize = cap; f->varying = 3;
    int r = cob_read(f);
    f->record = rec; f->recsize = n; f->varying = v;
    if (f->last_len == 0 && f->at_eof) { free(t); return r; }   /* 10, 46: nothing read */
    int trunc = io_stw == 4;                                    /* 04 */
    unsigned short *u = malloc((size_t)(cap + 1) * sizeof *u); if (!u) cob_fatal("out of memory");
    int save = nat_bad; nat_bad = 0;
    int k = utf8_to_nat((const unsigned char *)t, (int)f->last_len, u, (int)cap);
    int bad = nat_bad; nat_bad = save;
    if (k > (int)nch) { k = (int)nch; trunc = 1; }
    for (int i = 0; i < (int)nch; i++) nat_put((unsigned char *)rec, i, i < k ? u[i] : 0x20);
    f->last_len = (unsigned)(2 * k);
    free(u); free(t);
    return file_result(f, trunc ? "04" : bad ? "09" : "00", "");
}

/* rule 15 for national records: the line is decoded a character at a
 * time out of the read buffer, and READ stops before a character the
 * record has no room for (a pair needs two positions, which its first
 * byte tells), leaving it and the rest of the line for the next READ */
static int ls_peek(cob_file *f)
{
    if (f->rpos >= f->rlen) {
        size_t got = fread(f->rbuf, 1, COB_RBUF, (FILE *)f->fp);
        if (!got) return -1;
        f->rpos = 0; f->rlen = (unsigned)got;
    }
    return (unsigned char)f->rbuf[f->rpos];
}
static void ls_take(cob_file *f) { f->rpos++; f->fpos++; }

static int ls_read_national_r15(cob_file *f)
{
    if (f->at_eof) {                    /* as cob_read, which has checked the open mode */
        f->last_len = 0;
        if (f->eof_seen) return file_result(f, "46", "");
        f->eof_seen = 1;
        return file_result(f, "10", "");
    }
    if (!f->rbuf) { f->rbuf = malloc(COB_RBUF); f->rpos = f->rlen = 0; if (!f->rbuf) cob_fatal("out of memory"); }
    unsigned char *rec = (unsigned char *)f->record;
    unsigned nch = f->recsize / 2, k = 0;
    int any = 0, bad = 0, full = 0, save = nat_bad;
    s32u_dec d = { 0, 0, 0, 0 };
    unsigned char sb[4]; int sn = 0;
    for (;;) {
        int b = ls_peek(f);
        uint32_t cp;
        if (b < 0) {
            if (s32u_dec_end(&d, &cp)) { bad = 1; if (k < nch) nat_put(rec, k++, nat_repl); }
            break;
        }
        any = 1;
        if (!d.need) {
            if (b == '\n') { ls_take(f); break; }
            if (b == '\r') {
                ls_take(f);
                if (ls_peek(f) == '\n') { ls_take(f); break; }
                if (k < nch) { nat_put(rec, k++, 0x0D); continue; }
                full = 1; break;
            }
            if (k + (b >= 0xF0 && b <= 0xF4 ? 2u : 1u) > nch) { full = 1; break; }
            sn = 0;
        }
        int r = s32u_dec_byte(&d, (unsigned)b, &cp);
        if (r != 2) { ls_take(f); if (sn < 4) sb[sn++] = (unsigned char)b; }
        if (!r) continue;
        if (cp == S32U_REPL && !(sn == 3 && sb[0] == 0xEF && sb[1] == 0xBF && sb[2] == 0xBD)) { bad = 1; cp = nat_repl; }
        unsigned char u[4];
        int nu = s32u_u16_put(u, cp);
        for (int q = 0; q < nu && k < nch; q++) nat_put(rec, k++, (unsigned)(u[2 * q] << 8 | u[2 * q + 1]));
        sn = 0;
    }
    nat_bad = save;
    if (!any) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
    f->last_len = 2 * k;
    for (unsigned q = k; q < nch; q++) nat_put(rec, q, 0x20);
    return file_result(f, full ? "06" : bad ? "09" : "00", "");
}

static int ls_write_national(cob_file *f, int before, int after, int reclen)
{
    const unsigned char *rec = (const unsigned char *)f->record; unsigned n = f->recsize, nch = n / 2;
    for (unsigned i = 0; i < nch; i++) {
        unsigned u = nat_at(rec, (int)i);
        if (u >= 0xD800 && u <= 0xDBFF && i + 1 < nch && nat_at(rec, (int)i + 1) >= 0xDC00 && nat_at(rec, (int)i + 1) <= 0xDFFF) { i++; continue; }
        if (u >= 0xD800 && u <= 0xDFFF) return file_result(f, "71", "a lone surrogate has no UTF-8 form");
    }
    char *t = malloc((size_t)nch * 3 + 1); if (!t) cob_fatal("out of memory");
    unsigned k = (unsigned)nat_to_utf8(rec, (int)nch, t);
    char *save = f->record;
    unsigned v = f->varying;
    f->record = t; f->recsize = k; f->varying = 3;
    int r = cob_write(f, before, after, reclen);
    f->record = save; f->recsize = n; f->varying = v;
    free(t);
    return r;
}
/* FD CODE-SET (X3.23-1985 3.4; 2023 13.18.13): the record's characters
 * converted to the medium's code on output -- a copy, the record area
 * keeps its own -- and back in place on input */
static const char *cs_out(cob_file *f, const char *rec, unsigned len)
{
    static unsigned char *buf; static unsigned cap;
    if (!f->code_out || !len) return rec;
    if (len > cap) { unsigned char *nb = realloc(buf, len); if (!nb) cob_fatal("out of memory"); buf = nb; cap = len; }
    for (unsigned i = 0; i < len; i++) buf[i] = f->code_out[(unsigned char)rec[i]];
    return (const char *)buf;
}
static void cs_in(cob_file *f, char *rec, unsigned len)
{
    if (!f->code_in) return;
    for (unsigned i = 0; i < len; i++) rec[i] = (char)f->code_in[(unsigned char)rec[i]];
}


static int idx_read_prev(cob_file *f);
static int rel_read_prev(cob_file *f);
/* READ PREVIOUS of a sequential file of fixed-length records (2023
 * 14.9.30): the record before the current one -- fpos stands past the
 * current record, so the one before it starts two records back -- and
 * it becomes the current one; after a START (started), the record at
 * fpos itself (14.9.41 GR 20-21).  The input block buffer is given up:
 * the position moves against it. */
static int seq_read_prev(cob_file *f)
{
    FILE *fp = f->fp;
    unsigned n = f->recsize;
    if (f->varying) return file_result(f, "30", "READ PREVIOUS of variable-length records");
    if (f->at_eof) { if (f->eof_seen) return file_result(f, "46", ""); f->eof_seen = 1; return file_result(f, "10", ""); }
    if (f->rbuf) { f->rpos = f->rlen = 0; }
    f->fast_r = f->fast_r1 = 0;
    unsigned at;
    if (f->started) { at = f->fpos; f->started = 0; }
    else {
        if (f->fpos < 2 * n) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
        at = f->fpos - 2 * n;
    }
    fseek(fp, (long)at, 0);
    if (fread(f->record, 1, n, fp) != n) return file_result(f, "30", "read");
    cs_in(f, (char *)f->record, n);
    f->fpos = at + n; f->last_len = n;
    return file_result(f, "00", "");
}

int cob_read_prev(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "47", "READ of a file not open");
    if (f->open_mode == COB_OPEN_OUTPUT || f->open_mode == COB_OPEN_EXTEND)
        return file_result(f, "47", "READ of a file open for output");
    if (f->org == COB_ORG_INDEXED) return idx_read_prev(f);
    if (f->org == COB_ORG_RELATIVE) return rel_read_prev(f);
    if (f->org == COB_ORG_SEQ) return seq_read_prev(f);
    cob_fatal("READ PREVIOUS of a line sequential file");
    return 0;
}

/* START FIRST / LAST of a sequential file (14.9.41 GR 20-21): the file
 * position at its first or last record, which the next READ, NEXT or
 * PREVIOUS, reads; no records, 23.  Fixed-length records by size; RDW
 * records by walking them. */
static int seq_start(cob_file *f, int op)
{
    FILE *fp = f->fp;
    unsigned n = f->recsize;
    if (f->rbuf) { f->rpos = f->rlen = 0; }
    f->fast_r = f->fast_r1 = 0;
    fseek(fp, 0, 2);
    long size = ftell(fp);
    if (size <= 0) { fseek(fp, 0, 0); f->fpos = 0; return file_result(f, "23", ""); }
    unsigned at = 0;
    if (op == 6) {
        if (!f->varying) at = (unsigned)((size - 1) / n * n);          /* the last record's start */
        else {
            unsigned pos = 0; unsigned char rdw[4];
            fseek(fp, 0, 0);
            for (;;) {
                if (fread(rdw, 1, 4, fp) < 4) break;
                unsigned len = ((unsigned)rdw[0] << 8) | rdw[1];
                if (len < 4 || pos + len > (unsigned)size) break;
                at = pos; pos += len; fseek(fp, (long)pos, 0);
            }
        }
    }
    fseek(fp, (long)at, 0);
    f->fpos = at; f->started = 1; f->at_eof = 0; f->eof_seen = 0;
    return file_result(f, "00", "");
}


/* The short entries of READ and WRITE.  A program that reads a file a
 * character at a time and writes another the same way (majesty's CSV
 * converter: 2.6 million READs, 4.4 million WRITEs) is in these two
 * routines for every byte, and what a record costs is what is asked about
 * the file before a byte moves.  So it is asked once.  The first record
 * goes the whole way round -- the organization, the open mode, variable
 * records, REVERSED, CODE-SET, LINAGE, what kind of stream the libc gave
 * -- and what that found is left in the file's fast_ flags; CLOSE takes
 * them away.  After that
 *
 *   cob_read, cob_write    a one-byte record: one flag, one test that
 *                          the buffer has the byte (or the room), the
 *                          byte, the counts, the status.  No call, so no
 *                          frame: 28 and 27 instructions, which were 55,
 *                          and 52 and fwrite's 26.
 *   cob_read_n, _write_n   any other fixed length: the same with a
 *                          memcpy, and a frame for it.
 *   cob_read_rest, ...     everything else, and whatever the buffer
 *                          cannot settle: filling it, the end, a short
 *                          last record, a stream that must be emptied
 *                          (fwrite's, where a full device is found out).
 *
 * Each is a jump from the one before with the arguments where they were
 * (the backend makes tail calls), so the routine with seventeen saved
 * registers is paid for only when it runs.
 *
 * A WRITE stores into the stream's own buffer (__s32_out_room,
 * <stdio.h>): the same bytes at the same places fwrite would put them,
 * the buffer emptied by fwrite at the same record. */
#ifndef __S32_STREAM_ROOM       /* some other C library: every record through fwrite */
#define __s32_out_plain(s) 1
#define __s32_out_room(s, n) ((char *)0)
#define __s32_out_byte(s, c) 0
#endif
static __attribute__((noinline)) int cob_read_n(cob_file *f);
static __attribute__((noinline)) int cob_read_rest(cob_file *f);
int cob_read(cob_file *f)
{
    if (f->fast_r1) {
        unsigned pos = f->rpos;
        if (pos != f->rlen) {
            f->record[0] = f->rbuf[pos];
            char *st = f->status;
            f->rpos = pos + 1; f->fpos++; f->last_len = 1;
            io_stw = 0;
            if (st) { st[0] = '0'; st[1] = '0'; }
            return 0;
        }
    }
    return cob_read_n(f);
}
static __attribute__((noinline)) int cob_read_n(cob_file *f)
{
    if (f->fast_r) {
        unsigned n = f->recsize;
        if (f->rlen - f->rpos >= n) {
            memcpy(f->record, f->rbuf + f->rpos, n);
            char *st = f->status;
            f->rpos += n; f->fpos += n; f->last_len = n;
            io_stw = 0;
            if (st) { st[0] = '0'; st[1] = '0'; }
            return 0;
        }
    }
    return cob_read_rest(f);
}
static __attribute__((noinline)) int cob_read_rest(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "47", "READ of a file not open");
    if (f->open_mode == COB_OPEN_OUTPUT || f->open_mode == COB_OPEN_EXTEND)
        return file_result(f, "47", "READ of a file open for output");
    if (ls_national(f)) return ls_read_national(f);
    if (f->org == COB_ORG_INDEXED) return idx_read_next(f);
    if (f->org == COB_ORG_RELATIVE) return rel_read_next(f);
    if (f->at_eof) {
        /* the end: 10 the first time, 46 for every READ after it */
        f->last_len = 0;
        if (f->eof_seen) return file_result(f, "46", "");
        f->eof_seen = 1;
        return file_result(f, "10", "");
    }
    FILE *fp = (FILE *)f->fp;
    char *rec = f->record;
    unsigned n = f->recsize;

    if (f->org == COB_ORG_SEQ && f->varying) {
        /* mode V: the four-byte RDW tapemgr writes -- 2 bytes big-endian
         * length including the RDW, 2 zero bytes -- then the payload.  The
         * record area beyond a short record is left as it was (cobc370's
         * rule: move, do not promise the tail). */
        unsigned char rdw[4];
        size_t got = fread(rdw, 1, 4, fp);
        if (got == 0) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
        if (got < 4) return file_result(f, "30", "truncated RDW");
        unsigned len = ((unsigned)rdw[0] << 8) | rdw[1];
        if (len < 4) return file_result(f, "30", "bad RDW");
        len -= 4;
        unsigned take = len < n ? len : n;
        if (fread(rec, 1, take, fp) != take) return file_result(f, "30", "truncated record");
        cs_in(f, rec, take);
        f->fpos += 4 + len;
        if (len > n) { fseek(fp, (long)f->fpos, 0); }
        f->last_len = take;
        if (f->dep_item) cob_put_num(f->dep_item, (const cob_desc *)f->dep_desc, (long long)take, 0);
        return file_result(f, len > n ? "04" : "00", "");
    }
    if (f->org == COB_ORG_SEQ && f->reversed) {
        /* REVERSED: the record before the position, the position moved back */
        if (f->fpos < n) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
        f->fpos -= n;
        fseek(fp, (long)f->fpos, 0);
        if (fread(rec, 1, n, fp) != n) return file_result(f, "30", "read");
        cs_in(f, rec, n);
        f->last_len = n;
        return file_result(f, "00", "");
    }
    if (f->org == COB_ORG_SEQ) {
        size_t got;
        f->started = 0;                         /* a START's position: this read takes the record there, as any next one */
        if (f->open_mode == COB_OPEN_INPUT && n <= COB_RBUF / 4) {
            /* open for input only, so nothing else moves the file's
             * position: records out of the runtime's own block buffer, as
             * the line sequential read below has them.  A short record
             * through fread is a hundred-odd instructions before a byte
             * moves, and a program that reads a file a character at a time
             * pays that for every character (docs/performance.md). */
            if (!f->rbuf) { f->rbuf = malloc(COB_RBUF); f->rpos = f->rlen = 0; if (!f->rbuf) cob_fatal("out of memory"); }
            unsigned have = f->rlen - f->rpos;
            if (have < n) {
                if (have) memmove(f->rbuf, f->rbuf + f->rpos, have);
                f->rpos = 0;
                f->rlen = have + (unsigned)fread(f->rbuf + have, 1, COB_RBUF - have, fp);
                have = f->rlen;
            }
            got = have < n ? have : n;
            if (got == 1) rec[0] = f->rbuf[f->rpos]; else if (got) memcpy(rec, f->rbuf + f->rpos, got);
            f->rpos += (unsigned)got;
            if (got == n && !f->code_in) {
                /* and the next one need not come this far (the short entries) */
                f->fast_r = 1; if (n == 1) f->fast_r1 = 1;
                f->fpos += n; f->last_len = n;
                io_stw = 0;
                if (f->status) { f->status[0] = '0'; f->status[1] = '0'; }
                return 0;
            }
        } else got = fread(rec, 1, n, fp);
        if (got == 0) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
        cs_in(f, rec, (unsigned)got);
        f->fpos += (unsigned)got;
        if (got < n) { memset(rec + got, ' ', n - got); f->last_len = (unsigned)got; return file_result(f, "04", ""); }
        f->last_len = n;
        return file_result(f, "00", "");
    }

    /* line sequential: the bytes to the newline, out of a block buffer of
     * the runtime's own -- a byte through fgetc is thirty-odd instructions
     * on this target, a memchr over a block about three */
    if (!f->rbuf) { f->rbuf = malloc(COB_RBUF); f->rpos = f->rlen = 0; if (!f->rbuf) cob_fatal("out of memory"); }
    unsigned i = 0; int truncated = 0, any = 0, r15 = ls_rule15(f);
    for (;;) {
        if (f->rpos >= f->rlen) {
            size_t got = fread(f->rbuf, 1, COB_RBUF, fp);
            if (got == 0) break;
            f->rpos = 0; f->rlen = (unsigned)got;
        }
        any = 1;
        unsigned char *s = (unsigned char *)f->rbuf + f->rpos, *e = memchr(s, '\n', f->rlen - f->rpos);
        unsigned take = e ? (unsigned)(e - s) : f->rlen - f->rpos;
        if (take && r15 && take > n - i) {
            unsigned c = n - i;
            memcpy(rec + i, s, c); i += c;
            if (e && take == c + 1 && s[c] == '\r') {
                /* the line fills the record exactly and ends CR LF: 00 */
                f->rpos += take + 1; f->fpos += take + 1;
                break;
            }
            /* rule 15: the record is full before the line ends; the rest
             * stays in the buffer for the next READ */
            f->rpos += c; f->fpos += c;
            f->last_len = i;
            return file_result(f, "06", "");
        }
        if (take) {
            if (i < n) { unsigned c = take < n - i ? take : n - i; memcpy(rec + i, s, c); i += c; if (c < take) truncated = 1; }
            else truncated = 1;
        }
        f->rpos += take + (e ? 1 : 0);
        f->fpos += take + (e ? 1 : 0);
        if (e) break;
    }
    if (!any) { f->at_eof = 1; f->eof_seen = 1; f->last_len = 0; return file_result(f, "10", ""); }
    if (i > 0 && rec[i - 1] == '\r') i--;
    f->last_len = i;
    if (i < n) memset(rec + i, ' ', n - i);
    return file_result(f, truncated ? "04" : "00", "");
}

/* ---- LINAGE: the logical page of a print file ------------------------- */
/* The page is lin_top blank lines, lin_lines lines the records go on, and
 * lin_bot blank lines; LINAGE-COUNTER is the line the device stands on.
 * The steps below are GnuCOBOL's (fileio.c, cob_linage_write_opt), so the
 * bytes and the counter agree with the oracle: a WRITE AFTER n LINES adds
 * n to the counter and n-1 blank lines before the record; past the last
 * line it fills the page, the bottom and the next top and starts at 1;
 * END-OF-PAGE is the footing reached or the page overflowed. */

static unsigned lin_value(cob_file *f, int which)
{
    const unsigned *t = (const unsigned *)f->linage + which * 3;
    if (t[1]) { long long v = cob_get_num((const void *)(size_t)t[1], (const cob_desc *)(size_t)t[2]); return v > 0 ? (unsigned)v : 0; }
    return t[0];
}

static void lin_values(cob_file *f)
{
    f->lin_lines = lin_value(f, 0); f->lin_foot = lin_value(f, 1); f->lin_top = lin_value(f, 2); f->lin_bot = lin_value(f, 3);
    if (f->lin_lines < 1) f->lin_lines = 1;
    if (f->lin_foot > f->lin_lines) f->lin_foot = 0;
}

static void lin_newlines(cob_file *f, unsigned n) { FILE *fp = (FILE *)f->fp; for (unsigned i = 0; i < n; i++) fputc('\n', fp); f->fpos += n; }

static void lin_new_page(cob_file *f, unsigned from)
{
    if (from < f->lin_lines) lin_newlines(f, f->lin_lines - from);
    lin_newlines(f, f->lin_bot);
    lin_values(f);
    lin_newlines(f, f->lin_top);
    f->lin_counter = 1;
}

/* ADVANCING n LINES on a LINAGE file, before or after the record */
static void lin_lines_opt(cob_file *f, unsigned n)
{
    unsigned was = f->lin_counter;
    f->lin_counter += n;
    if (f->lin_foot && f->lin_counter >= f->lin_foot) f->lin_eop = 1;
    if (f->lin_counter > f->lin_lines) { f->lin_eop = 1; lin_new_page(f, was); }
    else if (n > 1) lin_newlines(f, n - 1);
}

static int lin_write(cob_file *f, int before, int after)
{
    FILE *fp = (FILE *)f->fp;
    const char *rec = f->record;
    unsigned n = f->recsize;
    f->lin_eop = 0;
    if (f->lin_needs_top) { lin_newlines(f, f->lin_top); f->lin_needs_top = 0; }
    if (before == 0 && after == 0) after = 1;               /* no ADVANCING phrase: BEFORE ADVANCING 1 */
    /* a record's own newline is one line of movement: the BEFORE phrase's
     * first line, or the AFTER phrase's.  After a WRITE whose BEFORE took
     * it, an AFTER n is n whole lines (pr_state, the print file's cursor,
     * says so for a LINAGE file; found with 2023's BEFORE and AFTER
     * together, which puts both on one record) */
    if (before < 0) lin_new_page(f, f->lin_counter);       /* AFTER ADVANCING PAGE */
    else if (before > 0) { if (f->pr_state) lin_newlines(f, 1); lin_lines_opt(f, (unsigned)before); }
    f->pr_state = 0;
    /* the whole record, trailing spaces included (GnuCOBOL keeps them on a LINAGE file) */
    if (fwrite(rec, 1, n, fp) != n) return file_result(f, write_fail_st(), "write failed");
    fputc('\n', fp); f->fpos += n + 1;
    if (after < 0) lin_new_page(f, f->lin_counter);        /* BEFORE ADVANCING PAGE */
    else if (after > 0) { lin_lines_opt(f, (unsigned)after); f->pr_state = 1; }
    f->last_len = 0;
    return file_result(f, "00", "");
}

/* before/after: extra newlines around the record (ADVANCING); reclen:
 * the size of the 01 the WRITE named, which is the length of a mode-V
 * record unless DEPENDING ON says otherwise */
/* The short entries: see cob_read.  (The rest of WRITE -- the print
 * file's carriage, the variable records, the other organizations -- needs
 * a frame of seventeen saved registers, and a function pays for its frame
 * whichever path it takes: docs/performance.md.) */
static __attribute__((noinline)) int cob_write_n(cob_file *f, int before, int after, int reclen);
static __attribute__((noinline)) int cob_write_rest(cob_file *f, int before, int after, int reclen);
/* WRITE ... AFTER n BEFORE m (2023 14.9.51: both phrases): the BEFORE
 * count for the next cob_write of a print file, whose encoding carries
 * one phrase; a LINAGE file's write takes both counts itself */
static int pr_also_before = -1;
void cob_write_also_before(int n) { pr_also_before = n; }
int cob_write(cob_file *f, int before, int after, int reclen)
{
    if (f->fast_w1) {
        /* (last_len, the length the last READ delivered, is 0 since OPEN:
         * nothing is read from a file open for output) */
        if (__s32_out_byte((FILE *)f->fp, f->record[0])) {
            char *st = f->status;
            f->fpos++;
            io_stw = 0;
            if (st) { st[0] = '0'; st[1] = '0'; }
            return 0;
        }
    }
    return cob_write_n(f, before, after, reclen);
}
static __attribute__((noinline)) int cob_write_n(cob_file *f, int before, int after, int reclen)
{
    if (f->fast_w) {
        unsigned n = f->recsize;
        char *p = __s32_out_room((FILE *)f->fp, n);
        if (p) memcpy(p, f->record, n);
        else if (fwrite(f->record, 1, n, (FILE *)f->fp) != n) return file_result(f, write_fail_st(), "write failed");
        char *st = f->status;
        f->fpos += n;
        io_stw = 0;
        if (st) { st[0] = '0'; st[1] = '0'; }
        return 0;
    }
    return cob_write_rest(f, before, after, reclen);
}
static __attribute__((noinline)) int cob_write_rest(cob_file *f, int before, int after, int reclen)
{
    if (!f->open_mode) return file_result(f, "48", "WRITE of a file not open");
    if (f->open_mode == COB_OPEN_INPUT) return file_result(f, "48", "WRITE of a file open for input");
    if (f->open_mode == COB_OPEN_IO && (f->org == COB_ORG_SEQ || f->org == COB_ORG_LINESEQ))
        return file_result(f, "48", "WRITE of a sequential file open I-O");
    if (f->org == COB_ORG_INDEXED) return idx_write(f);
    if (f->org == COB_ORG_RELATIVE) return rel_write(f, reclen);
    if (ls_national(f)) return ls_write_national(f, before, after, reclen);
    if (f->linage) return lin_write(f, before, after);
    FILE *fp = (FILE *)f->fp;
    const char *rec = f->record;
    unsigned n = f->recsize;
    if (f->org == COB_ORG_SEQ && f->varying) {
        unsigned len = reclen > 0 ? (unsigned)reclen : n;
        if (f->dep_item) {
            long long d = cob_get_num(f->dep_item, (const cob_desc *)f->dep_desc);
            if (d < (long long)f->minlen || d > (long long)n) return file_result(f, "44", "record length outside RECORD VARYING bounds");
            len = (unsigned)d;
        }
        unsigned char rdw[4] = { (unsigned char)((len + 4) >> 8), (unsigned char)((len + 4) & 255), 0, 0 };
        if (fwrite(rdw, 1, 4, fp) != 4 || fwrite(cs_out(f, rec, len), 1, len, fp) != len) return file_result(f, write_fail_st(), "write failed");
        f->fpos += 4 + len; f->last_len = 0;
        return file_result(f, "00", "");
    }
    if (f->org == COB_ORG_SEQ) {
        if (fwrite(cs_out(f, rec, n), 1, n, fp) != n) return file_result(f, write_fail_st(), "write failed");
        f->fpos += n; f->last_len = 0;
        /* a fixed-length record, open OUTPUT or EXTEND (the tests above),
         * nothing to translate, a stream that can be stored into: the next
         * one need not come this far (the short entries) */
        if (!f->code_out && __s32_out_plain(fp)) { f->fast_w = 1; if (n == 1) f->fast_w1 = 1; }
        return file_result(f, "00", "");
    }
    /* A print file is a line printer (cobol ISSUES-46).  The cursor sits on
     * the line last printed: AFTER n moves it n lines and prints there,
     * BEFORE n prints where it is and then moves it.  So a record's
     * newline is not written with it but when the cursor next moves --
     * by then it is known whether the next record goes below it or on
     * top of it.  Printing on a line that already carries ink is an
     * overprint, written as a carriage return: a printer, a terminal or
     * col(1) lays the second record over the first (SQ101M's WRITE
     * ADVANCING 0 tests; the forms-alignment line of ARINVCS and its
     * kind).  Where a file begins, and after BEFORE PAGE, the cursor is
     * above the first line: the first AFTER n lands n-1 lines down, so a
     * file opens on its first record as it always has here (GnuCOBOL
     * starts one line lower; a ruling, not yet read against the text).
     *
     * Encoding from the compiler: before = AFTER's count - 1, after =
     * BEFORE's, -1 for PAGE, -2 for zero lines; before = -3 marks a
     * BEFORE phrase, whose count is then in after; 0/0 is no ADVANCING,
     * which prints as AFTER 1. */
    enum { PR_TOP, PR_FRESH, PR_OPEN, PR_INK };
    int is_before = before == -3 || (before == 0 && after != 0);
    int also = pr_also_before; pr_also_before = -1;          /* BEFORE n beside an AFTER phrase (2023): the trailing move */
    int k = is_before ? after : before;
    int cnt = k == -1 ? -1 : k == -2 ? 0 : k + 1;
    if (before == 0 && after == 0) cnt = 1;
    unsigned st = f->pr_state;
    #define PR_PUT(c) do { fputc((c), fp); f->fpos++; } while (0)
    if (!is_before) {
        if (cnt == -1) { if (st >= PR_OPEN) PR_PUT('\n'); PR_PUT('\f'); st = PR_OPEN; }
        else if (st == PR_TOP) { for (int i = 1; i < cnt; i++) PR_PUT('\n'); st = PR_OPEN; }
        else if (cnt == 0) { if (st == PR_INK) PR_PUT('\r'); else st = PR_OPEN; }
        else { for (int i = 0; i < cnt; i++) PR_PUT('\n'); st = PR_OPEN; }
    } else {
        if (st == PR_INK) PR_PUT('\r');
        else st = PR_OPEN;
    }
    while (n > 0 && rec[n - 1] == ' ') n--;
    if (n && fwrite(rec, 1, n, fp) != n) return file_result(f, write_fail_st(), "write failed");
    f->fpos += n;
    if (n) st = PR_INK;
    if (is_before) {
        if (cnt == -1) { PR_PUT('\n'); PR_PUT('\f'); st = PR_TOP; }
        else if (cnt > 0) { for (int i = 0; i < cnt; i++) PR_PUT('\n'); st = PR_FRESH; }
    } else if (also > 0) { for (int i = 0; i < also; i++) PR_PUT('\n'); st = PR_FRESH; }
    #undef PR_PUT
    f->pr_state = st;
    f->last_len = 0;
    return file_result(f, "00", "");
}

/* ====================================================================== */
/* Relative I-O.  The file is fixed slots of 4 + recsize bytes; record n  */
/* is slot n.  A slot's four-byte prefix is the RDW our mode-V files      */
/* carry (big-endian length including the four, then two zero bytes),    */
/* all zero for an empty slot -- so a relative file is a sequence of     */
/* fixed-length V records, and a deleted record is unambiguous.          */
/* (GnuCOBOL 4 keeps an 8-byte native length there; docs/oracles.md.)    */
/* ====================================================================== */

static unsigned rel_slot_size(cob_file *f) { return 4 + f->recsize; }

static long rel_key_value(cob_file *f)
{
    if (!f->rel_key) return 0;
    return (long)cob_get_num(f->rel_key, (const cob_desc *)f->rel_key_desc);
}

static void rel_key_set(cob_file *f, unsigned n)
{
    if (f->rel_key) cob_put_num(f->rel_key, (const cob_desc *)f->rel_key_desc, (long long)n, 0);
}

/* the slot's state: 1 holds a record (read into the area when into_area),
 * 0 empty, -1 beyond the end of the file, -2 an I/O error */
static int rel_slot_get(cob_file *f, unsigned n, int into_area)
{
    FILE *fp = (FILE *)f->fp;
    unsigned char rdw[4];
    if (n < 1) return -1;
    if (fseek(fp, (long)(n - 1) * (long)rel_slot_size(f), 0) != 0) return -2;
    size_t got = fread(rdw, 1, 4, fp);
    if (got == 0) return -1;
    if (got < 4) return -2;
    unsigned len = ((unsigned)rdw[0] << 8) | rdw[1];
    if (len == 0) return 0;
    if (!into_area) return 1;
    if (len < 4) return -2;
    len -= 4;
    if (len > f->recsize) len = f->recsize;
    if (fread(f->record, 1, len, fp) != len) return -2;
    f->last_len = len;
    if (f->dep_item) cob_put_num(f->dep_item, (const cob_desc *)f->dep_desc, (long long)len, 0);
    return 1;
}

/* write slot n from the record area -- len bytes of it, the RDW saying so,
 * the rest of the slot zero -- or mark it empty; slots between the end of
 * the file and n come into being empty */
static int rel_slot_put(cob_file *f, unsigned n, int empty, unsigned len)
{
    FILE *fp = (FILE *)f->fp;
    unsigned sz = rel_slot_size(f);
    static const unsigned char zero[64];
    if (fseek(fp, 0, 2) != 0) return 0;
    long end = ftell(fp), want = (long)(n - 1) * (long)sz;
    for (long left = want - end; left > 0; ) {
        size_t k = left > 64 ? 64 : (size_t)left;
        if (fwrite(zero, 1, k, fp) != k) return 0;
        left -= (long)k;
    }
    if (fseek(fp, want, 0) != 0) return 0;
    unsigned char rdw[4] = { 0, 0, 0, 0 };
    if (empty) len = 0;
    if (len > f->recsize) len = f->recsize;
    if (!empty) { rdw[0] = (unsigned char)((len + 4) >> 8); rdw[1] = (unsigned char)((len + 4) & 255); }
    if (fwrite(rdw, 1, 4, fp) != 4) return 0;
    if (len && fwrite(f->record, 1, len, fp) != len) return 0;
    for (unsigned left = f->recsize - len; left > 0; ) {
        size_t k = left > 64 ? 64 : left;
        if (fwrite(zero, 1, k, fp) != k) return 0;
        left -= (unsigned)k;
    }
    fflush(fp);
    return 1;
}

static unsigned rel_slot_count(cob_file *f)
{
    FILE *fp = (FILE *)f->fp;
    if (fseek(fp, 0, 2) != 0) return 0;
    return (unsigned)(ftell(fp) / (long)rel_slot_size(f));
}

/* READ [NEXT]: the next slot that holds a record; the key item learns its number */
static int rel_read_next(cob_file *f)
{
    if (f->at_eof) {
        if (f->eof_seen) return file_result(f, "46", "");
        f->eof_seen = 1; return file_result(f, "10", "");
    }
    for (unsigned n = f->rel_pos; ; n++) {
        int r = rel_slot_get(f, n, 1);
        if (r == -2) return file_result(f, "30", "read failed");
        if (r == -1) { f->at_eof = 1; f->eof_seen = 1; f->rel_last = 0; return file_result(f, "10", ""); }
        if (r == 0) continue;
        if (f->rel_key) {       /* a record number the RELATIVE KEY item cannot hold: 14 */
            int kd = ((const cob_desc *)f->rel_key_desc)->digits;
            if (kd > 0 && kd < 10 && (long long)n >= pow10tab[kd]) { f->rel_pos = n + 1; return file_result(f, "14", ""); }
        }
        f->rel_last = n; f->rel_pos = n + 1;
        rel_key_set(f, n);
        return file_result(f, "00", "");
    }
}

/* READ PREVIOUS, relative (2023 14.9.30.4 GR 21, relative b-c): after
 * OPEN or START the record the position indicator selects, as NEXT
 * would; after a READ the existing record with the next lower number */
static int rel_read_prev(cob_file *f)
{
    if (f->at_eof) {
        if (f->eof_seen) return file_result(f, "46", "");
        f->eof_seen = 1; return file_result(f, "10", "");
    }
    if (!f->rel_last) return rel_read_next(f);
    for (unsigned n = f->rel_last - 1; n >= 1; n--) {
        int r = rel_slot_get(f, n, 1);
        if (r == -2) return file_result(f, "30", "read failed");
        if (r <= 0) continue;
        f->rel_last = n; f->rel_pos = n + 1;
        rel_key_set(f, n);
        return file_result(f, "00", "");
    }
    f->at_eof = 1; f->eof_seen = 1; f->rel_last = 0;
    return file_result(f, "10", "");
}

/* READ (random): the record the RELATIVE KEY names */
static int rel_read_key(cob_file *f)
{
    long k = rel_key_value(f);
    if (k < 1) { f->rel_last = 0; return file_result(f, "23", ""); }
    int r = rel_slot_get(f, (unsigned)k, 1);
    if (r == -2) return file_result(f, "30", "read failed");
    if (r <= 0) { f->rel_last = 0; return file_result(f, "23", ""); }
    f->rel_last = (unsigned)k; f->rel_pos = (unsigned)k + 1; f->at_eof = 0;
    return file_result(f, "00", "");
}

/* the length a WRITE records: DEPENDING ON's value, else the 01 named,
 * else the record area (a relative file may hold variable-length records;
 * the slot stays the maximum) */
static int rel_write_len(cob_file *f, int reclen, unsigned *len)
{
    *len = reclen > 0 ? (unsigned)reclen : f->recsize;
    if (f->dep_item) {
        long long d = cob_get_num(f->dep_item, (const cob_desc *)f->dep_desc);
        if (d < (long long)f->minlen || d > (long long)f->recsize) return file_result(f, "44", "record length outside RECORD VARYING bounds");
        *len = (unsigned)d;
    }
    return 0;
}

/* WRITE: sequential access fills the next slot and tells the key item;
 * random access takes the slot the key names -- occupied is 22, 0 is 24 */
static int rel_write(cob_file *f, int reclen)
{
    unsigned n, len; int rc;
    if ((rc = rel_write_len(f, reclen, &len))) return rc;
    if (f->access == 0) n = f->rel_pos;
    else {
        long k = rel_key_value(f);
        if (k < 1) return file_result(f, "24", "");
        n = (unsigned)k;
        int r = rel_slot_get(f, n, 0);
        if (r == -2) return file_result(f, "30", "read failed");
        if (r == 1) return file_result(f, "22", "");
    }
    if (f->access == 0 && f->rel_key) {
        /* the record number must fit the RELATIVE KEY item */
        int kd = ((const cob_desc *)f->rel_key_desc)->digits;
        if (kd > 0 && kd < 10 && (long long)n >= pow10tab[kd]) return file_result(f, "14", "");
    }
    if (!rel_slot_put(f, n, 0, len)) return file_result(f, write_fail_st(), "write failed");
    if (f->access == 0) { f->rel_pos = n + 1; rel_key_set(f, n); }
    return file_result(f, "00", "");
}

/* the slot REWRITE/DELETE act on: the last READ under sequential access
 * (43 when there was none), the key's under random or dynamic (23 absent) */
static int rel_target(cob_file *f, unsigned *n)
{
    if (f->access == 0) {
        if (!f->rel_last) return file_result(f, "43", "");
        *n = f->rel_last;
    } else {
        long k = rel_key_value(f);
        if (k < 1) return file_result(f, "23", "");
        *n = (unsigned)k;
    }
    int r = rel_slot_get(f, *n, 0);
    if (r == -2) return file_result(f, "30", "read failed");
    if (r <= 0) return file_result(f, "23", "");
    return 0;
}

static int rel_rewrite(cob_file *f)
{
    unsigned n, len; int rc = rel_target(f, &n);
    if (rc) return rc;
    if ((rc = rel_write_len(f, 0, &len))) return rc;
    if (!rel_slot_put(f, n, 0, len)) return file_result(f, write_fail_st(), "write failed");
    return file_result(f, "00", "");
}

static int rel_delete(cob_file *f)
{
    unsigned n; int rc = rel_target(f, &n);
    if (rc) return rc;
    if (!rel_slot_put(f, n, 1, 0)) return file_result(f, write_fail_st(), "write failed");
    f->rel_last = 0;
    return file_result(f, "00", "");
}

/* START: position on the first (or, for < and <=, the last) occupied slot
 * in the relation to the key; the key item is left alone */
static int rel_start(cob_file *f, int op)
{
    unsigned count = rel_slot_count(f), found = 0;
    if (op == 5 || op == 6) {
        /* FIRST, LAST (GR 11-12): the first or last existing record */
        if (op == 5) { for (unsigned n = 1; n <= count && !found; n++) if (rel_slot_get(f, n, 0) == 1) found = n; }
        else { for (unsigned n = count; n >= 1 && !found; n--) if (rel_slot_get(f, n, 0) == 1) found = n; }
        if (!found) return file_result(f, "23", "");
        f->rel_pos = found; f->rel_last = 0; f->at_eof = 0;
        return file_result(f, "00", "");
    }
    long k = rel_key_value(f);
    if (op == 3 || op == 4) {
        long from = op == 3 ? k - 1 : k;
        if (from > (long)count) from = (long)count;
        for (long n = from; n >= 1 && !found; n--) if (rel_slot_get(f, (unsigned)n, 0) == 1) found = (unsigned)n;
    } else {
        long from = op == 1 ? k + 1 : k;
        if (from < 1) from = 1;
        if (op == 0) { if (k >= 1 && rel_slot_get(f, (unsigned)k, 0) == 1) found = (unsigned)k; }
        else for (long n = from; n <= (long)count && !found; n++) if (rel_slot_get(f, (unsigned)n, 0) == 1) found = (unsigned)n;
    }
    if (!found) return file_result(f, "23", "");
    f->rel_pos = found; f->rel_last = 0; f->at_eof = 0;
    return file_result(f, "00", "");
}

/* ====================================================================== */
/* SORT (Sort-Merge, the file form).  The SD is a cob_file of              */
/* organization SORT; while a SORT statement runs, its records live in     */
/* memory behind the SD's idx pointer.  USING reads a file through the    */
/* ordinary READ, GIVING writes through the ordinary WRITE, so the        */
/* input and output files keep their own organizations and framings.     */
/* The sort is a merge sort on an index array: stable, which is what     */
/* WITH DUPLICATES IN ORDER asks for and costs nothing to give always.   */
/* ====================================================================== */

typedef struct {
    const cob_sort_key *keys; int nkeys;
    const unsigned char *coll;      /* SORT ... COLLATING SEQUENCE: the alphabet's ranks, or 0 */
    unsigned klen;                  /* the normalized key (below) */
    unsigned char *kbuf;            /* one key, built at RELEASE */
    unsigned n;                     /* records released: the arrival number */
    xsort xs;                       /* the engine: entries of klen + recsize */
    int sorted;                     /* cob_sort_perform ran */
    cob_file **giving; int ngiving; /* GIVING files, opened; written at cob_sort_end */
} cob_sorter;

/* The sort's memory: half the heap the program was linked with, or
 * S32_SORT_MEMORY (bytes, or with a K/M suffix) -- there is no sbrk,
 * so this is a share of a fixed pool, not a request for more.  The
 * fan-in is S32_SORT_FAN, default 32 (the emulator has 128 descriptors). */
extern char __heap_start[];
extern char __heap_end[];
static size_t sort_budget(void)
{
    const char *e = getenv("S32_SORT_MEMORY");
    if (e && *e) {
        char *end; unsigned long v = strtoul(e, &end, 10);
        if (*end == 'K' || *end == 'k') v <<= 10; else if (*end == 'M' || *end == 'm') v <<= 20;
        if (v >= 4096) return v;
    }
    size_t heap = (size_t)(__heap_end - __heap_start);
    return heap / 2;
}
static unsigned sort_fan(void)
{
    const char *e = getenv("S32_SORT_FAN");
    unsigned f = e && *e ? (unsigned)atoi(e) : 32;
    return f < 2 ? 2 : f > 100 ? 100 : f;
}

/* The normalized key: every SORT key rendered as bytes whose unsigned
 * byte order IS the COBOL order, so one memcmp compares a record on all
 * its keys at once (what DFSORT does; cob_cmp per key per comparison
 * was the sort's whole cost).  A numeric key becomes its cob_get_num
 * value as eight big-endian bytes with the sign bit flipped -- every
 * record of a key shares the descriptor, so the scale is common and
 * needs no alignment, and cob_cmp on two numerics is exactly this
 * order.  Any other key is its bytes through the collating sequence,
 * which is cmp_bytes on equal lengths.  A DESCENDING key's bytes are
 * complemented.  The arrival number trails every key, so equal keys
 * stay in RELEASE order: WITH DUPLICATES IN ORDER for free, and the
 * merge needs no tie-break of its own. */
static unsigned sort_klen(const cob_sorter *so)
{
    unsigned k = 4;
    for (int i = 0; i < so->nkeys; i++) {
        const cob_desc *d = so->keys[i].desc;
        k += d->cat == COB_NUM || d->cat == COB_NUM_ED ? (is_wide(d) ? 16 : 8) : d->size;
    }
    return k;
}

static void sort_key_build(const cob_sorter *so, const char *rec, unsigned seq, unsigned char *out)
{
    const unsigned char *t = so->coll ? so->coll : cob_collating;
    for (int i = 0; i < so->nkeys; i++) {
        const cob_sort_key *k = &so->keys[i];
        const cob_desc *d = k->desc;
        unsigned char *o = out;
        if ((d->cat == COB_NUM || d->cat == COB_NUM_ED) && is_wide(d)) {
            /* past 18 digits: the 128-bit two's complement, sign bit
             * flipped, big-endian -- memcmp order is the numeric order */
            cob_wnum w; cob_wget(rec + k->offset, d, &w);
            wl_t m[WL]; memcpy(m, w.m, sizeof m);
            if (w.neg) { for (int j = 0; j < WL; j++) m[j] = ~m[j]; wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(m, one, WL); }
            m[WL - 1] ^= 0x80000000u;
            for (int b = 0; b < 16; b++) o[b] = (unsigned char)(m[(15 - b) / 4] >> (8 * ((15 - b) % 4)));
            out += 16;
        } else if (is_float(d) || is_sfloat(d)) {
            /* a float: its double's bits, negatives complemented, positives
             * with the sign bit set -- memcmp order is the numeric order
             * (a software float by its nearest double: 15 digits of order) */
            double x = num_dbl(rec + k->offset, d); unsigned long long u;
            if (x == 0) x = 0;                      /* -0 sorts with 0 */
            memcpy(&u, &x, 8);
            u = (u >> 63) ? ~u : u | (1ULL << 63);
            for (int b = 7; b >= 0; b--) { o[b] = (unsigned char)u; u >>= 8; }
            out += 8;
        } else if (d->cat == COB_NUM || d->cat == COB_NUM_ED) {
            unsigned long long u = (unsigned long long)cob_get_num(rec + k->offset, d) ^ (1ULL << 63);
            for (int b = 7; b >= 0; b--) { o[b] = (unsigned char)u; u >>= 8; }
            out += 8;
        } else {
            const unsigned char *p = (const unsigned char *)rec + k->offset;
            unsigned n = d->size;
            if (t) for (unsigned b = 0; b < n; b++) o[b] = t[p[b]];
            else memcpy(o, p, n);
            out += n;
        }
        if (k->descending) for (unsigned char *q = o; q < out; q++) *q = (unsigned char)~*q;
    }
    out[0] = (unsigned char)(seq >> 24); out[1] = (unsigned char)(seq >> 16);
    out[2] = (unsigned char)(seq >> 8);  out[3] = (unsigned char)seq;
}

/* SORT of a table (COBOL 2002; 2023 14.9.40 format 2): the n
 * occurrences at base, stride bytes apart, put in order in place.  Each
 * gets its normalized key (the file SORT's, with its occurrence number
 * trailing, so equal keys keep their order); the keys are merge-sorted
 * with memcmp and the occurrences moved once through a copy. */
static unsigned char *tsort_keys; static unsigned tsort_klen;
static void tsort_merge(unsigned *a, unsigned *tmp, unsigned n)
{
    if (n < 2) return;
    unsigned h = n / 2;
    tsort_merge(a, tmp, h); tsort_merge(a + h, tmp, n - h);
    unsigned i = 0, j = h, k = 0;
    while (i < h && j < n)
        tmp[k++] = memcmp(tsort_keys + (size_t)a[i] * tsort_klen, tsort_keys + (size_t)a[j] * tsort_klen, tsort_klen) <= 0 ? a[i++] : a[j++];
    while (i < h) tmp[k++] = a[i++];
    while (j < n) tmp[k++] = a[j++];
    memcpy(a, tmp, n * sizeof *a);
}
void cob_sort_table(char *base, int n, int stride, const cob_sort_key *keys, int nkeys, const unsigned char *coll)
{
    if (n < 2 || stride < 1) return;
    cob_sorter so; memset(&so, 0, sizeof so);
    so.keys = keys; so.nkeys = nkeys; so.coll = coll;
    unsigned kl = sort_klen(&so);
    unsigned char *kb = malloc((size_t)n * kl);
    unsigned *ix = malloc((size_t)n * 2 * sizeof *ix);
    char *copy = malloc((size_t)n * (size_t)stride);
    if (!kb || !ix || !copy) cob_fatal("SORT of a table: out of memory");
    for (int i = 0; i < n; i++) { sort_key_build(&so, base + (size_t)i * stride, (unsigned)i, kb + (size_t)i * kl); ix[i] = (unsigned)i; }
    tsort_keys = kb; tsort_klen = kl;
    tsort_merge(ix, ix + n, (unsigned)n);
    memcpy(copy, base, (size_t)n * (size_t)stride);
    for (int i = 0; i < n; i++) memcpy(base + (size_t)i * stride, copy + (size_t)ix[i] * stride, (size_t)stride);
    free(kb); free(ix); free(copy);
}

static int cob_sorts_active;        /* sorts and merges under way (EC-SORT-MERGE-ACTIVE) */
void cob_sort_begin(cob_file *sd, const cob_sort_key *keys, int nkeys, int dups, const unsigned char *coll)
{
    (void)dups;
    if (sd->org != COB_ORG_SORT) cob_fatal("SORT of a file that is not an SD");
    cob_sorter *so = calloc(1, sizeof *so);
    if (!so) cob_fatal("SORT: out of memory");
    so->keys = keys; so->nkeys = nkeys; so->coll = coll;
    so->klen = sort_klen(so);
    so->kbuf = malloc(so->klen);
    if (!so->kbuf) cob_fatal("SORT: out of memory");
    xs_init(&so->xs, so->klen + sd->recsize, so->klen, sort_budget(), sort_fan(), file_name(sd), cob_fatal);
    sd->idx = so; sd->open_mode = COB_OPEN_IO; sd->at_eof = 0;
    cob_sorts_active++;
}

static cob_sorter *sorter_of(cob_file *sd, const char *what)
{
    if (sd->org != COB_ORG_SORT || !sd->idx) { char m[80]; snprintf(m, sizeof m, "%s outside a SORT of its SD", what); cob_fatal(m); }
    return (cob_sorter *)sd->idx;
}
/* what the compiler asks before RELEASE, RETURN, SORT and MERGE when a
 * sort condition's checking is on: the SD's sort is under way (else
 * EC-FLOW-RELEASE / -RETURN); its at end has been delivered
 * (EC-SORT-MERGE-RETURN); any sort or merge is under way
 * (EC-SORT-MERGE-ACTIVE); a MERGE USING file was out of order
 * (EC-SORT-MERGE-SEQUENCE) */
int cob_sort_under_way(cob_file *sd) { return sd->org == COB_ORG_SORT && sd->idx != NULL; }
int cob_sort_at_end(cob_file *sd) { return sd->at_eof; }
int cob_sort_any_active(void) { return cob_sorts_active; }
static int cob_merge_seq_err;
int cob_merge_sequence_error(void) { int e = cob_merge_seq_err; cob_merge_seq_err = 0; return e; }

/* RELEASE: the SD's record area joins the set to be sorted */
void cob_release(cob_file *sd)
{
    cob_sorter *so = sorter_of(sd, "RELEASE");
    sort_key_build(so, sd->record, so->n, so->kbuf);
    xs_put(&so->xs, so->kbuf, sd->record);
    so->n++;
}

/* a record moves between a file's area and the SD's as a group MOVE would */
static void sort_copy(char *dst, unsigned dn, const char *src, unsigned sn)
{
    unsigned k = sn < dn ? sn : dn;
    memcpy(dst, src, k);
    if (k < dn) memset(dst + k, ' ', dn - k);
}

/* USING: every record of a file, read as that file reads */
void cob_sort_using(cob_file *sd, cob_file *in)
{
    cob_sorter *so = sorter_of(sd, "SORT USING");
    (void)so;
    if (cob_open(in, COB_OPEN_INPUT) == 2) cob_fatal("SORT USING: cannot open the input file");
    for (;;) {
        int r = cob_read(in);
        if (r == 1) break;
        if (r == 2) cob_fatal("SORT USING: read failed");
        sort_copy(sd->record, sd->recsize, in->record, in->last_len ? in->last_len : in->recsize);
        cob_release(sd);
    }
    cob_close(in);
}

/* MERGE USING: a file already in key order joins as presorted runs */
void cob_merge_using(cob_file *sd, cob_file *in)
{
    cob_sorter *so = sorter_of(sd, "MERGE USING");
    xs_source_begin(&so->xs);
    if (cob_open(in, COB_OPEN_INPUT) == 2) cob_fatal("MERGE USING: cannot open the input file");
    unsigned char *prev = malloc(so->klen); int have = 0;
    for (;;) {
        int r = cob_read(in);
        if (r == 1) break;
        if (r == 2) cob_fatal("MERGE USING: read failed");
        sort_copy(sd->record, sd->recsize, in->record, in->last_len ? in->last_len : in->recsize);
        cob_release(sd);
        /* each USING file is in key order already (2023 14.9.24.4 rule 6):
         * a record before its predecessor is EC-SORT-MERGE-SEQUENCE, which
         * the compiler raises after this call when its checking is on;
         * the keys compare by memcmp, the sequence number last */
        if (prev) {
            if (have && memcmp(prev, so->kbuf, so->klen - 4) > 0) cob_merge_seq_err = 1;
            memcpy(prev, so->kbuf, so->klen); have = 1;
        }
    }
    free(prev);
    cob_close(in);
    xs_source_end(&so->xs);
}

void cob_sort_perform(cob_file *sd)
{
    cob_sorter *so = sorter_of(sd, "SORT");
    xs_finish(&so->xs);
    so->sorted = 1; sd->at_eof = 0;
}

/* GIVING: each file named is opened here and registered; the records
 * are written at cob_sort_end, which the compiler emits right after the
 * last GIVING in the same statement.  The sorted stream can be read once
 * (xsort merges runs off disk), and every GIVING file gets every record,
 * so one pass writes each record to all of them.  Writing per file here
 * drained the stream into the first and left the rest empty (CCVS-85
 * ST147A, a MERGE with three GIVING files; cobol ISSUES-42). */
void cob_sort_giving(cob_file *sd, cob_file *out)
{
    cob_sorter *so = sorter_of(sd, "SORT GIVING");
    if (cob_open(out, COB_OPEN_OUTPUT) == 2) cob_fatal("SORT GIVING: cannot open the output file");
    cob_file **g = realloc(so->giving, (size_t)(so->ngiving + 1) * sizeof *g);
    if (!g) cob_fatal("SORT GIVING: out of memory");
    so->giving = g; so->giving[so->ngiving++] = out;
}

static void sort_write_giving(cob_file *sd, cob_sorter *so)
{
    const unsigned char *e;
    while ((e = xs_next(&so->xs)) != 0)
        for (int i = 0; i < so->ngiving; i++) {
            cob_file *out = so->giving[i];
            sort_copy(out->record, out->recsize, (const char *)e + so->klen, sd->recsize);
            if (cob_write(out, 0, 0, 0) == 2) cob_fatal("SORT GIVING: write failed");
        }
    for (int i = 0; i < so->ngiving; i++) cob_close(so->giving[i]);
}

/* RETURN: the next sorted record into the SD's area; 1 at end */
int cob_return(cob_file *sd)
{
    cob_sorter *so = sorter_of(sd, "RETURN");
    if (!so->sorted) cob_fatal("RETURN before the sort (RETURN belongs in the OUTPUT PROCEDURE)");
    const unsigned char *e = xs_next(&so->xs);
    if (!e) { sd->at_eof = 1; return file_result(sd, "10", ""); }
    memcpy(sd->record, e + so->klen, sd->recsize);
    sd->last_len = sd->recsize;
    return file_result(sd, "00", "");
}

void cob_sort_end(cob_file *sd)
{
    cob_sorter *so = sorter_of(sd, "SORT");
    if (so->ngiving) sort_write_giving(sd, so);
    free(so->giving);
    xs_free(&so->xs); free(so->kbuf); free(so);
    sd->idx = 0; sd->open_mode = 0;
    if (cob_sorts_active) cob_sorts_active--;
}

/* MOVE of a group whose last child is an OCCURS DEPENDING ON table: the
 * sending length is base + n occurrences of elem; the receiver's is what
 * it was laid out at (its maximum) */
void cob_move_odo(const void *src, void *dst, int n, int dstlen, int base, int elem)
{
    if (n < 0) n = 0;
    cob_move_alnum(src, base + n * elem, dst, dstlen, 0);
}

int cob_odo_length(int d, int base, int elem) { return d < 0 ? base : base + d * elem; }
/* the table a bit array: base and the stride in bits, bits the element's; the bytes the whole spans */
int cob_odo_length_bits(int d, int base, int stride, int bits) { return (base + (d > 0 ? (d - 1) * stride + bits : 0) + 7) / 8; }

/* SPECIAL-NAMES SWITCH-1..8: from the environment at start (cob_init), then SET */
int cob_switches[8];

/* ====================================================================== */
/* STRING                                                                  */
/* ====================================================================== */

/* w: a character's bytes, 2 when the operands are national (cobol
 * ISSUES-69); pos is a byte position, POINTER counts characters */
static struct { char *dst; int dlen, pos, overflow, w; } cs;

/* pos is the 1-based POINTER value, 1 when there is none.  One out of
 * range is the overflow only when a character comes to be moved: the
 * test is made "before each move of a character" (X3.23-1985 VI-133,
 * STRING general rule 9; the same words in 2002 and 2023), so a STRING
 * whose sources give nothing to move does not overflow.  Then nothing
 * moves and the POINTER keeps its value (rule 7).  A POINTER below 1
 * breaks rule 5, which the text leaves undefined: the overflow at once,
 * as GnuCOBOL and Micro Focus give it. */
void cob_str_begin(char *dst, int dlen, int pos)
{
    cs.dst = dst; cs.dlen = dlen; cs.overflow = pos < 1; cs.w = 1;
    cs.pos = pos;
}

void cob_str_begin_nat(char *dst, int dlen, int pos)
{
    cs.dst = dst; cs.dlen = dlen; cs.overflow = pos < 1; cs.w = 2;
    cs.pos = 2 * (pos - 1) + 1;
}

/* delim of length dn; dn == 0 means DELIMITED BY SIZE */
void cob_str_src(const char *s, int n, const char *delim, int dn)
{
    if (cs.overflow) return;
    int take = n, w = cs.w;
    if (dn) {                                   /* the first byte in line, memcmp only on a match */
        for (int i = 0; i + dn <= n; i += w)
            if (s[i] == delim[0] && !memcmp(s + i, delim, dn)) { take = i; break; }
    }
    /* the characters that fit, in one copy; any left over is the overflow
     * (the character-at-a-time loop this replaces stopped at the first
     * character that did not fit, having moved the ones before it) */
    int chars = take / w, room = cs.pos >= 1 && cs.pos - 1 <= cs.dlen ? (cs.dlen - (cs.pos - 1)) / w : 0;
    int moved = chars < room ? chars : room;
    if (moved > 0) memcpy(cs.dst + cs.pos - 1, s, (size_t)(moved * w));
    cs.pos += moved * w;
    if (chars > room) cs.overflow = 1;
}

int cob_str_pointer(void) { return (cs.pos - 1) / cs.w + 1; }
int cob_str_overflow(void) { return cs.overflow; }

/* ---- UNSTRING ---------------------------------------------------------
 * begin (source, its length, the POINTER or 1), the DELIMITED BY list,
 * then one call per receiver: the characters up to the leftmost
 * delimiter (the first listed wins at equal positions; ALL takes the
 * repeats too) go to the receiver by the MOVE rules, the delimiter to
 * DELIMITER IN, their count to COUNT IN.  Receivers left over when the
 * source is exhausted are untouched; source left over when the
 * receivers are is the overflow, as is a POINTER outside the source. */
static struct {
    const char *src; int slen, pos, overflow, tally, moved, w;     /* w, pos: as STRING's */
    struct { const char *p; int n, all; } d[16]; int nd;
} cu;

void cob_unstr_begin(const char *src, int slen, int pos)
{
    cu.src = src; cu.slen = slen; cu.overflow = 0; cu.tally = 0; cu.nd = 0; cu.moved = 0; cu.w = 1;
    cu.pos = pos;
    if (cu.pos < 1 || cu.pos > slen) cu.overflow = 1;
}

void cob_unstr_begin_nat(const char *src, int slen, int pos)
{
    cu.src = src; cu.slen = slen; cu.overflow = 0; cu.tally = 0; cu.nd = 0; cu.moved = 0; cu.w = 2;
    if (pos < 1 || pos > slen / 2) cu.overflow = 1;
    cu.pos = 2 * (pos - 1) + 1;
}
void cob_unstr_setlen(int slen) { cu.slen = slen; if (cu.pos > slen) cu.overflow = 1; }
void cob_unstr_delim(const char *p, int n, int all)
{
    if (cu.nd == 16) cob_fatal("UNSTRING: more than 16 delimiters");
    cu.d[cu.nd].p = p; cu.d[cu.nd].n = n; cu.d[cu.nd].all = all; cu.nd++;
}
void cob_unstr_into(void *dst, const cob_desc *dd, void *ddst, const cob_desc *ddd, void *cdst, const cob_desc *cdd)
{
    if (cu.overflow || cu.pos > cu.slen) return;
    int start = cu.pos - 1, i = start, hit = -1;
    if (cu.nd == 0) {
        /* no DELIMITED BY: as many characters as the receiver holds (one
         * fewer for a separate sign), each cu.w bytes of the source (2023
         * 14.9.48.4 rule 11b: size in character positions; ISSUES-94 N5) */
        int chars = dd->cat == COB_NATIONAL || dd->usage == COB_U_NATIONAL ? (int)dd->size / 2 : (int)dd->size;
        int room = chars - ((dd->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL)) ? 1 : 0);
        if (room < 0) room = 0;
        i = start + room * cu.w; if (i > cu.slen) i = cu.slen;
    } else if (cu.nd == 1 && cu.d[0].n == 1 && cu.w == 1) {
        /* one delimiter of one byte, the common case: a plain scan */
        char c = cu.d[0].p[0];
        while (i < cu.slen && cu.src[i] != c) i++;
        if (i < cu.slen) hit = 0;
    } else {
        for (; i < cu.slen && hit < 0; i += cu.w)
            for (int k = 0; k < cu.nd; k++)
                if (cu.d[k].n && i + cu.d[k].n <= cu.slen && cu.src[i] == cu.d[k].p[0] &&
                    !memcmp(cu.src + i, cu.d[k].p, cu.d[k].n)) { hit = k; break; }
        if (hit >= 0) i -= cu.w;                /* the delimiter's position */
    }
    int k = i - start;                          /* the examined bytes */
    cob_desc sd; memset(&sd, 0, sizeof sd); sd.cat = cu.w == 2 ? COB_NATIONAL : COB_ALNUM; sd.size = (unsigned)k;
    if (k) cob_move(cu.src + start, &sd, dst, dd);
    else { sd.cat = COB_ALNUM; sd.size = 1; cob_move(dd->cat == COB_NUM || dd->cat == COB_NUM_ED ? "0" : " ", &sd, dst, dd); sd.cat = cu.w == 2 ? COB_NATIONAL : COB_ALNUM; }
    if (cdst) cob_put_num(cdst, cdd, k / cu.w, 0);  /* COUNT IN: characters */
    if (hit >= 0) {
        int dn = cu.d[hit].n;
        if (ddst) { sd.size = (unsigned)dn; cob_move(cu.d[hit].p, &sd, ddst, ddd); }
        i += dn;
        if (cu.d[hit].all) while (i + dn <= cu.slen && !memcmp(cu.src + i, cu.d[hit].p, dn)) i += dn;
    } else if (ddst) { sd.cat = COB_ALNUM; sd.size = 1; cob_move(" ", &sd, ddst, ddd); }
    cu.pos = i + 1;
    cu.tally++; cu.moved = 1;
}
int cob_unstr_pointer(void) { return (cu.pos - 1) / cu.w + 1; }
int cob_unstr_tally(void) { return cu.tally; }
int cob_unstr_overflow(void) { return cu.overflow || cu.pos <= cu.slen; }

/* an integer into any numeric item */
void cob_store_int(void *p, const cob_desc *d, int v) { cob_put_num(p, d, v, 0); }

/* ====================================================================== */
/* Intrinsic functions                                                     */
/* ====================================================================== */

static char fnbuf[4][8192];
static int fnrot;

static char *fn_buffer(int n)
{
    if (n > 8192) cob_fatal("intrinsic function result longer than 8192 bytes");
    char *b = fnbuf[fnrot++ & 3];
    return b;
}

/* ---- run-time-length results (COBOL 2002; cobol ISSUES-64) ------------ */

/* NATIONAL-OF and DISPLAY-OF return as many characters as their argument
 * converts to.  The compiler takes the length of the one just evaluated
 * from here, as a descriptor for a CALL-style operand or as a count. */
static int fn_conv_bad;                         /* a checked conversion substituted: EC-DATA-CONVERSION */

int cob_fn_last_len(void) { return fn_var_len; }

/* a function result reference-modified at computed positions (cobol
 * ISSUES-91): full bytes (-1: the result's own run-time length), start and
 * len in characters of unit bytes (len -1: to the end; a computed 0 is
 * out of range, ISSUES-94 E2).  The part's length is recorded as a
 * run-time-length result's; one outside the result is clamped to it and
 * noted, for EC-BOUND-REF-MOD -- as is a position that was no integer */
static int fn_rm_bad;
char *cob_fn_rm(char *p, int full, int start, int len, int unit)
{
    int chars = (full < 0 ? fn_var_len : full) / unit;
    fn_rm_bad = pos_nonint; pos_nonint = 0;
    if (start < 1 || start > chars) { fn_rm_bad = 1; start = start < 1 ? 1 : chars + 1; }
    if (len == -1) len = chars - start + 1;
    if (len < 1 || start - 1 + len > chars) { fn_rm_bad = 1; len = chars - start + 1; if (len < 0) len = 0; }
    fn_var_len = len * unit;
    return p + (start - 1) * unit;
}
int cob_fn_rm_bad(void) { return fn_rm_bad; }

/* a run-time-length result reference-modified to its end: n bytes skipped
 * (cobol ISSUES-88); a start past the end leaves nothing */
char *cob_fn_var_skip(char *p, int n)
{
    fn_rm_bad = n >= fn_var_len;                    /* the start is past the result's end (E3) */
    fn_var_len = fn_var_len > n ? fn_var_len - n : 0;
    return p + n;
}

/* a run-time-length result from text: alphanumeric as it is, or national
 * decoded from UTF-8 */
static char *fn_var_result(const char *s, int n, int national)
{
    if (!national) {
        char *b = fn_buffer(n);
        memcpy(b, s, (size_t)n);
        fn_var_len = n;
        return b;
    }
    unsigned short u[256];
    int save = nat_bad;
    int k = utf8_to_nat((const unsigned char *)s, n, u, 256);
    nat_bad = save;
    unsigned char *b = (unsigned char *)fn_buffer(2 * k);
    for (int i = 0; i < k; i++) nat_put(b, i, u[i]);
    fn_var_len = 2 * k;
    return (char *)b;
}
int cob_fn_conv_bad(void) { int b = fn_conv_bad; fn_conv_bad = 0; return b; }

static int fn_var_scale, fn_var_digits;      /* a numeric result's, for cob_fn_var_desc(3) */
const cob_desc *cob_fn_var_desc(int national)
{
    static cob_desc pool[8];
    static int rot;
    cob_desc *d = &pool[rot++ & 7];
    memset(d, 0, sizeof *d);
    if (national == 3) {                        /* an exact numeric function's result (docs/wide.md) */
        d->cat = COB_NUM; d->usage = COB_U_DISPLAY; d->flags = COB_F_SIGNED | COB_F_SEPLEAD;
        d->digits = (unsigned char)fn_var_digits; d->scale = (signed char)fn_var_scale; d->size = (unsigned)fn_var_len;
        return d;
    }
    d->cat = national == 1 ? COB_NATIONAL : national == 2 ? COB_BOOLEAN : COB_ALNUM;
    d->usage = COB_U_DISPLAY;
    d->size = (unsigned)fn_var_len;
    return d;
}

/* A function's result kept in a record of the program's -- its bytes, and
 * the length a result of run-time length has -- and made "the result just
 * evaluated" again from it as often as wanted: an alphanumeric, national
 * or boolean function as an EVALUATE subject is evaluated once (2023
 * 14.9.13.4 rule 3), and each WHEN compares against it, whatever
 * functions its objects evaluate in between.  rec: the length, then size
 * bytes. */
void cob_fn_keep(char *rec, const char *val, int size)
{
    memcpy(rec, &fn_var_len, sizeof fn_var_len);
    memcpy(rec + sizeof fn_var_len, val, (size_t)size);
}
char *cob_fn_kept(char *rec)
{
    memcpy(&fn_var_len, rec, sizeof fn_var_len);
    return rec + sizeof fn_var_len;
}

/* LENGTH (characters) or BYTE-LENGTH of the result just evaluated */
/* a length in bytes as nine digits, of characters when national */
char *cob_fn_len_digits(int bytes, int national)
{
    char *b = fn_buffer(9);
    int v = national ? bytes / 2 : bytes;
    for (int i = 8; i >= 0; i--) { b[i] = (char)('0' + v % 10); v /= 10; }
    return b;
}

char *cob_fn_last_len_digits(int national)
{
    char *b = fn_buffer(9);
    int v = national ? fn_var_len / 2 : fn_var_len;
    for (int i = 8; i >= 0; i--) { b[i] = (char)('0' + v % 10); v /= 10; }
    return b;
}

/* NATIONAL-OF (15.66): alphanumeric UTF-8 to national.  A byte that
 * begins no valid sequence becomes the substitution character, argument-2,
 * or U+FFFD without one -- and then, when track is set (checking on),
 * EC-DATA-CONVERSION at the end of the statement (15.66.4 rule 3) */
char *cob_fn_national_of(const char *p, int n, const char *sub, int track)
{
    unsigned short stk[256], *u = stk;
    if (n > 256) { u = malloc((size_t)n * sizeof *u); if (!u) cob_fatal("out of memory"); }
    int save = nat_bad;
    nat_bad = 0;
    if (sub) nat_repl = nat_at((const unsigned char *)sub, 0);
    int k = utf8_to_nat((const unsigned char *)p, n, u, n);
    nat_repl = 0xFFFD;
    if (nat_bad && !sub && track) fn_conv_bad = 1;
    nat_bad = save;
    unsigned char *b = (unsigned char *)fn_buffer(2 * k);
    for (int i = 0; i < k; i++) nat_put(b, i, u[i]);
    if (u != stk) free(u);
    fn_var_len = 2 * k;
    return (char *)b;
}

/* DISPLAY-OF (15.26): national to alphanumeric UTF-8.  A lone surrogate
 * has no UTF-8 form: it becomes the substitution character, argument-2,
 * or U+FFFD without one, and EC-DATA-CONVERSION as above (15.26.4 rule 3) */
/* TRIM (2014; 2023 15.96): the argument less its leading (mode 1),
 * trailing (2) or both (0) runs of each character to delete, each
 * character taken completely in turn (returned value rule 5); a space
 * when none is given.  National: two-byte characters. */
char *cob_fn_trim(const char *p, int nbytes, const char *chars, int nchars, int mode, int national)
{
    int u = national ? 2 : 1, n = nbytes / u, a = 0, z = n;
    static const char sp[2] = { 0, ' ' };
    const char *cs = chars ? chars : national ? sp : sp + 1;
    if (!chars) nchars = 1;
    for (int k = 0; k < nchars; k++) {
        const char *c = cs + k * u;
        if (mode != 2) while (a < z && !memcmp(p + a * u, c, (size_t)u)) a++;
        if (mode != 1) while (z > a && !memcmp(p + (z - 1) * u, c, (size_t)u)) z--;
    }
    int len = (z - a) * u;
    char *b = fn_buffer(len);
    memcpy(b, p + a * u, (size_t)len);
    fn_var_len = len;
    return b;
}

/* ---- the 2023 functions (standard-queue item 33) ----------------------- */
char *cob_fn_display_of(const char *p, int nbytes, const char *sub, int track);
static int hexval(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return -1;
}

/* string arguments handed over ahead of a call, oldest first (CONCAT's
 * list, SUBSTITUTE's pairs, CONVERT's and BASECONVERT's argument) */
static const char *sarg_p[64]; static int sarg_n[64], sarg_cnt;
static char sarg_buf[16384]; static int sarg_used;      /* copies: a nested function's result does not outlive the next */
int cob_fn_sarg_begin(void) { return sarg_cnt; }         /* a function's mark: it takes the arguments above it */
void cob_fn_sarg(const char *p, int n)
{
    if (sarg_cnt == 64) cob_fatal("intrinsic function: more than 64 string arguments");
    if (sarg_cnt == 0) sarg_used = 0;
    if (sarg_used + n > (int)sizeof sarg_buf) cob_fatal("intrinsic function: string arguments longer than 16384 bytes");
    memcpy(sarg_buf + sarg_used, p, (size_t)n);
    sarg_p[sarg_cnt] = sarg_buf + sarg_used; sarg_n[sarg_cnt] = n; sarg_cnt++; sarg_used += n;
}
/* a national string's characters narrowed to bytes for the character
 * functions (a unit above U+00FF becomes 0x7F, which matches nothing) */
static int sarg_narrow(const char *p, int n, int nat, char *out, int cap)
{
    if (!nat) { int k = n < cap ? n : cap; memcpy(out, p, (size_t)k); return k; }
    int k = 0;
    for (int i = 0; i + 1 < n && k < cap; i += 2) out[k++] = p[i] ? 0x7F : p[i + 1];
    return k;
}
static char *sarg_widen(const char *s, int n, int nat)
{
    if (!nat) { char *b = fn_buffer(n); memcpy(b, s, (size_t)n); fn_var_len = n; return b; }
    char *b = fn_buffer(2 * n);
    for (int i = 0; i < n; i++) { b[2 * i] = 0; b[2 * i + 1] = s[i]; }
    fn_var_len = 2 * n;
    return b;
}

/* BASECONVERT (15.12): the digits of argument-1 in base from, as digits in
 * base to; 2 to 16, unequal; an invalid digit is EC-ARGUMENT-FUNCTION and
 * a zero-length result */
char *cob_fn_baseconvert(const char *p, int n, int nat, int from, int to)
{
    char s[512]; int k = sarg_narrow(p, n, nat, s, sizeof s);
    if (from < 2 || from > 16 || to < 2 || to > 16 || from == to || n / (nat ? 2 : 1) > (int)sizeof s) { fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
    /* the value as a big number in base 1e9 is overkill: 8192 bits of result
     * cap the input; a 512-digit input in base 2 is 512 bits -- long
     * division digit by digit over a byte array of the input's digits */
    unsigned char dig[512]; int nd = 0;
    while (k > 0 && s[k - 1] == ' ') k--;
    int i0 = 0; while (i0 < k && s[i0] == ' ') i0++;
    for (int i = i0; i < k; i++) {
        int c = (unsigned char)s[i], v;
        if (c >= '0' && c <= '9') v = c - '0'; else if (c >= 'A' && c <= 'F') v = c - 'A' + 10; else if (c >= 'a' && c <= 'f') v = c - 'a' + 10; else v = 99;
        if (v >= from) { fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
        dig[nd++] = (unsigned char)v;
    }
    if (!nd) { fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
    char out[2100]; int no = 0;
    /* repeated division of the digit string by `to`, the remainders the result's digits from the right */
    int start = 0;
    while (start < nd && no < (int)sizeof out) {
        int rem = 0;
        for (int i = start; i < nd; i++) { int cur = rem * from + dig[i]; dig[i] = (unsigned char)(cur / to); rem = cur % to; }
        out[no++] = "0123456789ABCDEF"[rem];
        while (start < nd && dig[start] == 0) start++;
    }
    if (!no) out[no++] = '0';
    char r[2100]; for (int i = 0; i < no; i++) r[i] = out[no - 1 - i];
    return sarg_widen(r, no, nat);
}

/* CONCAT (15.18): the handed-over arguments in order; national when the
 * compiler says so (every argument then is) */
char *cob_fn_concat(int base, int nat)
{
    int total = 0;
    for (int i = base; i < sarg_cnt; i++) total += sarg_n[i];
    char *b = fn_buffer(total); int o = 0;
    for (int i = base; i < sarg_cnt; i++) { memcpy(b + o, sarg_p[i], (size_t)sarg_n[i]); o += sarg_n[i]; }
    sarg_cnt = base; fn_var_len = total; (void)nat;
    return b;
}

/* CONVERT (15.19): from 1 ANUM, 2 NAT, 3 HEX, 4 ANY; to 1 ANUM, 2 NAT, 3
 * ANUM HEX, 4 NAT HEX, 5 BYTE.  The bytes of argument-1 as the source
 * format reads them, written as the destination format spells them */
char *cob_fn_convert(const char *p, int n, int from, int to, int nat)
{
    static const char hx[] = "0123456789ABCDEF";
    if (from == 3) {
        /* hexadecimal digits (display or national: nat) to bytes */
        char s[1024]; int k = sarg_narrow(p, n, nat, s, sizeof s);
        unsigned char bytes[512]; int nb = 0;
        if (k % 2 || n / (nat ? 2 : 1) > (int)sizeof s) { fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
        for (int i = 0; i + 1 < k; i += 2) {
            int h = hexval(s[i]), l = hexval(s[i + 1]);
            if (h < 0 || l < 0) { fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
            bytes[nb++] = (unsigned char)(h * 16 + l);
        }
        if (to == 2) {
            /* HEX NAT: the bytes are UTF-16BE code units */
            char *b = fn_buffer(nb); memcpy(b, bytes, (size_t)nb); fn_var_len = nb & ~1; return b;
        }
        char *b = fn_buffer(nb); memcpy(b, bytes, (size_t)nb); fn_var_len = nb; return b;   /* ANUM, BYTE: the bytes */
    }
    if (to == 3 || to == 4) {
        /* the bytes as hexadecimal digits, alphanumeric or national */
        int w = to == 4 ? 2 : 1;
        char *b = fn_buffer(2 * n * w);
        for (int i = 0; i < n; i++) {
            unsigned char c = (unsigned char)p[i];
            if (w == 1) { b[2 * i] = hx[c >> 4]; b[2 * i + 1] = hx[c & 15]; }
            else { b[4 * i] = 0; b[4 * i + 1] = hx[c >> 4]; b[4 * i + 2] = 0; b[4 * i + 3] = hx[c & 15]; }
        }
        fn_var_len = 2 * n * w;
        return b;
    }
    if (from == 1 && to == 2) return cob_fn_national_of(p, n, 0, 0);
    if (from == 2 && to == 1) return cob_fn_display_of(p, n, 0, 0);
    fn_argbad = 1; fn_var_len = 0; return fn_buffer(1);
}

/* FIND-STRING (15.37): the position of argument-2 in argument-1, the
 * first or the last (last), after skip matches, letters in either case
 * (anycase); 0 when none; characters, so a national position is a unit */
static char *fn_digits(long v, int n);
char *cob_fn_find_string(const char *p, int n, const char *q, int m, int nat, int last, int skip, int anycase)
{
    int u = nat ? 2 : 1;
    if (n <= 0 || m <= 0 || m > n) return fn_digits(0, 9);
    long found = 0; int seen = 0;
    for (int i = 0; i + m <= n; i += u) {
        int eq = 1;
        for (int k = 0; k < m && eq; k++) {
            unsigned char a = (unsigned char)p[i + k], b = (unsigned char)q[k];
            if (anycase) { a = (unsigned char)tolower(a); b = (unsigned char)tolower(b); }
            eq = a == b;
        }
        if (!eq) continue;
        if (seen++ < skip) continue;
        found = i / u + 1;
        if (!last) break;
    }
    return fn_digits(found, 9);
}

/* MODULE-NAME (15.65): 1 ACTIVATING, 4 STACK, 5 TOP-LEVEL from the
 * activations under way (CURRENT and NESTED are the compiler's); the
 * externalized names, as the activation descriptors carry them */
static int act_name_put(char *b, int o, const char *s)
{
    for (; *s && o < 2047; s++) b[o++] = (char)toupper((unsigned char)*s);
    return o;
}
char *cob_fn_module_name(int which)
{
    char *b = fn_buffer(2048); int o = 0;
    const char *mods[256]; int d = 0;              /* the modules: the activations that are outermost programs */
    for (int i = 0; i < act_depth && i < 256; i++) if (act_names[i]) mods[d++] = act_names[i];
    if (which == 1) {                               /* ACTIVATING: the main program's is a single space (rule 5) */
        if (d <= 1) { b[0] = ' '; fn_var_len = 1; return b; }
        fn_var_len = act_name_put(b, 0, mods[d - 2]); return b;
    }
    if (which == 5) {                               /* TOP-LEVEL */
        if (!d) { b[0] = ' '; fn_var_len = 1; return b; }
        fn_var_len = act_name_put(b, 0, mods[0]); return b;
    }
    for (int i = d - 1; i >= 0; i--) {              /* STACK: current first, the environment's single space last */
        if (o + (int)strlen(mods[i]) + 2 > 2047) break;
        o = act_name_put(b, o, mods[i]); b[o++] = ';';
    }
    b[o++] = ' ';
    fn_var_len = o;
    return b;
}

/* SUBSTITUTE (15.87): argument-1 with each (argument-2, argument-3) pair
 * handed over substituted -- all occurrences, or the FIRST or the LAST
 * (mode 1, 2), letters in either case under ANYCASE; each pair starts
 * after the previous substitution's end */
char *cob_fn_substitute(const char *p, int n, int nat, int mode, int anycase, int base)
{
    int u = nat ? 2 : 1;
    if (n <= 0) { sarg_cnt = base; fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
    char *cur = fn_buffer(8192); memcpy(cur, p, (size_t)n); int cn = n;
    char *alt = fn_buffer(8192);
    int from = 0;                                   /* where this pair's search starts (rule 4) */
    for (int k = base; k + 1 < sarg_cnt; k += 2) {
        const char *a2 = sarg_p[k]; int l2 = sarg_n[k]; const char *a3 = sarg_p[k + 1]; int l3 = sarg_n[k + 1];
        if (l2 <= 0) { sarg_cnt = base; fn_argbad = 1; fn_var_len = 0; return fn_buffer(1); }
        int last_at = -1;                           /* LAST: the rightmost occurrence */
        if (mode == 2) for (int i = from; i + l2 <= cn; i += u) {
            int eq = 1; for (int j = 0; j < l2 && eq; j++) { unsigned char a = (unsigned char)cur[i + j], b = (unsigned char)a2[j]; if (anycase) { a = (unsigned char)tolower(a); b = (unsigned char)tolower(b); } eq = a == b; }
            if (eq) last_at = i;
        }
        int o = 0, i = 0, done = 0, next_from = from;
        for (; i < cn; ) {
            int eq = !done && i >= from && i + l2 <= cn && (mode != 2 || i == last_at);
            for (int j = 0; j < l2 && eq; j++) { unsigned char a = (unsigned char)cur[i + j], b = (unsigned char)a2[j]; if (anycase) { a = (unsigned char)tolower(a); b = (unsigned char)tolower(b); } eq = a == b; }
            if (eq) {
                if (o + l3 > 8192) cob_fatal("SUBSTITUTE: the result is longer than 8192 bytes");
                memcpy(alt + o, a3, (size_t)l3); o += l3; i += l2; next_from = o;
                if (mode) done = 1;
            } else { if (o >= 8192) cob_fatal("SUBSTITUTE: the result is longer than 8192 bytes"); alt[o++] = cur[i++]; }
        }
        char *t = cur; cur = alt; alt = t; cn = o; from = next_from;
    }
    sarg_cnt = base; fn_var_len = cn;
    return cur;
}

char *cob_fn_display_of(const char *p, int nbytes, const char *sub, int track)
{
    const unsigned char *q = (const unsigned char *)p;
    int nch = nbytes / 2, k = 0;
    char *b = fn_buffer(3 * nch);
    for (int i = 0; i < nch; ) {
        uint32_t cp;
        int nu = (int)s32u_u16_get(q, (size_t)nch, (size_t)i, &cp);
        unsigned u = nat_at(q, i);
        if (nu == 1 && u >= 0xD800 && u <= 0xDFFF) {            /* a lone surrogate */
            if (sub) b[k++] = sub[0];
            else { k += s32u_encode(cp, (unsigned char *)b + k); if (track) fn_conv_bad = 1; }
        } else k += s32u_encode(cp, (unsigned char *)b + k);    /* a pair: four bytes where two units took six */
        i += nu;
    }
    fn_var_len = k;
    return b;
}

/* ---- boolean expressions (2023 8.8.2; cobol ISSUES-77) -----------------
 * A stack of boolean values, each a string of characters 0 and 1.  Binary
 * operations extend the shorter operand on the right with zeros (rule 9);
 * a shift keeps its operand's length (rule 8); B-NOT its operand's. */
static struct bent { char *v; int n, all; } *bstk;   /* all: an ALL literal, repeated to its partner's length */
static int bsp, bcap;                                /* grows: a user function can run with its caller's operands on it */
static void bstk_push(char *v, int n)
{
    if (bsp == bcap) {
        bcap = bcap ? 2 * bcap : 32;
        bstk = realloc(bstk, (size_t)bcap * sizeof *bstk);
        if (!bstk) cob_fatal("out of memory");
    }
    bstk[bsp].v = v; bstk[bsp].n = n; bstk[bsp].all = 0; bsp++;
}
void cob_bpush_all(const char *lit, int n)
{
    char *v = malloc((size_t)n + 1); if (!v) cob_fatal("out of memory");
    memcpy(v, lit, (size_t)n);
    bstk_push(v, n); bstk[bsp - 1].all = 1;
}
/* an ALL entry at k taken to n positions, its value repeated */
static void ball_expand(int k, int n)
{
    if (!bstk[k].all) return;
    char *v = malloc((size_t)n + 1); if (!v) cob_fatal("out of memory");
    for (int i = 0; i < n; i++) v[i] = bstk[k].n ? bstk[k].v[i % bstk[k].n] : '0';
    free(bstk[k].v); bstk[k].v = v; bstk[k].n = n; bstk[k].all = 0;
}
void cob_bpush(const void *p, const cob_desc *d)
{
    unsigned char t[NATNUM_MAX]; cob_desc nd;
    const unsigned char *q = p; int n = (int)d->size;
    if (is_natnum(d)) { q = nat_narrow(p, d, t, &nd); n = (int)nd.size; }
    char *v = malloc((size_t)n + 1); if (!v) cob_fatal("out of memory");
    for (int i = 0; i < n; i++) v[i] = q[i] == '1' ? '1' : '0';
    bstk_push(v, n);
}
void cob_bnot(void)
{
    char *v = bstk[bsp - 1].v;
    for (int i = 0; i < bstk[bsp - 1].n; i++) v[i] = v[i] == '1' ? '0' : '1';
}
static void bbin(int op)
{
    if (bsp < 2) cob_fatal("boolean stack underflow");
    ball_expand(bsp - 2, bstk[bsp - 1].n); ball_expand(bsp - 1, bstk[bsp - 2].n);
    int na = bstk[bsp - 2].n, nb = bstk[bsp - 1].n, n = na > nb ? na : nb;
    char *a = bstk[bsp - 2].v, *b = bstk[bsp - 1].v, *r = malloc((size_t)n + 1);
    if (!r) cob_fatal("out of memory");
    for (int i = 0; i < n; i++) {
        int x = i < na && a[i] == '1', y = i < nb && b[i] == '1';
        r[i] = (char)('0' + (op == 0 ? (x & y) : op == 1 ? (x | y) : (x ^ y)));
    }
    free(a); free(b); bsp -= 2;
    bstk_push(r, n);
}
void cob_band(void) { bbin(0); }
void cob_bor(void) { bbin(1); }
void cob_bxor(void) { bbin(2); }
/* kind 0 left, 1 right, 2 circular left, 3 circular right */
void cob_bshift(int kind, int count)
{
    int n = bstk[bsp - 1].n;
    char *v = bstk[bsp - 1].v;
    if (n == 0 || count <= 0) return;
    char *t = malloc((size_t)n); if (!t) cob_fatal("out of memory");
    for (int i = 0; i < n; i++) {
        int src;
        switch (kind) {
        case 0: src = i + count; t[i] = src < n ? v[src] : '0'; break;
        case 1: src = i - count; t[i] = src >= 0 ? v[src] : '0'; break;
        case 2: t[i] = v[(i + count) % n]; break;
        default: t[i] = v[((i - count) % n + n) % n]; break;
        }
    }
    memcpy(v, t, (size_t)n); free(t);
}
/* a shift whose count is on the numeric stack, taken whole (cobol
 * ISSUES-94 B7): shifting L or R by the length or more leaves zeros, a
 * circular shift goes round count mod length times; a count below zero
 * shifts nothing */
void cob_bshift_pop(int kind)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[--nsp];
    long long c = a->v;
    if (a->scale > 0) c = div_pow10(c, a->scale, 0);
    int n = bstk[bsp - 1].n;
    if (c <= 0 || n == 0) return;
    if (kind >= 2) c %= n;
    else if (c > n) c = n;
    cob_bshift(kind, (int)c);
}
/* the top value into a receiver, by the MOVE rules (14.6.8.6) */
static void ball_expand(int k, int n);
void cob_bstore(void *p, const cob_desc *d)
{
    /* an ALL literal takes the receiver's positions (cobol ISSUES-94 B4) */
    if (bstk[bsp - 1].all) ball_expand(bsp - 1, d->usage == COB_U_BIT ? (int)d->size : d->usage == COB_U_NATIONAL ? (int)d->size / 2 : (int)d->size);
    cob_desc sd; memset(&sd, 0, sizeof sd);
    sd.cat = COB_BOOLEAN; sd.usage = COB_U_DISPLAY; sd.size = (unsigned)bstk[bsp - 1].n;
    cob_move(bstk[bsp - 1].v, &sd, p, d);
}
void cob_bdrop(void) { if (bsp) free(bstk[--bsp].v); }
/* the top two compared (8.8.4.2.8), both dropped */
int cob_bcmp(void)
{
    if (bsp < 2) cob_fatal("boolean stack underflow");
    ball_expand(bsp - 2, bstk[bsp - 1].n); ball_expand(bsp - 1, bstk[bsp - 2].n);
    int na = bstk[bsp - 2].n, nb = bstk[bsp - 1].n, r = 0;
    const char *a = bstk[bsp - 2].v, *b = bstk[bsp - 1].v;
    for (int i = 0; i < na || i < nb; i++) {
        char x = i < na ? a[i] : '0', y = i < nb ? b[i] : '0';
        if (x != y) { r = x < y ? -1 : 1; break; }
    }
    cob_bdrop(); cob_bdrop();
    return r;
}

/* BOOLEAN-OF-INTEGER (2023 15.13): argument-1, from the numeric stack,
 * as n boolean positions, the low-order binary digit rightmost, zero-
 * filled or truncated on the left (cobol ISSUES-76) */
char *cob_fn_boolean_of_integer(int n)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[--nsp];
    long long v = a->v;
    if (a->scale > 0) v = div_pow10(v, a->scale, 0);
    unsigned long long u = (unsigned long long)v;
    if (n < 1) n = 1;
    char *b = fn_buffer(n);
    for (int i = n - 1; i >= 0; i--) { b[i] = (char)('0' + (int)(u & 1)); u >>= 1; }
    fn_var_len = n;
    return b;
}

/* INTEGER-OF-BOOLEAN (2023 15.45): the unsigned binary value of the
 * boolean positions, as eighteen digits (a value past them is truncated
 * on the left, as a MOVE to PIC 9(18) would) */
char *cob_fn_integer_of_boolean(const void *p, const cob_desc *d)
{
    unsigned char t[NATNUM_MAX]; cob_desc nd;
    const unsigned char *q = p; int n = (int)d->size;
    if (is_natnum(d)) { q = nat_narrow(p, d, t, &nd); n = (int)nd.size; }
    unsigned long long u = 0;
    for (int i = 0; i < n; i++) u = (u << 1) | (q[i] == '1');
    char *b = fn_buffer(18);
    for (int i = 17; i >= 0; i--) { b[i] = (char)('0' + (int)(u % 10)); u /= 10; }
    return b;
}

/* CHAR-NATIONAL (15.16): the national character at ordinal position k,
 * one code unit, as CHAR is one byte */
char *cob_fn_char_national(int k)
{
    unsigned char *b = (unsigned char *)fn_buffer(2);
    nat_put(b, 0, (unsigned)(k - 1) & 0xFFFF);
    return (char *)b;
}

/* ---- UPPER-CASE, LOWER-CASE (cobol ISSUES-66) --------------------------- */

/* Unicode's simple, one-to-one case mappings (2002 Annex D note 1: use
 * UnicodeData.txt), generated from libutf's copy by gen_casemap.py.  With
 * no locale the result is the argument's length (E.13.2.4), so a letter
 * whose other case would not fit in the same space is left as it is. */
#include "casemap.h"

static unsigned case_map(const cob_caserun *t, int n, unsigned cp)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < t[mid].lo) hi = mid - 1;
        else if (cp > t[mid].hi) lo = mid + 1;
        else return (cp - t[mid].lo) % t[mid].stride ? cp : (unsigned)((int)cp + t[mid].delta);
    }
    return cp;
}
#define CASE_TABLE(up) ((up) ? cob_case_upper : cob_case_lower)
#define CASE_COUNT(up) ((up) ? (int)(sizeof cob_case_upper / sizeof *cob_case_upper) : (int)(sizeof cob_case_lower / sizeof *cob_case_lower))

/* one well-formed UTF-8 sequence at p (at most n bytes): its code point,
 * and its length -- 0 when the bytes begin none */
static int utf8_one(const unsigned char *p, int n, unsigned *cp)
{
    uint32_t v;
    int len = (int)s32u_decode(p, (size_t)n, &v);
    if (v == S32U_REPL && !(len == 3 && p[0] == 0xEF && p[1] == 0xBF && p[2] == 0xBD)) return 0;
    *cp = v;
    return len;
}

static int utf8_put(unsigned cp, char *out) { return s32u_encode(cp, (unsigned char *)out); }

/* alphanumeric: UTF-8 text (README ruling 5).  ASCII letters as always;
 * a well-formed multi-byte character mapped when its other case has the
 * same byte length; any other byte unchanged */
static char *fn_case(const char *s, int n, int up)
{
    const unsigned char *p = (const unsigned char *)s;
    char *b = fn_buffer(n);
    memcpy(b, s, (size_t)n);
    for (int i = 0; i < n; ) {
        unsigned c = p[i], cp;
        if (c < 0x80) {
            if (up ? (c >= 'a' && c <= 'z') : (c >= 'A' && c <= 'Z')) b[i] = (char)(c ^ 0x20);
            i++;
            continue;
        }
        int len = utf8_one(p + i, n - i, &cp);
        if (!len) { i++; continue; }
        unsigned m = case_map(CASE_TABLE(up), CASE_COUNT(up), cp);
        char out[4];
        if (m != cp && utf8_put(m, out) == len) memcpy(b + i, out, (size_t)len);
        i += len;
    }
    fn_var_len = n;
    return b;
}

/* national: each code unit, and a surrogate pair as its character */
static char *fn_case_nat(const char *s, int nbytes, int up)
{
    const unsigned char *p = (const unsigned char *)s;
    int nch = nbytes / 2;
    unsigned char *b = (unsigned char *)fn_buffer(nbytes);
    memcpy(b, s, (size_t)nbytes);
    for (int i = 0; i < nch; ) {
        uint32_t cp;
        int nu = (int)s32u_u16_get(p, (size_t)nch, (size_t)i, &cp);
        unsigned m = cp == S32U_REPL ? cp : case_map(CASE_TABLE(up), CASE_COUNT(up), cp);
        if (m != cp && s32u_u16_units(m) == nu) s32u_u16_put(b + 2 * i, m);   /* only where it fits the same positions */
        i += nu;
    }
    fn_var_len = nbytes;
    return (char *)b;
}

char *cob_fn_upper(const char *s, int n) { return fn_case(s, n, 1); }
char *cob_fn_lower(const char *s, int n) { return fn_case(s, n, 0); }
char *cob_fn_upper_nat(const char *s, int n) { return fn_case_nat(s, n, 1); }
char *cob_fn_lower_nat(const char *s, int n) { return fn_case_nat(s, n, 0); }

/* ====================================================================== */
/* Indexed files: the default path                                          */
/* ====================================================================== */

/* ====================================================================== */
/* INDEXED files.  The data file named by ASSIGN holds recsize-byte slots  */
/* in arrival order; beside it "<name>.key" holds one B+tree per key in a  */
/* 4K-paged file (libcob/btree.h): the RECORD KEY's tree and one for each  */
/* ALTERNATE RECORD KEY, entries of (key bytes, arrival number, slot) in    */
/* key-then-arrival order, a bitmap of the live slots so a DELETEd slot is */
/* reused, and a free chain of pages.  docs/indexed.md describes it.       */
/*                                                                         */
/* Until 2026-09-04 the key file was a sorted array per key ("S32KEY01",   */
/* prime key only; "S32KEY02", alternates too) loaded whole at OPEN.  Such */
/* a file is still read, once: OPEN converts it to the tree in place.      */
/* ====================================================================== */

/* The legacy key table, kept only to read an S32KEY01/02 file once and
 * convert it to the tree (below). */
typedef struct {
    unsigned char *e;       /* count entries of (klen bytes, u32 slot, u32 seq), sorted by key then seq */
    unsigned count, cap;
    unsigned off, klen;     /* the key's place in the record */
    int dups;               /* WITH DUPLICATES */
} cob_ktab;

/* The indexed file's keys live in `<data>.key`, one B+tree per key in a
 * 4K-paged file (libcob/btree.h; docs/indexed.md).  Program-visible
 * behaviour is what the sorted arrays gave: a random READ finds the key,
 * READ NEXT walks the key of reference, START positions, duplicates
 * come back in arrival order, and the status codes follow the 1985 text.
 * The cursor is the (key, arrival) of the next entry to deliver, so a
 * WRITE, REWRITE or DELETE between two READ NEXTs needs no fixing up. */
typedef struct {
    btf bt;                 /* the key file: bt.k[0] the prime key, bt.k[i] the i-th alternate */
    int ref;                /* key of reference: 0 the prime key, i the i-th alternate */
    int have_cur;           /* the cursor is set (else READ NEXT starts at the front) */
    unsigned char cur[BT_KEYMAX + 4];   /* next (key, arrival) to deliver, inclusive */
    int cur_at;             /* cur is the entry START found (READ PREVIOUS takes it), not one past the last READ */
    int last_slot;          /* slot the last READ delivered, for REWRITE/DELETE; -1 */
    unsigned char *tmp;     /* a record's worth of scratch */
    btpos hint;             /* where the last lookup landed (bt_first_ge_near) */
    unsigned char *cache;   /* the data file's slots in memory (write-through), or 0 */
    unsigned cache_slots;   /* slots the cache holds */
    long fpos;              /* the stream's position, -1 unknown: a write to the next slot needs no seek */
} cob_idx;

#define KEYMAGIC1 "S32KEY01"
#define KEYMAGIC2 "S32KEY02"

static unsigned tab_esize(const cob_ktab *t) { return t->klen + 8; }
static unsigned char *tab_entry(const cob_ktab *t, unsigned i) { return t->e + (size_t)i * tab_esize(t); }
static void put_u32(unsigned char *p, unsigned v) { p[0] = (unsigned char)v; p[1] = (unsigned char)(v >> 8); p[2] = (unsigned char)(v >> 16); p[3] = (unsigned char)(v >> 24); }
static unsigned get_u32(const unsigned char *p) { return p[0] | (p[1] << 8) | (p[2] << 16) | ((unsigned)p[3] << 24); }
static unsigned tab_slot(const cob_ktab *t, unsigned i) { return get_u32(tab_entry(t, i) + t->klen); }
static unsigned tab_seq(const cob_ktab *t, unsigned i) { return get_u32(tab_entry(t, i) + t->klen + 4); }

static const char *key_file_name(cob_file *f)
{
    static char name[300];
    const char *d = file_name(f);
    size_t n = strlen(d);
    if (n > 290) n = 290;
    memcpy(name, d, n); memcpy(name + n, ".key", 5);
    return name;
}

/* The data file's records.  Every random READ used to be an fseek and an
 * fread through the libc's 1K stream buffer -- two round trips through
 * the MMIO ring per record, which was most of a 55,000-line keyed join.
 * When the file fits a share of the heap (there is no sbrk: a quarter of
 * it), OPEN reads it whole and READ serves from memory; WRITE and REWRITE
 * go to both.  Larger files keep the stream path.  fseek flushes pending
 * writes, so slot_write no longer flushes per record. */
static int slot_read_to(cob_file *f, unsigned slot, unsigned char *buf)
{
    cob_idx *x = f->idx;
    if (x && x->cache && slot < x->cache_slots) { memcpy(buf, x->cache + (size_t)slot * f->recsize, f->recsize); return 1; }
    FILE *fp = (FILE *)f->fp;
    long at = (long)slot * (long)f->recsize;
    if (!x || x->fpos != at) { if (fseek(fp, at, 0) != 0) return 0; }
    int ok = fread(buf, 1, f->recsize, fp) == f->recsize;
    if (x) x->fpos = ok ? at + (long)f->recsize : -1;
    return ok;
}
static int slot_read(cob_file *f, unsigned slot) { return slot_read_to(f, slot, (unsigned char *)f->record); }
static int slot_write(cob_file *f, unsigned slot)
{
    cob_idx *x = f->idx;
    FILE *fp = (FILE *)f->fp;
    long at = (long)slot * (long)f->recsize;
    /* a seek flushes the stream: 24,584 records written in slot order used
     * to be 24,584 seeks and as many short writes.  The position is tracked
     * so the common case, the next slot, is one buffered fwrite. */
    if (!x || x->fpos != at) { if (fseek(fp, at, 0) != 0) return 0; }
    if (fwrite(f->record, 1, f->recsize, fp) != f->recsize) { if (x) x->fpos = -1; return 0; }
    if (x) {
        x->fpos = at + (long)f->recsize;
        if (x->cache) {
            if (slot >= x->cache_slots) {              /* grow, or give the cache up */
                unsigned want = x->cache_slots ? x->cache_slots : 256;
                while (want <= slot) want *= 2;
                size_t heap = (size_t)(__heap_end - __heap_start);
                unsigned char *nc = (size_t)want * f->recsize <= heap / 4 ? realloc(x->cache, (size_t)want * f->recsize) : 0;
                if (!nc) { free(x->cache); x->cache = 0; x->cache_slots = 0; return 1; }
                x->cache = nc; x->cache_slots = want;
            }
            memcpy(x->cache + (size_t)slot * f->recsize, f->record, f->recsize);
        }
    }
    return 1;
}

/* the data file into the cache, if it fits a quarter of the heap */
static void idx_cache_load(cob_file *f, cob_idx *x)
{
    FILE *fp = (FILE *)f->fp;
    if (!fp || !f->recsize) return;
    if (fseek(fp, 0, 2) != 0) return;
    long sz = ftell(fp);
    if (sz < 0) return;
    size_t heap = (size_t)(__heap_end - __heap_start);
    if ((size_t)sz > heap / 4) { fseek(fp, 0, 0); return; }
    unsigned slots = (unsigned)(sz / f->recsize);
    size_t bytes = (size_t)slots * f->recsize;
    unsigned char *c = malloc(bytes ? bytes : 1);
    if (!c) { fseek(fp, 0, 0); return; }
    if (fseek(fp, 0, 0) != 0 || (bytes && fread(c, 1, bytes, fp) != bytes)) { free(c); fseek(fp, 0, 0); return; }
    x->cache = c; x->cache_slots = slots; x->fpos = -1;
}

/* The page cache: S32_INDEX_CACHE pages, else a sixteenth of the heap the
 * program was linked with, 16..256 pages -- there is no sbrk. */
static unsigned idx_cache_pages(void)
{
    const char *e = getenv("S32_INDEX_CACHE");
    if (e && *e) { unsigned v = (unsigned)atoi(e); return v < BT_MINCACHE ? BT_MINCACHE : v; }
    size_t heap = (size_t)(__heap_end - __heap_start);
    unsigned n = (unsigned)(heap / 16 / BT_PAGE);
    return n < BT_MINCACHE ? BT_MINCACHE : n > 256 ? 256 : n;
}

/* the keys as the FD declares them: bt.k[0] prime, then the alternates */
static unsigned idx_fd_keys(cob_file *f, btkey *keys)
{
    unsigned n = f->naltkeys < BT_MAXKEYS - 1 ? f->naltkeys : BT_MAXKEYS - 1;
    /* the prime entry carries each alternate's arrival number, so a DELETE or
     * a REWRITE that moves an alternate key removes its entry exactly */
    keys[0].off = f->keyoff; keys[0].klen = f->keylen; keys[0].dups = 0; keys[0].root = 0; keys[0].count = 0; keys[0].extra = 4 * n;
    for (unsigned i = 0; i < n; i++) {
        const cob_altkey *a = &f->altkeys[i];
        keys[i + 1].off = a->offset; keys[i + 1].klen = a->len; keys[i + 1].dups = (unsigned)a->dups; keys[i + 1].root = 0; keys[i + 1].count = 0; keys[i + 1].extra = 0;
    }
    return n + 1;
}

static int idx_keys_match(cob_file *f, const btf *b)
{
    btkey keys[BT_MAXKEYS];
    unsigned n = idx_fd_keys(f, keys);
    if (b->recsize != f->recsize || b->keyoff != f->keyoff || b->keylen != f->keylen) return 0;
    if (b->nkeys != n) return 0;
    for (unsigned i = 0; i < n; i++)
        if (b->k[i].off != keys[i].off || b->k[i].klen != keys[i].klen || b->k[i].dups != keys[i].dups || b->k[i].extra != keys[i].extra) return 0;
    return 1;
}

/* --- reading an S32KEY01/02 file, once, to convert it --- */

static unsigned tab_find(const cob_ktab *t, const unsigned char *k, unsigned len, int *found)
{
    unsigned lo = 0, hi = t->count;
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        int c = memcmp(tab_entry(t, mid), k, len);
        if (c < 0) lo = mid + 1; else hi = mid;
    }
    *found = (lo < t->count && !memcmp(tab_entry(t, lo), k, len));
    return lo;
}

static int old_load(cob_file *f, FILE *kf, const unsigned char *h, cob_ktab *prime, cob_ktab **alt_out, unsigned *nalt_out, unsigned *nslots, unsigned *seq)
{
    if (get_u32(h + 8) != f->recsize || get_u32(h + 12) != f->keyoff || get_u32(h + 16) != f->keylen) return 0;
    int v2 = !memcmp(h, KEYMAGIC2, 8);
    memset(prime, 0, sizeof *prime);
    prime->off = f->keyoff; prime->klen = f->keylen;
    prime->count = get_u32(h + 20); *nslots = get_u32(h + 24);
    prime->cap = prime->count ? prime->count : 1;
    prime->e = malloc((size_t)prime->cap * tab_esize(prime));
    if (!prime->e) cob_fatal("out of memory for the key table");
    unsigned nalt = f->naltkeys;
    cob_ktab *alt = nalt ? calloc(nalt, sizeof *alt) : 0;
    if (nalt && !alt) cob_fatal("out of memory for the key tables");
    for (unsigned i = 0; i < nalt; i++) { alt[i].off = f->altkeys[i].offset; alt[i].klen = f->altkeys[i].len; alt[i].dups = (int)f->altkeys[i].dups; }
    int alts_ok = 0;
    if (v2) {
        *seq = get_u32(h + 28);
        size_t want = (size_t)prime->count * tab_esize(prime);
        if (fread(prime->e, 1, want, kf) != want) return 0;
        unsigned char ah[4];
        if (fread(ah, 1, 4, kf) == 4 && get_u32(ah) == nalt) {
            alts_ok = 1;
            for (unsigned a = 0; a < nalt && alts_ok; a++) {
                unsigned char th[16];
                cob_ktab *t = &alt[a];
                if (fread(th, 1, 16, kf) != 16 || get_u32(th) != t->off || get_u32(th + 4) != t->klen || get_u32(th + 8) != (unsigned)t->dups) { alts_ok = 0; break; }
                t->count = get_u32(th + 12); t->cap = t->count ? t->count : 1;
                t->e = malloc((size_t)t->cap * tab_esize(t));
                if (!t->e) cob_fatal("out of memory for a key table");
                size_t w = (size_t)t->count * tab_esize(t);
                if (fread(t->e, 1, w, kf) != w) { alts_ok = 0; break; }
            }
        }
    } else {
        for (unsigned i = 0; i < prime->count; i++) {
            unsigned char *e = tab_entry(prime, i);
            if (fread(e, 1, f->keylen + 4, kf) != f->keylen + 4) return 0;
            put_u32(e + f->keylen + 4, i);
        }
        *seq = prime->count;
    }
    *alt_out = alt; *nalt_out = alts_ok ? nalt : 0;    /* 0: the alternates are rebuilt from the records */
    return 1;
}

/* the alternate trees from the records the prime tree names */
static void idx_alt_rebuild(cob_file *f, cob_idx *x)
{
    btf *b = &x->bt;
    unsigned char zero[BT_KEYMAX + 4], ka[BT_KEYMAX + 4];
    memset(zero, 0, sizeof zero);
    unsigned page, ix;
    if (!bt_first_ge(b, 0, zero, b->k[0].klen + 4, &page, &ix)) return;
    unsigned char ex[4 * BT_MAXKEYS];
    do {
        unsigned slot = bt_read(b, 0, page, ix, ka), seq = bt_getbe(ka + b->k[0].klen);
        if (!slot_read_to(f, slot, x->tmp)) continue;
        for (unsigned a = 1; a < b->nkeys; a++) { bt_insert(b, a, x->tmp + b->k[a].off, seq, slot); bt_putbe(ex + 4 * (a - 1), seq); }
        if (b->nkeys > 1) bt_extra_set(b, 0, page, ix, ex);
    } while (bt_step(b, &page, &ix));
}

/* an old key file becomes a tree file in place */
static int idx_migrate(cob_file *f, cob_idx *x, FILE *kf, const unsigned char *h)
{
    cob_ktab prime, *alt = 0; unsigned nalt = 0, nslots = 0, seq = 0;
    int ok = old_load(f, kf, h, &prime, &alt, &nalt, &nslots, &seq);
    fclose(kf);
    if (!ok) { free(prime.e); if (alt) { for (unsigned a = 0; a < f->naltkeys; a++) free(alt[a].e); free(alt); } return 0; }
    btkey keys[BT_MAXKEYS];
    unsigned nkeys = idx_fd_keys(f, keys);
    if (!bt_create(&x->bt, key_file_name(f), idx_cache_pages(), f->recsize, f->keyoff, f->keylen, keys, nkeys, cob_fatal)) return 0;
    btf *b = &x->bt;
    b->nslots = nslots; b->seq = seq;
    unsigned maxslot = nslots;
    for (unsigned i = 0; i < prime.count; i++) if (tab_slot(&prime, i) >= maxslot) maxslot = tab_slot(&prime, i) + 1;
    unsigned char *ex = 0;
    if (nalt) {                                      /* slot -> each alternate's arrival, from the old tables */
        ex = calloc((size_t)maxslot, 4 * nalt);
        if (!ex) cob_fatal("out of memory converting the key file");
        for (unsigned a = 0; a < nalt; a++)
            for (unsigned i = 0; i < alt[a].count; i++) bt_putbe(ex + (size_t)tab_slot(&alt[a], i) * 4 * nalt + 4 * a, tab_seq(&alt[a], i));
    }
    for (unsigned i = 0; i < prime.count; i++) {
        unsigned slot = tab_slot(&prime, i);
        bt_insert_x(b, 0, tab_entry(&prime, i), tab_seq(&prime, i), slot, ex ? ex + (size_t)slot * 4 * nalt : 0);
        bt_slot_set(b, slot, 1);
        if (slot >= b->nslots) b->nslots = slot + 1;
    }
    if (nalt) for (unsigned a = 0; a < nalt; a++)
        for (unsigned i = 0; i < alt[a].count; i++) bt_insert(b, a + 1, tab_entry(&alt[a], i), tab_seq(&alt[a], i), tab_slot(&alt[a], i));
    else idx_alt_rebuild(f, x);
    free(ex);
    b->hdr_dirty = 1;
    free(prime.e); if (alt) { for (unsigned a = 0; a < f->naltkeys; a++) free(alt[a].e); free(alt); }
    return 1;
}

/* the FD's alternates differ from the key file's: rebuild the key file
 * from its prime tree and the records */
static int idx_rekey(cob_file *f, cob_idx *x)
{
    btf old = x->bt;
    char tmpname[320];
    snprintf(tmpname, sizeof tmpname, "%s.new", key_file_name(f));
    btkey keys[BT_MAXKEYS];
    unsigned nkeys = idx_fd_keys(f, keys);
    btf nb;
    if (!bt_create(&nb, tmpname, idx_cache_pages(), f->recsize, f->keyoff, f->keylen, keys, nkeys, cob_fatal)) return 0;
    nb.nslots = old.nslots; nb.seq = old.seq;
    unsigned char zero[BT_KEYMAX + 4], ka[BT_KEYMAX + 4];
    memset(zero, 0, sizeof zero);
    unsigned page, ix;
    if (bt_first_ge(&old, 0, zero, old.k[0].klen + 4, &page, &ix)) {
        do {
            unsigned slot = bt_read(&old, 0, page, ix, ka);
            bt_insert(&nb, 0, ka, bt_getbe(ka + old.k[0].klen), slot);
            bt_slot_set(&nb, slot, 1);
        } while (bt_step(&old, &page, &ix));
    }
    bt_close(&old, 0);
    x->bt = nb;
    idx_alt_rebuild(f, x);
    bt_close(&x->bt, 1);
    if (rename(tmpname, key_file_name(f)) != 0) return 0;
    return bt_open(&x->bt, key_file_name(f), 0, idx_cache_pages(), cob_fatal);
}

/* the key file for an existing data file: ours, or an old one converted; 0 = 39 */
static int idx_load(cob_file *f, cob_idx *x, int rdonly)
{
    const char *kn = key_file_name(f);
    if (bt_open(&x->bt, kn, rdonly, idx_cache_pages(), cob_fatal)) {
        if (idx_keys_match(f, &x->bt)) return 1;
        if (x->bt.recsize != f->recsize || x->bt.keyoff != f->keyoff || x->bt.keylen != f->keylen) { bt_close(&x->bt, 0); return 0; }
        return idx_rekey(f, x);                       /* the alternates changed under the file */
    }
    FILE *kf = fopen(kn, "rb");
    if (!kf) return 0;
    unsigned char h[32];
    if (fread(h, 1, 32, kf) != 32 || (memcmp(h, KEYMAGIC1, 8) && memcmp(h, KEYMAGIC2, 8))) { fclose(kf); return 0; }
    return idx_migrate(f, x, kf, h);
}

static cob_idx *idx_new(cob_file *f)
{
    cob_idx *x = calloc(1, sizeof *x);
    if (!x) cob_fatal("out of memory");
    x->bt.fd = -1; x->fpos = -1;
    x->last_slot = -1; x->ref = 0; x->have_cur = 0;
    x->tmp = malloc(f->recsize ? f->recsize : 1);
    if (!x->tmp) cob_fatal("out of memory");
    return x;
}

static void idx_free(cob_idx *x)
{
    if (!x) return;
    if (x->bt.fd >= 0) bt_close(&x->bt, 0);
    free(x->cache); free(x->tmp); free(x);
}

static int idx_open(cob_file *f, int mode)
{
    const char *name = file_name(f);
    if (f->keylen == 0 || f->keylen > BT_KEYMAX) cob_fatal("RECORD KEY must be 1 to 255 bytes");
    if (f->naltkeys > BT_MAXKEYS - 1) cob_fatal("more than 16 ALTERNATE RECORD KEYs");
    if (f->locked) return file_result(f, "38", "OPEN of a file closed WITH LOCK");
    cob_idx *x = idx_new(f);
    FILE *fp;
    errno = 0;
    if (mode == COB_OPEN_OUTPUT) {
        fp = fopen(name, "w+b");
        if (!fp) { idx_free(x); return file_result(f, open_fail_st(errno), name); }
        btkey keys[BT_MAXKEYS];
        unsigned nkeys = idx_fd_keys(f, keys);
        if (!bt_create(&x->bt, key_file_name(f), idx_cache_pages(), f->recsize, f->keyoff, f->keylen, keys, nkeys, cob_fatal)) { fclose(fp); idx_free(x); return file_result(f, "30", "key file"); }
    } else {
        fp = fopen(name, mode == COB_OPEN_INPUT ? "rb" : "r+b");
        if (!fp && errno && errno != ENOENT) {      /* there, but not to be opened so: never taken for absent */
            idx_free(x); return file_result(f, open_fail_st(errno), name);
        }
        if (!fp) {
            if (!f->optional) { idx_free(x); return file_result(f, "35", name); }
            if (mode == COB_OPEN_INPUT) { idx_free(x); f->open_mode = (unsigned char)mode; f->fp = 0; f->at_eof = 1; return file_result(f, "05", name); }
            /* OPTIONAL, absent, I-O or EXTEND: the file comes into being, empty */
            fp = fopen(name, "w+b");
            if (!fp) { idx_free(x); return file_result(f, "30", name); }
            btkey keys[BT_MAXKEYS];
            unsigned nkeys = idx_fd_keys(f, keys);
            if (!bt_create(&x->bt, key_file_name(f), idx_cache_pages(), f->recsize, f->keyoff, f->keylen, keys, nkeys, cob_fatal)) { fclose(fp); idx_free(x); return file_result(f, "30", "key file"); }
            f->fp = fp; f->idx = x; f->open_mode = (unsigned char)mode; f->at_eof = 0; f->eof_seen = 0;
            return file_result(f, "05", name);
        }
        f->fp = fp;
        if (!idx_load(f, x, 0)) { fclose(fp); f->fp = 0; idx_free(x); return file_result(f, "39", "key file missing or does not match the FD"); }
        idx_cache_load(f, x);
    }
    f->fp = fp; f->idx = x; f->open_mode = (unsigned char)mode; f->at_eof = 0; f->eof_seen = 0;
    return file_result(f, "00", name);
}

static int idx_close(cob_file *f)
{
    cob_idx *x = f->idx;
    if (x && getenv("S32_IDX_STATS"))
        fprintf(stderr, "libcob: %s: %lu keyed lookups, %lu near the last one, %lu full descents\n", file_name(f), x->hint.n_look, x->hint.n_near, x->hint.n_full);
    if (x) {
        if (x->bt.fd >= 0) bt_close(&x->bt, 1);
        idx_free(x);
    }
    if (f->fp) fclose((FILE *)f->fp);
    f->fp = 0; f->idx = 0; f->open_mode = 0; f->at_eof = 0;
    return file_result(f, "00", "key file");
}

/* the first entry of key ki whose key equals k (on the whole key); page/ix out */
static int idx_find(cob_idx *x, unsigned ki, const unsigned char *k, unsigned *page, unsigned *ix)
{
    btf *b = &x->bt;
    unsigned kl = b->k[ki].klen;
    unsigned char ka[BT_KEYMAX + 4];
    memcpy(ka, k, kl); memset(ka + kl, 0, 4);
    if (!bt_first_ge_near(b, ki, ka, kl + 4, &x->hint, page, ix)) return 0;
    bt_read(b, ki, *page, *ix, ka);
    return memcmp(ka, k, kl) == 0;
}

/* an alternate key that would duplicate an existing record's, at a slot
 * other than `skip`: 0 (a 22) if the key forbids duplicates, else the
 * 02 is remembered */
static int alt_check(cob_idx *x, const unsigned char *rec, unsigned skip, int *dup02)
{
    btf *b = &x->bt;
    for (unsigned a = 1; a < b->nkeys; a++) {
        unsigned page, ix, kl = b->k[a].klen;
        if (!idx_find(x, a, rec + b->k[a].off, &page, &ix)) continue;
        int other = 0;
        unsigned char ka[BT_KEYMAX + 4];
        do {
            unsigned slot = bt_read(b, a, page, ix, ka);
            if (memcmp(ka, rec + b->k[a].off, kl) != 0) break;
            if (slot != skip) other = 1;
        } while (!other && bt_step(b, &page, &ix));
        if (!other) continue;
        if (!b->k[a].dups) return 0;
        *dup02 = 1;
    }
    return 1;
}

/* the cursor: deliver from (key, arrival) on */
static void idx_cursor_at(cob_idx *x, unsigned ki, unsigned page, unsigned ix)
{
    bt_read(&x->bt, ki, page, ix, x->cur);
    x->have_cur = 1; x->cur_at = 1;
}
/* ... after the entry just delivered */
static void idx_cursor_after(cob_idx *x, unsigned ki, const unsigned char *ka)
{
    unsigned kl = x->bt.k[ki].klen;
    memcpy(x->cur, ka, kl + 4);
    bt_putbe(x->cur + kl, bt_getbe(ka + kl) + 1);
    x->have_cur = 1; x->cur_at = 0;
}

/* Micro Focus split keys (BP-D2): each the concatenation of its parts,
 * kept in a tail the compiler adds to the record area, so the index sees
 * an ordinary key there.  Put together before every keyed operation from
 * the parts as they stand in the record. */
static void split_fill(cob_file *f)
{
    const unsigned int *t = f->split;
    if (!t) return;
    unsigned n = *t++;
    for (unsigned k = 0; k < n; k++) {
        unsigned dst = *t++, parts = *t++;
        for (unsigned j = 0; j < parts; j++) {
            unsigned off = *t++, len = *t++;
            memmove(f->record + dst, f->record + off, len);
            dst += len;
        }
    }
}

static int idx_write(cob_file *f)
{
    split_fill(f);
    cob_idx *x = f->idx;
    if (!x) return file_result(f, "48", "WRITE to an OPTIONAL file that is absent");
    btf *b = &x->bt;
    const unsigned char *k = (const unsigned char *)f->record + f->keyoff;
    unsigned page, ix;
    if (f->access == 0 && b->k[0].count) {                       /* sequential access: keys must ascend */
        unsigned char last[BT_KEYMAX + 4];
        bt_last(b, 0, &page, &ix); bt_read(b, 0, page, ix, last);
        if (memcmp(last, k, f->keylen) >= 0) return file_result(f, "21", "");
    }
    if (idx_find(x, 0, k, &page, &ix)) return file_result(f, "22", "");    /* duplicate prime key */
    int dup02 = 0;
    if (!alt_check(x, (const unsigned char *)f->record, (unsigned)-1, &dup02)) return file_result(f, "22", "");
    unsigned slot = bt_slot_alloc(b);
    if (!slot_write(f, slot)) { bt_slot_set(b, slot, 0); return file_result(f, write_fail_st(), "write failed"); }
    unsigned seq = b->seq++; b->hdr_dirty = 1;
    unsigned char ex[4 * BT_MAXKEYS];
    for (unsigned a = 1; a < b->nkeys; a++) bt_putbe(ex + 4 * (a - 1), seq);
    bt_insert_x(b, 0, k, seq, slot, ex);
    for (unsigned a = 1; a < b->nkeys; a++) bt_insert(b, a, (const unsigned char *)f->record + b->k[a].off, seq, slot);
    x->last_slot = -1;
    return file_result(f, dup02 ? "02" : "00", "");
}

/* READ with KEY (random): by the prime key (ki 0) or an alternate (ki i),
 * whose value is what the record's field holds; that key becomes the key
 * of reference.  02: another record has the same alternate key. */
int cob_read_key(cob_file *f, int ki)
{
    if (!f->open_mode) return file_result(f, "47", "READ of a file not open");
    if (f->org == COB_ORG_RELATIVE) return rel_read_key(f);
    if (f->org != COB_ORG_INDEXED) cob_fatal("READ ... KEY on a file that is not INDEXED");
    split_fill(f);
    cob_idx *x = f->idx;
    if (!x) return file_result(f, "23", "");
    btf *b = &x->bt;
    if (ki < 0 || (unsigned)ki >= b->nkeys) cob_fatal("READ ... KEY: no such key");
    unsigned kl = b->k[ki].klen, page, ix;
    unsigned char key[BT_KEYMAX], ka[BT_KEYMAX + 4], nk[BT_KEYMAX + 4];
    memcpy(key, f->record + b->k[ki].off, kl);
    if (!idx_find(x, ki, key, &page, &ix)) { x->last_slot = -1; return file_result(f, "23", ""); }
    unsigned slot = bt_read(b, ki, page, ix, ka);
    if (!slot_read(f, slot)) return file_result(f, "30", "read failed");
    x->ref = ki; idx_cursor_after(x, ki, ka); x->last_slot = (int)slot; f->at_eof = 0; f->eof_seen = 0;
    int more = b->k[ki].dups && bt_step(b, &page, &ix) && (bt_read(b, ki, page, ix, nk), !memcmp(nk, key, kl));
    return file_result(f, more ? "02" : "00", "");
}

/* READ NEXT: along the key of reference; 02 when the next record has
 * the same (duplicate-allowing) key value as this one */
static int idx_read_next(cob_file *f)
{
    cob_idx *x = f->idx;
    if (!x) return file_result(f, "10", "");
    if (f->at_eof) { if (f->eof_seen) return file_result(f, "46", ""); f->eof_seen = 1; return file_result(f, "10", ""); }
    btf *b = &x->bt;
    unsigned ki = (unsigned)x->ref, kl = b->k[ki].klen, page, ix;
    if (!x->have_cur) { memset(x->cur, 0, kl + 4); x->have_cur = 1; }
    if (!bt_first_ge(b, ki, x->cur, kl + 4, &page, &ix)) { f->at_eof = 1; f->eof_seen = 1; x->last_slot = -1; return file_result(f, "10", ""); }
    unsigned char ka[BT_KEYMAX + 4], nk[BT_KEYMAX + 4];
    unsigned slot = bt_read(b, ki, page, ix, ka);
    if (!slot_read(f, slot)) return file_result(f, "30", "read failed");
    x->last_slot = (int)slot; idx_cursor_after(x, ki, ka);
    int more = b->k[ki].dups && bt_step(b, &page, &ix) && (bt_read(b, ki, page, ix, nk), !memcmp(nk, ka, kl));
    return file_result(f, more ? "02" : "00", "");
}

/* READ PREVIOUS (COBOL 2002; 2023 14.9.30.4 GR 21d-g): after OPEN, the
 * at end condition; after START, the record START found; after a READ,
 * the record before the one it delivered -- in each case the last entry
 * on the key of reference below a bound, the cursor's entry included
 * (START) or excluded (READ: the cursor is one past it).  The record
 * delivered leaves the cursor one past it, so NEXT and PREVIOUS go on
 * from there either way. */
static int idx_read_prev(cob_file *f)
{
    cob_idx *x = f->idx;
    if (!x) return file_result(f, "10", "");
    if (f->at_eof) { if (f->eof_seen) return file_result(f, "46", ""); f->eof_seen = 1; return file_result(f, "10", ""); }
    if (!x->have_cur) { f->at_eof = 1; f->eof_seen = 1; x->last_slot = -1; return file_result(f, "10", ""); }
    btf *b = &x->bt;
    unsigned ki = (unsigned)x->ref, kl = b->k[ki].klen, page, ix;
    unsigned char bound[BT_KEYMAX + 4], ka[BT_KEYMAX + 4], pk[BT_KEYMAX + 4];
    memcpy(bound, x->cur, kl + 4);
    unsigned t = bt_getbe(bound + kl);
    bt_putbe(bound + kl, x->cur_at ? t + 1 : t - 1);
    int got = bt_first_ge(b, ki, bound, kl + 4, &page, &ix) ? bt_back(b, &page, &ix) : bt_last(b, ki, &page, &ix);
    if (!got) { f->at_eof = 1; f->eof_seen = 1; x->last_slot = -1; return file_result(f, "10", ""); }
    unsigned slot = bt_read(b, ki, page, ix, ka);
    if (!slot_read(f, slot)) return file_result(f, "30", "read failed");
    x->last_slot = (int)slot; idx_cursor_after(x, ki, ka);
    int more = b->k[ki].dups && bt_back(b, &page, &ix) && (bt_read(b, ki, page, ix, pk), !memcmp(pk, ka, kl));
    return file_result(f, more ? "02" : "00", "");
}

/* START: position on key ki, comparing its first len bytes (len < the
 * key's length: a data item that begins where the key begins) with the
 * record area's.  op: 0 =, 1 >, 2 >=, 3 <, 4 <=.  The key becomes the
 * key of reference. */
int cob_start(cob_file *f, int op, int ki, int len)
{
    if (!f->open_mode) return file_result(f, "47", "START of a file not open");
    if (f->open_mode == COB_OPEN_OUTPUT || f->open_mode == COB_OPEN_EXTEND) return file_result(f, "47", "START of a file not open for input or I-O");
    int haslen = op & 0x100; op &= 0xff;        /* WITH LENGTH written: len is its value */
    if (f->org == COB_ORG_SEQ) return seq_start(f, op);
    if (f->org == COB_ORG_RELATIVE) return rel_start(f, op);
    if (f->org != COB_ORG_INDEXED) cob_fatal("START on a file that is not INDEXED");
    split_fill(f);
    cob_idx *x = f->idx;
    if (!x) return file_result(f, "23", "");
    btf *b = &x->bt;
    if (op == 5 || op == 6) {
        /* FIRST, LAST (GR 18-19): the first or last record by the prime
         * key, which becomes the key of reference */
        unsigned page, ix; unsigned char zero[BT_KEYMAX + 4]; memset(zero, 0, sizeof zero);
        int got = op == 5 ? bt_first_ge(b, 0, zero, b->k[0].klen + 4, &page, &ix) : bt_last(b, 0, &page, &ix);
        if (!got) return file_result(f, "23", "");
        x->ref = 0; idx_cursor_at(x, 0, page, ix); x->last_slot = -1; f->at_eof = 0; f->eof_seen = 0;
        return file_result(f, "00", "");
    }
    if (ki < 0 || (unsigned)ki >= b->nkeys) cob_fatal("START ... KEY: no such key");
    unsigned kl = b->k[ki].klen;
    if (haslen && (len < 1 || (unsigned)len > kl)) return file_result(f, "23", "");   /* GR 14: a length outside 1 to the key's */
    unsigned n = (len > 0 && (unsigned)len < kl) ? (unsigned)len : kl;
    const unsigned char *k = (const unsigned char *)f->record + b->k[ki].off;
    unsigned char target[BT_KEYMAX + 4], ka[BT_KEYMAX + 4];
    memset(target, 0, sizeof target); memcpy(target, k, n);
    unsigned page, ix;
    int got = bt_first_ge(b, ki, target, kl + 4, &page, &ix);       /* first entry whose leading n bytes >= k */
    int found = got && (bt_read(b, ki, page, ix, ka), !memcmp(ka, k, n));
    int pos = 0;
    switch (op) {
    case 0: pos = found; break;
    case 2: pos = got; break;
    case 1: case 4:                                                  /* past every entry equal on n bytes */
        if (found) { do { if (!bt_step(b, &page, &ix)) { got = 0; break; } bt_read(b, ki, page, ix, ka); } while (!memcmp(ka, k, n)); }
        if (op == 1) pos = got;
        else pos = got ? bt_back(b, &page, &ix) : bt_last(b, ki, &page, &ix);
        break;
    case 3: pos = got ? bt_back(b, &page, &ix) : bt_last(b, ki, &page, &ix); break;
    }
    if (!pos) return file_result(f, "23", "");
    x->ref = ki; idx_cursor_at(x, ki, page, ix); x->last_slot = -1; f->at_eof = 0; f->eof_seen = 0;
    return file_result(f, "00", "");
}

/* REWRITE (indexed): the record whose prime key the area holds -- under
 * sequential access it must be the last one read (21 otherwise); an
 * alternate key may change, keeping the duplicates rule (22), 02 when a
 * duplicate-allowing one now duplicates */
static int idx_rewrite(cob_file *f)
{
    split_fill(f);
    cob_idx *x = f->idx;
    btf *b = &x->bt;
    const unsigned char *k = (const unsigned char *)f->record + f->keyoff;
    unsigned page, ix;
    int found = idx_find(x, 0, k, &page, &ix);
    unsigned slot = found ? bt_read(b, 0, page, ix, 0) : 0;
    if (f->access == 0) {
        if (x->last_slot < 0) return file_result(f, "43", "");
        if (!found || slot != (unsigned)x->last_slot) return file_result(f, "21", "");
    } else if (!found) return file_result(f, "23", "");
    if (!slot_read_to(f, slot, x->tmp)) return file_result(f, "30", "read failed");
    int dup02 = 0;
    if (!alt_check(x, (const unsigned char *)f->record, slot, &dup02)) return file_result(f, "22", "");
    unsigned seq = b->seq++; b->hdr_dirty = 1;
    unsigned char ex[4 * BT_MAXKEYS];
    int moved = 0;
    if (b->nkeys > 1) bt_extra_get(b, 0, page, ix, ex);
    for (unsigned a = 1; a < b->nkeys; a++) {
        unsigned off = b->k[a].off, kl = b->k[a].klen;
        if (memcmp(x->tmp + off, f->record + off, kl) == 0) continue;
        if (!bt_remove_exact(b, a, x->tmp + off, bt_getbe(ex + 4 * (a - 1)))) bt_remove(b, a, x->tmp + off, slot);
        bt_insert(b, a, (const unsigned char *)f->record + off, seq, slot);
        bt_putbe(ex + 4 * (a - 1), seq); moved = 1;
    }
    if (moved) bt_extra_set(b, 0, page, ix, ex);
    if (!slot_write(f, slot)) return file_result(f, write_fail_st(), "write failed");
    return file_result(f, dup02 ? "02" : "00", "");
}

/* REWRITE: indexed by key; sequential in place after a READ, by the
 * position libcob kept */
int cob_rewrite(cob_file *f, int reclen)
{
    if (!f->open_mode) return file_result(f, "49", "REWRITE of a file not open");
    if (f->open_mode != COB_OPEN_IO) return file_result(f, "49", "REWRITE needs OPEN I-O");
    if (f->org == COB_ORG_RELATIVE) return rel_rewrite(f);
    if (f->org == COB_ORG_INDEXED) return idx_rewrite(f);
    if (f->org == COB_ORG_SEQ) {
        /* the record last read, at the position libcob kept (the libc's
         * buffered stream reads ahead, so its own position is not it);
         * the same length, or 44 */
        FILE *fp = (FILE *)f->fp;
        if (!f->last_len) return file_result(f, "43", "");                 /* no READ before it */
        unsigned len = f->last_len;
        if (f->varying) {
            unsigned want = reclen > 0 ? (unsigned)reclen : len;
            if (f->dep_item) want = (unsigned)cob_get_num(f->dep_item, (const cob_desc *)f->dep_desc);
            if (want != len) return file_result(f, "44", "");
            if (fseek(fp, (long)(f->fpos - 4 - len), 0) != 0) return file_result(f, "30", "seek failed");
            unsigned char rdw[4] = { (unsigned char)((len + 4) >> 8), (unsigned char)((len + 4) & 255), 0, 0 };
            if (fwrite(rdw, 1, 4, fp) != 4 || fwrite(cs_out(f, f->record, len), 1, len, fp) != len) return file_result(f, write_fail_st(), "write failed");
        } else {
            if (reclen > 0 && (unsigned)reclen != len) return file_result(f, "44", "");
            if (fseek(fp, (long)(f->fpos - len), 0) != 0) return file_result(f, "30", "seek failed");
            if (fwrite(cs_out(f, f->record, len), 1, len, fp) != len) return file_result(f, write_fail_st(), "write failed");
        }
        fseek(fp, (long)f->fpos, 0);                    /* back to after the record; the read buffer refills */
        f->last_len = 0;
        return file_result(f, "00", "");
    }
    return file_result(f, "49", "REWRITE on a LINE SEQUENTIAL file");
}

/* DELETE: the record whose prime key is in the record area (random) or
 * the one last read (sequential access); every key forgets it and the
 * slot is free for a later WRITE */
int cob_delete(cob_file *f)
{
    if (!f->open_mode) return file_result(f, "49", "DELETE of a file not open");
    if (f->open_mode != COB_OPEN_IO) return file_result(f, "49", "DELETE needs OPEN I-O");
    if (f->org == COB_ORG_RELATIVE) return rel_delete(f);
    if (f->org != COB_ORG_INDEXED) cob_fatal("DELETE on a file that is not INDEXED");
    split_fill(f);
    cob_idx *x = f->idx;
    btf *b = &x->bt;
    unsigned slot, page, ix;
    if (f->access == 0) {
        if (x->last_slot < 0) return file_result(f, "43", "");
        slot = (unsigned)x->last_slot;
        if (!slot_read_to(f, slot, x->tmp)) return file_result(f, "30", "read failed");
        if (!idx_find(x, 0, x->tmp + f->keyoff, &page, &ix)) return file_result(f, "23", "");
    } else {
        if (!idx_find(x, 0, (const unsigned char *)f->record + f->keyoff, &page, &ix)) return file_result(f, "23", "");
        slot = bt_read(b, 0, page, ix, 0);
        if (!slot_read_to(f, slot, x->tmp)) return file_result(f, "30", "read failed");
    }
    unsigned char ex[4 * BT_MAXKEYS];
    if (b->nkeys > 1) bt_extra_get(b, 0, page, ix, ex);
    for (unsigned a = 1; a < b->nkeys; a++)
        if (!bt_remove_exact(b, a, x->tmp + b->k[a].off, bt_getbe(ex + 4 * (a - 1)))) bt_remove(b, a, x->tmp + b->k[a].off, slot);
    bt_remove(b, 0, x->tmp + f->keyoff, slot);
    bt_slot_set(b, slot, 0);
    x->last_slot = -1;
    return file_result(f, "00", "");
}

/* ====================================================================== */
/* Report Writer                                                           */
/* ====================================================================== */

/* The page model that reproduces GnuCOBOL's line-sequential print files
 * (measured on majesty's .prn: every page is exactly PAGE LIMIT physical
 * lines, blank lines fill the gaps and the tail, no form feed):
 *   - a page heading is presented when the first body group of a page
 *     is generated; an absolute LINE n lands on line n, a relative one on
 *     LINE-COUNTER + n;
 *   - the first body group on a page with a relative first line lands on
 *     FIRST DETAIL (the 85 rule), later ones on LINE-COUNTER + n;
 *   - a body group whose last line would pass LAST DETAIL advances the
 *     page first: blank lines to PAGE LIMIT, then the heading again;
 *   - TERMINATE pads the current page to PAGE LIMIT. */

#define RW_WIDTH 512
static char rw_line[RW_WIDTH];
/* a national field's columns (cobol ISSUES-92): rw_kind 1 says the
 * column's cluster is UTF-8 at rw_pool + rw_off, rw_len bytes, 2 that the
 * column is the second of a double-width one; 0 is rw_line's byte, as for
 * every alphanumeric field.  The pool holds the line's clusters, however
 * long, and grows as it must (cobol ISSUES-94). */
static unsigned char rw_kind[RW_WIDTH];
static int rw_off[RW_WIDTH], rw_len[RW_WIDTH];
static char *rw_pool; static int rw_pool_n, rw_pool_cap;
static char *rw_out; static int rw_out_cap;

static char *rw_pool_room(int n)
{
    if (rw_pool_n + n > rw_pool_cap) {
        rw_pool_cap = (rw_pool_n + n) * 2 + 256;
        rw_pool = realloc(rw_pool, (size_t)rw_pool_cap);
        if (!rw_pool) cob_fatal("out of memory");
    }
    return rw_pool + rw_pool_n;
}

/* CODE (X3.23-1985 XIII 3.6; 2023 13.18.12): the characters each record of
 * a report begins with, kept here by report so the report block the
 * compiler lays out is unchanged for the reports without it */
static struct rw_code { cob_report *r; char *v; int n; } *rwcodes;
static int nrwcodes;
void cob_rw_code(cob_report *r, const char *p, int n)
{
    int k = 0;
    while (k < nrwcodes && rwcodes[k].r != r) k++;
    if (k == nrwcodes) {
        rwcodes = realloc(rwcodes, (size_t)(nrwcodes + 1) * sizeof *rwcodes);
        if (!rwcodes) cob_fatal("out of memory");
        rwcodes[k].r = r; rwcodes[k].v = NULL; nrwcodes++;
    }
    free(rwcodes[k].v);
    rwcodes[k].v = malloc((size_t)n + 1);
    if (!rwcodes[k].v) cob_fatal("out of memory");
    memcpy(rwcodes[k].v, p, (size_t)n); rwcodes[k].n = n;
}

static void rw_put_line(cob_report *r, const char *p, int n)
{
    cob_file *f = r->file;
    const struct rw_code *code = NULL;
    for (int k = 0; k < nrwcodes; k++) if (rwcodes[k].r == r) code = &rwcodes[k];
    if (!f->open_mode || !f->fp) cob_fatal("GENERATE: the report's print file is not open");
    unsigned cn = code ? (unsigned)code->n : 0;
    if (f->org != COB_ORG_LINESEQ && f->recsize) {
        /* a record-oriented print file: each line is one record, space-filled */
        if (cn > f->recsize) cn = f->recsize;
        if (cn) fwrite(code->v, 1, cn, (FILE *)f->fp);
        unsigned room = f->recsize - cn, m = (unsigned)n < room ? (unsigned)n : room;
        fwrite(p, 1, m, (FILE *)f->fp);
        for (unsigned k = m; k < room; k++) fputc(' ', (FILE *)f->fp);
        r->line_counter++;
        return;
    }
    while (n > 0 && p[n - 1] == ' ') n--;
    if (cn) fwrite(code->v, 1, cn, (FILE *)f->fp);
    if (n) fwrite(p, 1, n, (FILE *)f->fp);
    fputc('\n', (FILE *)f->fp);
    r->line_counter++;
}

static void rw_blank_to(cob_report *r, int line)   /* blank lines up to, not including, line */
{
    while (r->line_counter < line - 1) rw_put_line(r, "", 0);
}

/* INITIATE: LINE-COUNTER 0, PAGE-COUNTER 1 (X3.23 VIII-53 3.2.4); the
 * first page is begun by the first GENERATE without counting again */
/* The state the compiler asks about before raising a Report Writer or
 * sort condition (2023 Table 13; the compiler emits the raise, so a
 * condition whose checking is off costs nothing here) */
int cob_rw_active(cob_report *r) { return r->active; }
static int cob_rw_use_depth;        /* inside a USE BEFORE REPORTING procedure (EC-FLOW-REPORT) */
void cob_rw_use_in(void) { cob_rw_use_depth++; }
void cob_rw_use_out(void) { if (cob_rw_use_depth) cob_rw_use_depth--; }
int cob_rw_in_use(void) { return cob_rw_use_depth; }

void cob_rw_initiate(cob_report *r)
{
    r->active = 1;
    r->line_counter = 0; r->page_counter = 1; r->body_seen = 0; r->page_started = 0;
    r->first_gen = 0; r->brk = 0; r->next_line = 0; r->next_page = 0; r->suppress = 0;
    r->gi_pending = ~0;
}
int cob_rw_page_started(cob_report *r) { return r->page_started; }
void cob_rw_first_page(cob_report *r) { r->page_started = 1; }

/* where the next line would land: a body line while no body group has
 * been presented on the page goes to FIRST DETAIL -- the 85 rule for
 * the first body group, and (measured on majesty's activity report) where
 * GnuCOBOL puts a group's remaining lines when they spill onto a new
 * page */
static int rw_target(cob_report *r, int abs, int plus, int is_body)
{
    if (abs) return abs;
    if (is_body && !r->body_seen) return r->next_line ? r->next_line : r->first_detail;
    return r->line_counter + plus;
}

/* 1 if the body group (first line abs/plus, `height` further lines of
 * relative extent) needs a new page before it is presented */
int cob_rw_fit(cob_report *r, int abs, int plus, int height)
{
    if (!r->page_started) return 1;
    if (r->next_page) return 1;
    int first = rw_target(r, abs, plus, 1);
    return first + height > r->last_detail;
}

static int rw_body_bound(cob_report *r, int is_body) { return is_body == 2 ? r->footing : r->last_detail; }

/* end the page: pad to PAGE LIMIT (when anything was printed), count it */
void cob_rw_page_end(cob_report *r)
{
    if (r->page_started) {
        while (r->line_counter < r->page_limit) rw_put_line(r, "", 0);
        r->page_counter++;
    }
    r->page_started = 1;
    r->line_counter = 0; r->body_seen = 0;
    r->next_page = 0;
    r->gi_pending = ~0;                 /* GROUP INDICATE prints again after a page advance */
}

/* a print line: its position is settled first -- blank lines up to it,
 * LINE-COUNTER set to it -- so a SOURCE of LINE-COUNTER on the line
 * prints the line's own number; then the fields; then the write */
void cob_rw_line_begin(cob_report *r, int abs, int plus, int is_body)
{
    int target = rw_target(r, abs, plus, is_body);
    if (target < r->line_counter + 1) target = r->line_counter + 1;
    rw_blank_to(r, target);
    r->line_counter = target;
    memset(rw_line, ' ', RW_WIDTH);
    memset(rw_kind, 0, RW_WIDTH);
    rw_pool_n = 0;
}

/* columns [a, b) become plain bytes; half a double-width character left
 * outside them becomes a space */
static void rw_plain(int a, int b)
{
    if (a < RW_WIDTH && rw_kind[a] == 2) { rw_kind[a - 1] = 0; rw_line[a - 1] = ' '; }
    if (b < RW_WIDTH && rw_kind[b] == 2) { rw_kind[b] = 0; rw_line[b] = ' '; }
    for (int c = a; c < b; c++) rw_kind[c] = 0;
}

void cob_rw_field(int col, const cob_desc *dd, const void *src, const cob_desc *sd)
{
    int nat = dd->cat == COB_NATIONAL || dd->usage == COB_U_NATIONAL;
    int ncol = nat ? (int)dd->size / 2 : (int)dd->size;
    if (col < 1 || col - 1 + ncol > RW_WIDTH) cob_fatal("report line wider than 512 columns");
    rw_plain(col - 1, col - 1 + ncol);
    if (!nat) { cob_move(src, sd, rw_line + col - 1, dd); return; }
    unsigned char t[2 * RW_WIDTH];
    cob_cluster cl[RW_WIDTH];
    cob_move(src, sd, t, dd);
    int n = nat_clusters(t, ncol, cl, RW_WIDTH), x = col - 1, end = col - 1 + ncol;
    memset(rw_line + x, ' ', (size_t)ncol);
    for (int i = 0; i < n && x + cl[i].w <= end; i++) {
        if (cl[i].w == 0) {
            /* takes no column (U+200B): it rides with the column before,
             * whose cluster is the pool's last when this field put it there */
            if (x == col - 1) continue;
            int c = rw_kind[x - 1] == 2 ? x - 2 : x - 1;
            if (rw_kind[c] == 0) {
                char *q = rw_pool_room(1); *q = rw_line[c];
                rw_kind[c] = 1; rw_off[c] = rw_pool_n; rw_len[c] = 1; rw_pool_n++;
            }
            char *q = rw_pool_room(1 + 4 * cl[i].units);
            int m = cluster_utf8(t, &cl[i], q);
            if (rw_off[c] + rw_len[c] == rw_pool_n) { rw_len[c] += m; rw_pool_n += m; }
            continue;
        }
        if (cl[i].units == 1 && !cl[i].lone && nat_at(t, cl[i].off) < 0x80) rw_line[x] = (char)nat_at(t, cl[i].off);
        else {
            char *q = rw_pool_room(1 + 4 * cl[i].units);
            rw_len[x] = cluster_utf8(t, &cl[i], q);
            rw_off[x] = rw_pool_n; rw_pool_n += rw_len[x];
            rw_kind[x] = 1;
            if (cl[i].w == 2) rw_kind[x + 1] = 2;
        }
        x += cl[i].w;
    }
}

void cob_rw_line_write(cob_report *r, int is_body)
{
    r->line_counter--;                  /* rw_put_line counts it again */
    if (rw_out_cap < RW_WIDTH + rw_pool_n) {
        rw_out_cap = RW_WIDTH + rw_pool_n;
        rw_out = realloc(rw_out, (size_t)rw_out_cap);
        if (!rw_out) cob_fatal("out of memory");
    }
    int k = 0;
    for (int c = 0; c < RW_WIDTH; c++) {
        if (rw_kind[c] == 0) rw_out[k++] = rw_line[c];
        else if (rw_kind[c] == 1) { memcpy(rw_out + k, rw_pool + rw_off[c], (size_t)rw_len[c]); k += rw_len[c]; }
    }
    rw_put_line(r, rw_out, k);
    if (is_body) { r->body_seen = 1; r->next_line = 0; }
}

/* a body line that would land past LAST DETAIL spills onto a new page:
 * the compiler renders the heading, and the line then lands on FIRST
 * DETAIL.  Measured on majesty's activity report (a group's trailing blank line
 * starting the next page) and its profit-and-loss report (the same, with
 * TERMINATE padding that page). */
int cob_rw_line_overflows(cob_report *r, int abs, int plus, int is_body)
{
    if (!is_body || !r->page_started) return 0;
    if (r->next_page) return 1;
    return rw_target(r, abs, plus, is_body) > rw_body_bound(r, is_body);
}

/* NEXT GROUP, after its group presented (X3.23 VIII: the final-setting
 * rules, reduced to their effect): an integer ahead of the position
 * moves LINE-COUNTER there; one behind saves itself for the next page;
 * PLUS spaces down; NEXT PAGE defers the next body group to a new page */
void cob_rw_next_group(cob_report *r, int kind, int n)
{
    if (kind == 1) {
        if (n > r->line_counter && n <= r->last_detail) { while (r->line_counter < n) rw_put_line(r, "", 0); }
        else { r->next_page = 1; r->next_line = n; }
    } else if (kind == 2) {
        if (r->line_counter + n > r->last_detail) r->next_page = 1;
        else for (int i = 0; i < n; i++) rw_put_line(r, "", 0);
    } else r->next_page = 1;
}

/* the REPORT FOOTING's place (X3.23 VIII Table 5, as cobc370 derived
 * it): after the PAGE FOOTING when one printed, else from the FOOTING
 * line; a footing that cannot fit takes a page of its own, with no
 * PAGE HEADING after the eject (2.21.4(3)a) */
void cob_rw_rf_begin(cob_report *r, int abs, int plus)
{
    if (!r->page_started) return;
    /* in this engine LINE-COUNTER is the paper: positioning writes lines */
    while (r->line_counter < r->footing) rw_put_line(r, "", 0);
    if (abs ? abs <= r->line_counter : r->line_counter + plus > r->page_limit) {
        while (r->line_counter < r->page_limit) rw_put_line(r, "", 0);
        r->page_counter++; r->line_counter = 0; r->body_seen = 0;
    }
}

void cob_rw_terminate(cob_report *r)
{
    if (r->page_started) while (r->line_counter < r->page_limit) rw_put_line(r, "", 0);
    r->active = 0;
}

/* ====================================================================== */
/* SCREEN SECTION                                                          */
/* ====================================================================== */

/* DISPLAY paints every slot; ACCEPT paints, then runs the focus loop
 * over the TO and USING slots in order (dBase Stage 4's READ, on the
 * same term service): printable keys overwrite and advance, Backspace
 * erases, Tab moves to the next field, Escape and Enter end the ACCEPT,
 * AUTO advances when the field fills.  Each input field's text is then
 * MOVEd into its item through the ordinary conversion matrix.
 * (Enter ends the ACCEPT from any field, Tab moves: docs/screen.md.) */

static void term_need(void)
{
    if (term_up) return;
    out_flush();
    if (term_init() != 0) cob_fatal("the terminal service is not available (run under an emulator with the term service)");
    scr_tty = term_set_raw(1) == 0;
    term_up = 1;
}

void cbl_get_scr_size(unsigned char *lines, unsigned char *cols)
{
    int r = 24, c = 80;
    term_need();
    term_get_size(&r, &c);
    *lines = (unsigned char)(r > 255 ? 255 : r);
    *cols = (unsigned char)(c > 255 ? 255 : c);
}

/* CALL "C$JUSTIFY" USING item mode (BP-G7, compiled to this): the
 * item's text without its leading and trailing spaces, put at the left,
 * the right or the centre (the odd space to the right) of the item */
void cob_c_justify(unsigned char *p, int len, int mode)
{
    int a = 0, b = len;
    while (a < len && p[a] == ' ') a++;
    while (b > a && p[b - 1] == ' ') b--;
    int n = b - a, at = mode == 'L' ? 0 : mode == 'C' ? (len - n) / 2 : len - n;
    if (n == 0 || at == a) return;
    memmove(p + at, p + a, (size_t)n);
    memset(p, ' ', (size_t)at);
    memset(p + at + n, ' ', (size_t)(len - at - n));
}

/* CALL "CBL_CHECK_FILE_EXIST" USING name details (Micro Focus's library
 * routine; ACAS asks it whether a backup script is there): the name ends
 * at a space or a NUL.  0 and the details when the file is there --
 * size PIC X(8) COMP-X, then day, month, year (two bytes), hour, minute,
 * second, hundredths, all COMP-X -- or 35, as GnuCOBOL answers, when it
 * is not. */
int cbl_check_file_exist(const char *name, unsigned char *details)
{
    char path[1024]; int n = 0;
    while (n < (int)sizeof path - 1 && name[n] && name[n] != ' ') { path[n] = name[n]; n++; }
    path[n] = 0;
    struct stat st;
    if (!n || stat(path, &st) != 0) return 35;
    unsigned long long size = (unsigned long long)st.st_size;
    for (int i = 7; i >= 0; i--) { details[i] = (unsigned char)(size & 0xFF); size >>= 8; }
    time_t t = (time_t)st.st_mtime;
    struct tm *tm = localtime(&t);
    if (tm) {
        int y = tm->tm_year + 1900;
        details[8] = (unsigned char)tm->tm_mday; details[9] = (unsigned char)(tm->tm_mon + 1);
        details[10] = (unsigned char)(y >> 8); details[11] = (unsigned char)(y & 0xFF);
        details[12] = (unsigned char)tm->tm_hour; details[13] = (unsigned char)tm->tm_min;
        details[14] = (unsigned char)tm->tm_sec; details[15] = 0;
    }
    return 0;
}

/* the slot's kind, and its item: the high kind bit says the slot holds
 * the address of a cell the compiler fills at ACCEPT/DISPLAY (a
 * subscripted, LINKAGE or EXTERNAL item) */
/* ACCEPT screen-name WITH UPDATE (GnuCOBOL's; BP-G3): for that ACCEPT
 * only, a TO field starts from its item's current value, as a USING
 * field does -- it answers USING here */
static int scr_update_once;
void cob_scr_update_next(void) { scr_update_once = 1; }
static int scr_kind(const cob_scr_field *f)
{
    int k = f->kind & 0x7f;
    return k == COB_SCR_TO && scr_update_once ? COB_SCR_USING : k;
}
static void *scr_item(const cob_scr_field *f) { return (f->kind & 0x80) ? *(void **)f->item : f->item; }

static int scr_has_attr(const cob_scr_field *f)
{
    return (f->flags & (COB_SF_REVERSE | COB_SF_UNDERLINE | COB_SF_HIGHLIGHT | COB_SF_LOWLIGHT)) || (f->rsv & COB_SR_BLINK) || f->fg != 255 || f->bg != 255;
}

/* COBOL's colour numbers (0 black, 1 blue, 2 green, 3 cyan, 4 red, 5
 * magenta, 6 yellow, 7 white) to ANSI's (1 red, 4 blue); 9 = default */
static int scr_ansi_colour(unsigned c) { static const int m[8] = { 0, 4, 2, 6, 1, 5, 3, 7 }; return c < 8 ? m[c] : 9; }

/* BLANK SCREEN with a colour: the screen's default colours until the next
 * such entry (13.18.7.3 rules 3-4); a field with no colour of its own
 * takes them */
static int scr_def_fg = 255, scr_def_bg = 255;
static void scr_attr(const cob_scr_field *f)
{
    int fg = f->fg != 255 ? f->fg : scr_def_fg, bg = f->bg != 255 ? f->bg : scr_def_bg;
    if (!scr_has_attr(f) && fg == 255 && bg == 255) return;
    /* one attribute per field: the term service's cell carries one, so the
     * clauses written together (13.17.2 allows it) are painted by rank --
     * REVERSE-VIDEO, UNDERLINE, HIGHLIGHT, LOWLIGHT, BLINK (screen.md) */
    if (f->flags & COB_SF_REVERSE) term_set_attr(7);
    else if (f->flags & COB_SF_UNDERLINE) term_set_attr(4);
    else if (f->flags & COB_SF_HIGHLIGHT) term_set_attr(1);
    else if (f->flags & COB_SF_LOWLIGHT) term_set_attr(2);
    else if (f->rsv & COB_SR_BLINK) term_set_attr(5);
    else term_set_attr(0);
    if (fg != 255 || bg != 255) term_set_color(scr_ansi_colour(fg), scr_ansi_colour(bg));
}

static void scr_attr_off(const cob_scr_field *f)
{
    int fg = f->fg != 255 ? f->fg : scr_def_fg, bg = f->bg != 255 ? f->bg : scr_def_bg;
    if (!scr_has_attr(f) && fg == 255 && bg == 255) return;
    term_set_attr(0);
    if (fg != 255 || bg != 255) term_set_color(9, 9);
}

static void scr_puts_n(const char *p, unsigned n)
{
    for (unsigned i = 0; i < n; i++) term_putc(p[i]);
}

/* render a FROM/USING item through its picture into buf (width bytes) */
static void scr_render(const cob_scr_field *f, char *buf)
{
    if (scr_kind(f) == COB_SCR_VALUE) { memcpy(buf, f->value, f->width); return; }
    if ((f->rsv & COB_SR_FROMTO) && scr_kind(f) == COB_SCR_TO) { scr_render(f - 1, buf); return; }   /* FROM x TO y: shown from x */
    if (scr_kind(f) == COB_SCR_TO) { memset(buf, ' ', f->width); return; }
    if (f->rsv & COB_SR_DYNLEN) {
        /* the part's own characters; under SIZE, as many as the part has, then spaces */
        unsigned n = f->rsv & COB_SR_DYNSIZE ? (unsigned)(uintptr_t)f->value : f->width;
        if (n > f->width) n = f->width;
        memcpy(buf, scr_item(f), n);
        memset(buf + n, ' ', f->width - n);
        return;
    }
    if (f->rsv & COB_SR_DISPVAL) {
        /* a binary or packed item in a positioned DISPLAY: the text a
         * plain DISPLAY writes for it (sign, digits, point), placed */
        memset(buf, ' ', f->width);
        out_cap = buf; out_cap_n = 0; out_cap_max = (int)f->width;
        cob_display_field(scr_item(f), (const cob_desc *)f->item_desc);
        out_cap = NULL;
        return;
    }
    cob_move(scr_item(f), (const cob_desc *)f->item_desc, buf, (const cob_desc *)f->pic);
}

/* Where a positioned slot (COB_SX_POS) goes: LINE 0 is the line after the
 * last positioned statement, POSITION 0 is column 1, and a CONT slot follows
 * the slot painted before it.  A SCREEN SECTION slot keeps its numbers. */
static int scr_last_line = 1, scr_last_col = 1, scr_last_width = 0;   /* scr_next_line: above, with the console path */

static int scr_off_line, scr_off_col;           /* the screen record's placing (cob_screen.line_off/col_off), while its statement runs */
static int scr_errs;                            /* COB_SCR_E_* found by the statement under way */
static int scr_rows = 24, scr_cols = 80;
static unsigned char scr_cells[256][64];        /* the cells this statement painted, for EC-SCREEN-FIELD-OVERLAP (14.9.11.4 rule 13) */
static void scr_stmt_begin(const cob_screen *s)
{
    scr_off_line = s->line_off; scr_off_col = s->col_off; scr_errs = 0;
    memset(scr_cells, 0, sizeof scr_cells);
    term_get_size(&scr_rows, &scr_cols);
    if (scr_rows < 1) scr_rows = 24;
    if (scr_cols < 1) scr_cols = 80;
}
/* a field's cells claimed; a cell claimed already in this statement is an overlap */
static void scr_claim(int line, int col, unsigned width)
{
    if (line < 1 || line > 256) return;
    for (unsigned i = 0; i < width; i++) {
        int c = col + (int)i;
        if (c < 1 || c > 512) break;
        unsigned char *b = &scr_cells[line - 1][(c - 1) >> 3]; unsigned m = 1u << ((c - 1) & 7);
        if (*b & m) scr_errs |= COB_SCR_E_FIELD_OVERLAP;
        *b |= (unsigned char)m;
    }
}
/* a SCREEN SECTION field outside the terminal (13.18.14.4 rules 18-19, 13.18.35.4 rule 14): column 0 is painted at 1 and noted; a line outside leaves the field out */
static int scr_field_out(const cob_scr_field *f, int line, int col)
{
    if (f->ext & COB_SX_POS) return 0;
    if (col < 1) scr_errs |= COB_SCR_E_STARTING_COLUMN;
    if (line < 1 || line > scr_rows) { scr_errs |= COB_SCR_E_LINE_NUMBER; return 1; }
    return 0;
}
static void scr_pos(const cob_scr_field *f, int *line, int *col)
{
    *line = f->line; *col = f->col;
    if (!(f->ext & COB_SX_POS)) { *line += scr_off_line; *col += scr_off_col; if (*col < 1 && *line >= 1) *col = 1; return; }
    if (f->ext & COB_SX_CONT) { if (!*line) *line = scr_last_line; if (!*col) *col = scr_last_col + scr_last_width; }
    if (!*line) *line = scr_next_line ? scr_next_line : 1;
    if (!*col) *col = 1;
}

void cob_scr_at(cob_scr_field *f, int rrcc)
{
    f->line = (unsigned short)(rrcc / 100); f->col = (unsigned short)(rrcc % 100);
}

/* a national slot (cobol ISSUES-92): PIC N, or a national VALUE, whose
 * picture is a national descriptor; its width is columns */
static int scr_is_nat(const cob_scr_field *f)
{
    const cob_desc *d = (const cob_desc *)f->pic;
    return d && d->cat == COB_NATIONAL;
}

/* set through a screen ACCEPT: a SCREEN SECTION entry's ERASE is ignored
 * during all of it (2023 13.18.21.4 rule 2).  A positioned field's erase
 * (DISPLAY/ACCEPT ... AT ... WITH ERASE, BP-E7) is not the clause and
 * keeps its effect. */
static int scr_accepting;

static void scr_paint_begin(const cob_scr_field *f, int *line, int *col)
{
    int erase = !scr_accepting || (f->ext & COB_SX_POS);
    scr_pos(f, line, col);
    if (erase && (f->ext & COB_SX_ERASE_ALL)) term_clear(0);
    if (erase && (f->rsv & COB_SR_BLANK_LINE)) { term_gotoxy(*line, 1); term_clear(1); }   /* BLANK LINE: the whole line first (13.18.7.3 rule 1; ignored on an ACCEPT, rule 5) */
    term_gotoxy(*line, *col);
    if (erase && (f->ext & COB_SX_ERASE_EOS)) term_clear(2);
    else if (erase && (f->ext & COB_SX_ERASE_EOL)) term_clear(1);
    scr_attr(f);
}

static void scr_paint_end(const cob_scr_field *f, int line, int col)
{
    scr_attr_off(f);
    if (f->ext & COB_SX_POS) { scr_rm_mode = 1; con_col = 1; scr_last_line = line; scr_last_col = col; scr_last_width = (int)f->width; scr_next_line = line + 1; }
}

/* a national slot's clusters into its columns: SECURE shows an asterisk
 * a column, PROMPT its character where a space stands */
static void scr_paint_nat(const cob_scr_field *f, const unsigned char *p, const cob_cluster *cl, int n)
{
    int line, col, x = 0;
    scr_paint_begin(f, &line, &col);
    int prompt = (f->ext & COB_SX_PROMPT) && (scr_kind(f) == COB_SCR_TO || scr_kind(f) == COB_SCR_USING) ? f->prompt : 0;
    for (int i = 0; i < n && x + cl[i].w <= (int)f->width; i++) {
        if (cl[i].space) term_putc(prompt ? prompt : ' ');
        else if (f->flags & COB_SF_SECURE) { for (int j = 0; j < cl[i].w; j++) term_putc('*'); }
        else {
            char *u = malloc(1 + 4 * (size_t)cl[i].units);
            if (!u) cob_fatal("out of memory");
            int m = cluster_utf8(p, &cl[i], u);
            for (int j = 0; j < m; j++) term_putc(u[j]);
            free(u);
        }
        x += cl[i].w;
    }
    for (; x < (int)f->width; x++) term_putc(prompt ? prompt : ' ');
    scr_paint_end(f, line, col);
}

/* a national slot's text, its picture's code units at t: the VALUE
 * literal, the item through the picture, or spaces */
static void scr_nat_load(const cob_scr_field *f, unsigned char *t)
{
    const cob_desc *d = (const cob_desc *)f->pic;
    int nch = (int)d->size / 2;
    if (scr_kind(f) == COB_SCR_VALUE) memcpy(t, f->value, d->size);
    else if (scr_kind(f) == COB_SCR_TO) for (int i = 0; i < nch; i++) nat_put(t, i, ' ');
    else cob_move(scr_item(f), (const cob_desc *)f->item_desc, t, d);
}

static void scr_paint_text(const cob_scr_field *f, const char *buf)
{
    int line, col;
    scr_paint_begin(f, &line, &col);
    int prompt = (f->ext & COB_SX_PROMPT) && (scr_kind(f) == COB_SCR_TO || scr_kind(f) == COB_SCR_USING) ? f->prompt : 0;
    if (f->flags & COB_SF_SECURE) { for (unsigned i = 0; i < f->width; i++) term_putc(buf[i] == ' ' ? ' ' : '*'); }
    else if (prompt) { for (unsigned i = 0; i < f->width; i++) term_putc(buf[i] == ' ' ? prompt : buf[i]); }
    else scr_puts_n(buf, f->width);
    scr_paint_end(f, line, col);
}

static void scr_paint_field(const cob_scr_field *f)
{
    if (scr_is_nat(f)) {
        const cob_desc *d = (const cob_desc *)f->pic;
        int nch = (int)d->size / 2;
        unsigned char *t = malloc(d->size ? d->size : 1);
        cob_cluster *cl = malloc(((size_t)nch + 1) * sizeof *cl);
        if (!t || !cl) cob_fatal("out of memory");
        scr_nat_load(f, t);
        scr_paint_nat(f, t, cl, nat_clusters(t, nch, cl, nch + 1));
        free(t); free(cl);
        return;
    }
    char buf[512];
    if (f->width > sizeof buf) cob_fatal("screen field wider than 512");
    scr_render(f, buf);
    scr_paint_text(f, buf);
}

static void scr_paint_fields(const cob_screen *s)
{
    for (unsigned i = 0; i < s->nfields; i++) {
        const cob_scr_field *f = &s->fields[i];
        if (f->rsv & COB_SR_BLANK_SCREEN) {
            /* the BLANK SCREEN entry's colours are the screen's defaults from here on */
            if (f->fg != 255) scr_def_fg = f->fg;
            if (f->bg != 255) scr_def_bg = f->bg;
            if (!f->width) continue;
        }
        int line, col; scr_pos(f, &line, &col);
        if (scr_field_out(f, line, col)) continue;
        if (!(f->ext & COB_SX_POS)) scr_claim(line, col, f->width);
        scr_paint_field(f);
    }
}
int cob_screen_display(const cob_screen *s)
{
    term_need();
    if (!scr_accepting) scr_stmt_begin(s);
    /* BELL: the tone sounds once, at the start of a DISPLAY however many
     * entries ask for it, and not for an ACCEPT (2023 13.18.6.4 rule 1) */
    if (!scr_accepting)
        for (unsigned i = 0; i < s->nfields; i++)
            if (s->fields[i].rsv & COB_SR_BELL) { term_putc(7); break; }
    term_begin_update();
    if ((s->blank_screen & 3) && (!scr_accepting || (s->blank_screen & 3) == 2)) {
        /* BLANK SCREEN clears and homes (13.18.7.3 rule 2) in the default
         * colours its entry sets (rules 3-4; the word's bytes 1 and 2 carry
         * them, 1 + the colour); ignored during an ACCEPT (rule 5), unless
         * the dialect's */
        if ((s->blank_screen >> 8) & 255) scr_def_fg = ((s->blank_screen >> 8) & 255) - 1;
        if ((s->blank_screen >> 16) & 255) scr_def_bg = ((s->blank_screen >> 16) & 255) - 1;
        if (scr_def_fg != 255 || scr_def_bg != 255) term_set_color(scr_ansi_colour(scr_def_fg), scr_ansi_colour(scr_def_bg));
        term_clear(0);
    }
    scr_paint_fields(s);
    term_end_update();
    return scr_errs;
}
/* the conditions the last screen statement found (COB_SCR_E_*) */
int cob_screen_errs(void) { return scr_errs; }

/* ---- the focus loop (docs/screen.md, "the eventual target") ------------ */
/* Keys: the terminal's characters -- UTF-8 decoded, a byte that is not
 * UTF-8 standing for U+FFFD -- with the ANSI cursor sequences folded into
 * codes of their own, above Unicode's range; a lone Escape is K_ESC. */
enum { K_EOF = -1, K_ESC = 27, K_UP = 0x110001, K_DOWN, K_LEFT, K_RIGHT, K_HOME, K_END, K_DEL, K_BTAB, K_INS,
       K_PGUP, K_PGDN, K_F1, K_F12 = K_F1 + 11 };
enum { KM_SHIFT = 1, KM_ALT = 2, KM_CTRL = 4 };  /* scr_mods: the modifiers a sequence carried (xterm's parameter, less one) */

static int scr_pending = -2;                    /* a byte read past a lone Escape */
static int scr_mods;

/* An escape sequence, the ESC and its introducer ('[' or 'O') read:
 * parameter bytes (digits, ';' between parameters, anything else in
 * 30h-3Fh kept out of the numbers), intermediate bytes (20h-2Fh), and a
 * final byte (40h-7Eh) -- ECMA-48's shape, so a sequence this does not
 * know (a modified key, a mouse report, a paste bracket, CSI u) is
 * swallowed whole and answers 0, never typed into the field.  The
 * second parameter is the modifier (CSI 1;5C: Ctrl-Right), kept in
 * scr_mods; the key is the unmodified one. */
static int scr_sequence(void)
{
    int par[4] = { 0, 0, 0, 0 }, np = 0, priv = 0, d;
    for (;;) {
        d = term_getkey();
        if (d < 0) { scr_pending = K_EOF; return 0; }
        if (d >= '0' && d <= '9') { if (np < 4) par[np] = par[np] * 10 + (d - '0'); }
        else if (d == ';') { if (np < 4) np++; }
        else if (d >= 0x3A && d <= 0x3F) priv = 1;           /* : < = > ? */
        else if (d >= 0x20 && d <= 0x2F) priv = 1;
        else break;
    }
    if (priv) return 0;
    scr_mods = par[1] > 1 ? (par[1] - 1) & 7 : 0;
    switch (d) {
    case 'A': return K_UP;
    case 'B': return K_DOWN;
    case 'C': return K_RIGHT;
    case 'D': return K_LEFT;
    case 'H': return K_HOME;
    case 'F': return K_END;
    case 'Z': scr_mods |= KM_SHIFT; return K_BTAB;
    case 'P': case 'Q': case 'R': case 'S':
        return K_F1 + (d - 'P');                             /* ESC O P..S, CSI 1;m P..S: F1-F4 */
    case '~': {
        int n = par[0];
        if (n >= 11 && n <= 15) return K_F1 + (n - 11);          /* F1-F5 */
        if (n >= 17 && n <= 21) return K_F1 + 5 + (n - 17);      /* F6-F10 */
        if (n == 23 || n == 24) return K_F1 + 10 + (n - 23);     /* F11, F12 */
        return n == 3 ? K_DEL : n == 1 || n == 7 ? K_HOME : n == 4 || n == 8 ? K_END : n == 2 ? K_INS
             : n == 5 ? K_PGUP : n == 6 ? K_PGDN : 0;
    }
    default: return 0;
    }
}

/* How long a byte may follow an ESC and still belong to it: a terminal
 * sends a sequence in one burst, a person takes longer than this. */
#define SCR_ESC_MS 50

static int scr_key(void)
{
    scr_mods = 0;
    int k;
    if (scr_pending != -2) { k = scr_pending; scr_pending = -2; if (k != 27) return k; }
    else k = term_getkey();
    if (k == K_EOF) {
        /* a scripted run (keys on stdin) has run out: RM programs re-prompt
         * on a bad answer, so an ACCEPT that kept returning nothing would
         * repaint forever.  End the run, say so. */
        close_open_files();
        out_flush(); term_down();
        fprintf(stderr, "libcob: end of input on ACCEPT\n");
        exit(2);
    }
    if (k >= 0x80) {
        int need = k >= 0xF0 && k <= 0xF4 ? 3 : k >= 0xE0 && k <= 0xEF ? 2 : k >= 0xC2 && k <= 0xDF ? 1 : 0;
        if (!need) return 0xFFFD;
        unsigned u = (unsigned)k & (0x3Fu >> need);
        for (int j = 0; j < need; j++) {
            int c = term_getkey();
            if (c < 0x80 || c > 0xBF) { if (c != K_EOF) scr_pending = c; return 0xFFFD; }
            u = u << 6 | (unsigned)(c & 0x3F);
        }
        static const unsigned least[4] = { 0, 0x80, 0x800, 0x10000 };
        return u < least[need] || u > 0x10FFFF || (u >= 0xD800 && u <= 0xDFFF) ? 0xFFFD : (int)u;
    }
    if (k != 27) return k;
    /* ESC: the Escape key, or the start of a sequence.  At a terminal
     * the rest of a sequence is on its way and arrives within
     * SCR_ESC_MS; from a file or a pipe whatever follows is already
     * there.  Nothing following is the Escape key. */
    if (!(scr_tty ? term_wait_key(SCR_ESC_MS) : term_kbhit())) return K_ESC;
    int c = term_getkey();
    if (c < 0) { scr_pending = K_EOF; return K_ESC; }
    if (c == '[' || c == 'O') return scr_sequence();
    if (c == 9) { scr_mods = KM_SHIFT; return K_BTAB; }      /* ESC TAB: back-tab on terminals without a Shift-Tab */
    if (c == 27) { scr_pending = 27; return K_ESC; }         /* Escape twice */
    /* ESC and a key in one burst is Alt and that key at a terminal:
     * nothing here takes it, and reading it as Escape would abandon the
     * ACCEPT.  In a script it is the Escape key and then the next key. */
    if (scr_tty) { scr_mods = KM_ALT; return 0; }
    scr_pending = c;
    return K_ESC;
}

/* SPECIAL-NAMES CRT STATUS IS item: the ACCEPT's ending, in GnuCOBOL's
 * numbering -- 0 ordinary, 1001+n function key n, 2001/2002 page up and
 * down, 2005 Escape.  A numeric item takes the number; a three-byte
 * alphanumeric the packed form GnuCOBOL writes; anything else the four
 * digits as text. */
static void *crt_item; static const cob_desc *crt_desc;

void cob_crt_status(void *item, const void *desc) { crt_item = item; crt_desc = desc; }

/* SPECIAL-NAMES' CURSOR IS item, the cursor locator (2023 9.2.5): line
 * and column, three digits each.  The compiler names it before each
 * ACCEPT. */
static unsigned char *cursor_item;
void cob_crt_cursor(void *item, const void *desc) { (void)desc; cursor_item = item; }
static int scr_locator_get(int *line, int *col)
{
    if (!cursor_item) return 0;
    int v[2] = { 0, 0 };
    for (int k = 0; k < 2; k++)
        for (int i = 0; i < 3; i++) {
            unsigned char ch = cursor_item[k * 3 + i];
            if (ch < '0' || ch > '9') return 0;
            v[k] = v[k] * 10 + (ch - '0');
        }
    *line = v[0]; *col = v[1];
    return 1;
}
static void scr_locator_set(int line, int col)
{
    if (!cursor_item) return;
    int v[2] = { line, col };
    for (int k = 0; k < 2; k++)
        for (int i = 2; i >= 0; i--) { cursor_item[k * 3 + i] = (unsigned char)('0' + v[k] % 10); v[k] /= 10; }
}

static void scr_set_status(int fret)
{
    if (!crt_item) return;
    const cob_desc *d = crt_desc;
    if (d->cat == COB_NUM) { cob_put_num(crt_item, d, fret, 0); return; }
    unsigned char *p = crt_item;
    if (d->size == 3) {
        p[0] = '0'; p[1] = 0; p[2] = 0;
        if (fret == 0) { p[1] = '0'; }
        else if (fret == 2005) p[0] = '1';
        else if (fret >= 1001 && fret <= 1064) { p[0] = '1'; p[1] = (unsigned char)(fret - 1000); }
        else if (fret >= 2001 && fret <= 2110) { p[0] = '2'; p[1] = (unsigned char)(fret - 2000); }
        else if (fret >= 8000) p[0] = '9';
        return;
    }
    char b[4]; int n = fret;
    for (int i = 3; i >= 0; i--) { b[i] = (char)('0' + n % 10); n /= 10; }
    for (unsigned i = 0; i < d->size; i++) p[i] = i < 4 ? (unsigned char)b[i] : ' ';
}

static int scr_key_status(int k)
{
    if (k >= K_F1 && k <= K_F12) return 1001 + (k - K_F1);
    return k == K_PGUP ? 2001 : k == K_PGDN ? 2002 : k == K_ESC ? 2005 : 0;
}

static int scr_is_numeric(const cob_scr_field *f)
{
    const cob_desc *d = (const cob_desc *)f->pic;
    return d && (d->cat == COB_NUM || d->cat == COB_NUM_ED);
}

/* the state of one input field under edit */
typedef struct {
    const cob_scr_field *f;
    char *buf;                 /* the field's columns as last rendered */
    unsigned pos;              /* national: the cursor */
    /* a numeric field: the core's description and state (scredit.h);
     * tscale is the scale its digits are read at, cols whether the
     * core's columns are the picture's (not for a P picture, or one the
     * core does not take: the digits are then edited as a plain run) */
    int numeric, tscale, cols;
    int fresh;                 /* just entered: the first digit, point or Backspace replaces the value */
    sn_field *nf;
    sn_state *ns;
    /* national: the text's code units (u, nu of cap) and its clusters,
     * pos counting clusters; ut is the scratch copy an edit is built in */
    int nat, nu, cap, ncl;
    unsigned char *u, *ut;
    cob_cluster *cl;
    /* a text field: the core's description and state (scredit.h) */
    int text;
    se_field *sf;
    se_state *ss;
} scr_edit;

static int nat_cols(const cob_cluster *c, int n) { int w = 0; for (int i = 0; i < n; i++) w += c[i].w; return w; }
static void scr_nat_split(scr_edit *e) { e->ncl = nat_clusters(e->u, e->nu, e->cl, e->cap + 1); }
static void scr_nat_trim(scr_edit *e) { while (e->nu > 0 && nat_at(e->u, e->nu - 1) == ' ') e->nu--; scr_nat_split(e); }
/* the cursor stays on the field: on its last character when it is full */
static void scr_nat_clamp(scr_edit *e)
{
    if ((int)e->pos > e->ncl) e->pos = (unsigned)e->ncl;
    if (e->ncl && nat_cols(e->cl, (int)e->pos) >= (int)e->f->width) e->pos = (unsigned)e->ncl - 1;
}
static int scr_nat_full(const scr_edit *e) { return nat_cols(e->cl, e->ncl) >= (int)e->f->width || e->nu >= e->cap; }

/* units [at, at + cut) of the text become the n units at r; 0, the text
 * as it was, when the result has more units than the item or is wider
 * than both the field and the text before (a field already wider than
 * its columns stays editable) */
static int scr_nat_splice(scr_edit *e, int at, int cut, const unsigned char *r, int n)
{
    int nnu = e->nu - cut + n;
    if (nnu > e->cap) return 0;
    int old_cols = nat_cols(e->cl, e->ncl), old_nu = e->nu;
    memcpy(e->ut, e->u, 2 * (size_t)at);
    memcpy(e->ut + 2 * at, r, 2 * (size_t)n);
    memcpy(e->ut + 2 * (at + n), e->u + 2 * (at + cut), 2 * (size_t)(e->nu - at - cut));
    unsigned char *t = e->u; e->u = e->ut; e->ut = t;
    e->nu = nnu;
    scr_nat_split(e);
    int cols = nat_cols(e->cl, e->ncl);
    if (cols > (int)e->f->width && cols > old_cols) {
        t = e->u; e->u = e->ut; e->ut = t;
        e->nu = old_nu;
        scr_nat_split(e);
        return 0;
    }
    return 1;
}

/* the cluster that starts at or after unit off */
static unsigned scr_nat_pos_at(const scr_edit *e, int off)
{
    for (int i = 0; i < e->ncl; i++) if (e->cl[i].off + e->cl[i].units > off) return (unsigned)(e->cl[i].off >= off ? i : i + 1);
    return (unsigned)e->ncl;
}

/* a character typed into a national field: one that UAX #29 joins to the
 * cluster before the cursor (a combining mark, what follows a ZWJ in an
 * emoji sequence) goes on the end of it; another replaces the cluster
 * under the cursor.  0 when it does not fit. */
static int scr_nat_type(scr_edit *e, uint32_t cp)
{
    unsigned char cu[4];
    int cn = s32u_u16_put(cu, cp), at, cut = 0;
    unsigned pos = e->pos;
    int join = 0;
    if (pos) {
        s32u_clu st; memset(&st, 0, sizeof st);
        int end = e->cl[pos - 1].off + e->cl[pos - 1].units;
        for (int i = 0; i < end; ) { uint32_t c; i += (int)s32u_u16_get(e->u, (size_t)e->nu, (size_t)i, &c); s32u_clu_step(&st, c); }
        join = !s32u_clu_step(&st, cp);
    }
    if (join) at = e->cl[pos - 1].off + e->cl[pos - 1].units;
    else if ((int)pos < e->ncl) { at = e->cl[pos].off; cut = e->cl[pos].units; }
    else at = e->nu;
    if (!scr_nat_splice(e, at, cut, cu, cn)) return 0;
    e->pos = scr_nat_pos_at(e, at + cn);
    return 1;
}

/* the cluster at k removed */
static void scr_nat_delete(scr_edit *e, unsigned k)
{
    if ((int)k >= e->ncl) return;
    scr_nat_splice(e, e->cl[k].off, e->cl[k].units, NULL, 0);
    e->pos = k;
}

/* A numeric field's digits pass between the item, the core and the
 * picture as a DISPLAY number with a separate leading sign, moved by
 * cob_move: any width the picture has, any scale, any item. */
static void scr_num_desc(const scr_edit *e, cob_desc *t)
{
    memset(t, 0, sizeof *t);
    t->cat = COB_NUM; t->usage = COB_U_DISPLAY;
    t->digits = (unsigned char)(e->nf->ni + e->nf->nf); t->scale = (signed char)e->tscale;
    t->flags = COB_F_SIGNED | COB_F_SEPLEAD; t->size = 1u + t->digits;
}

/* the field for the picture: the core's reading of an edited picture, or
 * a run of 9s for a plain one */
static void scr_num_field(scr_edit *e)
{
    const cob_scr_field *f = e->f;
    const cob_desc *d = (const cob_desc *)f->pic;
    char pat[2 * SN_MAXD + 8]; int n = 0;
    e->nf = malloc(sizeof *e->nf); e->ns = calloc(1, sizeof *e->ns);
    if (!e->nf || !e->ns) cob_fatal("out of memory");
    if (d->cat == COB_NUM_ED && d->pic && !sn_field_init(e->nf, d->pic, cob_edit_floating(d->pic), 1) &&
        e->nf->ni + e->nf->nf == d->digits && e->nf->nf == d->scale && e->nf->width == (int)f->width) {
        e->tscale = d->scale; e->cols = 1;
        sn_natural(e->nf);
        return;
    }
    int plain = d->cat == COB_NUM && d->usage == COB_U_DISPLAY && d->scale >= 0 && d->scale <= d->digits && d->digits <= SN_MAXD;
    int digits = d->digits && d->digits <= SN_MAXD ? d->digits : 1;
    /* a P picture: the digit positions it has are its columns, read at
     * the picture's scale */
    if (!plain && d->cat == COB_NUM && d->usage == COB_U_DISPLAY && f->width && f->width <= SN_MAXD && !(d->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL)))
        digits = (int)f->width;
    int frac = plain ? d->scale : 0;
    if (plain && (d->flags & COB_F_SEPLEAD)) pat[n++] = '+';
    for (int i = 0; i < digits - frac; i++) pat[n++] = '9';
    if (frac) pat[n++] = 'V';
    for (int i = 0; i < frac; i++) pat[n++] = '9';
    if (plain && (d->flags & COB_F_SEPTRAIL)) pat[n++] = '+';
    pat[n] = 0;
    sn_field_init(e->nf, pat, 0, 0);
    e->nf->has_sign = (d->flags & COB_F_SIGNED) != 0;
    sn_natural(e->nf);
    e->tscale = plain ? frac : d->scale;
    e->cols = plain && e->nf->width == (int)f->width;
}

/* entering the field: the cursor on the point, the value there to be
 * replaced by the first thing typed, or edited by moving into it */
static void scr_num_start(scr_edit *e)
{
    e->ns->frac = 0; e->ns->pos = e->nf->ni; e->ns->off_end = 0;
    if (e->nf->nf == 0 && e->nf->ni && e->ns->lead == 0) { e->ns->pos = e->nf->ni - 1; e->ns->off_end = 1; }   /* no fraction, and full: on the last digit */
    e->fresh = 1;
}

/* the item's value into the core (a TO field starts from zero) */
static void scr_num_load(scr_edit *e)
{
    cob_desc t; char tb[2 * SN_MAXD + 2];
    scr_num_desc(e, &t);
    memset(tb, '0', sizeof tb); tb[0] = '+';
    if (scr_kind(e->f) == COB_SCR_USING) cob_move(scr_item(e->f), (const cob_desc *)e->f->item_desc, tb, &t);
    else if (e->f->rsv & COB_SR_FROMTO) cob_move(scr_item(e->f - 1), (const cob_desc *)(e->f - 1)->item_desc, tb, &t);   /* FROM x TO y: starts from x */
    sn_enter(e->nf, e->ns, tb + 1, tb[0] == '-' && e->nf->has_sign);
    scr_num_start(e);
}

/* The field's columns: the core's digits through the picture.  While the
 * cursor is in it (cur) the field shows what is being keyed rather than
 * the edited value: a zero typed into a suppressed position is there (it
 * is data until the field is left), the point and the fraction stand
 * though the value is zero, and BLANK WHEN ZERO waits. */
static void scr_num_image(const scr_edit *e, char *out, int cur)
{
    const sn_field *F = e->nf; const sn_state *S = e->ns;
    cob_desc t, dd = *(const cob_desc *)e->f->pic;
    char tb[2 * SN_MAXD + 2];
    scr_num_desc(e, &t);
    sn_digits(F, S, tb + 1); tb[0] = S->neg ? '-' : '+';
    int shown = cur && e->cols && F->edited && S->lead < F->ni && sn_firstsig(F, S) > S->lead;
    if (shown) tb[1 + S->lead] = '1';                   /* edited as a digit that shows, then put back */
    if (cur) dd.flags &= (unsigned char)~COB_F_BLANKZ;
    cob_move(tb, &t, out, &dd);
    if (shown) out[F->icol[S->lead]] = '0';
    if (cur && e->cols && F->edited) {
        if (F->pcol >= 0) out[F->pcol] = cob_dp_comma ? ',' : '.';
        for (int j = 0; j < F->nf; j++) out[F->fcol[j]] = S->fd[j];
    }
}

static void scr_num_paint(scr_edit *e, int cur)
{
    scr_num_image(e, e->buf, cur);
    scr_paint_text(e->f, e->buf);
}

static void scr_num_store(const scr_edit *e)
{
    cob_desc t; char tb[2 * SN_MAXD + 2];
    scr_num_desc(e, &t);
    sn_digits(e->nf, e->ns, tb + 1); tb[0] = e->ns->neg ? '-' : '+';
    cob_move(tb, &t, scr_item(e->f), (const cob_desc *)e->f->item_desc);
}

static int scr_num_zero(const scr_edit *e)
{
    char d[2 * SN_MAXD];
    sn_digits(e->nf, e->ns, d);
    for (int i = 0; i < e->nf->ni + e->nf->nf; i++) if (d[i] != '0') return 0;
    return 1;
}

static unsigned scr_num_cursor(const scr_edit *e)
{
    int c = sn_cursor(e->nf, e->ns);
    if (!e->cols) { c += (int)e->f->width - e->nf->width; if (c < 0) c = 0; }   /* the digits taken as the field's last columns */
    return (unsigned)c < e->f->width ? (unsigned)c : e->f->width - 1;
}

static void scr_beep_f(const cob_scr_field *f) { if (!(f->ext & COB_SX_NOBEEP)) term_putc(7); }   /* NO BEEP: silent */

/* entering a field: the cursor at its start */
static void scr_focus(scr_edit *e) { e->pos = 0; }

/* leaving a field forwards: REQUIRED wants something in it, FULL wants it
 * empty or full */
static int scr_may_leave(const scr_edit *e)
{
    const cob_scr_field *f = e->f;
    if (e->nat) {
        int n = e->nu; while (n > 0 && nat_at(e->u, n - 1) == ' ') n--;
        if ((f->flags & COB_SF_REQUIRED) && !n) return 0;
        if ((f->flags & COB_SF_FULL) && n && !scr_nat_full(e)) return 0;
        return 1;
    }
    if (e->text) {
        if ((f->flags & COB_SF_REQUIRED) && !se_required_ok(e->sf, e->ss)) return 0;
        if ((f->flags & COB_SF_FULL) && !se_full_ok(e->sf, e->ss)) return 0;
        return 1;
    }
    if (f->flags & COB_SF_REQUIRED) {
        if (e->numeric ? scr_num_zero(e) : strspn(e->buf, " ") >= f->width) return 0;
    }
    if ((f->flags & COB_SF_FULL) && e->numeric && !sn_full_ok(e->nf, e->ns)) return 0;
    if ((f->flags & COB_SF_FULL) && !e->numeric) {
        unsigned n = f->width; while (n > 0 && e->buf[n - 1] == ' ') n--;
        if (n != 0 && n != f->width) return 0;
    }
    return 1;
}

/* JUSTIFIED (2023 13.18.32): a text field's characters go to the right
 * of the screen item when the cursor leaves it */
static void scr_text_justify(scr_edit *e)
{
    const cob_desc *d = (const cob_desc *)e->f->pic;
    if (!e->text || !d || !(d->flags & COB_F_JUST)) return;
    unsigned w = e->f->width, n = w;
    se_text(e->sf, e->ss, e->buf);
    while (n > 0 && e->buf[n - 1] == ' ') n--;
    if (n == 0 || n == w) return;
    memmove(e->buf + (w - n), e->buf, n); memset(e->buf, ' ', w - n);
    int ins = e->ss->insert;
    se_enter(e->sf, e->ss, e->buf, 0);
    e->ss->insert = ins;
}

/* a text field as the core has it: the prompt character after the data
 * while the cursor is in the field (`cur`), spaces otherwise */
static void scr_paint_edit(const scr_edit *e, int cur)
{
    char img[SE_MAXW];
    int line, col;
    se_image(e->sf, e->ss, img, cur);
    scr_paint_begin(e->f, &line, &col);
    scr_puts_n(img, e->f->width);
    scr_paint_end(e->f, line, col);
}

/* The cursor goes from one input field to another: the field left is
 * shown as it stands, the field entered starts its editing again (a
 * text field keeps its text and takes the ACCEPT's insert mode;
 * at_end: arriving by Left, at the end of its data). */
static int scr_insert_mode;

/* Insert mode shows in the cursor: a bar between characters, where
 * replace mode has the terminal's own cursor on one (the term service's
 * cursor style; a host without it leaves the cursor as it is). */
static int scr_cursor_now = TERM_CURSOR_DEFAULT;
static void scr_cursor_style(int style)
{
    if (style == scr_cursor_now) return;
    scr_cursor_now = style;
    term_set_cursor(style);
}
static void scr_move(scr_edit *ed, unsigned *cur, unsigned to, int at_end)
{
    scr_edit *from = &ed[*cur], *e = &ed[to];
    if (from->text && to != *cur) { scr_text_justify(from); term_begin_update(); scr_paint_edit(from, 0); term_end_update(); }
    if (from->numeric && to != *cur) { term_begin_update(); scr_num_paint(from, 0); term_end_update(); }
    *cur = to;
    scr_focus(e);
    if (e->numeric) {
        /* the field as it stands is what is edited now: its digits
         * again from the first that shows (by Left: on its last) */
        char d[2 * SN_MAXD]; int neg = e->ns->neg;
        sn_digits(e->nf, e->ns, d);
        sn_enter(e->nf, e->ns, d, neg);
        scr_num_start(e);
        if (at_end && e->nf->nf) { e->ns->frac = 1; e->ns->pos = e->nf->nf - 1; }
        term_begin_update(); scr_num_paint(e, 1); term_end_update();
    }
    if (e->text) {
        se_reenter(e->sf, e->ss, at_end);
        e->ss->insert = scr_insert_mode;
        term_begin_update(); scr_paint_edit(e, 1); term_end_update();
    }
}

/* Returns 1 for the endings ON EXCEPTION takes (2023 14.9.1.4 rule 25):
 * a function key, or an ACCEPT that could not be made. */
static int screen_accept(const cob_screen *s);
int cob_screen_accept(const cob_screen *s)
{
    scr_accepting = 1;
    int r = screen_accept(s);
    scr_accepting = 0;
    scr_update_once = 0;
    cursor_item = NULL;
    return r;
}
static int screen_accept(const cob_screen *s)
{
    term_need();
    scr_stmt_begin(s);
    cob_screen_display(s);
    unsigned nin = 0;
    for (unsigned i = 0; i < s->nfields; i++)
        if (scr_kind(&s->fields[i]) == COB_SCR_TO || scr_kind(&s->fields[i]) == COB_SCR_USING) nin++;
    if (!nin) { scr_set_status(8000); return 1; }   /* no input screen item: unsuccessful (2023 9.2.3) */
    scr_edit *ed = calloc(nin, sizeof *ed);
    if (!ed) cob_fatal("out of memory");
    unsigned k = 0;
    for (unsigned i = 0; i < s->nfields; i++) {
        const cob_scr_field *f = &s->fields[i];
        if (scr_kind(f) != COB_SCR_TO && scr_kind(f) != COB_SCR_USING) continue;
        scr_edit *e = &ed[k++];
        e->f = f;
        e->buf = malloc(f->width + 1);
        if (!e->buf) cob_fatal("out of memory");
        memset(e->buf, ' ', f->width); e->buf[f->width] = 0;
        if (scr_is_nat(f)) {
            e->nat = 1;
            e->cap = (int)((const cob_desc *)f->pic)->size / 2;
            e->u = malloc(2 * (size_t)e->cap + 2);
            e->ut = malloc(2 * (size_t)e->cap + 2);
            e->cl = malloc(((size_t)e->cap + 1) * sizeof *e->cl);
            if (!e->u || !e->ut || !e->cl) cob_fatal("out of memory");
            scr_nat_load(f, e->u);
            e->nu = e->cap;
            scr_nat_trim(e);
            continue;
        }
        scr_render(f, e->buf);
        e->numeric = scr_is_numeric(f);
        if (!e->numeric) {
            /* a text field: the core takes it from here.  An input slot
             * carries its picture, a symbol a column, where a VALUE slot
             * has its literal (X everywhere when there is none: a group,
             * a part, a SIZE that is not the picture's). */
            const char *mask = f->value;
            e->text = 1;
            e->sf = malloc(sizeof *e->sf); e->ss = calloc(1, sizeof *e->ss);
            if (!e->sf || !e->ss) cob_fatal("out of memory");
            se_field_init(e->sf, mask && strlen(mask) == f->width ? mask : NULL, (int)f->width,
                          ((f->flags & COB_SF_SECURE) ? SE_F_SECURE : 0) | ((f->ext & COB_SX_PROMPT) ? 0 : SE_F_NOPROMPT), f->prompt);
            se_enter(e->sf, e->ss, e->buf, 0);
        }
        if (e->numeric) { scr_num_field(e); scr_num_load(e); }
    }
    unsigned cur = 0;
    int done = 0, abandon = 0, fret = 0;
    scr_insert_mode = 0;                        /* each ACCEPT starts in replace mode */
    /* a numeric field with nothing to show starts as zeros (2023
     * 14.9.1.4 rule 13), through its picture */
    for (unsigned i = 0; i < nin; i++)
        if (ed[i].numeric && scr_kind(ed[i].f) == COB_SCR_TO && !(ed[i].f->ext & COB_SX_POS)) {   /* a screen item's; a positioned ACCEPT leaves what is there */ term_begin_update(); scr_num_paint(&ed[i], 0); term_end_update(); }
    /* the cursor starts in the first input field, or where the CURSOR
     * item says when that is in one (rule 18) */
    {
        int ln, cl;
        if (scr_locator_get(&ln, &cl))
            for (unsigned i = 0; i < nin; i++) {
                int fl, fc; scr_pos(ed[i].f, &fl, &fc);
                if (ln != fl || cl < fc || cl >= fc + (int)ed[i].f->width) continue;
                cur = i;
                if (ed[i].text) {                       /* the position too, as far as the data goes */
                    const se_field *F = ed[i].sf; se_state *S = ed[i].ss;
                    int k = 0, n = se_len(F, S);
                    while (k < F->nd - 1 && F->col[k] < cl - fc) k++;
                    S->pos = k < n ? k : n < F->nd ? n : F->nd - 1;
                }
                break;
            }
    }
    if (ed[cur].text) { term_begin_update(); scr_paint_edit(&ed[cur], 1); term_end_update(); }
    if (ed[cur].numeric) { term_begin_update(); scr_num_paint(&ed[cur], 1); term_end_update(); }
    while (!done) {
        scr_edit *e = &ed[cur];
        const cob_scr_field *f = e->f;
        { int ln, cl; scr_pos(f, &ln, &cl); term_gotoxy(ln, cl + (int)(e->text ? (unsigned)se_cursor(e->sf, e->ss) : e->numeric ? scr_num_cursor(e) : e->nat ? (unsigned)nat_cols(e->cl, (int)e->pos) : e->pos)); }
        scr_cursor_style(e->text && e->ss->insert ? TERM_CURSOR_BAR : TERM_CURSOR_DEFAULT);
        int key = scr_key();
        if (key == K_EOF) { done = 1; break; }
        if (key == K_ESC) { done = 1; abandon = 1; fret = 2005; break; }
        if ((key >= K_F1 && key <= K_F12) || key == K_PGUP || key == K_PGDN) {
            fret = scr_key_status(key);         /* an exception key ends the ACCEPT, the fields kept */
            done = 1; break;
        }
        /* Enter is the terminator key from any field (2023 9.2.3, CRT
         * status 0000: "the operator pressing the enter key"), as GnuCOBOL
         * and Micro Focus have it; Tab and Down move to the next input
         * field in the order the screen declares them (AUTO's "next input
         * field declared"), wrapping.  REQUIRED and FULL hold the field the
         * cursor is in (2023 13.18.47.4 rule 3, 13.18.26.4 rule 3). */
        if (key == '\r' || key == '\n' || key == '\t' || key == K_DOWN) {
            if (!scr_may_leave(e)) { scr_beep_f(e->f); continue; }
            if (key == '\r' || key == '\n') { done = 1; continue; }
            scr_move(ed, &cur, cur + 1 < nin ? cur + 1 : 0, 0);
            continue;
        }
        /* Up, Shift-Tab and Home leave the field as Tab does: REQUIRED and
         * FULL refuse any cursor move out of it (2023 13.18.47.4 rule 3,
         * 13.18.26.4 rule 3).  Home is the first field of the screen
         * (ADIS's Home; its start-of-field has no key). */
        if (key == K_UP || key == K_BTAB || key == K_HOME) {
            if (!scr_may_leave(e)) { scr_beep_f(e->f); continue; }
            scr_move(ed, &cur, key == K_HOME ? 0 : cur ? cur - 1 : nin - 1, 0);
            continue;
        }
        if (e->numeric) {
            /* a numeric field: the core edits its digits (scredit.h) */
            int fn, ch = 0;
            if (key >= '0' && key <= '9') { fn = SN_DIGIT; ch = key; }
            else if (key == (cob_dp_comma ? ',' : '.')) fn = SN_POINT;
            else if (key == '-') fn = SN_MINUS;
            else if (key == '+') fn = SN_PLUS;
            else if (key == K_LEFT) fn = SN_LEFT;
            else if (key == K_RIGHT) fn = SN_RIGHT;
            else if (key == K_END) fn = SN_END;
            else if (key == 8 || key == 127) fn = SN_BACKSPACE;
            else if (key == K_DEL) fn = SN_DELETE;
            else if (key == 24) fn = SN_CLEAR_FIELD;            /* Ctrl-X */
            else if (key == 26) fn = SN_CLEAR_EOF;              /* Ctrl-Z */
            else if (key == 1) fn = SN_UNDO;                    /* Ctrl-A */
            else { if (key >= 32 && key < 127) scr_beep_f(f); continue; }   /* a character a number does not take */
            /* a point where there is no fraction, a sign on an unsigned
             * picture: refused, and the field is as it was */
            if ((fn == SN_POINT && !e->nf->nf) || ((fn == SN_MINUS || fn == SN_PLUS) && !e->nf->has_sign)) { scr_beep_f(f); continue; }
            if (e->fresh && (fn == SN_DIGIT || fn == SN_POINT || fn == SN_BACKSPACE)) sn_key(e->nf, e->ns, SN_CLEAR_FIELD, 0);
            if (fn != SN_MINUS && fn != SN_PLUS) e->fresh = 0;
            int v = sn_key(e->nf, e->ns, fn, ch);
            if (v == SN_REFUSED) { if (fn == SN_DIGIT || fn == SN_POINT || fn == SN_MINUS || fn == SN_PLUS) scr_beep_f(f); continue; }
            if (v == SN_OK || v == SN_FILLED) { term_begin_update(); scr_num_paint(e, 1); term_end_update(); }
            if (v == SN_FILLED && (f->flags & COB_SF_AUTO)) {
                if (!scr_may_leave(e)) { scr_beep_f(f); continue; }
                if (cur + 1 < nin) scr_move(ed, &cur, cur + 1, 0); else done = 1;
            } else if (v == SN_GO_PREV || v == SN_GO_NEXT || v == SN_GO_LAST) {
                unsigned to = v == SN_GO_PREV ? cur - 1 : v == SN_GO_NEXT ? cur + 1 : nin - 1;
                if ((v == SN_GO_PREV && cur == 0) || (v == SN_GO_NEXT && cur + 1 >= nin) || to == cur) continue;
                if (!scr_may_leave(e)) { scr_beep_f(f); continue; }
                scr_move(ed, &cur, to, v == SN_GO_PREV);
            }
            continue;
        }
        if (e->nat) {
            /* a national field: edited a character (cluster) at a time,
             * the cursor moving by the columns each takes */
            if (key == K_LEFT) { if (e->pos) e->pos--; continue; }
            if (key == K_RIGHT) {
                if ((int)e->pos < e->ncl) e->pos++;
                else if (!scr_nat_full(e)) scr_nat_type(e, ' ');
                scr_nat_clamp(e); continue;
            }
            if (key == K_END) { scr_nat_trim(e); e->pos = (unsigned)e->ncl; scr_nat_clamp(e); continue; }
            if (key == 8 || key == 127 || key == K_DEL) {
                if (key != K_DEL && !e->pos) continue;
                unsigned at = key == K_DEL ? e->pos : e->pos - 1;
                if ((int)at >= e->ncl) continue;
                scr_nat_delete(e, at);
                scr_paint_nat(f, e->u, e->cl, e->ncl);
                continue;
            }
            if (key >= 32 && key != 127 && key < 0x110000) {
                if (!scr_nat_type(e, (uint32_t)key)) { scr_beep_f(e->f); continue; }
                scr_paint_nat(f, e->u, e->cl, e->ncl);
                if (scr_nat_full(e) && (f->flags & COB_SF_AUTO)) {
                    if (!scr_may_leave(e)) { scr_beep_f(e->f); scr_nat_clamp(e); continue; }
                    if (cur + 1 < nin) scr_move(ed, &cur, cur + 1, 0); else done = 1;
                }
                scr_nat_clamp(e);
                continue;
            }
            continue;
        }
        /* a text field: the core edits it (scredit.h); here its keys are
         * named, its verdicts acted on and the field repainted */
        {
            int fn, ch = 0;
            if (key == K_LEFT) fn = SE_LEFT;
            else if (key == K_RIGHT) fn = SE_RIGHT;
            else if (key == K_END) fn = SE_END;
            else if (key == 8 || key == 127) fn = SE_BACKSPACE;
            else if (key == K_DEL) fn = SE_DELETE;
            else if (key == K_INS) fn = SE_INSERT_TOGGLE;
            else if (key == 24) fn = SE_CLEAR_FIELD;            /* Ctrl-X */
            else if (key == 26) fn = SE_CLEAR_EOF;              /* Ctrl-Z */
            else if (key == 1) fn = SE_UNDO;                    /* Ctrl-A */
            else if (key == 15) fn = SE_INSERT_SPACE;           /* Ctrl-O */
            else if (key == 18) fn = SE_RESTORE_CHAR;           /* Ctrl-R */
            else if (key == 6) fn = SE_CHANGE_CASE;             /* Ctrl-F */
            else if (key >= 32 && key < 127) { fn = SE_CHAR; ch = key; }
            else continue;                                      /* other keys: nothing */
            int v = se_key(e->sf, e->ss, fn, ch);
            scr_insert_mode = e->ss->insert;
            if (v == SE_REFUSED) { if (fn == SE_CHAR) scr_beep_f(f); continue; }   /* a character the picture does not take */
            if (v == SE_OK || v == SE_FILLED) { term_begin_update(); scr_paint_edit(e, 1); term_end_update(); }
            if (v == SE_FILLED && (f->flags & COB_SF_AUTO)) {
                if (!scr_may_leave(e)) { scr_beep_f(f); continue; }
                if (cur + 1 < nin) scr_move(ed, &cur, cur + 1, 0); else done = 1;
            } else if (v == SE_GO_PREV || v == SE_GO_NEXT || v == SE_GO_LAST) {
                /* Left at the first position, Right or End at the end of
                 * the data: on into the neighbouring field, if there is one */
                unsigned to = v == SE_GO_PREV ? cur - 1 : v == SE_GO_NEXT ? cur + 1 : nin - 1;
                if ((v == SE_GO_PREV && cur == 0) || (v == SE_GO_NEXT && cur + 1 >= nin) || to == cur) continue;
                if (!scr_may_leave(e)) { scr_beep_f(f); continue; }
                scr_move(ed, &cur, to, v == SE_GO_PREV);
            }
        }
    }
    scr_cursor_style(TERM_CURSOR_DEFAULT);
    /* the field the cursor was in, as it is left; the cursor locator is
     * where the cursor stood when the key was pressed (2023 9.2.5) */
    {
        scr_edit *e = &ed[cur];
        int ln, cl; scr_pos(e->f, &ln, &cl);
        scr_locator_set(ln, cl + (int)(e->text ? (unsigned)se_cursor(e->sf, e->ss) : e->numeric ? scr_num_cursor(e) : e->nat ? (unsigned)nat_cols(e->cl, (int)e->pos) : e->pos));
    }
    if (ed[cur].text || ed[cur].numeric) {
        if (!abandon) scr_text_justify(&ed[cur]);
        term_begin_update();
        if (ed[cur].text) scr_paint_edit(&ed[cur], 0); else scr_num_paint(&ed[cur], 0);
        { int ln, cl; scr_pos(ed[cur].f, &ln, &cl); term_gotoxy(ln, cl + (int)(ed[cur].text ? (unsigned)se_cursor(ed[cur].sf, ed[cur].ss) : scr_num_cursor(&ed[cur]))); }   /* the cursor where the operator left it */
        term_end_update();
    }
    scr_set_status(fret);
    if (!abandon) {
        /* commit every input field into its item */
        for (unsigned i = 0; i < nin; i++) {
            scr_edit *e = &ed[i];
            const cob_scr_field *f = e->f;
            if (e->numeric) scr_num_store(e);
            else if (e->nat) {
                cob_desc td; memset(&td, 0, sizeof td);
                td.cat = COB_NATIONAL; td.usage = COB_U_DISPLAY; td.size = 2u * (unsigned)e->cap;
                unsigned char *t = malloc(td.size ? td.size : 1);
                if (!t) cob_fatal("out of memory");
                memcpy(t, e->u, 2 * (size_t)e->nu);
                for (int q = e->nu; q < e->cap; q++) nat_put(t, q, ' ');
                cob_move(t, &td, scr_item(f), (const cob_desc *)f->item_desc);
                free(t);
            } else {
                cob_desc td; memset(&td, 0, sizeof td);
                td.cat = COB_ALNUM; td.usage = COB_U_DISPLAY; td.size = f->width;
                if (e->text) se_text(e->sf, e->ss, e->buf);
                cob_move(e->buf, &td, scr_item(f), (const cob_desc *)f->item_desc);
            }
        }
    }
    for (unsigned i = 0; i < nin; i++) { free(ed[i].buf); free(ed[i].u); free(ed[i].ut); free(ed[i].cl); free(ed[i].sf); free(ed[i].ss); free(ed[i].nf); free(ed[i].ns); }
    free(ed);
    return fret != 0;
}

/* ====================================================================== */
/* Stage 9: INSPECT, reference modification, the clock                     */
/* ====================================================================== */

/* the integer value of the numeric stack's top; pops it */
/* a reference modification's position: as cob_pop_int, a fraction noted
 * for the bound check (8.4.3.3.4 rule 5: a non-integer position is out
 * of range; cobol ISSUES-94 E17) */
int cob_pop_int(void);
int cob_pop_pos(void)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[nsp - 1];
    if (a->scale > 0) {
        long long f;
        div_pow10(a->v < 0 ? -a->v : a->v, a->scale, &f);
        if (f) pos_nonint = 1;
    }
    return cob_pop_int();
}
/* CONTINUE AFTER expression SECONDS (2023 14.9.9): the value on the
 * numeric stack, in a 9(9)V99 temporary (the implementor's n and m, GR
 * 1); more than 999,999,999 seconds is that; below zero is zero, and
 * EC-CONTINUE-LESS-THAN-ZERO when checked (1 returned).  The suspension
 * is the libc's nanosleep, the MMIO sleep service. */
int cob_continue_after(void)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num a = nstk[--nsp];
    long long h = cob_rescale(a.v, a.scale, 2);             /* hundredths */
    int neg = h < 0;
    if (neg) h = 0;
    if (h > 99999999999LL) h = 99999999999LL;
    if (h > 0) { struct timespec ts; ts.tv_sec = (time_t)(h / 100); ts.tv_nsec = (long)(h % 100) * 10000000L; nanosleep(&ts, 0); }
    return neg;
}

/* DELETE FILE [OVERRIDE] file-name (2023 14.9.10 format 2): the file
 * removed from storage, and an indexed file's key file with it -- the
 * connector not open (41 if it is), 00 or 05 when it is not there (GR
 * 13, 14); 37 when the medium or the authority refuses (GR 16, 17); the
 * fixed file attributes are not validated (GR 19: none are) */
int cob_delete_file(cob_file *f, int override)
{
    (void)override;
    if (f->open_mode) return file_result(f, "41", "DELETE FILE of an open file");
    const char *name = file_name(f);
    if (!*name) return file_result(f, "31", "the ASSIGN item holds no file name");
    int r = remove(name);
    if (r && errno == ENOENT) return file_result(f, "05", "");
    if (r) return file_result(f, "37", "DELETE FILE: the file cannot be removed");
    if (f->org == COB_ORG_INDEXED) remove(key_file_name(f));
    return file_result(f, "00", "");
}

/* an intrinsic function's integer argument, computed: as cob_pop_int, a
 * fraction noted as an incorrect argument (2023 15.3 rule 6) */
int cob_pop_fnint(void)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[nsp - 1];
    if (a->scale > 0 && a->v % pow10tab[a->scale]) fn_argbad = 1;
    return cob_pop_int();
}

/* the wide stack's top as an integer (a subscript or position computed
 * in a wide statement); pops it */
int cob_wpop_int(void)
{
    if (wsp <= 0) cob_fatal("numeric stack underflow");
    cob_wnum a = wstk[--wsp];
    if (a.isf) {                               /* a float: the nearest integer (MF, for subscripts and reference modification) */
        double x = a.f < 0 ? ceil(a.f - 0.5) : floor(a.f + 0.5);
        return x >= 2147483647.0 ? 0x7fffffff : x <= -2147483647.0 ? -0x7fffffff : (int)x;
    }
    if (a.scale > 0) w_drop_digits(a.m, WL, a.scale, 0, 0);
    if (a.m[1] || a.m[2] || a.m[3] || a.m[0] > 0x7fffffffu) return a.neg ? -0x7fffffff : 0x7fffffff;
    return a.neg ? -(int)a.m[0] : (int)a.m[0];
}
int cob_wpop_pos(void)
{
    if (wsp <= 0) cob_fatal("numeric stack underflow");
    cob_wnum *a = &wstk[wsp - 1];
    if (!a->isf && a->scale > 0) { cob_wnum t = *a; int nz; w_drop_digits(t.m, WL, a->scale, 0, &nz); if (nz) pos_nonint = 1; }
    return cob_wpop_int();
}

int cob_pop_int(void)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[--nsp];
    long long v = a->v;
    if (a->scale > 0) v = div_pow10(v, a->scale, 0);
    return (int)v;
}

/* ALLOCATE's byte count (2002 14.8.3 GR 1): an arithmetic expression's
 * value, a fraction rounded up */
int cob_pop_alloc_size(void)
{
    if (nsp <= 0) cob_fatal("numeric stack underflow");
    cob_num *a = &nstk[--nsp];
    long long v = a->v, d = 1;
    for (int i = 0; i < a->scale; i++) d *= 10;
    long long q = v / d;
    if (v % d > 0) q++;
    return q > 0x7fffffff ? 0x7fffffff : (int)q;
}

/* the number of arguments the last CALL passed, for a called program with
 * OPTIONAL parameters: a trailing argument not passed is omitted (2023
 * 14.9.4 GR 11).  The program reads it at entry and sets it back to -1,
 * "not known", which a program entered from C code sees. */
int cob_call_nargs = -1;
/* ANY LENGTH (2023 13.18.2): each argument's length in bytes, and how
 * many the CALL set; the called program takes them at entry and sets the
 * count back to -1, "none", which a caller compiled -std=85 or C leaves */
int cob_call_lens[16];
int cob_call_nlens = -1;
void cob_anylen_missing(const char *prog)
{
    char m[200];
    snprintf(m, sizeof m, "'%s' has an ANY LENGTH parameter, and its caller passed no lengths (a CALL compiled -std=85, or from C)", prog);
    cob_fatal(m);
}
/* PROCEDURE DIVISION RETURNING for a program (2023 14.8.3): the caller
 * allocates the returning item (14.2.3 GR 6 NOTE 1) and leaves its
 * address here for the program to take at entry; every program compiled
 * -std=2002 says at exit whether it had a returning item, so a CALL ...
 * RETURNING of a C function (the result in r1) is told from one of a
 * COBOL program (the result already in place). */
void *cob_call_retaddr;
int cob_call_returned;

/* ALLOCATE and FREE (2002 14.8.3, 14.8.14): storage from the heap, zeroed
 * (pointers in it NULL, 14.8.3 GR 9), and a list of the blocks this run
 * unit holds, so FREE can tell allocated storage from anything else */
static void **alloc_blk; static int alloc_n, alloc_cap;

void *cob_allocate(int n)
{
    if (n <= 0) return NULL;                    /* GR 2: NULL, no exception */
    void *p = calloc((size_t)n, 1);
    if (!p) return NULL;
    if (alloc_n == alloc_cap) {
        int c = alloc_cap ? 2 * alloc_cap : 16;
        void **nb = realloc(alloc_blk, (size_t)c * sizeof *nb);
        if (!nb) { free(p); return NULL; }
        alloc_blk = nb; alloc_cap = c;
    }
    alloc_blk[alloc_n++] = p;
    return p;
}

/* 0 freed, 1 not storage ALLOCATE obtained (EC-STORAGE-NOT-ALLOC), 2 NULL */
int cob_free(void *p)
{
    if (!p) return 2;
    for (int i = alloc_n - 1; i >= 0; i--)
        if (alloc_blk[i] == p) { free(p); alloc_blk[i] = alloc_blk[--alloc_n]; return 0; }
    return 1;
}

/* a descriptor for item(start:len): the base's category, the given
 * length (0: to the end of the item).  Rotating buffers, like the
 * intrinsic functions'. */
static cob_desc rmdesc[8];
static int rmrot;

/* start and len count character positions: a national item's are two
 * bytes each (2023 8.4.2.4), and its part is national */
const cob_desc *cob_refmod_desc(const cob_desc *base, int start, int len)
{
    /* a USAGE NATIONAL item counts characters: a national part, or a
     * boolean one in national usage (2023 8.4.3.3.4 rule 6) */
    int nat = base->cat == COB_NATIONAL || base->usage == COB_U_NATIONAL, chars = nat ? (int)base->size / 2 : (int)base->size;
    if (start < 1 || start > chars) cob_fatal("reference modification: start is outside the item");
    if (len == 0) len = chars - start + 1;
    if (len < 1 || start - 1 + len > chars) cob_fatal("reference modification: length is outside the item");
    cob_desc *d = &rmdesc[rmrot++ & 7];
    memset(d, 0, sizeof *d);
    if (base->usage == COB_U_BIT) {
        /* bits (cobol ISSUES-84): base->size bits from the scale-th bit; the
         * part starts at bit scale + start - 1, the compiler having put the
         * address at the byte that holds it */
        d->cat = COB_BOOLEAN; d->usage = COB_U_BIT; d->size = (unsigned)len;
        d->scale = (signed char)((base->scale + start - 1) % 8);
        return d;
    }
    d->cat = base->cat == COB_BOOLEAN ? COB_BOOLEAN : nat ? COB_NATIONAL : COB_ALNUM;
    d->usage = base->cat == COB_BOOLEAN && nat ? COB_U_NATIONAL : COB_U_DISPLAY;
    d->size = (unsigned)(nat ? 2 * len : len);
    return d;
}

/* The length in bytes of a part of an item of single-byte characters,
 * the part checked as cob_refmod_desc checks it: for the move of bytes
 * the compiler makes of a part with a computed or omitted length, which
 * needs the length and no descriptor (docs/performance.md). */
int cob_refmod_len_chk(const cob_desc *base, int start, int len)
{
    int chars = (int)base->size;
    if (start < 1 || start > chars) cob_fatal("reference modification: start is outside the item");
    if (len == 0) len = chars - start + 1;
    if (len < 1 || start - 1 + len > chars) cob_fatal("reference modification: length is outside the item");
    return len;
}

/* the part's length in bytes */
int cob_refmod_len(const cob_desc *base, int start, int len)
{
    if (base->usage == COB_U_BIT) return len ? len : (int)base->size - start + 1;   /* bits: positions */
    int nat = base->cat == COB_NATIONAL || base->usage == COB_U_NATIONAL;
    if (len == 0) len = (nat ? (int)base->size / 2 : (int)base->size) - start + 1;
    return nat ? 2 * len : len;
}

/* The same three under >>REF-MOD-ZERO-LENGTH ON (2023 7.3.23, 8.5.4): a
 * length of zero is a zero-length part, not an omitted length (the
 * compiler supplies an omitted one itself for these), and EC-BOUND-REF-MOD
 * takes a start within the item, a length of zero or more, and the two
 * within it (8.4.3.3.3 rule 1c) */
const cob_desc *cob_refmod_desc_z(const cob_desc *base, int start, int len)
{
    int nat = base->cat == COB_NATIONAL || base->usage == COB_U_NATIONAL, chars = nat ? (int)base->size / 2 : (int)base->size;
    if (start < 1 || start > chars) cob_fatal("reference modification: start is outside the item");
    if (len < 0 || start - 1 + len > chars) cob_fatal("reference modification: length is outside the item");
    if (len > 0) return cob_refmod_desc(base, start, len);
    cob_desc *d = &rmdesc[rmrot++ & 7];
    memset(d, 0, sizeof *d);
    d->cat = base->cat == COB_BOOLEAN ? COB_BOOLEAN : nat ? COB_NATIONAL : COB_ALNUM;
    d->usage = base->usage == COB_U_BIT ? COB_U_BIT : base->cat == COB_BOOLEAN && nat ? COB_U_NATIONAL : COB_U_DISPLAY;
    d->size = 0;
    return d;
}
int cob_refmod_len_chk_z(const cob_desc *base, int start, int len)
{
    int chars = (int)base->size;
    if (start < 1 || start > chars) cob_fatal("reference modification: start is outside the item");
    if (len < 0 || start - 1 + len > chars) cob_fatal("reference modification: length is outside the item");
    return len;
}
int cob_refmod_len_z(const cob_desc *base, int start, int len)
{
    (void)start;
    if (base->usage == COB_U_BIT) return len;
    int nat = base->cat == COB_NATIONAL || base->usage == COB_U_NATIONAL;
    return nat ? 2 * len : len;
}
int cob_bound_refmod_z(int start, int len, int size)
{
    if (pos_nonint) { pos_nonint = 0; return 1; }
    if (start < 1 || start > size) return 1;
    return len < 0 || start + len - 1 > size;
}

/* INSPECT, as X3.23 VIII (NC) describes it: one pass over the item, the
 * phrases tried in order at each position; a phrase that matches takes
 * the positions (tallied or replaced), which no later phrase sees; with
 * no match the position is passed over.  BEFORE/AFTER INITIAL bound
 * each phrase's range, found in the item's original contents from its
 * first character (AFTER absent: the phrase sees nothing; BEFORE
 * absent: to the end).  LEADING ends at the first position of its range
 * the phrase does not take; FIRST takes once.  The compiler registers
 * the phrases (cob_inspect_range before each, when it has one), runs
 * the pass, then adds each TALLYING phrase's count to its item. */
static const char *ci_before, *ci_after; static int ci_blen, ci_alen;
void cob_inspect_range(const char *bp, int bl, const char *ap, int al)
{
    ci_before = bp; ci_blen = bl; ci_after = ap; ci_alen = al;
}
static int ci_w = 1;                   /* a character's bytes: 2 for a national item */
static int ci_find(const char *p, int n, const char *x, int xl)
{
    if (xl < 1) return -1;
    for (int i = 0; i + xl <= n; i += ci_w) if (!memcmp(p + i, x, xl)) return i;
    return -1;
}
static struct {
    char *item; int n, np;
    struct { int tallying, kind, plen, lo, hi, done, count; const char *pat, *rep; } ph[32];
    char *real; int signpos, neg;       /* a signed DISPLAY item: inspected without its embedded sign */
    int backward;                       /* INSPECT BACKWARD (2023 14.9.22.4 rule 3): the scan from the right */
} cin;
/* the rightmost occurrence of x in p[0..n), the window to the right of
 * the position: BACKWARD's BEFORE and AFTER boundaries, found in the
 * direction of the scan (2023 14.9.22.4 rule 3, note 1) */
static int ci_rfind(const char *p, int n, const char *x, int xl)
{
    if (xl < 1) return -1;
    for (int i = n - xl; i >= 0; i -= ci_w) if (!memcmp(p + i, x, xl)) return i;
    return -1;
}
/* the range [lo, hi) a phrase's BEFORE / AFTER leave it, in the scan's direction */
static void ci_range(int *lo, int *hi)
{
    *lo = 0; *hi = cin.n;
    if (!cin.backward) {
        if (ci_after) { int i = ci_find(cin.item, cin.n, ci_after, ci_alen); *lo = i < 0 ? cin.n : i + ci_alen; }
        if (ci_before) { int i = ci_find(cin.item, cin.n, ci_before, ci_blen); if (i >= 0) *hi = i; }
    } else {
        /* AFTER x: the positions left of the rightmost x; BEFORE x: those right of it */
        if (ci_after) { int i = ci_rfind(cin.item, cin.n, ci_after, ci_alen); *hi = i < 0 ? 0 : i; }
        if (ci_before) { int i = ci_rfind(cin.item, cin.n, ci_before, ci_blen); if (i >= 0) *lo = i + ci_blen; }
    }
    if (*hi < *lo) *hi = *lo;
    ci_before = ci_after = NULL; ci_blen = ci_alen = 0;
}
void cob_inspect_backward(void) { cin.backward = 1; }
static char ci_copy[4096];
/* a signed numeric DISPLAY item with the sign in a digit is inspected as
 * though it had been moved to an unsigned item of the same size (X3.23
 * INSPECT general rules); the sign goes back afterwards */
void cob_inspect_begin(char *item, int n, const cob_desc *d)
{
    cin.item = item; cin.n = n; cin.np = 0; cin.real = NULL; cin.signpos = -1; cin.neg = 0; cin.backward = 0;
    ci_w = d && (d->cat == COB_NATIONAL || d->usage == COB_U_NATIONAL) ? 2 : 1;     /* positions are characters (2023 14.9.22.4 rule 3) */
    if (d && d->cat == COB_NUM && d->usage == COB_U_DISPLAY && (d->flags & COB_F_SIGNED) && !(d->flags & (COB_F_SEPLEAD | COB_F_SEPTRAIL)) && n > 0 && n <= (int)sizeof ci_copy) {
        int sp = (d->flags & COB_F_LEAD) ? 0 : n - 1;
        unsigned char c = (unsigned char)item[sp];
        memcpy(ci_copy, item, (size_t)n);
        if (c >= 'p' && c <= 'y') { cin.neg = 1; ci_copy[sp] = (char)(c - 'p' + '0'); }
        cin.real = item; cin.item = ci_copy; cin.signpos = sp;
    }
}
void cob_inspect_phrase(int tallying, int kind, const char *pat, int plen, const char *rep)
{
    if (cin.np == 32) cob_fatal("INSPECT: more than 32 phrases");
    int lo, hi; ci_range(&lo, &hi);
    cin.ph[cin.np].tallying = tallying; cin.ph[cin.np].kind = kind; cin.ph[cin.np].pat = pat;
    cin.ph[cin.np].plen = kind == 0 ? ci_w : plen; cin.ph[cin.np].rep = rep;
    cin.ph[cin.np].lo = lo; cin.ph[cin.np].hi = hi; cin.ph[cin.np].done = 0; cin.ph[cin.np].count = 0;
    cin.np++;
}
void cob_inspect_run(void)
{
    /* One pass left to right, the first phrase that matches taking the
     * position.  A one-byte pattern is compared in line (a TALLYING FOR
     * ALL "a" called memcmp per phrase per character), and the LEADING
     * bookkeeping pass runs only when there is a LEADING phrase. */
    int leading = 0, bytewise = ci_w == 1 && cin.np > 0;
    for (int k = 0; k < cin.np; k++) {
        if (cin.ph[k].kind == 2) leading = 1;
        if (cin.ph[k].kind > 1 || cin.ph[k].plen != 1 || cin.ph[k].lo != 0 || cin.ph[k].hi != cin.n) bytewise = 0;
    }
    if (cin.backward && !bytewise) {
        /* BACKWARD (2023 14.9.22.4 rule 3): the leftmost position of the
         * window walks from the right; a match's positions are taken, and
         * no later window reaches into them (they all start further left,
         * so the leftmost start taken so far bounds every window); LEADING
         * ends at the first position of its range, from the right, the
         * phrase does not take; FIRST takes once */
        int min_taken = cin.n;
        for (int pos = cin.n - ci_w; pos >= 0; ) {
            int took = 0, taker = -1;
            for (int k = 0; k < cin.np && !took; k++) {
                if (cin.ph[k].done || pos < cin.ph[k].lo || pos + cin.ph[k].plen > cin.ph[k].hi || pos + cin.ph[k].plen > min_taken) continue;
                int m = cin.ph[k].kind == 0 || !memcmp(cin.item + pos, cin.ph[k].pat, cin.ph[k].plen);
                if (!m) continue;
                if (cin.ph[k].tallying) cin.ph[k].count++;
                else memcpy(cin.item + pos, cin.ph[k].rep, cin.ph[k].plen);
                if (cin.ph[k].kind == 3) cin.ph[k].done = 1;
                took = 1; taker = k; min_taken = pos;
            }
            if (leading)
                for (int k = 0; k < cin.np; k++)
                    if (cin.ph[k].kind == 2 && !cin.ph[k].done && pos + cin.ph[k].plen <= cin.ph[k].hi && taker != k) cin.ph[k].done = 1;
            pos -= ci_w;
        }
        goto done;                              /* the forward passes below are not run */
    }
    if (bytewise) {
        /* every phrase CHARACTERS or ALL of one byte over the whole item:
         * which phrase takes a byte depends on the byte alone, so a table
         * (the first phrase listed wins) and one sweep do it -- the pass
         * below tries every phrase at every position */
        unsigned char who[256];
        memset(who, 0xFF, sizeof who);
        for (int k = 0; k < cin.np; k++) {
            if (cin.ph[k].kind == 0) { for (int c = 0; c < 256; c++) if (who[c] == 0xFF) who[c] = (unsigned char)k; }
            else if (who[(unsigned char)cin.ph[k].pat[0]] == 0xFF) who[(unsigned char)cin.ph[k].pat[0]] = (unsigned char)k;
        }
        unsigned char *p = (unsigned char *)cin.item;
        for (int pos = 0; pos < cin.n; pos++) {
            int k = who[p[pos]];
            if (k == 0xFF) continue;
            if (cin.ph[k].tallying) cin.ph[k].count++;
            else p[pos] = (unsigned char)cin.ph[k].rep[0];
        }
    }
    for (int pos = 0; !bytewise && cin.np && pos < cin.n; ) {
        int took = 0, taker = -1;
        for (int k = 0; k < cin.np && !took; k++) {
            if (cin.ph[k].done || pos < cin.ph[k].lo || pos + cin.ph[k].plen > cin.ph[k].hi) continue;
            int m = cin.ph[k].kind == 0 ||
                    (cin.ph[k].plen == 1 ? cin.item[pos] == cin.ph[k].pat[0] : !memcmp(cin.item + pos, cin.ph[k].pat, cin.ph[k].plen));
            if (!m) continue;
            if (cin.ph[k].tallying) cin.ph[k].count++;
            else if (cin.ph[k].plen == 1) cin.item[pos] = cin.ph[k].rep[0];
            else memcpy(cin.item + pos, cin.ph[k].rep, cin.ph[k].plen);
            if (cin.ph[k].kind == 3) cin.ph[k].done = 1;
            took = cin.ph[k].plen; taker = k;
        }
        /* a LEADING phrase whose range has begun and which did not take
         * this position is over */
        if (leading)
            for (int k = 0; k < cin.np; k++)
                if (cin.ph[k].kind == 2 && !cin.ph[k].done && pos >= cin.ph[k].lo && taker != k) cin.ph[k].done = 1;
        pos += took ? took : ci_w;
    }
done:
    if (cin.real) {
        memcpy(cin.real, cin.item, (size_t)cin.n);
        unsigned char c = (unsigned char)cin.real[cin.signpos];
        if (cin.neg && c >= '0' && c <= '9') cin.real[cin.signpos] = (char)('p' + (c - '0'));
        cin.item = cin.real; cin.real = NULL;
    }
}
int cob_inspect_count(int k) { return cin.ph[k].count; }

/* CONVERTING from TO to [range]: one single-character replacing phrase per
 * character of `from`, all in the range set for the next phrase */
void cob_inspect_convert(const char *from, int n, const char *to)
{
    if (ci_w == 1 && cin.np == 0) {
        /* single-byte characters: one translation table, applied over the
         * range in one sweep.  The phrase-per-character pass below does the
         * same thing at O(length x alphabet) -- 930 instructions a
         * character for CONVERTING a-z.  A character that occurs twice in
         * FROM converts as its first occurrence does (the table is built
         * from the right, so the leftmost wins). */
        int lo, hi; ci_range(&lo, &hi);
        /* the last table is kept: a loop converts with the same FROM and
         * TO every time, and comparing them is cheaper than a rebuild.
         * Their contents are compared, not their addresses, since either
         * may be an item whose value changes */
        static unsigned char tab[256], cfrom[256], cto[256]; static int cn = -1;
        if (!(n == cn && n <= 256 && !memcmp(from, cfrom, (size_t)n) && !memcmp(to, cto, (size_t)n))) {
            for (int c = 0; c < 256; c++) tab[c] = (unsigned char)c;
            for (int i = n - 1; i >= 0; i--) tab[(unsigned char)from[i]] = (unsigned char)to[i];
            if (n <= 256) { memcpy(cfrom, from, (size_t)n); memcpy(cto, to, (size_t)n); cn = n; } else cn = -1;
        }
        unsigned char *p = (unsigned char *)cin.item;
        for (int i = lo; i < hi; i++) p[i] = tab[p[i]];
        return;
    }
    const char *bp = ci_before, *ap = ci_after; int bl = ci_blen, al = ci_alen;
    for (int i = 0; i + ci_w <= n; i += ci_w) {
        ci_before = bp; ci_after = ap; ci_blen = bl; ci_alen = al;
        cob_inspect_phrase(0, 1, from + i, ci_w, to + i);
    }
}

/* FUNCTION CURRENT-DATE: YYYYMMDDhhmmsshh followed by the offset from
 * UTC as +hhmm / -hhmm (21 characters); the guest clock through the
 * emulator, local time as the guest libc gives it */
/* The calendar functions of the 1989 addendum.  Integer 1 is 1601-01-01
 * (Gregorian); a date is yyyymmdd, a day yyyyddd.  An argument that is
 * not a valid date or day gives 0; a day count is ten DISPLAY digits, a
 * date eight, a day-of-year seven, as GnuCOBOL renders them. */
static long civil_to_days(long y, long m, long d)      /* days since 1601-01-01, +1 */
{
    y -= m <= 2;
    long era = (y >= 0 ? y : y - 399) / 400;
    long yoe = y - era * 400;
    long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    long from_0000_03_01 = era * 146097 + doe;
    return from_0000_03_01 - 584694 + 1;                /* 584694 = 1601-01-01 counted from 0000-03-01 */
}
static void days_to_civil(long n, long *y, long *m, long *d)
{
    long z = n - 1 + 584694;
    long era = (z >= 0 ? z : z - 146096) / 146097;
    long doe = z - era * 146097;
    long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    long yy = yoe + era * 400;
    long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    long mp = (5 * doy + 2) / 153;
    *d = doy - (153 * mp + 2) / 5 + 1;
    *m = mp + (mp < 10 ? 3 : -9);
    *y = yy + (*m <= 2);
}
static int leap(long y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
static int valid_date(long y, long m, long d)
{
    static const int mdays[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (y < 1601 || y > 9999 || m < 1 || m > 12 || d < 1) return 0;
    return d <= mdays[m - 1] + (m == 2 && leap(y));
}
static char *fn_digits(long v, int n)
{
    char *b = fn_buffer(n);
    if (v < 0) v = 0;
    for (int i = n - 1; i >= 0; i--) { b[i] = (char)('0' + v % 10); v /= 10; }
    return b;
}
#define MAX_DAY 3067671L                                 /* 9999-12-31 */
/* ---- the 1989 amendment's numeric intrinsics -------------------------- */
/* Arguments arrive on the numeric stack; the result is a sign and 18
 * digits (SIGN LEADING SEPARATE), scale 0 for the integer class and 9
 * for the rest.  Exact i64 arithmetic where the function allows it,
 * libm doubles where it does not (the DBT runs those natively). */


static char *fn_signed18(long long v)
{
    char *b = fn_buffer(20);
    unsigned long long m = v < 0 ? 0 - (unsigned long long)v : (unsigned long long)v;
    b[0] = v < 0 ? '-' : '+';
    mag_to_digits(m, b + 1, 18);
    b[19] = 0;
    return b;
}

/* PCG-XSH-RR-64/32, the pcg32 of O'Neill's family -- the generator
 * ~/tinymux's svdrand.cpp uses when no 128-bit integers exist, which
 * is SLOW-32's situation exactly */
static unsigned long long pcg_state = 0x853c49e6748fea9bULL;
static const unsigned long long pcg_inc = 0xda3e39cb94b95bdbULL;   /* odd */

static unsigned pcg32(void)
{
    unsigned long long old = pcg_state;
    pcg_state = old * 6364136223846793005ULL + pcg_inc;
    unsigned xorshifted = (unsigned)(((old >> 18) ^ old) >> 27);
    unsigned rot = (unsigned)(old >> 59);
    return (xorshifted >> rot) | (xorshifted << ((32 - rot) & 31));
}

static int fn_cmp(const void *a, const void *b)
{
    double x = *(const double *)a, y = *(const double *)b;
    return x < y ? -1 : x > y ? 1 : 0;
}

static void cob_clock(struct tm *out, int *hund, long *gmtoff);

/* YEAR-TO-YYYY (2002 15.81): the year in the 100-year window ending at
 * argument-2 + argument-3 (defaults 50 and the current year) */
static long fn_year_window(long yy, int n, const cob_num *a)
{
    long w = n > 1 ? (long)(a[1].v / pow10tab[a[1].scale]) : 50, cy;
    if (n > 2) cy = (long)(a[2].v / pow10tab[a[2].scale]);
    else { struct tm t; int h; long g; cob_clock(&t, &h, &g); cy = t.tm_year + 1900; }
    long maxy = w + cy;
    if (yy < 0 || yy > 99 || maxy < 1700 || maxy > 9999) return 0;
    return maxy % 100 >= yy ? yy + 100 * (maxy / 100) : yy + 100 * (maxy / 100 - 1);
}

/* An exact numeric function's result (docs/wide.md phase 3): a sign and
 * as many digits as the value needs, at least what the function's
 * 18-digit result had (18 - fscale integer digits, fscale decimals), so
 * any value that fitted before is written as before; the descriptor is
 * cob_fn_var_desc(3)'s.  Past 38 digits the decimals are shortened. */
static char *fn_wresult(const cob_wnum *w, int fscale)
{
    char D[40]; int nd = w_to_digits(w->m, D, 38);
    int ws = w->scale > 38 ? 38 : w->scale;
    int intd = nd - ws; if (intd < 0) intd = 0;
    int scale = ws > fscale ? ws : fscale;
    int iw = 18 - fscale; if (intd > iw) iw = intd;
    if (iw + scale > 38) scale = 38 - iw;
    char *b = fn_buffer(40);
    int zero = nd == 0;
    b[0] = w->neg && !zero ? '-' : '+';
    int o = 1;
    /* the integer digits, right-aligned: D[38 - ws - iw ..], zeros where
     * that runs off the front; then the decimals, left-aligned */
    int lead = iw - (38 - ws); if (lead < 0) lead = 0;
    memset(b + o, '0', (size_t)lead); o += lead;
    memcpy(b + o, D + 38 - ws - (iw - lead), (size_t)(iw - lead)); o += iw - lead;
    int dk = ws < scale ? ws : scale;
    memcpy(b + o, D + 38 - ws, (size_t)dk); o += dk;
    memset(b + o, '0', (size_t)(scale - dk)); o += scale - dk;
    b[o] = 0;
    fn_var_len = o; fn_var_scale = scale; fn_var_digits = iw + scale;
    return b;
}

static int w_isint(const cob_wnum *a)
{
    if (a->isf) return a->f == floor(a->f);
    if (a->scale <= 0) return 1;
    cob_wnum t = *a; int nz = 0;
    w_drop_digits(t.m, WL, a->scale, 0, &nz);
    return !nz;
}
/* a function computed in double: its value to 15 significant digits,
 * what a double holds (so EXP(LOG(5)) is 5, not 4.99999...), as wide as
 * the value is -- MEAN(2000000000 3000000000) is 2500000000 (it was held
 * to nine integer digits, 999999999).  Not a finite number, or past 38
 * digits: an incorrect returned value (2023 15.3), 0. */
static void fn_dres(cob_wnum *r, double x)
{
    if (x == x && fabs(x) < 1e38) {
        int e = x == 0 ? 0 : (int)floor(log10(fabs(x)));
        int sc = 14 - e; if (sc > 30) sc = 30;
        if (sc >= 0) { if (!w_from_dbl(r, x, sc, 1)) return; }
        else if (!w_from_dbl(r, x / pow10d(-sc), 0, 1)) {
            w_scale_up(r->m, -sc);              /* past 15 digits, zeros -- not the double's binary noise, which differs by engine */
            return;
        }
    }
    fn_argbad = 1; memset(r, 0, sizeof *r);
}

/* the exact functions over the wide stack: MAX, MIN, ORD-MAX, ORD-MIN,
 * SUM, RANGE, MIDRANGE, MOD, REM, INTEGER, INTEGER-PART, ABS, SIGN,
 * FRACTION-PART -- any argument of up to 31 digits, the result exact */
char *cob_fn_wnum(int which, int n, int fscale)
{
    cob_wnum *a = &wstk[wsp - n], r;
    memset(&r, 0, sizeof r);
    switch (which) {
    case COB_FN_MAX: case COB_FN_MIN: case COB_FN_ORD_MAX: case COB_FN_ORD_MIN:
    case COB_FN_RANGE: case COB_FN_MIDRANGE: {
        int hi = 0, lo = 0;
        for (int i = 1; i < n; i++) {
            if (w_cmp_val(&a[i], &a[hi]) > 0) hi = i;
            if (w_cmp_val(&a[i], &a[lo]) < 0) lo = i;
        }
        if (which == COB_FN_MAX) r = a[hi];
        else if (which == COB_FN_MIN) r = a[lo];
        else if (which == COB_FN_ORD_MAX) w_from_i64(&r, hi + 1, 0);
        else if (which == COB_FN_ORD_MIN) w_from_i64(&r, lo + 1, 0);
        else if (which == COB_FN_RANGE) { r = a[hi]; w_addsub(&r, &a[lo], 1); }
        else {                                      /* (hi + lo) / 2, one more decimal */
            r = a[hi]; w_addsub(&r, &a[lo], 0);
            if (w_ndigits(r.m) < 38) { w_scale_up(r.m, 1); r.scale++; }
            mp_div_small(r.m, WL, 2);
            if (mp_is_zero(r.m, WL)) r.neg = 0;
        }
        break;
    }
    case COB_FN_SUM:
        r = a[0];
        for (int i = 1; i < n; i++) w_addsub(&r, &a[i], 0);
        break;
    case COB_FN_MOD: case COB_FN_REM: {
        /* on a common scale, |x| mod |y|: REM takes x's sign (x less y times
         * the integer part of x / y); MOD the divisor's, the integers only
         * (x less y times the greatest integer not above x / y) */
        cob_wnum x = a[0], y = a[1];
        if (which == COB_FN_MOD) {
            if (!w_isint(&x) || !w_isint(&y)) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }   /* integers (15.64.3 rule 1) */
            if (x.scale > 0) { w_drop_digits(x.m, WL, x.scale, 0, 0); x.scale = 0; }
            if (y.scale > 0) { w_drop_digits(y.m, WL, y.scale, 0, 0); y.scale = 0; }
        }
        w_align2(&x, &y);
        if (mp_is_zero(y.m, WL)) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }   /* MOD 15.64.3 rule 2, REM 15.77.3 */
        wl_t q[WL], rm[WL];
        mp_divmod(x.m, y.m, WL, q, rm);
        memcpy(r.m, rm, sizeof rm); r.scale = x.scale; r.neg = x.neg && !mp_is_zero(rm, WL);
        if (which == COB_FN_MOD && !mp_is_zero(rm, WL) && x.neg != y.neg) {
            wl_t t[WL]; memcpy(t, y.m, sizeof t); mp_sub(t, rm, WL); memcpy(r.m, t, sizeof t);
            r.neg = y.neg;
        } else if (which == COB_FN_MOD) r.neg = y.neg && !mp_is_zero(r.m, WL);
        break;
    }
    case COB_FN_INTEGER: case COB_FN_INTEGER_PART: case COB_FN_FRACTION_PART: {
        r = a[0];
        if (r.scale > 0) {
            cob_wnum ip = r; int nz;
            w_drop_digits(ip.m, WL, r.scale, 0, &nz);
            ip.scale = 0;
            if (which == COB_FN_INTEGER && r.neg && nz) { wl_t one[WL] = { 1, 0, 0, 0 }; mp_add(ip.m, one, WL); }
            if (which == COB_FN_FRACTION_PART) {
                cob_wnum t = ip; t.neg = r.neg;
                w_addsub(&r, &t, 1);                 /* x less its integer part */
            } else r = ip;
        } else if (which == COB_FN_FRACTION_PART) { memset(r.m, 0, sizeof r.m); r.neg = 0; }
        if (mp_is_zero(r.m, WL)) r.neg = 0;
        break;
    }
    case COB_FN_ABS: r = a[0]; r.neg = 0; break;
    case COB_FN_SIGN: w_from_i64(&r, mp_is_zero(a[0].m, WL) ? 0 : a[0].neg ? -1 : 1, 0); break;
    case COB_FN_PI: case COB_FN_E: {
        /* native arithmetic: an approximation of 3 + 0.1415926535897932384626433832795
         * (2023 15.73.3 rule 1), and of e likewise (15.27.3); these are those 31 decimals */
        const char *k = which == COB_FN_PI ? "31415926535897932384626433832795" : "27182818284590452353602874713527";
        memset(&r, 0, sizeof r);
        w_from_digits(r.m, k, 32); r.scale = 31;
        break;
    }
    case COB_FN_FACTORIAL: {                    /* exact: 33! is the last within 38 digits */
        double k = w_to_dbl(&a[0]);
        if (!w_isint(&a[0]) || k < 0 || k > 33) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }
        w_from_i64(&r, 1, 0);
        for (int i = 2; i <= (int)k; i++) mp_mul_small(r.m, WL, (wl_t)i, 0);
        break;
    }
    /* computed in double (libm; the DBT runs those natively) */
    case COB_FN_MEAN: case COB_FN_MEDIAN: case COB_FN_VARIANCE: {
        /* exact, in decimal, as MIDRANGE is: the quotients to the scale
         * the wide division keeps (at least nine decimals) */
        int anyf = 0;
        for (int i = 0; i < n; i++) anyf |= a[i].isf;
        if (anyf) goto dbl_stats;
        int save = div0; div0 = 0;
        cob_wnum cnt; w_from_i64(&cnt, n, 0);
        if (which == COB_FN_MEDIAN) {
            int *ix = malloc((size_t)n * sizeof *ix);
            if (!ix) cob_fatal("out of memory");
            for (int i = 0; i < n; i++) {
                int j = i;
                while (j > 0 && w_cmp_val(&a[ix[j - 1]], &a[i]) > 0) { ix[j] = ix[j - 1]; j--; }
                ix[j] = i;
            }
            r = a[ix[n / 2]];
            if (!(n & 1)) { cob_wnum two; w_from_i64(&two, 2, 0); w_addsub(&r, &a[ix[n / 2 - 1]], 0); w_div(&r, &two); }
            free(ix);
        } else {
            cob_wnum m = a[0];
            for (int i = 1; i < n; i++) w_addsub(&m, &a[i], 0);
            w_div(&m, &cnt);
            if (which == COB_FN_MEAN) r = m;
            else {
                w_from_i64(&r, 0, 0);
                for (int i = 0; i < n; i++) { cob_wnum d = a[i]; w_addsub(&d, &m, 1); w_mul(&d, &d); w_addsub(&r, &d, 0); }
                w_div(&r, &cnt);
            }
        }
        if (div0) { fn_argbad = 1; w_from_i64(&r, 0, 0); }   /* past 38 digits: not a returned value it can give */
        div0 = save;
        break;
    }
    case COB_FN_STDDEV: dbl_stats: {
        double *d = malloc((size_t)n * sizeof *d);
        if (!d) cob_fatal("out of memory");
        double sum = 0;
        for (int i = 0; i < n; i++) { d[i] = w_to_dbl(&a[i]); sum += d[i]; }
        double m = sum / n, out;
        if (which == COB_FN_MEAN) out = m;
        else if (which == COB_FN_MEDIAN) {
            qsort(d, (size_t)n, sizeof *d, fn_cmp);
            out = (n & 1) ? d[n / 2] : (d[n / 2 - 1] + d[n / 2]) / 2;
        } else {
            double v = 0;
            for (int i = 0; i < n; i++) v += (d[i] - m) * (d[i] - m);
            v /= n;
            out = which == COB_FN_VARIANCE ? v : sqrt(v);
        }
        free(d);
        fn_dres(&r, out);
        break;
    }
    case COB_FN_SQRT: case COB_FN_LOG: case COB_FN_LOG10: case COB_FN_SIN: case COB_FN_COS: case COB_FN_TAN:
    case COB_FN_ASIN: case COB_FN_ACOS: case COB_FN_ATAN: case COB_FN_EXP: case COB_FN_EXP10: {
        if ((which == COB_FN_SIN || which == COB_FN_COS || which == COB_FN_TAN) && !a[0].isf) {
            /* the argument reduced to [0, 2 pi) in decimal first, the
             * exact value's own period: a double holds 16 digits, and
             * SIN(10 ** 24) is sin of 10 ** 24, not of the nearest double
             * (-0.9964..., as GnuCOBOL's MPFR has it; the double's would
             * be -0.5586...) */
            static const char twopi_d[] = "62831853071795864769252867665590057684";   /* 2 pi to 38 digits */
            cob_wnum tp, q, x = a[0];
            memset(&tp, 0, sizeof tp); w_from_digits(tp.m, twopi_d, 38); tp.scale = 37;
            int save = div0; div0 = 0;
            q = x; w_div(&q, &tp);
            if (!div0) {
                int nz; w_drop_digits(q.m, WL, q.scale, 0, &nz); q.scale = 0;   /* the quotient's integer part (toward zero) */
                w_mul(&q, &tp); w_addsub(&x, &q, 1);                           /* x - q * 2 pi: in (-2 pi, 2 pi) */
                a[0] = x;
            }
            div0 = save;
        }
        double x = w_to_dbl(&a[0]), y = 0;
        int bad = 0;
        switch (which) {
        case COB_FN_SQRT: bad = x < 0; if (!bad) y = sqrt(x); break;                 /* 15.84.3 rule 2 */
        case COB_FN_LOG: bad = x <= 0; if (!bad) y = log(x); break;                  /* 15.55.3 rule 2 */
        case COB_FN_LOG10: bad = x <= 0; if (!bad) y = log10(x); break;              /* 15.56.3 rule 2 */
        case COB_FN_SIN: y = sin(x); break;
        case COB_FN_COS: y = cos(x); break;
        case COB_FN_TAN: y = tan(x); break;
        case COB_FN_ASIN: bad = x < -1 || x > 1; if (!bad) y = asin(x); break;       /* argument-1 from -1 to +1 */
        case COB_FN_ACOS: bad = x < -1 || x > 1; if (!bad) y = acos(x); break;
        case COB_FN_ATAN: y = atan(x); break;
        case COB_FN_EXP: y = exp(x); break;
        default: y = pow(10.0, x); break;
        }
        if (bad) { fn_argbad = 1; w_from_i64(&r, 0, 0); } else fn_dres(&r, y);
        break;
    }
    case COB_FN_ANNUITY: {                      /* argument-1 >= 0, argument-2 a positive integer (15.9.3) */
        double x = w_to_dbl(&a[0]), p = w_to_dbl(&a[1]);
        if (x < 0 || !w_isint(&a[1]) || p < 1) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }
        fn_dres(&r, x == 0 ? 1.0 / p : x / (1.0 - pow(1.0 + x, -p)));
        break;
    }
    case COB_FN_PRESENT_VALUE: {                /* argument-1 > -1 (15.74.3) */
        double x = w_to_dbl(&a[0]), pv = 0, f = 1.0 + x, acc = 1.0;
        if (x <= -1) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }
        for (int i = 1; i < n; i++) { acc *= f; pv += w_to_dbl(&a[i]) / acc; }
        fn_dres(&r, pv);
        break;
    }
    case COB_FN_RANDOM: {                       /* a seed: zero or a positive integer (15.75.3) */
        if (n > 0) {
            double k = w_to_dbl(&a[0]);
            if (!w_isint(&a[0]) || k < 0) { fn_argbad = 1; w_from_i64(&r, 0, 0); break; }
            pcg_state = (unsigned long long)k * 2u + 1u; pcg32(); pcg32();
        }
        fn_dres(&r, (double)pcg32() / 4294967296.0);
        break;
    }
    default: cob_fatal("internal: cob_fn_wnum of a function it does not compute");
    }
    wsp -= n;
    return fn_wresult(&r, fscale);
}

char *cob_fn_num(int which, int n)
{
    cob_num *a = &nstk[nsp - n];               /* the n arguments, oldest first */
    char *res = 0;
    switch (which) {
    case COB_FN_MAX: case COB_FN_MIN: case COB_FN_ORD_MAX: case COB_FN_ORD_MIN:
    case COB_FN_SUM: case COB_FN_RANGE: case COB_FN_MIDRANGE: {
        /* exact: everything aligned to the widest scale */
        int sc = 0;
        for (int i = 0; i < n; i++) if (a[i].scale > sc) sc = a[i].scale;
        long long hi = 0, lo = 0, sum = 0; int ihi = 0, ilo = 0;
        for (int i = 0; i < n; i++) {
            long long v = cob_rescale(a[i].v, a[i].scale, sc);
            if (i == 0 || v > hi) { hi = v; ihi = i; }
            if (i == 0 || v < lo) { lo = v; ilo = i; }
            sum += v;
        }
        long long r9;
        switch (which) {
        case COB_FN_MAX: r9 = cob_rescale(hi, sc, 9); break;
        case COB_FN_MIN: r9 = cob_rescale(lo, sc, 9); break;
        case COB_FN_SUM: r9 = cob_rescale(sum, sc, 9); break;
        case COB_FN_RANGE: r9 = cob_rescale(hi - lo, sc, 9); break;
        case COB_FN_MIDRANGE: r9 = cob_rescale(hi + lo, sc, 9) / 2; break;
        case COB_FN_ORD_MAX: r9 = ihi + 1; break;
        default: r9 = ilo + 1; break;
        }
        res = fn_signed18(r9);
        break;
    }
    case COB_FN_MOD: {                          /* integer args; the result has the divisor's sign */
        long long x = a[0].v / pow10tab[a[0].scale], y = a[1].v / pow10tab[a[1].scale];
        if (y == 0 || x * pow10tab[a[0].scale] != a[0].v || y * pow10tab[a[1].scale] != a[1].v) { fn_argbad = 1; res = fn_signed18(0); break; }
        long long r = x % y;
        if (r != 0 && ((r < 0) != (y < 0))) r += y;
        res = fn_signed18(r);
        break;
    }
    case COB_FN_REM: {                          /* a - b * INTEGER-PART(a / b), exact at the common scale */
        int sc = a[0].scale > a[1].scale ? a[0].scale : a[1].scale;
        long long x = cob_rescale(a[0].v, a[0].scale, sc), y = cob_rescale(a[1].v, a[1].scale, sc);
        if (y == 0) { fn_argbad = 1; res = fn_signed18(0); break; }
        long long q = x / y;                    /* truncation is INTEGER-PART */
        res = fn_signed18(cob_rescale(x - q * y, sc, 9));
        break;
    }
    case COB_FN_INTEGER: {                      /* the greatest integer not greater */
        long long k = pow10tab[a[0].scale];
        long long q = a[0].v / k;
        if (a[0].v < 0 && q * k != a[0].v) q--;
        res = fn_signed18(q);
        break;
    }
    case COB_FN_INTEGER_PART:
        res = fn_signed18(a[0].v / pow10tab[a[0].scale]);
        break;
    /* FACTORIAL and the functions computed in double: cob_fn_wnum */
    /* COBOL 2002 */
    case COB_FN_ABS: res = fn_signed18(cob_rescale(a[0].v < 0 ? -a[0].v : a[0].v, a[0].scale, 9)); break;
    case COB_FN_SIGN: res = fn_signed18(a[0].v > 0 ? 1 : a[0].v < 0 ? -1 : 0); break;
    case COB_FN_FRACTION_PART: {
        long long k = pow10tab[a[0].scale];
        res = fn_signed18(cob_rescale(a[0].v - a[0].v / k * k, a[0].scale, 9));
        break;
    }
    case COB_FN_YEAR_TO_YYYY: case COB_FN_DATE_TO_YYYYMMDD: case COB_FN_DAY_TO_YYYYDDD: {
        /* integers; argument-1 below 100, 1000000 or 100000; the window's
         * last year from 1700 to 9999 (15.100.3, 15.23.3, 15.25.3): 0 otherwise */
        long unit = which == COB_FN_DATE_TO_YYYYMMDD ? 10000 : which == COB_FN_DAY_TO_YYYYDDD ? 1000 : 1;
        long v = (long)(a[0].v / pow10tab[a[0].scale]), y = 0;
        int ok = v >= 0 && v < 100 * unit;
        for (int i = 0; i < n; i++) if (a[i].scale > 0 && a[i].v % pow10tab[a[i].scale]) ok = 0;
        if (ok) y = fn_year_window(v / unit, n, a);
        if (!y) fn_argbad = 1;
        res = fn_signed18(y ? y * unit + v % unit : 0);
        break;
    }
    case COB_FN_TEST_DATE_YYYYMMDD: {                 /* 15.73: 0 valid, 1 year, 2 month, 3 day */
        if (a[0].scale > 0 && a[0].v % pow10tab[a[0].scale]) fn_argbad = 1;     /* an integer */
        long v = (long)(a[0].v / pow10tab[a[0].scale]);
        long y = v / 10000, m = v / 100 % 100, d = v % 100;
        static const int md[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        int r = v < 16010000 || v > 99999999 ? 1 : m < 1 || m > 12 ? 2 : d < 1 || d > md[m - 1] + (m == 2 && leap(y)) ? 3 : 0;
        res = fn_signed18(r);
        break;
    }
    case COB_FN_TEST_DAY_YYYYDDD: {                   /* 15.74: 0 valid, 1 year, 2 day */
        if (a[0].scale > 0 && a[0].v % pow10tab[a[0].scale]) fn_argbad = 1;
        long v = (long)(a[0].v / pow10tab[a[0].scale]);
        long y = v / 1000, d = v % 1000;
        int r = v < 1601000 || v > 9999999 ? 1 : d < 1 || d > 365 + leap(y) ? 2 : 0;
        res = fn_signed18(r);
        break;
    }
    case COB_FN_COMBINED_DATETIME: {                   /* 2014; 2023 15.17: argument-1 + argument-2 / 100000 */
        long dt = (long)(a[0].v / pow10tab[a[0].scale]);
        if ((a[0].scale > 0 && a[0].v % pow10tab[a[0].scale]) || dt < 1 || dt > MAX_DAY) fn_argbad = 1;   /* integer date form */
        long long sec9 = cob_rescale(a[1].v, a[1].scale, 9);
        if (sec9 < 0 || sec9 >= 86400LL * 1000000000LL) fn_argbad = 1;              /* standard numeric time form */
        res = fn_signed18(fn_argbad ? 0 : dt * 1000000000LL + sec9 / 100000);
        break;
    }
    case COB_FN_SECONDS_PAST_MIDNIGHT: {               /* 15.80: the local time of day, to the hundredth */
        struct tm t; int h; long g; cob_clock(&t, &h, &g);
        res = fn_signed18(((long long)t.tm_hour * 3600 + t.tm_min * 60 + t.tm_sec) * 1000000000LL + (long long)h * 10000000LL);
        break;
    }
    default: cob_fatal("unknown intrinsic function");
    }
    nsp -= n;
    return res;
}

/* ---- the 2014 international date and time functions (15.38-15.41,
 * 15.48, 15.79, 15.92) ------------------------------------------------- */

/* integer date n: the day of the week, 1 Monday .. 7 Sunday (1601-01-01 was a Monday) */
static int dt_dow(long n) { return (int)((n - 1) % 7) + 1; }
/* the ISO week date of n: the week's Thursday names the year (15.3.1.7) */
static void dt_to_week(long n, long *wy, int *ww, int *wd)
{
    int dow = dt_dow(n);
    long thu = n + (4 - dow), y, m, d;
    days_to_civil(thu, &y, &m, &d);
    *wy = y; *ww = (int)((thu - civil_to_days(y, 1, 1)) / 7) + 1; *wd = dow;
}
/* the weeks of year y: 53 when January 4 is a Sunday, or a Saturday too in a leap year */
static int dt_weeks(long y)
{
    int j4 = dt_dow(civil_to_days(y, 1, 4));
    return j4 == 7 || (leap(y) && j4 == 6) ? 53 : 52;
}
static long dt_from_week(long y, int ww, int wd)
{
    long j4 = civil_to_days(y, 1, 4);
    return j4 - (dt_dow(j4) - 1) + (ww - 1) * 7L + (wd - 1);
}

/* the format of the next scan, and the national flag (the data's bytes are
 * UTF-16BE then, each unit one format character) */
static cob_dtfmt dt_fmt; static int dt_fmt_nat;
void cob_fn_dtfmt_arg(const unsigned char *f, int flen, int nat)
{
    unsigned char nf[64]; int n = 0;
    if (nat) { for (int i = 0; i + 1 < flen && n < 63; i += 2) nf[n++] = f[i] ? '?' : f[i + 1]; }
    else { n = flen < 63 ? flen : 63; memcpy(nf, f, (size_t)n); }
    if (cob_dtfmt_parse(nf, n, cob_dp_comma, &dt_fmt)) cob_fatal("a date or time format the compiler did not check");
    dt_fmt_nat = nat;
}

/* render: the date n (integer date form) and the time sec9 (seconds past
 * midnight, scale 9) with the offset off (minutes from UTC) by the format;
 * into out, len bytes of ASCII */
static void dt_render(const cob_dtfmt *f, long n, long long sec9, int off, char *out)
{
    int o = 0;
    #define D2(v) do { out[o++] = (char)('0' + (v) / 10 % 10); out[o++] = (char)('0' + (v) % 10); } while (0)
    if (f->tz == 1 && (f->kind & 2)) {
        /* UTC: the local time less the offset, the date rolling with it (15.40.4 rule 2) */
        sec9 -= (long long)off * 60 * 1000000000LL;
        while (sec9 < 0) { sec9 += 86400LL * 1000000000LL; n--; }
        while (sec9 >= 86400LL * 1000000000LL) { sec9 -= 86400LL * 1000000000LL; n++; }
    }
    if (f->kind & 1) {
        long y, m, d; days_to_civil(n, &y, &m, &d);
        if (f->dkind == 3) { long wy; int ww, wd; dt_to_week(n, &wy, &ww, &wd); y = wy; m = ww; d = wd; }
        D2(y / 100); D2(y % 100);
        if (f->ext) out[o++] = '-';
        if (f->dkind == 1) { D2(m); if (f->ext) out[o++] = '-'; D2(d); }
        else if (f->dkind == 2) { long doy = n - civil_to_days(y, 1, 1) + 1; out[o++] = (char)('0' + doy / 100); D2(doy % 100); }
        else { out[o++] = 'W'; D2(m); if (f->ext) out[o++] = '-'; out[o++] = (char)('0' + d); }
        if (f->kind == 3) out[o++] = 'T';
    }
    if (f->kind & 2) {
        long long s = sec9 / 1000000000LL, fr = sec9 % 1000000000LL;
        D2(s / 3600); if (f->ext) out[o++] = ':'; D2(s / 60 % 60); if (f->ext) out[o++] = ':'; D2(s % 60);
        if (f->frac) {
            if (f->ext) out[o++] = cob_dp_comma ? ',' : '.';
            char fd[10]; for (int i = 8; i >= 0; i--) { fd[i] = (char)('0' + fr % 10); fr /= 10; }
            for (int i = 0; i < f->frac; i++) out[o++] = i < 9 ? fd[i] : '0';
        }
        if (f->tz == 1) out[o++] = 'Z';
        else if (f->tz == 2) {
            int a = off < 0 ? -off : off;
            out[o++] = off < 0 ? '-' : '+';
            D2(a / 60); if (f->ext) out[o++] = ':'; D2(a % 60);
        }
    }
    #undef D2
}

/* the formatting functions: which 1 FORMATTED-CURRENT-DATE, 2 FORMATTED-
 * DATE (date), 3 FORMATTED-DATETIME (date, seconds [, offset]), 4
 * FORMATTED-TIME (seconds [, offset]); the n numeric arguments on the
 * stack; the result the data's length, national when the format is */
char *cob_fn_dtfmt(int which, const unsigned char *fmt, int flen, int nat, int n)
{
    cob_fn_dtfmt_arg(fmt, flen, nat);
    cob_dtfmt *f = &dt_fmt;
    cob_num *a = &nstk[nsp - n];
    long dt = 1; long long sec9 = 0; int off = 0, k = 0;
    if (which == 1) {
        struct tm t; int h; long g; cob_clock(&t, &h, &g);
        dt = civil_to_days(t.tm_year + 1900, t.tm_mon + 1, t.tm_mday);
        sec9 = ((long long)t.tm_hour * 3600 + t.tm_min * 60 + t.tm_sec) * 1000000000LL + (long long)h * 10000000LL;
        off = (int)(g / 60);
    } else {
        if (which != 4) {
            dt = (long)(a[k].v / pow10tab[a[k].scale]);
            if ((a[k].scale > 0 && a[k].v % pow10tab[a[k].scale]) || dt < 1 || dt > MAX_DAY) { fn_argbad = 1; dt = 1; }
            k++;
        }
        if (which != 2) {
            sec9 = cob_rescale(a[k].v, a[k].scale, 9);
            if (sec9 < 0 || sec9 >= 86400LL * 1000000000LL) { fn_argbad = 1; sec9 = 0; }
            k++;
        }
        if (k < n) {
            off = (int)(a[k].v / pow10tab[a[k].scale]);
            if ((a[k].scale > 0 && a[k].v % pow10tab[a[k].scale]) || off < -1439 || off > 1439) { fn_argbad = 1; off = 0; }
        }
    }
    nsp -= n;
    char tmp[64];
    dt_render(f, dt, sec9, off, tmp);
    char *b = fn_buffer(f->len * (nat ? 2 : 1));
    if (nat) for (int i = 0; i < f->len; i++) { b[2 * i] = 0; b[2 * i + 1] = tmp[i]; }
    else memcpy(b, tmp, (size_t)f->len);
    return b;
}

/* scan data by the format set by cob_fn_dtfmt_arg: 0 and the values, or
 * the 1-based position of the first character at which an error can be
 * seen (15.92.4) */
static int dt_scan(const cob_dtfmt *f, const unsigned char *p, int n, long *date, long long *sec9)
{
    int i = 0;                                  /* a shorter item: the missing positions are errors where they are reached */
    #define DIG(k) ((i + (k) < n && p[i + (k)] >= '0' && p[i + (k)] <= '9') ? p[i + (k)] - '0' : -1)
    #define LITC(c) do { if (i >= n || p[i] != (c)) return i + 1; i++; } while (0)
    long y = 0, m = 0, d = 0; int ww = 0, wd = 0;
    if (f->kind & 1) {
        /* the year: more than 1600, at most 9999 -- the first digit that decides */
        for (int k = 0; k < 4; k++) if (DIG(k) < 0) return i + k + 1;
        y = DIG(0) * 1000 + DIG(1) * 100 + DIG(2) * 10 + DIG(3);
        if (DIG(0) < 1) return i + 1;
        if (DIG(0) == 1 && DIG(1) < 6) return i + 2;
        if (y == 1600) return i + 4;
        i += 4;
        if (f->ext) LITC('-');
        if (f->dkind == 1) {
            if (DIG(0) < 0) return i + 1;
            if (DIG(0) > 1) return i + 1;
            if (DIG(1) < 0) return i + 2;
            m = DIG(0) * 10 + DIG(1);
            if (m < 1 || m > 12) return i + 2;
            i += 2;
            if (f->ext) LITC('-');
            static const int md[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
            int mx = md[m - 1] + (m == 2 && leap(y));
            if (DIG(0) < 0) return i + 1;
            if (DIG(0) > 3) return i + 1;
            if (DIG(1) < 0) return i + 2;
            d = DIG(0) * 10 + DIG(1);
            if (d < 1 || d > mx) return i + 2;
            i += 2;
            *date = civil_to_days(y, m, d);
        } else if (f->dkind == 2) {
            int mx = 365 + leap(y);
            for (int k = 0; k < 3; k++) {
                if (DIG(k) < 0) return i + k + 1;
                long sofar = 0; for (int j = 0; j <= k; j++) sofar = sofar * 10 + DIG(j);
                long pw = 1; for (int j = k + 1; j < 3; j++) pw *= 10;
                if (sofar * pw > mx) return i + k + 1;                 /* too big already */
                if (k == 2 && sofar == 0) return i + 3;
            }
            d = DIG(0) * 100 + DIG(1) * 10 + DIG(2);
            i += 3;
            *date = civil_to_days(y, 1, 1) + d - 1;
        } else {
            LITC('W');
            int mx = dt_weeks(y);
            if (DIG(0) < 0) return i + 1;
            if (DIG(0) > 5) return i + 1;
            if (DIG(1) < 0) return i + 2;
            ww = DIG(0) * 10 + DIG(1);
            if (ww < 1 || ww > mx) return i + 2;
            i += 2;
            if (f->ext) LITC('-');
            if (DIG(0) < 1 || DIG(0) > 7) return i + 1;
            wd = DIG(0);
            i += 1;
            *date = dt_from_week(y, ww, wd);
        }
        if (f->kind == 3) LITC('T');
    }
    if (f->kind & 2) {
        if (DIG(0) < 0 || DIG(0) > 2) return i + 1;
        if (DIG(1) < 0) return i + 2;
        long h = DIG(0) * 10 + DIG(1);
        if (h > 23) return i + 2;
        i += 2;
        if (f->ext) LITC(':');
        if (DIG(0) < 0 || DIG(0) > 5) return i + 1;
        if (DIG(1) < 0) return i + 2;
        long mi = DIG(0) * 10 + DIG(1);
        i += 2;
        if (f->ext) LITC(':');
        if (DIG(0) < 0 || DIG(0) > 5) return i + 1;
        if (DIG(1) < 0) return i + 2;
        long s = DIG(0) * 10 + DIG(1);
        i += 2;
        long long fr = 0; int fd = 0;
        if (f->frac) {
            if (f->ext) LITC(cob_dp_comma ? ',' : '.');
            for (int k = 0; k < f->frac; k++) {
                if (DIG(0) < 0) return i + 1;
                if (fd < 9) { fr = fr * 10 + DIG(0); fd++; }
                i++;
            }
            while (fd < 9) { fr *= 10; fd++; }
        }
        *sec9 = (h * 3600 + mi * 60 + s) * 1000000000LL + fr;
        if (f->tz == 1) LITC('Z');
        else if (f->tz == 2) {
            if (i >= n || (p[i] != '+' && p[i] != '-' && p[i] != '0')) return i + 1;
            int zero = p[i] == '0';
            i++;
            if (DIG(0) < 0 || DIG(0) > 2) return i + 1;
            if (DIG(1) < 0) return i + 2;
            long oh = DIG(0) * 10 + DIG(1);
            if (zero && DIG(0)) return i + 1;             /* a zero sign: both subfields zero, the first digit that is not */
            if (oh > 23 || (zero && oh)) return i + 2;
            i += 2;
            if (f->ext) LITC(':');
            if (DIG(0) < 0 || DIG(0) > 5) return i + 1;
            if (zero && DIG(0)) return i + 1;
            if (DIG(1) < 0) return i + 2;
            if (zero && DIG(1)) return i + 2;
            i += 2;
        }
    }
    #undef DIG
    #undef LITC
    return 0;
}

/* which: 1 INTEGER-OF-FORMATTED-DATE, 2 SECONDS-FROM-FORMATTED-TIME, 3
 * TEST-FORMATTED-DATETIME; p[0..n) the data, in the format's type */
char *cob_fn_dtfmt_scan(const unsigned char *p, int n, int which)
{
    unsigned char nb[128];
    if (dt_fmt_nat) {
        /* UTF-16BE: ASCII units narrowed, any other a character that fits no format */
        int k = 0;
        for (int i = 0; i + 1 < n && k < 127; i += 2) nb[k++] = p[i] ? '?' : p[i + 1];
        p = nb; n = k;
    } else if (n > 127) n = 127;
    long date = 0; long long sec9 = 0;
    int e = dt_scan(&dt_fmt, p, n, &date, &sec9);
    if (which == 3) return fn_signed18(e);
    if (e) { fn_argbad = 1; return fn_signed18(0); }
    if (which == 1) return fn_signed18(date);
    return fn_signed18(sec9);
}

/* MAX and MIN over alphanumeric arguments: the winning argument's
 * value, space-padded comparison in the native sequence; ORD-MAX and
 * ORD-MIN its position */
static const char *al_arg_p[64]; static int al_arg_n[64]; static int al_cnt;

void cob_fn_al_arg(const char *p, int n)
{
    if (al_cnt < 64) { al_arg_p[al_cnt] = p; al_arg_n[al_cnt] = n; al_cnt++; }
}

static int al_cmp(const char *a, int an, const char *b, int bn)
{
    int n = an > bn ? an : bn;
    for (int i = 0; i < n; i++) {
        unsigned char x = i < an ? (unsigned char)a[i] : ' ';
        unsigned char y = i < bn ? (unsigned char)b[i] : ' ';
        if (x != y) return x < y ? -1 : 1;
    }
    return 0;
}

char *cob_fn_al(int which, int fsize)
{
    int best = 0;
    for (int i = 1; i < al_cnt; i++) {
        int c = al_cmp(al_arg_p[i], al_arg_n[i], al_arg_p[best], al_arg_n[best]);
        if ((which == COB_FN_MAX || which == COB_FN_ORD_MAX) ? c > 0 : c < 0) best = i;
    }
    int n = al_cnt; al_cnt = 0;
    if (n == 0) cob_fatal("FUNCTION MAX/MIN with no arguments");
    if (which == COB_FN_ORD_MAX || which == COB_FN_ORD_MIN) return fn_signed18(best + 1);
    char *b = fn_buffer((unsigned)fsize + 1);
    memset(b, ' ', (size_t)fsize);
    memcpy(b, al_arg_p[best], (size_t)(al_arg_n[best] < fsize ? al_arg_n[best] : fsize));
    b[fsize] = 0;
    fn_var_len = al_arg_n[best] < fsize ? al_arg_n[best] : fsize;   /* the selected argument's size (2023 15.59.4 rule 3) */
    return b;
}

/* CHAR: the character at ordinal position n of the native sequence;
 * ORD: an argument character's position -- each the other's inverse */
char *cob_fn_char(int n)
{
    char *b = fn_buffer(2);
    if (n < 1 || n > 256) { fn_argbad = 1; n = ' ' + 1; }   /* 1 to the sequence's 256 positions (15.15.3 rule 2) */
    b[0] = (char)(n - 1); b[1] = 0;
    return b;
}

char *cob_fn_ord(const char *p)
{
    return fn_signed18((unsigned char)p[0] + 1);
}

char *cob_fn_reverse(const char *p, int n)
{
    char *b = fn_buffer((unsigned)n + 1);
    for (int i = 0; i < n; i++) b[i] = p[n - 1 - i];
    b[n] = 0;
    fn_var_len = n;                             /* an argument of run-time length: the result's is the same */
    return b;
}

/* NUMVAL / NUMVAL-C: the numeric value of a character string --
 * spaces, an optional sign either side, digits with one point (comma
 * under DECIMAL-POINT IS COMMA); NUMVAL-C also passes over the
 * currency sign and the grouping separators */
/* NUMVAL, NUMVAL-C and NUMVAL-F's argument formats (2002 15.54-15.56),
 * as one scanner: 0 when p conforms, else the position of the first
 * character in error, or n + 1 when the error is no one character's
 * (TEST-NUMVAL's returned value, 15.75-15.77).  form 0 NUMVAL, 1
 * NUMVAL-C (a currency string, grouping commas), 2 NUMVAL-F (an exponent).
 * The value, when it conforms: v at scale sc, times 10**exp. */
static const char *fn_cur_p; static int fn_cur_n, fn_cur_ci;    /* NUMVAL-C argument-2, for the next call; ANYCASE */

void cob_fn_currency_arg(const char *p, int n, int anycase)
{
    while (n > 0 && *p == ' ') { p++; n--; }
    while (n > 0 && p[n - 1] == ' ') n--;
    fn_cur_p = p; fn_cur_n = n; fn_cur_ci = anycase;
}
static int cs_match(const char *p, const char *cs, int n, int ci)
{
    for (int i = 0; i < n; i++)
        if (ci ? tolower((unsigned char)p[i]) != tolower((unsigned char)cs[i]) : p[i] != cs[i]) return 0;
    return 1;
}

static int numval_scan(const char *p, int n, int form, cob_wnum *wv, int *exp10)
{
    char cs[64]; int csn;
    int ci = fn_cur_ci;
    if (form == 1 && fn_cur_p) { csn = fn_cur_n < 63 ? fn_cur_n : 63; memcpy(cs, fn_cur_p, (size_t)csn); }
    else { csn = cob_currency_len; memcpy(cs, cob_currency_str, (size_t)csn); }   /* the program's currency string (15.65: the default) */
    fn_cur_p = 0; fn_cur_ci = 0;
    int dp = cob_dp_comma ? ',' : '.', grp = cob_dp_comma ? '.' : ',';
    int i = 0, neg = 0, lead = 0, nd = 0, seen_pt = 0, scale = 0, any = 0;
    char dg[40]; int ndg = 0;                       /* the digits, up to 31 (15.54: the argument's limit) */
#define SP() while (i < n && p[i] == ' ') i++
    SP();
    if (i < n && (p[i] == '+' || p[i] == '-')) { neg = p[i] == '-'; lead = 1; i++; SP(); }
    if (form == 1 && csn && i + csn <= n && cs_match(p + i, cs, csn, ci)) { i += csn; SP(); }
    /* the number: digits, one decimal separator, NUMVAL-C's grouping commas */
    int start = i;
    for (; i < n; i++) {
        unsigned char c = (unsigned char)p[i];
        if (c >= '0' && c <= '9') {
            if (++nd > 31) return i + 1;
            any = 1;
            dg[ndg++] = (char)c; if (seen_pt) scale++;
        } else if (c == dp && !seen_pt) seen_pt = 1;
        else if (form == 1 && c == grp && !seen_pt && any) {
            /* digit [, digit]...: the comma needs a digit after it; the
             * character that is not one is the one in error ("1,,2": 3) */
            if (i + 1 < n && p[i + 1] >= '0' && p[i + 1] <= '9') continue;
            return i + 1 < n ? i + 2 : n + 1;
        }
        else break;
    }
    if (!any) return i < n && i > start ? i + 1 : i < n ? i + 1 : n + 1;
    SP();
    int e = 0;
    if (form == 2 && i < n && (p[i] == 'E' || p[i] == 'e')) {
        i++; SP();
        if (i >= n) return n + 1;
        if (p[i] != '+' && p[i] != '-') return i + 1;
        int eneg = p[i] == '-'; i++; SP();
        int k = 0;
        while (i < n && p[i] >= '0' && p[i] <= '9' && k < 4) { e = e * 10 + (p[i] - '0'); i++; k++; }
        if (k == 0) return i < n ? i + 1 : n + 1;
        if (k > 3) return i;
        if (eneg) e = -e;
        SP();
    } else if (form != 2 && !lead && i < n) {
        if (p[i] == '+' || p[i] == '-') { neg = p[i] == '-'; i++; SP(); }
        else if (i + 1 < n && (p[i] == 'C' || p[i] == 'c') && (p[i + 1] == 'R' || p[i + 1] == 'r')) { neg = 1; i += 2; SP(); }
        else if (i + 1 < n && (p[i] == 'D' || p[i] == 'd') && (p[i + 1] == 'B' || p[i + 1] == 'b')) { neg = 1; i += 2; SP(); }
    }
    if (i < n) return i + 1;
#undef SP
    memset(wv, 0, sizeof *wv);
    w_from_digits(wv->m, dg, ndg); wv->scale = scale; wv->neg = neg && !mp_is_zero(wv->m, WL);
    *exp10 = e;
    return 0;
}

int cob_fn_test_numval_pos(const char *p, int n, int form)
{
    cob_wnum w; int e;
    return numval_scan(p, n, form, &w, &e);
}

char *cob_fn_test_numval(const char *p, int n, int form)
{
    return fn_signed18(cob_fn_test_numval_pos(p, n, form));
}

char *cob_fn_numval_f(const char *p, int n)
{
    cob_wnum w; int e;
    if (numval_scan(p, n, 2, &w, &e)) { fn_argbad = 1; w_from_i64(&w, 0, 0); return fn_wresult(&w, 9); }
    /* the value times 10**e: the scale moves, and a negative one is made
     * up with zeros while 38 digits hold them */
    w.scale -= e;
    if (w.scale < 0) {
        int up = -w.scale, room = 38 - w_ndigits(w.m);
        if (up > room) up = room;
        w_scale_up(w.m, up); w.scale = 0;
    }
    return fn_wresult(&w, 9);
}

char *cob_fn_numval(const char *p, int n, int cform)
{
    if (cform && fn_cur_p) {
        /* NUMVAL-C with argument-2, a currency string of any length:
         * the format scanner, which TEST-NUMVAL-C shares */
        cob_wnum w; int e;
        if (numval_scan(p, n, 1, &w, &e)) { fn_argbad = 1; w_from_i64(&w, 0, 0); }
        return fn_wresult(&w, 9);
    }
    /* out of format: noted (15.67.3, 15.68.3); the value is still the
     * digits read up to the first character out of place, as it was */
    { cob_wnum tw; int te; if (numval_scan(p, n, cform, &tw, &te)) fn_argbad = 1; else return fn_wresult(&tw, 9); }
    int i = 0, neg = 0, seen_pt = 0, scale = 0;
    char dg[40]; int ndg = 0;
    int dp = cob_dp_comma ? ',' : '.', grp = cob_dp_comma ? '.' : ',';
    int any_digit = 0;
    while (i < n && p[i] == ' ') i++;
    if (i < n && (p[i] == '+' || p[i] == '-')) { neg = p[i] == '-'; i++; }
    for (; i < n; i++) {
        unsigned char c = (unsigned char)p[i];
        if (c >= '0' && c <= '9') { any_digit = 1; if (ndg < 38) { dg[ndg++] = (char)c; if (seen_pt) scale++; } }
        else if (c == dp && !seen_pt) seen_pt = 1;
        else if (cform && (c == grp || c == (unsigned char)cob_currency)) continue;
        else if (c == ' ' && !any_digit) continue;      /* spaces stand between the sign, the currency and the number */
        else break;
    }
    while (i < n && p[i] == ' ') i++;               /* the trailing sign may stand off from the number */
    if (i < n) {
        unsigned char c = (unsigned char)p[i];
        if (c == '+' || c == '-') neg = c == '-';
        else if (cform && (c == 'C' || c == 'c' || c == 'D' || c == 'd')) neg = 1;   /* CR / DB */
    }
    cob_wnum w; memset(&w, 0, sizeof w);
    w_from_digits(w.m, dg, ndg); w.scale = scale; w.neg = neg && !mp_is_zero(w.m, WL);
    return fn_wresult(&w, 9);
}

char *cob_fn_integer_of_date(long ymd)
{
    long y = ymd / 10000, m = ymd / 100 % 100, d = ymd % 100;
    if (!valid_date(y, m, d)) { fn_argbad = 1; return fn_digits(0, 10); }   /* 15.46.3 */
    return fn_digits(civil_to_days(y, m, d), 10);
}
char *cob_fn_date_of_integer(long n)
{
    if (n < 1 || n > MAX_DAY) { fn_argbad = 1; return fn_digits(0, 8); }   /* integer date form */
    long y, m, d; days_to_civil(n, &y, &m, &d);
    return fn_digits(y * 10000 + m * 100 + d, 8);
}
char *cob_fn_day_of_integer(long n)
{
    if (n < 1 || n > MAX_DAY) { fn_argbad = 1; return fn_digits(0, 7); }
    long y, m, d; days_to_civil(n, &y, &m, &d);
    return fn_digits(y * 1000 + (n - civil_to_days(y, 1, 1) + 1), 7);
}
char *cob_fn_integer_of_day(long yddd)
{
    long y = yddd / 1000, doy = yddd % 1000;
    if (y < 1601 || y > 9999 || doy < 1 || doy > 365 + leap(y)) { fn_argbad = 1; return fn_digits(0, 10); }
    return fn_digits(civil_to_days(y, 1, 1) + doy - 1, 10);
}

/* The clock, for ACCEPT FROM DATE/DAY/TIME/DAY-OF-WEEK and FUNCTION
 * CURRENT-DATE.  COB_CURRENT_DATE, GnuCOBOL's name and its two forms,
 * YYYY/MM/DD or YYYY/MM/DD hh:mm:ss, fixes it: the run then sees that
 * moment and no other, so a program whose output depends on the date
 * prints the same paper every day it is run.  Every date field is
 * GnuCOBOL's.  Where GnuCOBOL 4.0 lets the real clock through -- the
 * time of day under the date-only form, the hundredths under the other
 * -- this clock stays fixed (missing fields read zero), and the offset
 * reads +0000; the point is reproducibility (cobol ISSUES-45, and the
 * divergence in section C).  A malformed value is fatal: silently
 * running on the real date would defeat the reason to set it. */
static int clk_state = -1;              /* -1 not yet read, 0 the real clock, 1 fixed */
static struct tm clk_tm;
static void cob_clock(struct tm *out, int *hund, long *gmtoff)
{
    if (clk_state < 0) {
        clk_state = 0;
        const char *e = getenv("COB_CURRENT_DATE");
        if (e && *e) {
            int y, mo, d, h = 0, mi = 0, sc = 0, used = 0, k;
            if (sscanf(e, "%4d/%2d/%2d%n", &y, &mo, &d, &used) != 3) used = -1;
            else if (e[used] == ' ' && sscanf(e + used, " %2d:%2d:%2d%n", &h, &mi, &sc, &k) == 3) used += k;
            if (used < 0 || e[used] != '\0' || !valid_date(y, mo, d) || h > 23 || mi > 59 || sc > 59 || h < 0 || mi < 0 || sc < 0) {
                fprintf(stderr, "libcob: COB_CURRENT_DATE='%s': expected YYYY/MM/DD or YYYY/MM/DD hh:mm:ss\n", e);
                exit(1);
            }
            long n = civil_to_days(y, mo, d);            /* 1601-01-01 is day 1, a Monday */
            memset(&clk_tm, 0, sizeof clk_tm);
            clk_tm.tm_year = y - 1900; clk_tm.tm_mon = mo - 1; clk_tm.tm_mday = d;
            clk_tm.tm_hour = h; clk_tm.tm_min = mi; clk_tm.tm_sec = sc;
            clk_tm.tm_yday = (int)(n - civil_to_days(y, 1, 1));
            clk_tm.tm_wday = (int)(((n - 1) % 7 + 1) % 7);   /* tm's: 0 Sunday */
            clk_state = 1;
        }
    }
    if (clk_state == 1) { *out = clk_tm; *hund = 0; *gmtoff = 0; return; }
    struct timespec ts; ts.tv_sec = 0; ts.tv_nsec = 0;
    *hund = 0;
    if (clock_gettime(0, &ts) == 0) *hund = (int)(ts.tv_nsec / 10000000);   /* CLOCK_REALTIME: the hundredths */
    else ts.tv_sec = time(0);
    time_t now = (time_t)ts.tv_sec;
    struct tm *t = localtime(&now);
    *out = *t; *gmtoff = t->tm_gmtoff;
}

/* ACCEPT ... FROM DATE (YYMMDD) | DAY (YYDDD) | TIME (HHMMSShh) |
 * DAY-OF-WEEK (1 Monday .. 7 Sunday): the text's unsigned integer,
 * moved to the item by the MOVE rules (X3.23 6.2.4) */
void cob_accept_datetime(int which, void *dst, const cob_desc *dd)
{
    struct tm tmv; int hund; long off;
    cob_clock(&tmv, &hund, &off);
    struct tm *t = &tmv;
    char b[16]; int n;
    switch (which) {
    case 0: n = snprintf(b, sizeof b, "%02d%02d%02d", t->tm_year % 100, t->tm_mon + 1, t->tm_mday); break;
    case 1: n = snprintf(b, sizeof b, "%02d%03d", t->tm_year % 100, t->tm_yday + 1); break;
    case 2: n = snprintf(b, sizeof b, "%02d%02d%02d%02d", t->tm_hour, t->tm_min, t->tm_sec, hund); break;
    case 4: n = snprintf(b, sizeof b, "%04d%02d%02d", t->tm_year + 1900, t->tm_mon + 1, t->tm_mday); break;   /* DATE YYYYMMDD (2002) */
    case 5: n = snprintf(b, sizeof b, "%04d%03d", t->tm_year + 1900, t->tm_yday + 1); break;                  /* DAY YYYYDDD */
    default: n = snprintf(b, sizeof b, "%d", t->tm_wday == 0 ? 7 : t->tm_wday); break;
    }
    cob_desc sd; memset(&sd, 0, sizeof sd);
    sd.cat = COB_NUM; sd.usage = COB_U_DISPLAY; sd.digits = (unsigned char)n; sd.size = (unsigned)n;
    cob_move(b, &sd, dst, dd);
}

char *cob_fn_current_date(void)
{
    char *b = fn_buffer(21);
    struct tm tmv; int hund; long off;
    cob_clock(&tmv, &hund, &off);
    struct tm *t = &tmv;
    int y = t->tm_year + 1900, mo = t->tm_mon + 1, d = t->tm_mday;
    int neg = off < 0; if (neg) off = -off;
    int oh = (int)(off / 3600), om = (int)((off % 3600) / 60);
    char tmp[32];
    int n = 0;
    #define PUT2(v) do { tmp[n++] = (char)('0' + (v) / 10 % 10); tmp[n++] = (char)('0' + (v) % 10); } while (0)
    tmp[n++] = (char)('0' + y / 1000 % 10); tmp[n++] = (char)('0' + y / 100 % 10); PUT2(y % 100);
    PUT2(mo); PUT2(d); PUT2(t->tm_hour); PUT2(t->tm_min); PUT2(t->tm_sec); PUT2(hund);
    tmp[n++] = neg ? '-' : '+'; PUT2(oh); PUT2(om);
    #undef PUT2
    memcpy(b, tmp, 21);
    return b;
}

/* ====================================================================== */
/* The command line: ACCEPT FROM ARGUMENT-NUMBER / ARGUMENT-VALUE /       */
/* COMMAND-LINE, DISPLAY UPON ARGUMENT-NUMBER (GnuCOBOL's implementor      */
/* module, measured: the count excludes the program name; ARGUMENT-VALUE   */
/* yields the arguments in turn from 1, DISPLAY n UPON ARGUMENT-NUMBER     */
/* makes the next one n, and past the end the item is left unchanged).     */
/* ====================================================================== */

static int cl_argc;
static char **cl_argv;
static int cl_next = 1;

void cob_set_args(int argc, char **argv) { cl_argc = argc; cl_argv = argv; cl_next = 1; }

static void put_text(void *p, const cob_desc *d, const char *s, int n)
{
    cob_desc td; memset(&td, 0, sizeof td);
    td.cat = COB_ALNUM; td.usage = COB_U_DISPLAY; td.size = (unsigned)n;
    cob_move(s, &td, p, d);
}

void cob_accept_argnum(void *p, const cob_desc *d)
{
    cob_put_num(p, d, cl_argc > 0 ? cl_argc - 1 : 0, 0);
}

void cob_display_upon_argnum(int n) { cl_next = n; }

void cob_accept_argval(void *p, const cob_desc *d)
{
    if (cl_next < 1 || cl_next >= cl_argc) return;            /* past the end: unchanged */
    const char *a = cl_argv[cl_next++];
    put_text(p, d, a, (int)strlen(a));
}

/* ---- the environment (X/Open, Micro Focus; BP-E31) ----------------------
 * DISPLAY ... UPON ENVIRONMENT-NAME names a variable; ACCEPT ... FROM
 * ENVIRONMENT-VALUE reads it, DISPLAY ... UPON ENVIRONMENT-VALUE sets it,
 * trailing spaces and all (MF DISPLAY rule 9).  ACCEPT ... FROM
 * ENVIRONMENT name reads one in a step.  The guest libc has no setenv: a
 * value set here is kept in a table this run unit reads first.  1 is the
 * exception condition: no name given yet, or no such variable. */
static char env_name[256]; static int env_named;
static struct { char *name, *value; } *env_set; static int env_nset;

static void env_copy_name(char *out, const char *p, int n)
{
    while (n > 0 && (p[n - 1] == ' ' || p[n - 1] == 0)) n--;
    if (n > 255) n = 255;
    memcpy(out, p, (size_t)n); out[n] = 0;
}
static const char *env_lookup(const char *name)
{
    for (int i = env_nset - 1; i >= 0; i--) if (!strcmp(env_set[i].name, name)) return env_set[i].value;
    return getenv(name);
}
void cob_env_set_name(const char *p, int n) { env_copy_name(env_name, p, n); env_named = 1; }
int cob_env_set_value(const char *p, int n)
{
    if (!env_named) return 1;
    env_set = realloc(env_set, (size_t)(env_nset + 1) * sizeof *env_set);
    char *v = malloc((size_t)n + 1), *k = malloc(strlen(env_name) + 1);
    if (!env_set || !v || !k) return 1;
    memcpy(v, p, (size_t)n); v[n] = 0; strcpy(k, env_name);
    env_set[env_nset].name = k; env_set[env_nset].value = v; env_nset++;
    return 0;
}
static void put_text(void *p, const cob_desc *d, const char *s, int n);
int cob_env_accept(void *p, const cob_desc *d)
{
    if (!env_named) return 1;
    const char *v = env_lookup(env_name);
    if (!v) return 1;
    put_text(p, d, v, (int)strlen(v));          /* the libc's buffer is the next getenv's: moved now */
    return 0;
}
int cob_env_accept_named(const char *np, int nn, void *p, const cob_desc *d)
{
    char name[256]; env_copy_name(name, np, nn);
    const char *v = env_lookup(name);
    if (!v) return 1;
    put_text(p, d, v, (int)strlen(v));
    return 0;
}
/* SET ENVIRONMENT name TO value (GnuCOBOL's own; BP-G1): the name and the
 * value both without their trailing spaces, as GnuCOBOL takes them --
 * unlike DISPLAY UPON ENVIRONMENT-VALUE, which keeps them (MF DISPLAY rule
 * 9).  Kept in the run unit's table like a DISPLAY's; no setenv. */
int cob_env_set_named(const char *np, int nn, const char *vp, int vn)
{
    char name[256]; env_copy_name(name, np, nn);
    while (vn > 0 && (vp[vn - 1] == ' ' || vp[vn - 1] == 0)) vn--;
    env_set = realloc(env_set, (size_t)(env_nset + 1) * sizeof *env_set);
    char *v = malloc((size_t)vn + 1), *k = malloc(strlen(name) + 1);
    if (!env_set || !v || !k) return 1;
    memcpy(v, vp, (size_t)vn); v[vn] = 0; strcpy(k, name);
    env_set[env_nset].name = k; env_set[env_nset].value = v; env_nset++;
    return 0;
}

/* ACCEPT ... FROM LINES | COLUMNS (X/Open's; BP-E32): the terminal's size,
 * 24 by 80 when it has none (output not to a terminal) */
void cob_accept_scr_dim(int cols, void *p, const cob_desc *d)
{
    int r = 24, c = 80;
    term_get_size(&r, &c);
    if (r <= 0) r = 24;
    if (c <= 0) c = 80;
    cob_put_num(p, d, cols ? c : r, 0);
}

/* ACCEPT identifier: one line from standard input, without its newline,
 * moved as alphanumeric text.  At end of file the item is left as it was. */
/* ... once the terminal is in use (a positioned or screen statement has
 * run), the line is read a key at a time from the terminal service and
 * echoed where the console's output stands: standard input is in raw
 * mode there (Enter is a carriage return, nothing echoes), and stdio's
 * read-ahead would take keys the next screen ACCEPT is owed.  Backspace
 * takes back a character; Enter ends the line; other keys are ignored. */
static int con_read_line(char *line, int cap)
{
    int n = 0, col0 = con_col, row = scr_next_line ? scr_next_line : 1;
    term_gotoxy(row, con_col);
    for (;;) {
        int key = scr_key();
        if (key == K_EOF || key == '\r' || key == '\n') break;
        if (key == 8 || key == 127) {
            if (!n) continue;
            do n--; while (n > 0 && ((unsigned char)line[n] & 0xC0) == 0x80);    /* one character back */
            int was = con_col;
            con_col = col0; con_write(line, n);                                  /* where the text now ends */
            int end = con_col;
            term_gotoxy(row, end);
            for (int k = end; k < was; k++) term_putc(' ');
            term_gotoxy(row, end);
            continue;
        }
        if (key < 32 || key >= 0x110000 || n + 4 >= cap) continue;
        int at = n;
        if (key < 0x80) line[n++] = (char)key;
        else if (key < 0x800) { line[n++] = (char)(0xC0 | key >> 6); line[n++] = (char)(0x80 | (key & 0x3F)); }
        else if (key < 0x10000) { line[n++] = (char)(0xE0 | key >> 12); line[n++] = (char)(0x80 | (key >> 6 & 0x3F)); line[n++] = (char)(0x80 | (key & 0x3F)); }
        else { line[n++] = (char)(0xF0 | key >> 18); line[n++] = (char)(0x80 | (key >> 12 & 0x3F)); line[n++] = (char)(0x80 | (key >> 6 & 0x3F)); line[n++] = (char)(0x80 | (key & 0x3F)); }
        con_write(line + at, n - at);
    }
    con_write("\n", 1);
    return n;
}

void cob_accept_console(void *p, const cob_desc *d)
{
    char line[4096];
    int n;
    if (term_up) n = con_read_line(line, (int)sizeof line);
    else {
        if (!fgets(line, sizeof line, stdin)) return;
        n = (int)strlen(line);
    }
    while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r')) n--;
    /* a line longer than a numeric DISPLAY item arrives as characters,
     * left-justified and truncated (what the NIST suite and GnuCOBOL do);
     * otherwise it is moved as text, which converts */
    if (d->cat == COB_NUM && d->usage == COB_U_DISPLAY && n > (int)d->size) { memcpy(p, line, d->size); return; }
    put_text(p, d, line, n);
}

void cob_accept_cmdline(void *p, const cob_desc *d)
{
    char line[4096]; int n = 0;
    for (int i = 1; i < cl_argc; i++) {
        const char *a = cl_argv[i];
        if (i > 1 && n < (int)sizeof line) line[n++] = ' ';
        for (const char *q = a; *q && n < (int)sizeof line; q++) line[n++] = *q;
    }
    put_text(p, d, line, n);
}
